#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_UID 1000
#define MIN_UID 1

typedef struct {
    time_t timestamp;
    enum EventType { STOP, SPEEDING, ACCIDENT } event_type;
    int uID;
} TrafficEvent;

void log_error(const char *msg) {
    fprintf(stderr, "[ERROR] %s\n", msg);
}

TrafficEvent* create_traffic_event() {
    TrafficEvent * event = (TrafficEvent *) malloc(sizeof(TrafficEvent));
    if (!event) {
        log_error("Memory allocation failure");
        return NULL;
    }

    return event;
}

void populate_traffic_events(TrafficEvent **list, size_t num_elements) {
    for (size_t i = 0; i < num_elements; ++i) {
        TrafficEvent *event = create_traffic_event();
        if (!event) continue;

        event->timestamp = time(NULL);
        event->event_type = static_cast<enum EventType>(rand() % 3);

        int uID = rand() % (MAX_UID - MIN_UID + 1) + MIN_UID;
        if (uID < MIN_UID || uID > MAX_UID) {
            log_error("UID out of range. Generated: ");
            printf("%d\n", uID);
            continue;
        }
        event->uID = uID;

        list[i] = event;
    }
}
