#include <iostream>
#include <fstream>
#include <sstream>
#include <string>
#include <vector>
#include <boost/program_options.hpp>
#include <boost/filesystem.hpp>
#include <boost/thread.hpp>
#include <chrono>
#include "log4cxx/logger"
#include "log4cxx/basicconfigurator"
#include "log4cxx/fileappender"
#include "log4cxx/rollingfileappender.h"

using namespace std;
namespace po = boost::program_options;
using namespace log4cxx;

struct Config {
    string inputFile, outputFile, configFile;
    bool manpage, cs;
};

void process_file(const Config& cfg, const string& filePath) {
    ifstream in(filePath);
    if (!in.is_open()) throw runtime_error("Could not open file: " + filePath);

    int64_t lineCount = 0;
    string line;
    size_t bufferSize = 1024 * 1024; // 1MB buffer
    char* buffer = new char[bufferSize];

    while (getline(in, line, '\n')) {
        ++lineCount;
        if (line.size() + 1 >= bufferSize) {
            bufferSize *= 2;
            char* tempBuffer = new char[bufferSize];
            memcpy(tempBuffer, buffer, in.gcount());
            delete[] buffer;
            buffer = tempBuffer;
        }
        memcpy(buffer + in.tellg(), line.c_str(), line.size() + 1);
        in.seekg(0, in.beg);
        in.read(buffer + in.tellg(), bufferSize - in.tellg());
    }

    delete[] buffer;
    in.close();

    LoggerPtr logger = Logger::getLogger("file_counter");
    auto now = chrono::system_clock::now();
    TimeStamp ts(now);
    StringAppenderPtr appender = RollingFileAppender::createDefaultRollingFileAppender("log.txt");
    appender->activateOptions();
    logger->addAppender(appender);
    logger->info(ts.toLongString() + ": Processed file: " + filePath + ", lines: " + to_string(lineCount));
}

int main(int argc, char* argv[]) {
    Config cfg;
    po::options_description desc("Allowed options");
    desc.add_options()
        ("help", "Produce help message")
        ("manpage", "Show detailed program usage")
        ("input-file", po::value<string>(&cfg.inputFile)->default_value(""), "Input file to process")
        ("output-file", po::value<string>(&cfg.outputFile)->default_value("-"), "Output file for the result (defaults to stdout)")
        ("cs", "Count lines in a file (without processing it further)")
        ("config", po::value<string>(&cfg.configFile)->default_value("config.txt"), "Configuration file path");

    po::variables_map vm;
    try {
        po::store(po::parse_command_line(argc, argv, desc), vm);
        po::notify(vm);

        if (vm.count("help")) {
            cout << desc << '\n';
            return 0;
        }

        if (vm.count("manpage")) {
            system("man -w file_counter");
            return 0;
        }
    } catch (const po::error& e) {
        cerr << "Error parsing command line options: " << e.what() << '\n';
        cout << desc << '\n';
        return 1;
    }

    ifstream config(cfg.configFile);
    if (!config.is_open()) throw runtime_error("Could not open configuration file: " + cfg.configFile);

    // Read and parse the configuration file here...

    vector<string> files;
    // Populate 'files' with the paths of the input files to process...

    int numThreads = std::thread::hardware_concurrency();
    vector<boost::thread> threads(numThreads);

    for (auto& file : files) {
        Config threadCfg = cfg; // Copy the configuration for each thread
        threadCfg.inputFile = file;
        threads[threads.size() - 1].reset(new boost::thread([&]() { process_file(threadCfg, file); }));
        threads.pop_back();
    }

    for (auto& t : threads) t.join();

    return 0;
}
```

