    char* details;
} LogEvent;

LogEvent* parse_event(char line[]) {
    LogEvent* event = malloc(sizeof(LogEvent));
    sscanf(line, "%" SCNu64 " %[^,],%s\n", &event->timestamp, event->event, &(event->details));
    return event;
}

void free_event(LogEvent* event) {
    free(event->details);
    free(event);
}

bool should_include(char filter[], const LogEvent* event) {
    // Implement your filtering logic here, using strstr or strcmp as needed.
