#include <sys/socket.h>

typedef struct {
    char hostname[256];
    u_char ip_addr[4];
} DnsRequest;

void* dns_query(void *arg);

int dns_resolve(const char *hostname, u_char *ip_addr) {
    DnsRequest req;
    strcpy(req.hostname, hostname);
    pthread_t thread_id;

    // Initialize IP address to zero
    memset(ip_addr, 0, sizeof(u_char) * 4);

    pthread_create(&thread_id, NULL, dns_query, &req);
    pthread_join(thread_id, NULL);

    memcpy(ip_addr, req.ip_addr, sizeof(u_char) * 4);

    return req.ip_addr[0] == 0 ? DNS_ERROR : 0;
}

