// Function to validate if the input contains any negative numbers
bool validate_input(const int* arr, size_t len) {
    for (size_t i = 0; i < len; ++i) {
        if (arr[i] < 0) {
            printf("Warning: Negative number detected.\n");
            return true;
        }
    }
    return false;
}

// Function to read integers and store them in a dynamically allocated array
void read_and_store(int** arr, size_t* len) {
    *arr = (int*)malloc((*len + 1000) * sizeof(int)); // Allocate additional space for safety
    int count = 0;
    while (count < *len && scanf("%d", &(*arr)[count]) == 1) {
        ++count;
    }
    *len = count;
}

// Function to calculate the sum of all integers in an array and check if it exceeds a threshold
void sum_check(int* arr, size_t len, int threshold) {
    long long sum = 0;
    for (size_t i = 0; i < len; ++i) {
        sum += arr[i];
        if (sum > threshold) {
            printf("Sum exceeded the defined threshold. Exiting gracefully.\n");
            exit(1);
        }
    }
}

// Function to find and print the largest integer in an array
void find_max(int* arr, size_t len) {
    int max = arr[0];
    for (size_t i = 1; i < len; ++i) {
        if (arr[i] > max) {
            max = arr[i];
        }
    }
    printf("Largest integer: %d\n", max);
}

int main() {
    const int threshold = 1000000;
    size_t len = 0;
    int* arr;
    bool is_negative_num_detected = validate_input(arr, len);
    if (is_negative_num_detected) {
        return 1;
    }
    read_and_store(&arr, &len);
    sum_check(arr, len, threshold);
    find_max(arr, len);
    free(arr);
    return 0;
}
