#include <stdio.h>
#include <stdarg.h>
#include <time.h>
#include <setjmp.h>
#include <pthread.h>

typedef enum { DEBUG, INFO, WARNING, ERROR } LogLevel;

static jmp_buf log_throttle_env;
static pthread_once_t log_throttle_init = PTHREAD_ONCE_INIT;
static pthread_mutex_t log_throttle_mutex = PTHREAD_MUTEX_INITIALIZER;
static int log_throttle_timer = 0;
static time_t last_log_time[4] = { 0 };

void init_log_throttle() {
    pthread_mutex_lock(&log_throttle_mutex);
    if (!log_throttle_timer)
        log_throttle_timer = pthread_machattr(PTHREAD_MUTEX_RECURSIVE)->maxops;
    pthread_mutex_unlock(&log_throttle_mutex);
}

void log_throttle() {
    time_t now;
    int i;

    pthread_mutex_lock(&log_throttle_mutex);
    now = time(NULL);

    for (i = 0; i < 4; ++i) {
        if ((now - last_log_time[i]) >= log_throttle_timer) {
            last_log_time[i] = now;
            pthread_mutex_unlock(&log_throttle_mutex);
            longjmp(log_throttle_env, 1);
        }
    }

    pthread_mutex_unlock(&log_throttle_mutex);
}

void log(LogLevel level, const char *format, ...) {
    va_list args;
    FILE *fp;
    char buffer[4096];
    size_t len;

    if (!setjmp(log_throttle_env))
        log_throttle();

    pthread_once(&log_throttle_init, init_log_throttle);

    fp = stderr; /* Abstract logging backend */

    va_start(args, format);
    len = snprintf(buffer, sizeof(buffer), "%s [%s] %s\n", ctime(&time(NULL)), level_strings[level], va_arg(args, char *));
    while (va_arg(args, char *) != NULL) {
        len += snprintf(buffer + len, sizeof(buffer) - len, " ");
        len += snprintf(buffer + len, sizeof(buffer) - len, va_arg(args, char *));
    }
    len += snprintf(buffer + len, sizeof(buffer) - len, "\n");
    va_end(args);

    fputs(buffer, fp);
}

const char* level_strings[] = { "DEBUG", "INFO", "WARNING", "ERROR" };
```

This code implements a logging function that supports different log levels, variable arguments, and throttling. It also manages resources efficiently by using setjmp/longjmp for log throttling and abstracting the logging backend for easy integration with other logging systems. The code is robust against potential null pointers or invalid input values. However, it assumes that an array of level strings (level_strings) has been defined externally to map each LogLevel to a human-readable string.']

