import hashlib
import hmac
from os import path, stat
from io import BytesIO
import requests
import time

def get_chunk(file_path, chunk_size=65536):
    with open(file_path, 'rb') as f:
        file_size = stat(file_path).st_size
        for offset in range(0, file_size, chunk_size):
            yield f.read(chunk_size)[offset:]

def md5_hash(file_path):
    m = hashlib.md5()
    for chunk in get_chunk(file_path):
        m.update(chunk)
    return m.hexdigest()

def verify_checksum(local_hash, service_url):
    with BytesIO(local_hash.encode()) as local_data:
        h = hmac.new(b"secretkey", local_data, hashlib.md5)
        signed_hash = h.digest()

        timeout = 10  # adjust this to desired time-out in seconds
        start_time = time.time()
        while True:
            try:
                response = requests.get(f"{service_url}/verify", data=signed_hash, timeout=timeout)
                if response.status_code == 200:
                    return True, response.json()['message']
                elif response.status_code == 429:
                    elapsed = time.time() - start_time
                    if elapsed > timeout:
                        raise TimeoutError(f"Request timed out after {timeout} seconds.")
                    remaining_time = timeout - elapsed
                    time.sleep(remaining_time)
                else:
                    raise Exception(f"Unexpected response from server: {response.status_code}")
            except requests.exceptions.RequestException as e:
                if time.time() - start_time > timeout:
                    raise TimeoutError("Failed to connect after the specified time-out.")
                else:
                    print(f"Error during request: {e}. Retrying...")

def hash_file_and_verify(file_path):
    local_hash = md5_hash(file_path)
    verification_result = verify_checksum(local_hash, "https://your-metadata-service.com/api")
    return local_hash, verification_result[0]
