crypt_context *parse_json_and_init_cipher(const char *json) {
    json_t *root = json_loads(json, JSON_DEEP_STRICT, NULL);
    if (!root || !json_is_object(root)) {
        return NULL;
    }

    const char *access_token = json_object_get(root, "access_token");
    const char *token_type = json_object_get(root, "token_type");
    int expires_in = json_integer_value(json_object_get(root, "expires_in"));
    const char *refresh_token = json_object_get(root, "refresh_token");

    if (!access_token || !token_type || expires_in <= 0) {
        json_decref(root);
        return NULL;
    }

    if (strcmp(token_type, "Bearer") != 0) {
        json_decref(root);
        return NULL;
    }

    crypt_context *ctx = malloc(sizeof(crypt_context));

    const EVP_CIPHER *des_ecb = EVP_des_ecb();
    ctx->cipher = des_ecb;
    ctx->iv = NULL;
    ctx->iv_len = 0;

    if (strcmp(json_object_get(root, "mode"), "ECB") == 0) {
        // ECB mode implementation here
    } else if (strcmp(json_object_get(root, "mode"), "EDE") == 0) {
        // EDE mode implementation here
    } else if (strcmp(json_object_get(root, "mode"), "EDE3") == 0) {
        // EDE3 mode implementation here
    } else if (strcmp(json_object_get(root, "mode"), "CFB") == 0) {
        // CFB mode implementation here
    } else if (strcmp(json_object_get(root, "mode"), "NULL") == 0) {
        ctx->cipher = NULL;
    } else {
        json_decref(root);
        free(ctx);
        return NULL;
    }

    json_decref(root);
    return ctx;
}
