import os
import subprocess
import sys
from typing import Dict

def replace_placeholders(config_file: str, placeholders: Dict[str, str]) -> None:
    for placeholder, value in placeholders.items():
        command = f'sed -i "s/{placeholder}/{value}/g" {config_file}'
        try:
            subprocess.run(command, shell=True, check=True)
        except subprocess.CalledProcessError as e:
            raise Exception(f'Failed to replace placeholder {placeholder} in file {config_file}. Command failed: {e.cmd}')

    # Add encrypted password at the end of the file
    command = f'echo "ENC_PASSWORD=mysecretpassword" >> {config_file}'
    try:
        subprocess.run(command, shell=True, check=True)
    except subprocess.CalledProcessError as e:
        raise Exception(f'Failed to add encrypted password in file {config_file}. Command failed: {e.cmd}')

def log(message: str) -> None:
    print(f'\033[92m{message}\033[0m')  # Green color for log messages

# This is just an example, replace it with actual logging mechanisms like logging library in Python

if __name__ == '__main__':
