import java.util.HashMap;
import java.util.Map;
import static java.lang.String.format;

public class PokemonWeaknesses {
    private static final Map<String, String[]> POKEMON_TYPES = new HashMap<>();

    static {
        // Initialize the map with appropriate data for all possible types of Pokemon
        POKEMON_TYPES.put("Fire", new String[]{"Water", "Ground"});
        POKEMON_TYPES.put("Water", new String[]{"Electric", "Grass"});
        // Add more types as needed...
    }

    public static String getWeaknesses(Pokemon pokemon) {
        String type = pokemon.getType();
        String[] weaknesses = POKEMON_TYPES.getOrDefault(type, new String[0]);

        StringBuilder result = new StringBuilder();
        for (String weakness : weaknesses) {
            result.append(format("%s, ", weakness));
        }

        // Remove the last comma from the result and return it
        if (result.length() > 0) {
            return result.substring(0, result.length() - 1);
        } else {
            return "";
        }
    }
}
