#include <pthread.h>
#include <semaphore.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <sys/time.h>

typedef struct Semaphore {
    sem_t sem;
    pthread_mutex_t mutex;
    bool active;
} Semaphore;

Semaphore* create_semaphore(int value) {
    Semaphore *s = malloc(sizeof(Semaphore));
    if (!s) return NULL;

    sem_init(&s->sem, 0, value);
    pthread_mutex_init(&s->mutex, NULL);
    s->active = true;

    return s;
}

void destroy_semaphore(Semaphore *s) {
    if (!s || !s->active) return;

    sem_destroy(&s->sem);
    pthread_mutex_destroy(&s->mutex);
    free(s);
}

bool try_wait(Semaphore *s, struct timespec *timeout) {
    bool ret = true;

    if (timeout) {
        struct timespec now, remaining;
        clock_gettime(CLOCK_REALTIME, &now);

        // Calculate remaining time from the given timeout
        remaining.tv_sec = timeout->tv_sec - now.tv_sec;
        remaining.tv_nsec = timeout->tv_nsec - now.tv_nsec;
        if (remaining.tv_nsec < 0) {
            remaining.tv_sec--;
            remaining.tv_nsec += 1000000000UL;
        }

        // Try to wait on the semaphore with a timeout
        if (sem_timedwait(&s->sem, &remaining) == -1 && errno != ETIMEDOUT) {
            perror("sem_timedwait");
            ret = false;
        }
    } else {
        // Wait on the semaphore without a timeout
        if (sem_wait(&s->sem) == -1) {
            perror("sem_wait");
            ret = false;
        }
    }

    return ret;
}

void signal(Semaphore *s) {
    // Signal the semaphore without waiting for it to be available
    if (sem_post(&s->sem) == -1) perror("sem_post");
}

int get_active_semaphores() {
    pthread_mutex_lock(&global_mutex);
    int count = active_semaphores;
    pthread_mutex_unlock(&global_mutex);
    return count;
}

// Add global variables to keep track of the number of active semaphores and manage locks
pthread_mutex_t global_mutex = PTHREAD_MUTEX_INITIALIZER;
int active_semaphores = 0;
