use llvm_parser::lexer::{Language, SourceManager};
use llvm_parser::parser::Parser;

type ParseResult<T> = Result<T, Box<dyn std::error::Error>>;

// Language configurations with their respective parsers and lexers.
let languages: HashMap<&'static str, (Box<dyn Language>, Box<dyn Parser<SourceManager>>)> = HashMap::from_iter([
    ("cpp", (Box::new(Language::Cpp), Box::new(Parser::new()))),
    ("py", (Box::new(Language::Python), Box::new(Parser::new()))),
    ("rs", (Box::new(Language::Rust), Box::new(Parser::new()))),
]);

fn generate_llvm_ir(file_path: &str) -> ParseResult<()> {
    // Validate the file path for existence and correct format.
    let file_path = Path::new(file_path);
    if !file_path.exists() || !file_path.is_file() {
        return Err(Box::new(std::io::Error::new(
            std::io::ErrorKind::NotFound,
            format!("File {} does not exist.", file_path.display()),
        )));
    }

    let ext = file_path.extension().and_then(AsRef::as_ref).map(|s| s.to_str().unwrap());
    if ext.is_none() || !languages.contains_key(ext) {
        return Err(Box::new(std::io::Error::new(
            std::io::ErrorKind::InvalidInput,
            "File has unsupported extension.",
        )));
    }

    // Create a context for the LLVM IR module.
    let context = Context::create_native();

    // Load the source code from the file.
    let reader = BufReader::new(File::open(file_path)?);

    // Initialize the SourceManager with the loaded source code and the language configuration.
    let mut source_manager = SourceManager::create();
    source_manager.add_source_file(file_path, reader);

    // Get the appropriate lexer and parser based on the file extension.
    let (_, parser) = languages[ext.unwrap()].1.clone();

    // Parse the source code using the selected parser and lexer, and generate an LLVM IR module.
    let mut module = Module::new("generated", context);
    let mut parser = Parser::new(source_manager, &module);

    match parser.parse() {
        Ok(FunctionDecl::ModuleFunc(func_decl)) => {
            // Generate LLVM IR code optimized for the specified level (O0, O1, O2).
            let target_triple = "x86_64-pc-linux-gnu";
            let target_cpu = "generic";
            let target_arch = "x86_64";
            let opt_level = 0; // Change this value to adjust the optimization level (O0, O1, O2)
            let target_machine = TargetMachine::new(target_triple, target_cpu, target_arch, context);

            let mut mf = module.fold_with(&mut target_machine);
            for basic_block in &func_decl.body().iter() {
                mf.visit_basic_block(basic_block, &mut target_machine);
            }
            let llvm_ir = mf.finalize();

            // Print the parsed nodes and the generated LLVM IR code for debugging.
            println!("Parsed Nodes: {:#?}", func_decl);
            writeln!(io::stdout(), "Generated LLVM IR:\n{}", llvm_ir)?;

            // Ensure thread safety when generating LLVM IR code from multiple files concurrently.
            let mut guard = mf.lock();

            // Allow the user to specify a target architecture for the LLVM IR code generation.
