namespace po = boost::program_options;
using boost::asio::ip::tcp;

class Connection final {
public:
    explicit Connection(boost::asio::io_service& io) : socket_(io), strand_(io) {}
    tcp::socket& socket() noexcept { return socket_; }
    void start(std::function<void(Connection&)> cb) {
        strand_.wrap(cb, boost::bind(&tcp::socket::close, &socket_));
        do_work(cb);
    }
private:
    void do_work(std::function<void(Connection&)> cb) {
        async_read_some(cb);
    }
    void async_read_some(std::function<void(Connection&)> cb) {
        read_.swap(buffer_);
        auto self = shared_from_this();
        boost::asio::async_read_some(*this, read_, [self, cb](boost::system::error_code ec, std::size_t /*length*/) {
            if (!ec) {
                cb(*self);
            } else {
                do_work(cb);
            }
        });
    }
    tcp::socket socket_;
    boost::asio::strand<boost::asio::io_service::executor_type> strand_;
    boost::asio::streambuf read_;
    char buffer_[4096];
};

class ConnectionPool final {
public:
    explicit ConnectionPool(size_t maxConnections, size_t timeoutSecs)
        : maxConnections_(maxConnections), timeout_(std::chrono::seconds(timeoutSecs)), pool_() {}

    Connection& getConnection() {
        boost::unique_lock<boost::mutex> lock(mutex_);
        if (pool_.empty()) {
            pool_.emplace_back(io_);
        }
        auto it = std::find_if(pool_.begin(), pool_.end(), [this](const Connection& c) {
            return !c.socket().is_open() || c.elapsedTime() > timeout_;
        });
        if (it != pool_.end()) {
            pool_.erase(it);
            it = std::end(pool_);
        }
        if (it == std::end(pool_)) {
            it = pool_.begin();
        }
        Connection& conn = *it;
        lastUsedTime_[&conn] = std::chrono::steady_clock::now();
        return *it;
    }

    void releaseConnection(Connection& conn) {
        boost::unique_lock<boost::mutex> lock(mutex_);
        lastUsedTime_.erase(&conn);
    }
private:
    size_t maxConnections_;
    std::chrono::steady_clock::time_point timeout_;
    std::vector<Connection> pool_;
    std::map<const Connection*, std::chrono::steady_clock::time_point> lastUsedTime_;
    boost::mutex mutex_;
    boost::asio::io_service io_;
};

