namespace CustomRNG {
    class ThreadSafeMersenneTwister {
        std::mt19937 engine;
        std::mutex mtx;
        std::vector<uint32_t> state;

    public:
        ThreadSafeMersenneTwister() : engine(state.data()) {}

        ~ThreadSafeMersenneTwister() {}

        const std::vector<uint32_t>& getState() const {
            return state;
        }

        uint32_t next() {
            std::unique_lock<std::mutex> lock(mtx);
            uint32_t result = engine();
            lock.unlock();
            return result;
        }
    };
}
