            catch (Exception ex)
            {
                Debug.LogError($"Failed to load asset at path '{path}'. Error: {ex.Message}");
            }
        }
    }

    private static AssetInfo LoadAsset(string path)
    {
        var extension = Path.GetExtension(path);
        switch (extension)
        {
            case ".png":
                return new Texture2DAssetInfo(Texture2D.LoadImageAtPath(path));
            case ".jpg":
            case ".jpeg":
                return new Texture2DAssetInfo(JpegImporter.GetDataFromFileOrBuildAsset(path).texture);
            default:
                throw new ArgumentException($"Unsupported asset format '{extension}' at path '{path}'.");
        }
    }
}

[System.Serializable]
public struct Texture2DAssetInfo
{
    public Texture2D texture;
}
```

In this example, the `ConfigLoader` class loads configuration from a JSON file and deserializes it into a `Configuration` object containing the necessary settings for the game engine. The `AssetLoader` handles dynamic loading of assets based on the configured paths in the `Configuration`. It uses a `Dictionary<string, AssetInfo>` to keep track of loaded assets and throws an exception if unsupported asset formats are encountered during loading.']

