const express = require('express');
const app = express();
const uuidv1 = require('uuid/v1');
const bodyParser = require('body-parser');
let users = {}; // In-memory data structure to store user profiles

app.use(bodyParser.json());

// Create or update user profile, handling both POST and PUT methods based on the existence of the id in the URL path
app.route('/user/:id')
  .all((req, res, next) => {
    const userId = req.params.id;
    if (!users[userId]) users[userId] = {}; // Create a new user profile entry if it doesn't exist
    next();
  })
  .get((req, res) => res.json(users[req.params.id] || {})) // Return the user profile or a default placeholder if it does not exist
  .post((req, res) => {
    const userId = uuidv1();
    users[userId] = req.body;
    res.status(201).json({ id: userId });
  })
  .put((req, res) => {
    users[req.params.id] = req.body;
    res.status(200).send();
  });

// Start the server
app.listen(3000);
