    $stmt = $db->prepare("SELECT COUNT(*) as count FROM users WHERE email = ?");
    $stmt->execute([$request['email']]);
    if ($stmt->fetchColumn() > 0) {
        $errors[] = 'EMAIL_EXISTS';
    }

    // Encrypt password, create/update user account or delete user account
    $passwordHasher = new PasswordHasher(); // Use a library for secure hashing (e.g., bcrypt)
    $password = isset($request['id']) ? '' : $passwordHasher->hash($request['password']);
    $subAction = isset($request['sub_action']) ? $request['sub_action'] : '';

    if (empty($errors)) {
        $data = [
            'name' => $request['name'],
            'email' => $request['email'],
            'password' => $password
        ];

        if (!isset($request['id'])) { // Create a new user account
            $externalAuthService = new ExternalAuthenticationService(); // Use your external authentication service for 2FA
            if (!$externalAuthService->authenticate($request)) {
                return json_encode(['message' => 'error', 'code' => 'AUTHENTICATION_FAILED']);
            }

            $stmt = $db->prepare("INSERT INTO users (name, email, password) VALUES (?, ?, ?)");
            $stmt->execute($data);
            logAction('create', $db->lastInsertId(), 'User creation', $ipAddress);
        } else { // Update an existing user account or delete a user account
            $stmt = $db->prepare("SELECT COUNT(*) as count FROM users WHERE id = ? AND email != ?");
            $stmt->execute([$request['id'], $request['email']]);
            if ($stmt->fetchColumn() > 0) {
                // If ID exists but email doesn't match, it means the user is trying to update someone else's account
                return json_encode(['message' => 'error', 'code' => 'UNAUTHORIZED']);
            }

            if ($subAction == 'delete') {
                $stmt = $db->prepare("DELETE FROM users WHERE id = ?");
                $stmt->execute([$request['id']]);
                logAction('delete', $request['id'], 'User deletion', $ipAddress);
            } else { // Partial update for specified fields
                // Only update the specified fields to avoid unnecessary overhead
                $updateFields = ['name' => isset($data['name']) ? $data['name'] : null, 'email' => isset($data['email']) ? $data['email'] : null];
                $stmt = $db->prepare("UPDATE users SET " . implode(', ', array_keys($updateFields)) . " = ? WHERE id = ?");
                foreach ($updateFields as $field => $value) {
                    $stmt->execute([$value, $request['id']]);
                }
                logAction('update', $request['id'], 'User update', $ipAddress);
            }
        }
    } else { // Return errors for invalid input
        return json_encode(['message' => 'error', 'code' => implode(', ', $errors)]);
    }

    // If no errors occurred, the function should return success
    return json_encode(['message' => 'success']);
}

function logAction($actionType, $userId, $description, $ipAddress) {
    // Logging implementation (e.g., using a database table or logging service)
}

// Rate limiter implementation (replace with your own rate limiter library if needed)
class RateLimiter {
    private $ips = [];
    private $maxRequests;
    private $interval;

    public function __construct($ip, $maxRequests, $interval) {
        $this->ips[$ip] = ['requests' => 0, 'timestamp' => time()];
        $this->maxRequests = $maxRequests;
        $this->interval = $interval;
    }

    public function check() {
        $currentTime = time();
        $timeDifference = $currentTime - $this->ips[$_SERVER['REMOTE_ADDR']]['timestamp'];

        if ($timeDifference < $this->interval) {
            $remainingRequests = $this->maxRequests - $this->ips[$_SERVER['REMOTE_ADDR']]['requests'];
            if ($remainingRequests <= 0) {
                return false;
            }
            $this->ips[$_SERVER['REMOTE_ADDR']]['requests'] += 1;
        } else {
            $this->ips[$_SERVER['REMOTE_ADDR']]['requests'] = 1;
            $this->ips[$_SERVER['REMOTE_ADDR']]['timestamp'] = $currentTime;
        }

        return true;
    }
}
