public async Task<bool> UpdateUserProfileAsync(int userId, string sessionToken, RequestType requestType, object payloadData)
{
    bool needsReload = false;
    var httpClient = new HttpClient();

    try
    {
        // Validate the session token
        if (!await UserSessionValidator.IsValidAsync(sessionToken))
            return false;

        // Create the request URI
        var requestUri = $"api/profiles/{userId}";

        // Set up the request header
        httpClient.DefaultRequestHeaders.Authorization = new System.Net.Http.Headers.AuthenticationHeaderValue("Bearer", sessionToken);

        // Process the request type
        switch (requestType)
        {
            case RequestType.UpdateProfile:
                // Serialize the payload data to JSON string
                var jsonPayload = JsonConvert.SerializeObject(payloadData);

                // Send the HTTP POST request with the payload data
                var response = await httpClient.PostAsync(requestUri, new StringContent(jsonPayload));
                response.EnsureSuccessStatusCode();

                needsReload = true;
                break;

            default:
                throw new ArgumentException($"Invalid request type '{requestType}'.");
        }

        // Update and persist the user's profile data using a service class
        await UserProfileService.UpdateAsync(userId, payloadData);
    }
    catch (HttpRequestException ex)
    {
        Console.WriteLine($"An error occurred while making HTTP request: {ex.Message}");
    }
    catch (JsonSerializationException ex)
    {
        Console.WriteLine($"An error occurred while serializing the payload data: {ex.Message}");
    }
    catch (ArgumentException ex)
    {
        Console.WriteLine(ex.Message);
    }

    return needsReload;
}
