import java.io.*;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.TimeoutException;

public class MoSTStateLoader {
    private static final ConcurrentHashMap<String, MoSTState> cache = new ConcurrentHashMap<>();
    private static final long READ_TIMEOUT_MILLIS = 5000; // Adjust this value as needed

    public static MoSTState loadFromFile(String filePath) {
        Path path = Paths.get(filePath);
        String fileName = path.getFileName().toString();

        try (ObjectInputStream ois = new ObjectInputStream(new FileInputStream(path.toFile()))) {
            long startTime = System.currentTimeMillis();
            try {
                Object object = ois.readObject();
                if (object instanceof MoSTState) {
                    cache.putIfAbsent(filePath, (MoSTState) object);
                    logReadOperation("Successfully loaded " + fileName);
                    return cache.get(filePath);
                }
            } catch (ClassNotFoundException e) {
                logError("Failed to deserialize object from file: ", e);
            }
        } catch (FileNotFoundException | IOException e) {
            logError("Could not find file: " + fileName, e);
        }

        if (!Files.exists(path)) {
            logError("Path does not exist: " + filePath);
            return null;
        }

        waitForReadCompletion(path);
        return null;
    }

    private static void waitForReadCompletion(Path path) {
        try {
            if (!Files.isReadable(path)) {
                throw new IllegalStateException("File is not readable.");
            }
            if (Files.size(path) > Long.MAX_VALUE) {
                throw new IllegalArgumentException("File size exceeds max supported value.");
            }

            long timeLeft = READ_TIMEOUT_MILLIS;
            while (Files.readAllBytes(path).length == 0 && timeLeft > 0) {
                Thread.sleep(100);
                timeLeft -= 100;
            }

            if (timeLeft <= 0) {
                throw new TimeoutException("Read operation timed out.");
            }
        } catch (InterruptedException | IOException e) {
            logError("An error occurred while waiting for read completion: ", e);
            throw new RuntimeException(e);
        }
    }

    private static void logReadOperation(String message) {
        // Implement logging using an external service here
    }

    private static void logError(String message, Exception e) {
        // Implement error logging using an external service here
    }
}
```

