['```javascript
function runTests({ moduleName, blueslip, tests }) {
  let totalTests = tests.length;
  let passedTests = 0;
  let failedTests = 0;

  function logTestResult(testName, result) {
    const now = new Date();
    blueslip.log(`${now.toLocaleTimeString()} - Test "${testName}" ${result ? 'PASSED' : 'FAILED'}`);
  }

  try {
    for (const test of tests) {
      // Load the module using dynamic require
      const module = require(moduleName);

      // Reset the blueslip instance before running each test
      blueslip.reset();

      try {
        // Execute the testFunction, passing the blueslip instance as a dependency
        logTestResult(test.name, true);
        module[test.testFunction](blueslip);
        passedTests++;
      } catch (error) {
        logTestResult(test.name, false);
        blueslip.log(`${now.toLocaleTimeString()} - Test "${test.name}" FAILED: ${error.message}`);
        failedTests++;
      }
    }
  } catch (error) {
    blueslip.log(`Test suite terminated unexpectedly: ${error.message}`);
  }

  return { totalTests, passedTests, failedTests };
}
```']

