    if (err) console.error(err);
    keys.forEach((key) => {
      redisClient.del(key, (expireErr, success) => {
        if (expireErr) console.error(expireErr);
        else if (success) console.log(`Cleared expired session: ${key}`);
      });
    });
  });
}, app.get('session:timeout'));

// Retrieve user profile image from session cache
