function hashPassword($password, $algorithm = 'BCrypt') {
    if ($algorithm === 'SHA-256') {
        return hash('sha256', $password);
    } elseif ($algorithm === 'BCrypt') {
        return password_hash($password, PASSWORD_BCRYPT);
    } else {
        throw new Exception("Invalid hashing algorithm provided.");
    }
}

function validatePasswordComplexity($password) {
    if (strlen($password) < 8 || strlen($password) > 128) {
        throw new Exception("Password length must be between 8 and 128 characters.");
    }

    // Regular expression for password complexity check
    $regex = '/(?=.*[A-Z])(?=.*[a-z])(?=.*\d)(?=.*[@$!%*?&])/';
    if (!preg_match($regex, $password)) {
        throw new Exception("Password must contain at least one uppercase letter, one lowercase letter, one digit, and one special character.");
    }
}

