public class GraphInitializer {
    private static final String CERTIFICATE_KEY = "certificate";

    public void init(String oauthRequest) throws Exception {
        var provider = new BouncyCastleProvider();
        Security.addProvider(provider);

        KeyPair keyPair = KeyPairGeneratorFactory.getInstance("RSA").generateKeyPair();
        ContentSigner signer = new JcaContentSignerBuilder("SHA256withRSA").build(keyPair.getPrivate());

        X500Name subjectDN = new X500Name("CN=Neo4jGraph, OU=Development, O=ExampleInc");
        long notBefore = Instant.now().toEpochMilli();
        long notAfter = Instant.now().plusYears(1).toEpochMilli();
        BigInteger serialNumber = new BigInteger(32, new SecureRandom());

        X509v3CertificateBuilder certificateBuilder = new JcaX509v3CertificateBuilder(subjectDN, serialNumber, notBefore, notAfter, subjectDN, keyPair.getPublic(), signer);

        byte[] pemCert = encodePEM(certificateBuilder.build(keyPair));

        try (Driver driver = GraphDatabase.driver("bolt://localhost", Config.builder()
                .withAuthBasic("neo4j", oauthRequest)
                .build())) {
            Session session = driver.session();

            session.run("CREATE CONSTRAINT ON (c:Certificate) ASSERT c.certificate IS UNIQUE");
            Result result = session.run("MERGE (c:Certificate {certificate: apoc.text.base64Encode(data:byte[], '" + pemCert.toString() + "')}) RETURN c");
            String certificateId = StreamSupport.stream(result.list().spliterator(), false).findFirst().get().get("c").asMap().keySet().iterator().next();

            int numVertices = new Random().nextInt(10) + 5;
            int numEdges = new Random().nextInt(numVertices * 2);

            for (int i = 0; i < numVertices; i++) {
                String vertexLabel = "Vertex" + i;
                String[] properties = {"property1", "property2", "property3"};
                Random random = new Random();
                Map<String, Object> props = new HashMap<>();

                for (int j = 0; j < properties.length; j++) {
                    props.put(properties[j], random.nextInt());
                }

                session.run("CREATE (:" + vertexLabel + " {" + props + "})");
            }

            for (int i = 0; i < numEdges; i++) {
                String edgeLabel = "Edge" + i;
                Random random = new Random();
                int startVertexId = random.nextInt(numVertices);
                int endVertexId = (startVertexId + 1) % numVertices;
                String[] properties = {"property1", "property2"};
                Map<String, Object> props = new HashMap<>();

                for (int j = 0; j < properties.length; j++) {
                    props.put(properties[j], random.nextInt());
                }

                session.run("CREATE -[:" + edgeLabel + "]->(:Vertex" + startVertexId + ") {" + props + "}");
            }
        }
    }

    private byte[] encodePEM(X509Certificate certificate) throws Exception {
        StringWriter pem = new StringWriter();
        pem.write("-----BEGIN CERTIFICATE-----\n");
        pem.write(Base64.getEncoder().encodeToString(certificate.getEncoded()));
        pem.write("\n-----END CERTIFICATE-----");
        return pem.toString().getBytes(StandardCharsets.UTF_8);
    }
}
