<?php
class UserProfile {
    private $apiUrl;
    private $cacheDuration;
    private $rateLimit;
    private $retryBackoff;
    private $log;
    private $cachedProfile;
    private $lastFetchTime;

    public function __construct($apiUrl, $cacheDuration, $rateLimit, $retryBackoff, $log) {
        $this->apiUrl = $apiUrl;
        $this->cacheDuration = $cacheDuration;
        $this->rateLimit = $rateLimit;
        $this->retryBackoff = $retryBackoff;
        $this->log = $log;
        $this->cachedProfile = null;
        $this->lastFetchTime = 0;
    }

    public function getUserProfile($userId) {
        if (!empty($this->cachedProfile[$userId])) {
            $currentTime = time();
            if (($currentTime - $this->lastFetchTime) < $this->cacheDuration) {
                return $this->cachedProfile[$userId];
            }
        }

        $attempts = 0;
        do {
            try {
                $response = file_get_contents($this->apiUrl . '/' . $userId);
                if ($response) {
                    $this->cachedProfile[$userId] = json_decode($response, true);
                    $this->lastFetchTime = time();
                    return $this->cachedProfile[$userId];
                }
            } catch (Exception $e) {
                $this->log->error('Error fetching user profile: ' . $e->getMessage());
            }

            sleep($this->retryBackoff * pow(2, $attempts));
            ++$attempts;
        } while ($attempts < $this->rateLimit && empty($this->cachedProfile[$userId]));
    }
}
```

