typedef struct StateNode {
    int state_id;
    struct StateNode *next;
} StateNode;

StateNode* create_state_list(StateNode *states, int total_states, const FiniteStateAutomaton *fsa, int last_state) {
    // Create a new linked list to store the desired states
    StateNode *new_head = NULL;
    StateNode *new_tail = NULL;

    // Iterate through the given state list
    for (int i = 0; i < total_states; ++i) {
        // If a state is valid and meets the specified criteria, add it to the new list
        if (isValidState(states + i, fsa) && shouldIncludeState(i, last_state)) {
            StateNode *new_node = malloc(sizeof(StateNode));
            if (!new_node) {
                // If memory allocation fails, return NULL
                free_linked_list(new_head);
                return NULL;
            }
            new_node->state_id = states[i].state_id;
            new_node->next = NULL;

            if (!new_tail) {
                // If the new list is empty, set both head and tail pointers
                new_head = new_node;
                new_tail = new_node;
            } else {
                // Otherwise, update the tail pointer to point to the new node
                new_tail->next = new_node;
                new_tail = new_node;
            }
        }
    }

    // Update the next pointer of the last state in the original list
    if (last_state >= 0 && last_state < total_states) {
        states[last_state].next = new_head;
    }

    return new_head;
}

// Helper function to check if a state is valid within the given FSA
bool isValidState(const StateNode *state, const FiniteStateAutomaton *fsa) {
    // Implement this function based on the validation criteria for your FSA
