}

// Helper function to check if a state should be included in the new list
bool shouldIncludeState(int state_id, int last_state) {
    // Implement this function based on the desired criteria for your FSA
    // Return true if the state should be included and false otherwise
}

// Helper function to free a linked list of StateNode structures
void free_linked_list(StateNode *head) {
    StateNode *current = head;
    while (current != NULL) {
        StateNode *next = current->next;
        free(current);
        current = next;
    }
}
