const unsigned int MAX_DATA_POINTS = 10000000;

// Define the OctreeNodeData structure to store custom data for each node
struct OctreeNodeData {
    // Custom data representation for each octree node (e.g., position, velocity, etc.)
};

// Function prototype for creating an Octree with a given initial capacity
template<typename T>
class DynamicOctree {
public:
    explicit DynamicOctree(unsigned int initialCapacity = 4);
    ~DynamicOctree();

    void insertDataPoint(const T& data);
    std::vector<T> queryNearbyPoints(const T& position, float radius) const;
    void adjustCapacity(unsigned int newCapacity);

private:
    // Octree node data type for custom data management
    using Node = typename Octree<OctreeNodeData>::Node;
    // Octree object for spatial data management
    std::unique_ptr<Octree<OctreeNodeData>> _octree;
    unsigned int _currentCapacity;
};

template<typename T>
DynamicOctree<T>::DynamicOctree(unsigned int initialCapacity)
    : _currentCapacity(initialCapacity) {
    if (initialCapacity < 4)
        _currentCapacity = 4;
    _octree.reset(new Octree<OctreeNodeData>(_currentCapacity));
}

template<typename T>
DynamicOctree<T>::~DynamicOctree() {}

template<typename T>
void DynamicOctree<T>::insertDataPoint(const T& data) {
    _octree->insert({ data });
    if (_octree->nodeCount() > _currentCapacity * 0.75f)
        adjustCapacity(_currentCapacity * 2);
}

template<typename T>
std::vector<T> DynamicOctree<T>::queryNearbyPoints(const T& position, float radius) const {
    std::vector<T> results;
    _octree->query({ position }, radius, [&results](const Node& node, const T& data) {
        // Check if the distance between the query position and the data point is within the specified radius
        if (distance(position, data) <= radius)
            results.push_back(data);
    });
    return results;
}

template<typename T>
void DynamicOctree<T>::adjustCapacity(unsigned int newCapacity) {
    _currentCapacity = newCapacity;
    _octree.reset(new Octree<OctreeNodeData>(_currentCapacity));
    for (const auto& node : *_octree)
        _octree->getRoot()->addChild(node);
}
```

