#include <stdio.h>
#include <stdint.h>
#include <time.h>
#include <stdbool.h>

typedef struct {
    uint64_t id;
    double value;
    time_t timestamp;
} Transaction;

struct SlidingWindow {
    size_t size;
    size_t head;
    size_t tail;
    Transaction transactions[3];
};

double weightFactor(const struct SlidingWindow *window) {
    double recency = (time(NULL) - window->transactions[window->head].timestamp);
    double frequency = (double)window->size / recency;
    return 1.0 / (recency + frequency);
}

void updateMetrics(double *totalValue, double *avgValue, double *cumulativeWeightedSum, const Transaction *transaction, const double weightFactor) {
    *totalValue += transaction->value;
    *avgValue = (*totalValue / (1.0 + *totalNumberOfTransactions++));
    *cumulativeWeightedSum += transaction->value * weightFactor;
}

Transaction findMaxWeighted(const double *cumulativeWeightedSum, size_t size) {
    Transaction maxTransaction = { .id = 0, .value = 0.0 };
    double maxWeighted = 0.0;
    for (size_t i = 1; i < size; ++i) {
        if (cumulativeWeightedSum[i] > maxWeighted) {
            maxTransaction = transactions[i];
            maxWeighted = cumulativeWeightedSum[i];
        }
    }
    return maxTransaction;
}

void processTransactions(const double *input, size_t inputSize, double *totalValue, double *avgValue, double *cumulativeWeightedSum, Transaction *maxTransactionId) {
    struct SlidingWindow slidingWindow;
    slidingWindow.size = 3;
    slidingWindow.head = 0;
    slidingWindow.tail = 0;
    size_t totalNumberOfTransactions = 0;

    for (size_t i = 0; i < inputSize; ++i) {
        time_t now = time(NULL);
        if ((now - input[i]) > 5) continue;

        Transaction transaction = { .id = input[i + 1], .value = input[i + 2], .timestamp = now };

        if (slidingWindow.head == slidingWindow.size) {
            slidingWindow.head = (slidingWindow.head + 1) % slidingWindow.size;
            updateMetrics(totalValue, avgValue, cumulativeWeightedSum, &transaction, weightFactor(&slidingWindow));
        }

        memcpy(slidingWindow.transactions + slidingWindow.tail, &transaction, sizeof(Transaction));
        slidingWindow.tail = (slidingWindow.tail + 1) % slidingWindow.size;
    }

    *maxTransactionId = findMaxWeighted(cumulativeWeightedSum, totalNumberOfTransactions);
}
