// Function to select attack based on energy, cooldown, and skill points
void SelectAttack(int energy, int maxEnergy, int cooldown, bool onCooldown, int skillPoints) {
    std::chrono::steady_clock::time_point currentTime = std::chrono::steady_clock::now();
    auto cooldownExpiration = currentTime + std::chrono::seconds(9);

    if (onCooldown && cooldownExpiration > currentTime) {
        // Still on cooldown, do nothing
        return;
    }

    int attackPointsCost = rand() % 3 + 1; // Cost of each attack

    if (energy - attackPointsCost <= 0 || skillPoints < attackPointsCost) {
        // Insufficient energy or skill points, do nothing
        return;
    }

    energy -= attackPointsCost;
    --skillPoints;

    std::cout << "Attack selected: " << (rand() % 2 + 1) << "\n";
    std::cout << "Updated energy level: " << energy << "\n";
}

int main() {
