    bool onCooldown = false; // Indicates if the character is currently on cooldown
    int maxEnergy = 150; // Character's maximum energy capacity
    int skillPoints = 5; // Number of skill points available for attack usage

    while (true) {
        UpdateSkillPoints(skillPoints);
        SelectAttack(energy, maxEnergy, onCooldown, onCooldown, skillPoints);

        std::this_thread::sleep_for(std::chrono::milliseconds(rand() % 200 + 100)); // Simulate network latency and other tasks
    }

    return 0;
}
