    while (current != NULL) {
        if (strcmp(current->path, path) == 0) {
            pthread_mutex_lock(&resource_bundle_cache_mutex);
            current->last_accessed = get_current_time();
            pthread_mutex_unlock(&resource_bundle_cache_mutex);
            return current;
        }
        current = current->next;
    }
    return NULL;
}

ResourceBundle *load_resource_bundle(const char *path) {
    ResourceBundle *cached_bundle = find_resource_bundle_in_cache(path);
    if (cached_bundle != NULL && get_current_time() - cached_bundle->last_accessed < cache_timeout_sec) {
        return cached_bundle;
    }

    FILE *file = fopen(path, "r");
    if (!file) {
        perror("Error opening file");
        return NULL;
    }

    json_object *obj = json_tokener_parse(fileno(file));
    fclose(file);

    if (json_object_get_type(obj) != json_object_t::json_object_t::jso_t_array) {
        fprintf(stderr, "Error: Expected JSON array\n");
        json_object_put(obj);
        return NULL;
    }

    ResourceBundle *new_bundle = (ResourceBundle *)malloc(sizeof(ResourceBundle));
    new_bundle->path = strdup(path);
    new_bundle->obj = obj;
    new_bundle->next = resource_bundle_cache;
    new_bundle->last_accessed = get_current_time();
    resource_bundle_cache = new_bundle;

    return new_bundle;
}

int count_items_in_resource_bundle(json_object *obj) {
    int count = 0;
    json_object_iterator it, end;
    it = json_objects_iter_begin(obj);
    end = json_objects_iter_end(obj);

    while (!json_objects_iter_equal(&it, &end)) {
        count++;
        it = json_objects_iter_next(&it);
    }

    return count;
}

int load_and_count_resource_bundle(const char *path) {
    ResourceBundle *bundle = load_resource_bundle(path);
    if (!bundle) {
        return -1;
    }

    int count = count_items_in_resource_bundle(bundle->obj);
    json_object_put(bundle->obj); // Free the memory used by the JSON object
    free(bundle); // Free the memory used by the ResourceBundle struct

    return count;
}
```

You will need to link your program with the `json-c` library and include the appropriate header file (`#include <json-c/json.h>`) for parsing the JSON data. Also, make sure to define a mechanism for clearing the cache after the specified timeout period in your main function or another part of your code that manages the program's lifecycle.']

