#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <limits.h>
#include <unistd.h>
#include <sys/mman.h>
#define BUFFER_SIZE 1024 * 64 // 64KB chunk size for efficient processing of large files
#define MAX_FIELDS 50 // Predefined limit for memory usage

void appendLog(const char *message) {
    FILE *logFile = fopen("error.log", "a");
    if (logFile != NULL) {
        fprintf(logFile, "%s\n", message);
        fclose(logFile);
    }
}

int isNumber(const char *str) {
    int i;
    for (i = 0; str[i] != '\0'; ++i) {
        if (!isdigit(str[i])) return 0;
    }
    return 1;
}

void processLine(char **line, char **result) {
    int fieldsCount = 0;
    int index;
    double sum = 0.0;
    for (index = 0; line[index] != NULL; ++index) {
        if (isNumber(line[index])) {
            sum += atof(line[index]);
            fieldsCount++;
            if (fieldsCount > 3) break;
        }
    }
    if (fieldsCount < 3) line[fieldsCount] = ""; // Append empty string for lines with fewer than three numerical fields.
    else {
        double average = sum / 3.0;
        *result = malloc(sizeof(char) * (strlen(line[index]) + 15)); // +15 for the decimal and spaces
        sprintf(*result, "%f ", average);
        strcat(*result, line[index]);
    }
}

int main(int argc, char **argv) {
    if (argc < 2) {
        appendLog("Usage: ./average <input_file>");
        return 1;
    }

    FILE *file = fopen(argv[1], "r");
    if (!file) {
        appendLog("Error opening file.");
        return 1;
    }

    char buffer[BUFFER_SIZE];
    size_t bytesRead, fieldsCount = 0;
    char **lineArray = NULL;
    char *currentLine = NULL;
    double memoryUsage = 0.0;

    while ((bytesRead = fread(buffer, sizeof(char), BUFFER_SIZE, file)) > 0) {
        if (memoryUsage + bytesRead >= MAX_FIELDS * sizeof(char *)) {
            reallocarray(lineArray, fieldsCount, fieldsCount + BUFFER_SIZE / sizeof(char *));
            memoryUsage += BUFFER_SIZE / sizeof(char *) * (sizeof(char *) - sizeof(lineArray[0]));
        }

        char *token = strtok(buffer, ",");
        while (token != NULL) {
            lineArray[fieldsCount++] = token;
            memoryUsage += sizeof(char *) + strlen(token) + 1; // +1 for the null character
            token = strtok(NULL, ",");
        }

        char *result = NULL;
        if (fieldsCount > 0) processLine(lineArray, &result);
        free(currentLine);
        currentLine = result;
    }

    fclose(file);

    for (int index = 0; lineArray[index] != NULL; ++index) {
        printf("%s", lineArray[index]);
        free(lineArray[index]);
    }
    free(lineArray);
    return 0;
}
```
This program reads a text file line by line, processes each line in a comma-separated format and calculates the average of the last three numerical fields. It dynamically allocates memory for each line and ensures that memory is freed after use. The program handles error scenarios like file I/O operations, large files by processing them in chunks and maintains memory usage within predefined limits to prevent system resource exhaustion. Processing errors are logged to a separate log file.']

