char *modify_filename(const char *input_filename) {
    size_t len = strlen(input_filename);
    if (len > 254)
        return NULL; // Too long to process

    size_t unique_id_len = 1; // Minimum length for unique identifier is 1 digit
    size_t i;
    for (i = len - 1; i > 0 && isdigit(input_filename[i]); --i)
        ++unique_id_len; // Calculate the number of digits in the filename

    char unique_id[unique_id_len + 1]; // Allocate memory for the unique identifier
    int has_extension = 0;
    for (i = len - 1; i >= 0; --i) {
        if (input_filename[i] == '.') {
            has_extension = 1;
            break;
        }
        if (!isalnum(input_filename[i]) && input_filename[i] != '_') // Allow underscores in the filename
            break;
        unique_id[unique_id_len - 1] = tolower(input_filename[i]); // Ensure lowercase letters for the identifier
    }

    if (!has_extension) {
        switch (input_filename[i]) {
            case '.':
                return NULL; // Invalid filename format
            case '\0':
                sprintf(unique_id, "%lu", (unsigned long)time(NULL)); // Generate a unique identifier based on the current time
                break;
            default:
                strcpy(unique_id, "_"); // Add an underscore as the identifier if no extension or invalid character is found
        }
    } else {
        strncpy(unique_id, input_filename + i + 1, unique_id_len); // Copy the existing extension and the characters after it to the unique identifier
        unique_id[unique_id_len] = '\0'; // Null terminate the unique identifier
    }

    static char output_filename[256]; // Allocate memory for the modified filename
    if (strlen(input_filename) + strlen(unique_id) + 4 > sizeof(output_filename)) // Check total length before concatenation to avoid buffer overflows
        return NULL;

    sprintf(output_filename, "%s%s.txt", input_filename, unique_id); // Append the unique identifier and a default file type extension (.txt)

    for (i = 0; i < strlen(output_filename); ++i) {
        if (output_filename[i] == '.') {
            if (strcmp(&output_filename[i + 1], ".csv") == 0 || strcmp(&output_filename[i + 1], ".log") == 0)
                continue; // Accept .txt, .csv, or .log as the file type extension
            sprintf(&output_filename[i + 1], "%s", ".txt"); // Overwrite any invalid extensions with a default one (.txt)
        }
    }

    return output_filename; // Return the modified filename as a char* pointer
}
