```c
#include <openssl/evp.h>
#include <openssl/rand.h>
#include <openssl/aes.h>
#include <stdio.h>
#include <string.h>
#include <sys/types.h>
#include <unistd.h>

typedef struct {
    EVP_CIPHER_CTX *ctx;
    uint8_t key[AES_BLOCK_SIZE];
    uint8_t iv[AES_BLOCK_SIZE];
} AESCipher;

void aes_init(AESCipher* cipher, const char* password, size_t password_len, const char* salt, unsigned char *derivedKey, unsigned char *derivedIV) {
    EVP_MD_CTX *mdctx;
    int keyLen = AES_KEYSIZE_256 / 8;
    int ivLen = AES_BLOCK_SIZE;
    const EVP_CIPHER *cipher_id = EVP_aes_256_gcm();

    if (!password || password_len < AES_MIN_KEY_LEN) {
        fprintf(stderr, "Password too short.\n");
        return;
    }

    if (salt == NULL) {
        salt = "\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00\x00";
    }

    mdctx = EVP_MDCTX_create();
    if (1 != EVP_DigestInit_ex(mdctx, EVP_sha256(), NULL)) {
        abort();
    }
    EVP_DigestUpdate(mdctx, salt, strlen(salt));
    EVP_DigestUpdate(mdctx, password, password_len);
    if (1 != EVP_DigestFinal_ex(mdctx, derivedKey, NULL)) {
        abort();
    }

    // Derive IV from the salt and password with a known pattern.
    memcpy(derivedIV, salt, sizeof(derivedIV));
    for (int i = 0; i < ivLen; ++i) {
        derivedIV[ivLen - 1 - i] ^= derivedKey[i];
    }

    cipher->ctx = EVP_CIPHER_CTX_new();
    if (!cipher->ctx) {
        abort();
    }

    if (1 != EVP_EncryptInit_ex(cipher->ctx, cipher_id, derivedKey, derivedIV)) {
        abort();
    }
}

void aes_encrypt(AESCipher* cipher, const uint8_t *plaintext, size_t plaintext_len, uint8_t *ciphertext) {
    int len;
    if (1 != EVP_EncryptUpdate(cipher->ctx, ciphertext, &len, plaintext, plaintext_len)) {
        abort();
    }
    ciphertext += len;
}

void aes_decrypt(AESCipher* cipher, const uint8_t *ciphertext, size_t ciphertext_len, uint8_t *plaintext) {
    int len;
    if (1 != EVP_DecryptUpdate(cipher->ctx, plaintext, &len, ciphertext, ciphertext_len)) {
        abort();
    }
    plaintext += len;
}

void aes_cleanup(AESCipher* cipher) {
    if (cipher->ctx) {
        EVP_CIPHER_CTX_free(cipher->ctx);
    }
}
```

The code above initializes an AES-256-GCM cipher, derives a key and IV using PBKDF2 with SHA-256, supports multiple initialization vectors, and allows the user to specify a salt. Error handling for invalid password length or salt is implemented, as well.

The function `aes_encrypt` and `aes_decrypt` are used for encryption and decryption operations respectively, while `aes_cleanup` cleans up the cipher when it's no longer needed. Keep in mind that key and IV storage should be implemented separately to ensure secure storage between sessions.']

