    private void handleProcessOutputAndError(Process process) throws IOException {
        BufferedReader outputReader = new BufferedReader(new InputStreamReader(process.getInputStream()));
        BufferedReader errorReader = new BufferedReader(new InputStreamReader(process.getErrorStream()));

        Thread outputThread = new Thread(() -> {
            try {
                String line;
                while ((line = outputReader.readLine()) != null) {
                    log("Command Output: " + line);
                }
            } catch (IOException e) {
                log("Error reading command output: " + e.getMessage());
            }
        });

        Thread errorThread = new Thread(() -> {
            try {
                String line;
                while ((line = errorReader.readLine()) != null) {
                    log("Command Error: " + line);
                }
            } catch (IOException e) {
                log("Error reading command error: " + e.getMessage());
            }
        });

        outputThread.start();
        errorThread.start();
        try {
            outputThread.join();
            errorThread.join();
        } catch (InterruptedException e) {
            log("Error joining threads: " + e.getMessage());
        }
    }

    private void log(String message) {
        try (PrintWriter writer = new PrintWriter(LOG_FILE, "UTF-8")) {
            if (shouldRotateLog()) {
                rotateLogFile();
            }
            writer.println(dateFormat.format(new Date()) + ": " + message);
        } catch (Exception e) {
            log("Failed to write log: " + e.getMessage());
        }
    }

    private boolean shouldRotateLog() {
        return new File(LOG_FILE).length() > 10485760 || dateFormat.format(new Date()).equals(dateFormat.format(new File(LOG_FILE).lastModified()));
    }

    private void rotateLogFile() throws IOException {
        String logFileName = LOG_FILE;
        String newLogFileName = "log-" + dateFormat.format(new Date()) + ".txt";
        Files.move(new File(logFileName).toPath(), new File(newLogFileName).toPath());
    }

    // Run this method every day to clean old log files
    public void cleanOldLogFiles() {
        for (File file : new File(".").listFiles()) {
            if (file.isFile() && file.getName().startsWith("log-")) {
                long lastModified = file.lastModified();
                long daysAgo = System.currentTimeMillis() - TimeUnit.DAYS.toMillis(1);
                if (lastModified < daysAgo) {
                    file.delete();
                    log("Deleted old log file: " + file.getName());
                }
            }
        }
    }
}
```

In this example, replace `https://example.com/your-remote-repository/` with the remote repository URL you want to fetch files from. Also, add your validation logic for checking if a file is corrupted inside the `isValidFile(File)` method. Additionally, you can modify the cleanOldLogFiles() method as needed to manage log files according to your requirements. Lastly, don't forget to call the cleanOldLogFiles() method daily to remove old logs.']

