#include <json-c/json.h>
#include <stdbool.h>
#include <string.h>
#include <stdio.h>

bool validate_oauth2_token(const char *token_str) {
    json_object *jo = json_tokener_parse(token_str);
    if (!jo) {
        return false;
    }

    json_object *access_token_obj, *expires_in_obj, *token_type_obj, *refresh_token_obj = json_object_get_ex(jo, "refresh_token");
    bool is_valid = true;

    access_token_obj = json_object_get_ex(jo, "access_token");
    if (!json_object_get_string(access_token_obj)) {
        is_valid = false;
    } else if (strlen(json_object_get_string(access_token_obj)) > 512) {
        is_valid = false;
    }

    expires_in_obj = json_object_get_ex(jo, "expires_in");
    if (!json_object_get_int64(expires_in_obj)) {
        is_valid = false;
    } else if (json_object_get_int64(expires_in_obj) > 86400 || json_object_get_int64(expires_in_obj) < 0) {
        is_valid = false;
    }

    token_type_obj = json_object_get_ex(jo, "token_type");
    if (!json_object_get_string(token_type_obj)) {
        is_valid = false;
    } else if (strcmp(json_object_get_string(token_type_obj), "Bearer") != 0) {
        is_valid = false;
    }

    if (refresh_token_obj) {
        const char *refresh_token = json_object_get_string(refresh_token_obj);
        if (!refresh_token) {
            is_valid = false;
        } else if (strlen(refresh_token) > 1024) {
            is_valid = false;
        }
    }

    json_object_put(jo);
    return is_valid;
}
