namespace YourNamespace
{
    public static class EncryptionHelper
    {
        private static readonly ILog Log = LogManager.GetLogger(typeof(EncryptionHelper));
        private const int MaxLogEntriesPerSecond = 1;
        private const int MillisecondsPerSecond = 1000;

        private static readonly SemaphoreSlim ThrottleSemaphore = new SemaphoreSlim(MaxLogEntriesPerSecond, MaxLogEntriesPerSecond);

        public static async Task<string> DecryptAndLogMessage(string base64EncodedMessage, byte[] tripleDesKey, byte[] iv)
        {
            if (string.IsNullOrEmpty(base64EncodedMessage))
                return string.Empty;

            var decryptedData = Convert.FromBase64String(base64EncodedMessage);

            using (var tripleDes = TripleDESCreate(tripleDesKey, iv))
            {
                var plainTextBytes = DecryptTripleDES(decryptedData, tripleDes);

                var decryptedMessage = Encoding.UTF8.GetString(plainTextBytes);

                await LogMessageAsync(decryptedMessage, LogLevel.Info);

                return decryptedMessage;
            }
        }

        private static TripleDESCryptoServiceProvider TripleDESCreate(byte[] key, byte[] iv)
        {
            var tripleDes = new TripleDESCryptoServiceProvider();
            tripleDes.Key = key;
            tripleDes.IV = iv;
            return tripleDes;
        }

        private static byte[] DecryptTripleDES(byte[] cipherText, TripleDESCryptoServiceProvider tripleDes)
        {
            var encryptedData = tripleDes.CreateDecryptor().TransformFinalBlock(cipherText, 0, cipherText.Length);
            return encryptedData;
        }

        private static async Task LogMessageAsync(string message, LogLevel logLevel)
        {
            await ThrottleSemaphore.WaitAsync();

            try
            {
                switch (logLevel)
                {
                    case LogLevel.Debug:
                        Log.Debug(message);
                        break;
                    case LogLevel.Info:
                        Log.Info(message);
                        break;
                    case LogLevel.Warning:
                        Log.Warn(message);
                        break;
                    case LogLevel.Error:
                        Log.Error(message);
                        break;
                }
            }
            finally
            {
                ThrottleSemaphore.Release();
            }
        }

        private enum LogLevel
        {
            Debug,
            Info,
            Warning,
            Error
        }
    }
}
