using System;
using System.Security.Cryptography;
using System.Linq;

public byte[] DecryptAES_CBC(byte[] ciphertext, byte[] key, byte[] iv, PaddingMode paddingScheme = PaddingMode.PKCS7)
{
    if (key.Length < 128 || key.Length > 256)
        throw new ArgumentException("Key must be either 128-bit or 256-bit.");

    if (iv.Length != 16) // Assuming IV is a 128-bit block for AES_CBC
        throw new ArgumentException("IV must be 128-bits long.");

    using (var aes = new Aes(key, iv, CryptoConfig.AllowOnlyEncryptionPadding))
    {
        aes.Padding = paddingScheme;
        var decryptor = aes.CreateDecryptor();

        if (paddingScheme == PaddingMode.PKCS5) // Handle PKCS5 padding if requested
            ciphertext = ciphertext.Concat(Enumerable.Repeat((byte)ciphertext.Last(), aes.BlockSize / 8 - ciphertext.Length % azer.BlockSize / 8 + 1)).ToArray();

        var plaintext = decryptor.TransformFinalBlock(ciphertext, 0, ciphertext.Length);

        if (plaintext.Length == 0 && ciphertext.Length > 0) // Handle edge case for zero-length plaintext with non-zero length ciphertext
            throw new CryptographicException("Invalid padding.");

        return plaintext;
    }
}
