const axios = require('axios');
const fs = require('fs');
const FormData = require('form-data');
const path = require('path');
const { v4: uuidv4 } = require('uuid');
const log = require('./customLoggingFramework'); // Import your custom logging framework here

function validateUrlFormat(url) {
  const regex = /^(https?:\/\/)?([da-z.-]+)\.([a-z]{2,})([-/.][a-z0-9]*)*([/?].*)?$/;
  return regex.test(url);
}

function isValidFileType(ext) {
  const validTypes = ['.pdf', '.docx', '.xlsx', '.jpg', '.png'];
  return validTypes.includes(ext);
}

async function uploadFile(filePath, storageService, bucketName, region) {
  let fileUrl;
  try {
    const formData = new FormData();
    formData.append('file', fs.createReadStream(filePath));

    for (let attempt = 1; attempt <= 3; attempt++) {
      log.info(`Attempt ${attempt}: Uploading file...`);
      try {
        const response = await axios.post(`https://${storageService}.region.amazonaws.com/${bucketName}.${region}.amazonaws.com`, formData, {
          maxRedirects: 0,
          maxContentLength: Infinity,
          headers: {
            'key': path.basename(filePath),
            'Content-Type': fs.mimetypeSync(filePath),
            'x-amz-acl': 'public-read'
          }
        });

        fileUrl = response.headers.location;
        log.success('File uploaded successfully!');
        break;
      } catch (error) {
        if (attempt < 3) {
          log.warn(`Upload attempt ${attempt} failed. Retrying...`);
        } else {
          throw new Error(`Failed to upload file after 3 attempts. Error: ${error}`);
        }
      }
    }
  } catch (error) {
    throw new Error(`Error during file upload: ${error}`);
  }

  return fileUrl;
}

async function processFile(inputUrl, fileType) {
  if (!validateUrlFormat(inputUrl)) {
    throw new Error('Invalid URL format');
  }

  const filePath = path.resolve(require('path').parse(inputUrl).dir, path.basename(inputUrl));
  const fileStats = fs.statSync(filePath);

  if (fileStats.size > 52428800) { // 50MB in bytes
    throw new Error('File size exceeds 50MB');
  }

  if (!isValidFileType(path.extname(inputUrl))) {
    throw new Error(`Invalid file type: ${path.extname(inputUrl)}`);
  }

  try {
    const fileName = `${uuidv4()}${path.extname(inputUrl)}`;
    const uploadedFileUrl = await uploadFile(filePath, 'S3', 'my-bucket', 'us-west-2'); // Replace with your storage service and bucket name
    return uploadedFileUrl;
  } catch (error) {
    throw new Error(`Error during file processing: ${error}`);
  }
}
```

