use std::env;
use std::fs::create_dir_all;
use std::path::PathBuf;
use std::sync::{Mutex, Once};
use log::*;

const DEFAULT_DATA_STORAGE: &str = "data_storage";
const VALID_CHARS: &str = r"[a-zA-Z0-9.-]";

static DATA_STORAGE_PATH: Mutex<Option<PathBuf>> = Mutex::new(None);
static INITIALIZE: Once = Once::new();

fn init_data_storage(custom_path: Option<String>) {
    let custom_path = match custom_path {
        Some(ref path) if path.chars().all(|c| VALID_CHARS.matches(c)) => Some(PathBuf::from(path)),
        _ => None,
    };
    let data_storage_path = custom_path.or_else(|| DEFAULT_DATA_STORE_PATH.clone());
    let mut abs_path = data_storage_path;

    if let Some(ref path) = data_storage_path {
        match create_dir_all(path) {
            Ok(_) => {
                info!("Created directory: {}", path.display());
                set_data_storage_path(path);
            }
            Err(e) => error!("Failed to create directory {}: {}", path.display(), e),
        }
    }
}

fn set_data_storage_path(path: PathBuf) {
    let mut guard = DATA_STORAGE_PATH.lock().unwrap();
    if guard.is_none() {
        *guard = Some(path);
        env::set_var("DATA_STORAGE_PATH", path.to_str().unwrap());
    } else if !guard.as_ref().unwrap().eq(&path) {
        warn!("Tried to set DATA_STORAGE_PATH to an existing value");
    }
}

fn get_data_storage_path() -> Option<String> {
    let data_storage_path = DATA_STORAGE_PATH.lock().unwrap().clone();
    if data_storage_path.is_some() {
        Some(data_storage_path.as_ref().unwrap().to_str().unwrap().to_owned())
    } else {
        None
    }
}

fn teardown() {
    INITIALIZE.call_once(|| {
        let _ = env::remove_var("DATA_STORAGE_PATH");
    });
}

#[thread_local]
static THREAD_LOCAL: thread_local::ThreadLocal<Option<String>> =
    thread_local! { static LOCAL: Option<String> = None };

fn with_data_storage_path<F, T>(custom_path: Option<String>, f: F) -> T
where
    F: FnOnce() -> T,
{
    let data_storage_path = custom_path.or_else(|| THREAD_LOCAL.with(|local| local.get().clone()));
    match data_storage_path {
        Some(ref path) => {
            THREAD_LOCAL.with(|local| *local = Some(path.clone()));
            f()
        }
        None => {
            init_data_storage(custom_path);
            let data_storage_path = THREAD_LOCAL.with(|local| local.get().clone());
            if data_storage_path.is_none() {
                panic!("Failed to set up DATA_STORAGE_PATH");
            } else {
                THREAD_LOCAL.with(|local| *local = Some(data_storage_path.unwrap()));
                f()
            }
        }
    }
}

fn main() {
    env_logger::init();
    teardown();

    let custom_data_storage = Some("my_custom_data".to_owned());
    let data_storage_path = with_data_storage_path(custom_data_storage, || get_data_storage_path());

    // Continue to use `data_storage_path` as needed...
}
```
This code defines an initialization function for a directory called `init_data_storage()`, which can be optionally provided with a custom path. It creates the directory if it does not exist, and sets an environment variable `DATA_STORAGE_PATH` to the absolute path of the created or existing directory. The function is thread-safe due to the use of `Mutex`.

The code also provides a function to get the current value of `DATA_STORAGE_PATH`, and ensures that it is properly unset when the program exits using a `thread_local` variable and `call_once()`.

Finally, the `with_data_storage_path()` function allows you to execute blocks of code with the current data storage path set.']

