import json
from typing import Any, Callable, Dict, Type

class JSONParser:
    _registry = {}

    def to_json(self) -> str:
        return json.dumps(self.__dict__, default=lambda o: str(o))

    @staticmethod
    def from_json(json_str: str, cls: Type['JSONParser'] = JSONParser) -> 'JSONParser':
        data = json.loads(json_str)
        instance = cls()
        for key, value in data.items():
            setattr(instance, key, value)
        return instance

    def register_factory(self, id: str, factory: Callable[[Dict[str, Any]], 'JSONParser']) -> None:
        self._registry[id] = factory

    def create_instance_from_id(self, id: str) -> 'JSONParser':
        factory = self._registry.get(id)
        if not factory:
            raise ValueError(f"No registered factory function for ID '{id}'.")
        return factory({k: v for k, v in self.__dict__.items() if k != '_json_type'})

    @property
    def _json_type(self) -> str:
        return self.__class__.__name__

def custom_factory(json_data: Dict[str, Any]) -> 'CustomClass':
    # Define your custom class and deserialization logic here.
    pass

class CustomClass(JSONParser):
    pass

# Register the custom factory function for CustomClass.
CustomClass.register_factory('custom', custom_factory)
