#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <limits.h>

#define MAX_KEYS 1000000
#define MAX_OFFSETS 1000000
#define MAX_RECORDS 10000000
#define MIN_VALUE 0
#define MAX_VALUE INT_MAX

typedef struct {
    int key;
    int offset;
} RecordKeyOffset;

typedef struct {
    int value;
} Record;

void init_data(int *offsets, int *keys, Record **records, int size, int *ext_offsets, int *ext_keys) {
    if (!(offsets = realloc(offsets, size * sizeof(int)))) {
        fprintf(stderr, "Error: Failed to allocate memory for offsets.\n");
        exit(EXIT_FAILURE);
    }

    if (!(keys = realloc(keys, size * sizeof(int)))) {
        fprintf(stderr, "Error: Failed to allocate memory for keys.\n");
        exit(EXIT_FAILURE);
    }

    if (!(records = malloc((size + 1) * sizeof(Record*)))) {
        fprintf(stderr, "Error: Failed to allocate memory for records.\n");
        exit(EXIT_FAILURE);
    }

    int used_offsets = 0;
    int used_keys = 0;

    for (int i = 0; i < size; ++i) {
        if (ext_offsets[i] > INT_MAX - used_offsets) {
            fprintf(stderr, "Error: Offset value exceeds the maximum integer limit.\n");
            exit(EXIT_FAILURE);
        }

        if (ext_keys[i] > INT_MAX - used_keys) {
            fprintf(stderr, "Error: Key value exceeds the maximum integer limit.\n");
            exit(EXIT_FAILURE);
        }

        offsets[used_offsets++] = ext_offsets[i];
        keys[used_keys++] = ext_keys[i];
    }

    if (used_offsets > MAX_OFFSETS) {
        fprintf(stderr, "Error: Exceeded the maximum limit for offsets.\n");
        exit(EXIT_FAILURE);
    }

    if (used_keys > MAX_KEYS) {
        fprintf(stderr, "Error: Exceeded the maximum limit for keys.\n");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL));

    Record **temp = records;
    for (int i = 0; i < size + 1; ++i) {
        temp[i] = malloc(sizeof(Record));
        if (!temp[i]) {
            fprintf(stderr, "Error: Failed to allocate memory for a record.\n");
            exit(EXIT_FAILURE);
        }
        *temp[i] = (Record){};
        temp = &temp[i + 1];
    }

    for (int i = 0; i < size; ++i) {
        records[offsets[i]]->value = rand() % (MAX_VALUE - MIN_VALUE + 1) + MIN_VALUE;
    }
}
```

