#include <pthread.h>
#include <time.h>

typedef struct Record {
    int value;
    long offset;
} Record;

struct HashTableNode {
    int key;
    struct Record* record;
    struct HashTableNode* next;
};

pthread_mutex_t hash_table_mutex = PTHREAD_MUTEX_INITIALIZER;

// Custom hash function for the hash table
unsigned long hash(int key) {
    unsigned long hash = 5381;
    int c;

    while (key != 0) {
        c = (key & 0x7ffc0001) >> 1;
        key = key * 0x800fc6b4 + (key << 21);
        hash = hash * 5381 + c;
    }

    return hash % INT_MAX;
}

// Custom hash table implementation with thread-safety and concurrent insertions/lookups
struct HashTable {
    int size;
    struct HashTableNode** nodes;
};

void initHashTable(struct HashTable* table, int size) {
    table->size = size;
    table->nodes = calloc(size, sizeof(struct HashTableNode*));
}

int findNode(struct HashTable* table, int key) {
    unsigned long index = hash(key) % table->size;
    struct HashTableNode* current = table->nodes[index];

    pthread_mutex_lock(&hash_table_mutex);
    while (current != NULL && current->key != key) {
        current = current->next;
    }
    pthread_mutex_unlock(&hash_table_mutex);

    return current ? current->record : NULL;
}

void insertNode(struct HashTable* table, int key, struct Record* record) {
    unsigned long index = hash(key) % table->size;
    struct HashTableNode* new_node = malloc(sizeof(struct HashTableNode));
    struct HashTableNode* current = table->nodes[index];

    pthread_mutex_lock(&hash_table_mutex);
    new_node->key = key;
    new_node->record = record;
    new_node->next = current;
    table->nodes[index] = new_node;
    pthread_mutex_unlock(&hash_table_mutex);
}

int createRecords(struct HashTable* hash_table, size_t max_records) {
    if (max_records > INT_MAX / 2) {
        return -1; // Error: maximum limit exceeded
    }

    long* offsets = malloc((max_records + 1) * sizeof(long));
    int* keys = malloc(max_records * sizeof(int));
    Record* records = calloc(max_records, sizeof(Record));
    int uniqueness_tracker[INT_MAX] = {0};

    for (size_t i = 0; i < max_records; ++i) {
        int key, j;
        do {
            key = rand() % INT_MAX;
            j = uniqueness_tracker[key];
        } while (j && i - j <= 10 && findNode(hash_table, key));

        if (key >= INT_MAX) {
            break; // Error: potential loop in random value generation process
        }

        uniqueness_tracker[key] = i + 1;
        keys[i] = key;
        records[i].value = rand() % INT_MAX;
        records[i].offset = i + keys[i] * records[i].value;
    }

    free(uniqueness_tracker); // Memory cleanup for uniqueness tracking array

    return max_records;
}

void freeRecords(long* offsets, int* keys, Record* records, size_t count) {
    free(offsets);
    free(keys);
    free(records);
}
