#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <openssl/evp.h>

typedef struct {
    int integer_value;
} Record;

int validate_token(char *json_str) {
    json_object *json = json_tokener_parse(json_str, 0);
    if (!json || !json_object_get_ex(json, "access_token") ||
        !json_object_get_ex(json, "expires_in") ||
        !json_object_get_ex(json, "token_type")) {
        json_object_put(json);
        return 0;
    }

    const char *token_type = json_object_get_string(json_object_get_ex(json, "token_type"));
    if (strcmp(token_type, "Bearer") != 0) {
        json_object_put(json);
        return 0;
    }

    int expires_in = json_object_get_int(json_object_get_ex(json, "expires_in"));
    if (expires_in <= 0) {
        json_object_put(json);
        return 0;
    }

    json_object *optional = json_object_get_ex(json, "refresh_token");
    int has_refresh_token = optional ? 1 : 0;

    json_object_put(json);
    return 1 | (has_refresh_token << 1);
}

size_t dataset_size(char *json_str) {
    if (!validate_token(json_str)) return 0;

    json_object *json = json_tokener_parse(json_str, 0);
    size_t dataset_size = json_object_get_uint(json_object_get_ex(json, "dataset_size"));
    json_object_put(json);
    return dataset_size;
}

Record* create_record_array(size_t size) {
    Record *records = (Record*)calloc(size, sizeof(Record));
    if (!records) return NULL;

    for (size_t i = 0; i < size; ++i)
        records[i].integer_value = rand() % RAND_MAX;

    return records;
}

void free_record_array(Record *records, size_t size) {
    if (!records) return;

    free(records);
}

int* create_offset_key_arrays(size_t offsets_keys_size, size_t dataset_size) {
    int *offsets = (int*)calloc(offsets_keys_size, sizeof(int));
    int *keys = (int*)calloc(offsets_keys_size, sizeof(int));

    if (!offsets || !keys) {
        free(offsets);
        free(keys);
        return NULL;
    }

    for (size_t i = 0; i < offsets_keys_size; ++i) {
        offsets[i] = rand() % dataset_size;
        keys[i] = rand() % RAND_MAX;
    }

    return offsets;
}

void free_offset_key_arrays(int *offsets, int *keys) {
    if (!offsets || !keys) return;

    free(offsets);
    free(keys);
}

EVP_CIPHER* init_component(char *json_str, size_t dataset_size) {
    if (!validate_token(json_str)) return NULL;

    int offsets_keys_size = json_object_get_uint(json_object_get_ex(json_tokener_parse(json_str, 0), "offsets_keys_size"));
    size_t *pointers = (size_t*)malloc(2 * offsets_keys_size * sizeof(size_t));

    if (!pointers) return NULL;

    int *offsets = create_offset_key_arrays(offsets_keys_size, dataset_size);
    if (!offsets) {
        free(pointers);
        return NULL;
    }

    size_t data_index = 0;
    for (size_t i = 0; i < offsets_keys_size; ++i) {
        pointers[2 * i] = offsets[i];
        pointers[2 * i + 1] = data_index;
        data_index += offsets[i];
    }

    Record *records = create_record_array(dataset_size);
    if (!records) {
        free_offset_key_arrays(offsets, NULL);
        free(pointers);
        return NULL;
    }

    EVP_CIPHER_CTX *cipher_ctx = EVP_CIPHER_CTX_new();
    if (!cipher_ctx) {
        free_record_array(records, dataset_size);
        free_offset_key_arrays(offsets, NULL);
        free(pointers);
        return NULL;
    }

    const EVP_CIPHER *cipher = EVP_des_ecb();
    int rc = EVP_CIPHER_init(cipher_ctx, cipher, NULL, NULL);
    if (rc <= 0) {
        EVP_CIPHER_CTX_free(cipher_ctx);
        free_record_array(records, dataset_size);
        free_offset_key_arrays(offsets, NULL);
        free(pointers);
        return NULL;
    }

    // Implement ECB, EDE, EDE3, and CFB modes, as well as null encryption here.
    // ...

    EVP_CIPHER *cipher_out = EVP_CIPHER_CTX_get0_cipher(cipher_ctx);

    free_record_array(records, dataset_size);
    free_offset_key_arrays(offsets, NULL);
    free(pointers);

    return cipher_out;
}
