// Packet structure definition
struct packet {
    char ip[16]; // IPv4 address
    time_t timestamp;
    size_t payload_len;
};

// Global variables for peak loads and predefined limits
size_t max_packets = 100000;
size_t avg_payload_len = 512;

// Function to handle memory allocation and initialization
void process_network_packets(struct packet** packets, size_t* metadata_arr, size_t* payload_len_arr, size_t num_packets) {
    if(!packets || !metadata_arr || !payload_len_arr || num_packets > max_packets) {
        fprintf(stderr, "Error: Invalid input or exceeded maximum number of packets.\n");
        return;
    }

    *packets = malloc(num_packets * sizeof(struct packet));
    if(!*packets) {
        perror("Error: Memory allocation failure.\n");
        return;
    }

    // Allocate memory for metadata and payload length arrays
    *metadata_arr = malloc(num_packets * sizeof(size_t));
    if(!metadata_arr) {
        perror("Error: Memory allocation failure.\n");
        free(*packets);
        return;
    }

    *payload_len_arr = malloc(num_packets * sizeof(size_t));
    if(!payload_len_arr) {
        perror("Error: Memory allocation failure.\n");
        free(*metadata_arr);
        free(*packets);
        return;
    }

    // Initialize metadata and payload length arrays with data from the external network interface
    for(size_t i = 0; i < num_packets; ++i) {
        struct timeval tv;
        gettimeofday(&tv, NULL);
        (*metadata_arr)[i] = (i * avg_payload_len % max_packets) + 1; // Heuristic to estimate payload size based on average and peak limits

        // Handle packet reordering and duplicates by using the packet index as a sorting key
        snprintf((*packets)[i].ip, sizeof((*packets)[i].ip), "%d", i);
        (*packets)[i].timestamp = tv.tv_sec;
        (*payload_len_arr)[i] = (*metadata_arr)[i];
    }
}
