#include <stdarg.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_LOG_ENTRIES 1000
#define FLUSH_INTERVAL (60 * 5) // Flush logs every 5 minutes

typedef enum {
    LOG_LEVEL_ERROR,
    LOG_LEVEL_WARNING,
    LOG_LEVEL_INFO,
    LOG_LEVEL_DEBUG,
    LOG_LEVEL_COUNT
} LogLevel;

struct Logger {
    char** logs;
    size_t entries_count;
    size_t current_index;
    LogLevel min_log_level;
};

void logger_init(struct Logger* logger, LogLevel min_log_level) {
    logger->min_log_level = min_log_level;
    logger->logs = malloc(MAX_LOG_ENTRIES * sizeof(char*));
    for (size_t i = 0; i < MAX_LOG_ENTRIES; ++i) {
        logger->logs[i] = NULL;
    }
    logger->entries_count = 0;
    logger->current_index = 0;
}

void logger_flush(struct Logger* logger, void (*callback)(const char*)) {
    if (logger->entries_count == 0) return;

    time_t now = time(NULL);
    char timestamp[256];
    strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

    for (size_t i = 0; i < logger->entries_count; ++i) {
        callback(logger->logs[i]);
        free(logger->logs[i]);
        logger->logs[i] = NULL;
    }

    memmove(logger->logs, &logger->logs[logger->current_index], (MAX_LOG_ENTRIES - logger->current_index) * sizeof(char*));
    logger->current_index = 0;
    logger->entries_count -= logger->current_index;
}

void log_error(struct Logger* logger, const char* format, ...) {
    if (logger->min_log_level >= LOG_LEVEL_ERROR) {
        va_list args;
        va_start(args, format);
        char* log_entry = malloc(256 + 32); // 256 for formatted message and 32 for timestamp
        strftime(log_entry, sizeof(log_entry), "%Y-%m-%d %H:%M:%S: ", localtime(time(NULL)));
        vsnprintf(log_entry + strlen(log_entry), sizeof(log_entry) - strlen(log_entry), format, args);
        va_end(args);

        if (logger->entries_count >= MAX_LOG_ENTRIES) {
            logger_flush(logger, free);
        }

        logger->logs[logger->current_index] = log_entry;
        logger->current_index++;
    }
}
```

