['1. MD5 Hash Map with Caching (Java)

```java
import java.math.BigInteger;
import java.security.MessageDigest;
import java.util.HashMap;
import java.util.Map;

public class MD5Cache {
    private final Map<String, String> cache = new HashMap<>();

    public String computeMD5(String input) {
        if (cache.containsKey(input)) {
            return cache.get(input);
        }
        try {
            MessageDigest digest = MessageDigest.getInstance("MD5");
            byte[] hash = digest.digest(input.getBytes());
            BigInteger number = new BigInteger(1, hash);
            StringBuilder sb = new StringBuilder(number.toString(16));
            while (sb.length() < 32) {
                sb.insert(0, "0");
            }
            cache.put(input, sb.toString());
            return sb.toString();
        } catch (Exception e) {
            throw new RuntimeException("Error computing MD5", e);
        }
    }
}
```

