const { PubSub } = require('graphql-subscriptions');
const { JSONFileStorage } = require('./JSONFileStorage'); // Custom module for serialization/deserialization and persistence

class GraphDatabase {
  constructor() {
    this.storage = new JSONFileStorage('graph.json');
    this.pubSub = new PubSub();
    this.memoryGraph = new Map();
    this.throttle = new LimitFrequency(100); // Adjust the limit based on system resource availability
  }

  async insertVertex(id, data) {
    if (this.memoryGraph.has(id)) return;
    await this.throttle.wait();
    this.memoryGraph.set(id, data);
    await this.storage.save(this.memoryGraph);
    this.pubSub.publish('VERTEX_ADDED', { id, data });
  }

  async insertEdge(fromId, toId, data) {
    const fromVertex = this.memoryGraph.get(fromId);
    const toVertex = this.memoryGraph.get(toId);

    if (!fromVertex || !toVertex) return;
    await this.throttle.wait();
    fromVertex.edges.push({ toId, data });
    toVertex.incomingEdges.push({ fromId, data });
    await this.storage.save(this.memoryGraph);
    this.pubSub.publish('EDGE_ADDED', { fromId, toId, data });
  }

  async subscribeToUpdates(callback) {
    return this.pubSub.asyncIterator(['VERTEX_ADDED', 'EDGE_ADDED']);
  }
}

class LimitFrequency {
  constructor(limit) {
    this.limit = limit;
    this.timer = null;
    this.count = 0;
  }

  wait() {
    return new Promise((resolve) => {
      this.count++;
      if (this.count > this.limit) {
        if (!this.timer) {
          this.timer = setTimeout(() => {
            this.count = 1;
            this.timer = null;
            resolve();
          }, 1000);
        }
      } else {
        resolve();
      }
    });
  }
}
```

