public class JsonDataProcessor {
    private static final ObjectMapper objectMapper = new ObjectMapper();
    private static final ValidatorFactory validatorFactory = Validation.buildDefaultValidatorFactory();
    private static final Validator validator = validatorFactory.getValidator();
    private static LoadingCache<String, MyObjectModel> jsonDataCache = CacheBuilder.newBuilder()
            .expireAfterAccess(Duration.ofMinutes(10))
            .maximumSize(1000)
            .build((key) -> fetchJsonDataAndValidate(key));

    public static MyObjectModel getJsonData(String apiEndpoint) throws IOException, ExecutionException {
        return jsonDataCache.get(apiEndpoint);
    }

    private static MyObjectModel fetchJsonDataAndValidate(String apiEndpoint) throws IOException {
        URL url = new URL(apiEndpoint);
        MyObjectModel jsonData = objectMapper.readValue(url, MyObjectModel.class);
        validator.validate(jsonData); // Validate the structure and data types
        return jsonData;
    }
}
