struct Attack { int energyCost; int cooldown; };
struct SkillPoints { int current; int max; };
struct MoSTState {
    int energyLevel;
    time_t lastAttack;
    Attack* basicAttack;
    Attack* specialAttack;
    SkillPoints skillPoints;

    friend class boost::serialization::access;
    template<typename Archive> void serialize(Archive & ar, const unsigned int version) {
        ar & energyLevel & lastAttack & basicAttack & specialAttack & skillPoints;
    }
};

std::unique_ptr<MoSTState> loadStateFromFile(const std::string& filename) {
    std::ifstream ifs(filename, std::ios::binary);
    if (!ifs.is_open()) throw std::runtime_error("Failed to open file");
    MoSTState state;
    try {
        boost::archive::binary_iarchives<std::ifstream> ia(ifs, boost::serialization::load_nvm);
        ia >> state;
        return std::make_unique<MoSTState>(state);
    } catch (const std::exception& e) {
        ifs.close();
        throw std::runtime_error("Failed to deserialize state from file");
    }
}

void attackSelection(MoSTState& state) {
    time_t now = time(nullptr);
    if (now - state.lastAttack < 9) return; // cooldown period not over yet

    SkillPoints skillPoints = loadSkillPoints(); // replace this with actual API call

    int energyCostThreshold = state.energyLevel * 0.8; // set a threshold based on current energy level

    if (skillPoints.current >= energyCostThreshold && state.basicAttack->cooldown > now - state.lastAttack) {
        state.energyLevel -= state.basicAttack->energyCost;
        state.lastAttack = now;
        std::cout << "Selected attack: 1 (Basic)\nUpdated energy level: " << state.energyLevel << "\n";
    } else if (skillPoints.current >= state.specialAttack->energyCost && state.specialAttack->cooldown > now - state.lastAttack) {
        state.energyLevel -= state.specialAttack->energyCost;
        state.lastAttack = now;
        std::cout << "Selected attack: 2 (Special)\nUpdated energy level: " << state.energyLevel << "\n";
    } else {
        std::cout << "Cannot perform an attack due to low energy or cooldown.\n";
    }
}
