typedef struct Transaction {
    double amount;
    char date[20];
} Transaction;

Transaction* create_transaction() {
    Transaction *transaction = malloc(sizeof(Transaction));
    if (!transaction) {
        perror("malloc failed");
        exit(EXIT_FAILURE);
    }
    transaction->amount = 0.0;
    memset(transaction->date, '\0', sizeof(transaction->date));
    return transaction;
}

void read_csv(const char *filename, size_t *num_transactions) {
    FILE *file = fopen(filename, "r");
    if (!file) {
        perror("fopen failed");
        exit(EXIT_FAILURE);
    }

    size_t row_count = 0;
    Transaction **transactions = NULL;

    char line[4096];
    while (fgets(line, sizeof(line), file)) {
        if (row_count >= *num_transactions) {
            transactions = realloc(transactions, (*num_transactions)*2);
            if (!transactions) {
                perror("realloc failed");
                exit(EXIT_FAILURE);
            }
        }
        transactions[row_count] = create_transaction();
        sscanf(line, "%*[^,],%lf,%[^\n]", &(transactions[row_count]->amount), transactions[row_count]->date);
        ++row_count;
    }

    fclose(file);
    *num_transactions = row_count;
}

bool is_negative(double value) {
    return value < 0.0;
}

void validate_data(size_t num_transactions, Transaction **transactions) {
    size_t i;
    for (i = 0; i < num_transactions; ++i) {
        if (is_negative(transactions[i]->amount)) {
            printf("Warning: Negative transaction found\n");
        }
    }
}

double calculate_total(size_t num_transactions, Transaction **transactions) {
    double total = 0.0;
    size_t i;
    for (i = 0; i < num_transactions; ++i) {
        total += transactions[i]->amount;
    }
    return total;
}

void print_average(double total, size_t num_transactions) {
    printf("Average transaction value: %.2f\n", total / num_transactions);
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        fprintf(stderr, "Usage: %s <csv-file>\n", argv[0]);
        exit(EXIT_FAILURE);
    }

    size_t num_transactions = 0;
    Transaction **transactions = NULL;

    read_csv(argv[1], &num_transactions);

    validate_data(num_transactions, transactions);

    double total = calculate_total(num_transactions, transactions);
    const double threshold = 10000000.0;
    if (total > threshold) {
        printf("Error: Total transaction amount exceeds the threshold of $%.2f\n", threshold);
        exit(EXIT_FAILURE);
    }

    print_average(total, num_transactions);

    size_t i;
    for (i = 0; i < num_transactions; ++i) {
        free(transactions[i]);
    }
    free(transactions);

    return EXIT_SUCCESS;
}
```

