    size_t capacity;
    size_t used;
} RecordArray;

void mem_init(RecordArray* array, size_t capacity) {
    array->capacity = capacity;
    array->used = 0;
    array->data = malloc(capacity * sizeof(int));
}

void mem_resize(RecordArray* array, size_t new_capacity) {
    int* temp = realloc(array->data, new_capacity * sizeof(int));
    if (!temp) return;
    array->data = temp;
    array->capacity = new_capacity;
}

void mem_free(RecordArray* array) {
    free(array->data);
    array->data = NULL;
    array->capacity = 0;
    array->used = 0;
}

// Hybrid random number generator using xorshift128+ and pcg32
void randomize_seed() {
    uint64_t seed[2] = {time(NULL), (unsigned) rand() };
    pcg32_init_from_array(seed, sizeof(seed));
}

int random_in_range(int min, int max) {
    static pthread_once_t once_control = PTHREAD_ONCE_INIT;
    static struct pcg32 rng;

    pthread_once(&once_control, pcg32_init);
    pcg32_seed_seq(pcg32_get_state(&rng), (unsigned long) time(NULL));
    int64_t value = pcg32_boundedrand(&rng, min - 1, max);
    return value + min;
}
