#include <json/json.h>

Json::Value parse_token(const char* json) {
    Json::CharReaderBuilder builder;
    Json::CharReader* reader = builder.newCharReader();
    Json::Value root;
    std::string errors;

    bool parsed = reader->parse(json, root, &errors);
    delete reader;

    if (!parsed || !root.isObject()) {
        return nullptr;
    }

    Json::Value token_type = root["token_type"];
    Json::Value access_token = root["access_token"];
    Json::Value expires_in = root["expires_in"];
    Json::Value refresh_token = root["refresh_token"];

    if (!token_type.isString() || token_type != "Bearer"
        || !access_token.isString()
        || !expires_in.isInt() || expires_in < 0
        || refresh_token.isArray()) {
        return nullptr;
    }

    return root;
}
