} service_param;

struct dynamic_set {
    int num_params;
    int flags_size;
    int names_size;
    service_param *params;
    int *flags;
    char **names;
    pthread_mutex_t mutex;
    size_t memory_limit;
};

struct dynamic_set *create_dynamic_set(int num_params, size_t memory_limit) {
    struct dynamic_set *ds = malloc(sizeof(struct dynamic_set));
    if (!ds) {
        perror("Memory allocation failed");
        return NULL;
    }

    ds->num_params = num_params;
    ds->memory_limit = memory_limit;

    // Calculate required memory for each component
    int flags_size = num_params * sizeof(int);
    int names_size = num_params * sizeof(char*);

    // Allocate contiguous blocks for flags and names to reduce fragmentation
    ds->flags = malloc(flags_size);
    if (!ds->flags) {
        perror("Memory allocation failed");
        free(ds);
        return NULL;
    }

    ds->names = malloc(names_size);
    if (!ds->names) {
        perror("Memory allocation failed");
        free(ds->flags);
        free(ds);
        return NULL;
    }

    // Allocate service_param structures using calloc for zero-initialization
    int params_size = num_params * sizeof(service_param);
    ds->params = calloc(num_params, params_size);
    if (!ds->params) {
        perror("Memory allocation failed");
        free(ds->flags);
        free(ds->names);
        free(ds);
        return NULL;
    }

    pthread_mutex_init(&ds->mutex, NULL);

    return ds;
}

// Implement set_param and get_param functions here...

void destroy_dynamic_set(struct dynamic_set *ds) {
    free(ds->flags);
    free(ds->names);
    free(ds->params);
    pthread_mutex_destroy(&ds->mutex);
    free(ds);
}
