Record* read_record(FILE *fp) {
    char c;
    Record *record = mmap(NULL, sizeof(Record), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANON, -1, 0);
    record->capacity = 5;
    record->length = 0;

    while ((c = fgetc(fp)) != EOF) {
        if (record->length >= record->capacity) {
            record->capacity *= 2;
            record = realloc(record, record->capacity * sizeof(Record));
        }

        if (c == ' ') continue;

        ((char *)record->data)[record->length++] = c;
    }

    // Parse metadata fields and fill `record` structure
    // ...

    return record;
}

void process_record(Record *record) {
    char *fields = (char *)record->data;
    double sum = 0.0;
    int num_values = 0;

    for (size_t i = TIMESTAMP + 1; i < record->length - AVG_FIELD - 1; ++i) {
        if (isdigit(fields[i])) {
            sum += atof(&fields[i]);
            num_values++;
        }

        if (num_values >= 3) break;
    }

    if (num_values < 3) strcpy((char *)record->data + record->length, "");
    else sprintf((char *)record->data + record->length, "%f", sum / num_values);
}

void write_processed_record(Record *record, FILE *out_fp) {
