import java.io.*;
import java.math.BigInteger;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.*;
import java.util.concurrent.*;
import okhttp3.*;
import org.slf4j.*;

public class MD5Hasher {
    private static final Logger LOGGER = LoggerFactory.getLogger(MD5Hasher.class);

    private Map<String, String> cache;
    private OkHttpClient httpClient;
    private ConnectionPool connectionPool;

    public MD5Hasher() throws IOException {
        cache = new ConcurrentHashMap<>();
        OkHttpClient.Builder builder = new OkHttpClient.Builder();
        builder.connectionPool(new ConnectionPool(10, 30, TimeUnit.SECONDS));
        httpClient = builder.build();
        connectionPool = new CustomConnectionPool(builder);
    }

    public void computeMD5Hashes(List<String> strings) {
        ExecutorService executor = Executors.newFixedThreadPool(10);
        Future[] futures = new Future[strings.size()];
        for (int i = 0; i < strings.size(); i++) {
            final int index = i;
            Callable<Pair<String, String>> callable = () -> computeMD5(strings.get(index));
            futures[index] = executor.submit(callable);
        }
        executor.shutdown();
        try {
            for (Future future : futures) {
                Pair<String, String> result = future.get();
                cache.put(result.getKey(), result.getValue());
            }
        } catch (InterruptedException | ExecutionException e) {
            LOGGER.error("Error computing MD5 hashes", e);
        }
    }

    private Pair<String, String> computeMD5(String string) {
        String cachedHash = cache.get(string);
        if (cachedHash != null) {
            return new ImmutablePair<>(string, cachedHash);
        }

        MessageDigest md;
        try {
            md = MessageDigest.getInstance("MD5");
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException(e);
        }
        md.update(string.getBytes(StandardCharsets.UTF_8));
        byte[] digest = md.digest();
        BigInteger bigInt = new BigInteger(1, digest);
        String hashedString = bigInt.toString(16);
        while (hashedString.length() < 32) {
            hashedString = "0" + hashedString;
        }
        cache.putIfAbsent(string, hashedString);
        return new ImmutablePair<>(string, hashedString);
    }

