#define THRESHOLD_MEMORY 90

pid_t convert_pid;
int temp_file_fd;
FILE *progress_pipe;
char *temp_file_path;

void handle_signal(int sig) {
    if (convert_pid > 0) {
        kill(convert_pid, SIGTERM);
        close(temp_file_fd);
        unlink(temp_file_path);
    }
}

void log_error(const char *message) {
    fprintf(stderr, "[Error] %s\n", message);
}

int jpeg_to_pdf(char *input_file, char *output_file, int compression_level) {
    if (compression_level < 0 || compression_level > MAX_COMPRESSION_LEVEL) {
        log_error("Invalid compression level");
        return 1;
    }

    char temp_dir[256], cmd[2048];
    getcwd(temp_dir, sizeof(temp_dir));
    snprintf(cmd, sizeof(cmd), "mkdir -p %s/tmp && \
                                convert -compress Zip %s/%s temp_file.jpg %s/tmp/converted_process.pdf -density 300 -quality %d && \
                                pdf2svg temp_file.pdf temp_file.svg && \
                                svg2pdf -o temp_file.pdf temp_file.svg && \
                                rm temp_file.jpg temp_file.svg", temp_dir, temp_dir, input_file, temp_dir, compression_level);

    pid_t tmp = fork();
    if (tmp == -1) {
        log_error("Failed to fork process");
        return 1;
    } else if (tmp == 0) { // child process
        execl("/bin/bash", "/bin/bash", "-c", cmd, NULL);
        log_error("Error while executing command");
        exit(1);
    } else { // parent process
        convert_pid = tmp;
        struct sigaction sa;
        sa.sa_handler = handle_signal;
        sigemptyset(&sa.sa_mask);
        sa.sa_flags = 0;
        if (sigaction(SIGINT, &sa, NULL) == -1 || sigaction(SIGHUP, &sa, NULL) == -1 || sigaction(SIGTERM, &sa, NULL) == -1) {
            log_error("Failed to setup signal handlers");
            kill(convert_pid, SIGTERM);
            return 1;
        }

        temp_file_fd = open("temp_file.pdf", O_RDONLY | O_CREAT | O_EXCL, S_IRUSR | S_IWUSR | S_IRGRP | S_IROTH);
        if (temp_file_fd == -1) {
            log_error("Failed to create temp file");
            kill(convert_pid, SIGTERM);
            return 1;
        }

        pipe(progress_pipe);
        dup2(fileno(progress_pipe[1]), STDOUT_FILENO);
        close(progress_pipe[1]);
        temp_file_path = temp_dir"/tmp/temp_file.pdf";
    }

    // Monitor memory usage and CPU load here

    if (waitpid(convert_pid, NULL, 0) == -1) {
        log_error("Failed to wait for conversion process");
        return 1;
    }

    close(temp_file_fd);

    int status;
    if (WIFEXITED(status)) {
        if (WEXITSTATUS(status) != 0) {
            log_error("Conversion failed with non-zero exit code");
            return 1;
        }
    } else {
        log_error("Conversion failed unexpectedly");
        return 1;
    }

    return 0;
}
