#include "jsoncpp/json.h"

typedef struct {
    bool valid;
    char error[1024];
    struct timespec total_time;
    struct timespec task_times[128];
    size_t task_count;
    Task tasks[];
} Config;

typedef struct {
    char id[32];
    char name[64];
    void* (*callback)(void*);
} Task;

Config* load_config(char* filename) {
    struct stat st;
    if (stat(filename, &st) == -1) {
        snprintf(err, sizeof(err), "Unable to read configuration file: %s", filename);
        return NULL;
    }

    YAML::Node config = YAML::LoadFile(filename);
    if (!config.IsSequence()) {
        snprintf(err, sizeof(err), "Invalid configuration file format");
        return NULL;
    }

    Config* config_data = (Config*)malloc(sizeof(Config));
    memset(config_data, 0, sizeof(Config));

    for (YAML::const_iterator it = config.begin(); it != config.end(); ++it) {
        if (!it->IsMap()) {
            snprintf(err, sizeof(err), "Invalid section format in configuration file");
            free(config_data);
            return NULL;
        }

        YAML::Node section = *it;
        if (strcmp(section["id"].as<std::string>().c_str(), "") == 0) {
            snprintf(err, sizeof(err), "Missing id for section in configuration file");
            free(config_data);
            return NULL;
        }

        Task* task = &config_data->tasks[config_data->task_count];
        task->id = section["id"].as<std::string>().c_str();
        task->name = section["name"].as<std::string>().c_str();
        if (section.FindP("callback") == NULL) {
            snprintf(err, sizeof(err), "Missing callback function for task %s", task->name);
            free(config_data);
            return NULL;
        }
        task->callback = reinterpret_cast<void*(*)(void*)>(section["callback"].as<uint64_t>());
        config_data->task_count++;
    }

    config_data->valid = true;
    return config_data;
}

