typedef struct {
    int value;
} record_t;

typedef struct {
    size_t capacity;
    size_t size;
    record_t** data;
} dataset_t;

typedef struct {
    size_t* offsets;
    unsigned long long* keys;
    char** tokens;
    sem_t* resize_semaphore;
} memory_manager_t;

memory_manager_t* create_memory_manager(size_t max_records) {
    memory_manager_t* manager = malloc(sizeof(memory_manager_t));
    manager->capacity = (max_records + BLOCK_SIZE - 1) / BLOCK_SIZE * BLOCK_SIZE;
    manager->size = 0;
    manager->offsets = calloc((manager->capacity + 1), sizeof(size_t));
    manager->keys = malloc((manager->capacity + 1) * sizeof(unsigned long long));
    manager->tokens = malloc((manager->capacity + 1) * sizeof(char*));
    manager->resize_semaphore = sem_init(0, 0, BLOCK_SIZE);
    return manager;
}

void resize_memory_manager(memory_manager_t* manager) {
    size_t new_capacity = (manager->size + BLOCK_SIZE * 2 - 1) / BLOCK_SIZE * BLOCK_SIZE;
    if (new_capacity <= manager->capacity) return;

    record_t** new_data = realloc(manager->data, new_capacity * sizeof(record_t*));
    if (!new_data) {
        fprintf(stderr, "Failed to resize memory manager\n");
        exit(1);
    }
    manager->data = new_data;

    size_t* new_offsets = realloc(manager->offsets, (new_capacity + 1) * sizeof(size_t));
    if (!new_offsets) {
        fprintf(stderr, "Failed to resize offsets array\n");
        exit(1);
    }
    manager->offsets = new_offsets;

    unsigned long long* new_keys = realloc(manager->keys, (new_capacity + 1) * sizeof(unsigned long long));
    if (!new_keys) {
        fprintf(stderr, "Failed to resize keys array\n");
        exit(1);
    }
    manager->keys = new_keys;

    char** new_tokens = realloc(manager->tokens, (new_capacity + 1) * sizeof(char*));
    if (!new_tokens) {
        fprintf(stderr, "Failed to resize tokens array\n");
        exit(1);
    }
    manager->tokens = new_tokens;
}

void add_record(memory_manager_t* manager, record_t* record) {
    sem_wait(manager->resize_semaphore);
    if (manager->size == manager->capacity) resize_memory_manager(manager);

    size_t current_offset = manager->offsets[manager->size];
    manager->offsets[manager->size] = current_offset + 1;
    manager->data[current_offset] = record;
    manager->keys[manager->size] = md5((char*)&record->value, sizeof(int));
}

