    int expires_in;

    json_object_object_get(json, "access_token", &access_token);
    json_object_object_get(json, "expires_in", &expires_in_str);
    json_object_object_get(json, "token_type", &token_type);
    json_object_object_get(json, "refresh_token", &refresh_token);

    if (!access_token || !strcmp(access_token, "") ||
        !expires_in_str || strcmp(expires_in_str, "") ||
        !token_type || strcmp(token_type, "") ||
        (strcmp(token_type, "Bearer") && strcmp(token_type, "none"))) {
