#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <jansson.h>
#include <openssl/sha.h>

#define MAX_OFFSET 10000000
#define KEY_SIZE 32
#define ACCESS_TOKEN_LENGTH 256

typedef struct {
    size_t offset;
    uint64_t key;
    char access_token[ACCESS_TOKEN_LENGTH];
} Record;

// Hybrid PRNG function
void hybrid_prng(uint64_t *state) {
    static const uint32_t M = 0x5deece66d;
    static const uint32_t A = 0xb;
    static const uint32_t C = 0x9e3779b9;

    uint64_t x = *state;
    x = ((x << 32) | (x >> 32));
    x += C;
    x = (x + A) * M;

    *state = x;
}

Record* process_dataset(const char *data, size_t *num_records) {
    const size_t buffer_size = 1024 * 1024; // 1MB for JSON buffer
    json_error_t error;
    json_t *root = json_loads(data, 0, &error);

    if (!root) {
        fprintf(stderr, "JSON parsing failed: %s\n", error.text);
        return NULL;
    }

    size_t offset = 0;
    Record *records = malloc(MAX_OFFSET * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Memory allocation failed.\n");
        json_decref(root);
        return NULL;
    }

    size_t access_token_count = 0;
    for (json_t *access_token_list = json_object_get(root, "access_tokens"); access_token_list; access_token_list = json_array_next(access_token_list)) {
        if (!json_is_string(json_array_get(access_token_list, offset))) {
            fprintf(stderr, "Invalid 'access_tokens' field. Expected string.\n");
            goto cleanup;
        }

        char *token = strdup(json_string_value(json_array_get(access_token_list, offset)));
        if (!token) {
            fprintf(stderr, "Memory allocation failed during JSON copying.\n");
            goto cleanup;
        }

        size_t token_len = strlen(token);
        if (token_len > ACCESS_TOKEN_LENGTH - 1) {
            fprintf(stderr, "Invalid 'access_tokens' field. Token length exceeds limit.\n");
            free(token);
            goto cleanup;
        }

        memcpy(records[access_token_count].access_token, token, token_len + 1);
        records[access_token_count].key = SHA256(records[access_token_count].access_token);
        access_token_count++;
    }

    if (access_token_count > MAX_OFFSET) {
        fprintf(stderr, "Too many records. Limit exceeded.\n");
        goto cleanup;
    }

    *num_records = access_token_count;
    return records;

cleanup:
    for (size_t i = 0; i < access_token_count; ++i) {
        free(records[i].access_token);
    }
    free(records);
    json_decref(root);
    return NULL;
}

