#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct Record {
    char timestamp[25]; // ISO 8601 format
    int values[5];
    int num_values;
    char average[7]; // Space for float with precision of two digits after the decimal point
    struct Record *next;
} Record;

// Function to compute the average of an array
void compute_average(int* arr, int len, char* output) {
    int sum = 0;
    double avg;
    for (int i = 0; i < len; ++i)
        sum += arr[i];

    avg = sum / len;
    snprintf(output, sizeof(output), "%.2f", avg);
}

// Function to process a single record and append the average
void process_record(Record* record) {
    int i;
    int valid_values = 0;

    for (i = record->num_values - 1; i >= 0 && valid_values < 5; --i) {
        if (record->values[i] != 0) { // Replace this with your condition to identify valid values
            record->values[valid_values++] = record->values[i];
        }
    }

    compute_average(record->values + valid_values, 5, record->average);
}

// Function to add a new record to the list
void append_record(Record** head_ptr) {
    Record* new_record = malloc(sizeof(Record));
    if (!new_record) return; // Handle memory allocation failure

    memset(new_record, 0, sizeof(*new_record));
    new_record->next = *head_ptr;
    *head_ptr = new_record;
}
