1. MemoryPool class for managing dynamic memory allocation:

```cpp
#include <memory>
#include <vector>

template<typename T>
class MemoryPool {
public:
    MemoryPool(size_t maxSize) : buffer_(std::make_unique<std::vector<T>>()), maxSize_(maxSize), currentSize_(0) {}

    T* allocate() {
        if (currentSize_ + sizeof(T) <= maxSize_) {
            T* mem = &buffer_->at(currentSize_);
            currentSize_ += sizeof(T);
            return mem;
        }
        return nullptr;
    }

    void free(T* ptr) {
        if (ptr) {
            --currentSize_;
        }
    }

private:
    std::unique_ptr<std::vector<T>> buffer_;
    size_t maxSize_, currentSize_;
};
```

