void insert(TrafficEvent* event) {
    Node *new_node = new_node(event), *current = head;

    pthread_mutex_lock(&list_lock);

    if (current == NULL) {
        head = new_node;
    } else {
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }

    pthread_mutex_unlock(&list_lock);
}

Node* find(int uID) {
    Node *current = head;

    pthread_mutex_lock(&list_lock);
    while (current != NULL) {
        if (current->data->uID == uID) {
            pthread_mutex_unlock(&list_lock);
            return current;
        }
        current = current->next;
    }
    pthread_mutex_unlock(&list_lock);
    return NULL;
