#include <des.h> // Include the DES library for cryptographic ciphering

typedef struct {
    int value;
    long offset;
    time_t timestamp;
    bool status; // processed or not
} Record;

typedef struct HashTableNode {
    int key;
    int idx;
    pthread_mutex_t lock;
    struct HashTableNode *next;
} HashTableNode;

struct CustomHashTable {
    unsigned long size;
    HashTableNode **table;
};

void init_hash_table(CustomHashTable *ht, unsigned long size) {
    ht->size = size;
    ht->table = calloc(size, sizeof(HashTableNode*));
}

unsigned long hash(int key, unsigned long size) {
    return key % size;
}

void insert_node(CustomHashTable *ht, int key, Record r) {
    unsigned long idx = hash(key, ht->size);
    pthread_mutex_init(&ht->table[idx]->lock, NULL);

    HashTableNode *n = malloc(sizeof(HashTableNode));
    n->key = key;
    n->idx = -1; // Not yet inserted
    n->next = ht->table[idx];

    ht->table[idx] = n;
}

int find_node(CustomHashTable *ht, int key) {
    unsigned long idx = hash(key, ht->size);
    pthread_mutex_lock(&ht->table[idx]->lock);

    HashTableNode *n = ht->table[idx];
    while (n != NULL) {
        if (n->key == key && n->idx != -1) {
            pthread_mutex_unlock(&ht->table[idx]->lock);
            return n->idx;
        }
        n = n->next;
    }

    pthread_mutex_unlock(&ht->table[idx]->lock);
    return -1;
}

void free_hash_table(CustomHashTable *ht) {
    for (unsigned long i = 0; i < ht->size; ++i) {
        HashTableNode *n = ht->table[i];
        while (n != NULL) {
            HashTableNode *tmp = n;
            n = n->next;
            free(tmp);
        }
    }
    free(ht->table);
}

int* alloc_offsets(unsigned long size) {
    int *offsets = calloc(size, sizeof(int));
    if (!offsets) return NULL;
    return offsets;
}

int* alloc_keys(unsigned long size) {
    int *keys = malloc(size * sizeof(int));
    if (!keys) return NULL;
    memset(keys, 0, size * sizeof(int));
    return keys;
}

Record* alloc_records(unsigned long size) {
    Record *records = calloc(size, sizeof(Record));
    if (!records) return NULL;
    memset(records, 0, size * sizeof(Record));
    return records;
}

void free_arrays(int *offsets, int *keys, Record *records) {
    if (offsets) free(offsets);
    if (keys) free(keys);
    if (records) free(records);
}

void generate_random_record(Record *r, int keys[], unsigned long offsets_size) {
    r->value = rand();
    for (int i = 0; i < sizeof(keys)/sizeof(int); ++i) {
        r->offset += keys[i] + keys[i] * r->value;
        if (r->offset >= offsets_size) {
            r->offset -= offsets_size;
            r->value = rand();
            i--;
        }
    }
}

void process_record(Record *r, CustomHashTable *ht, int keys[], unsigned long offsets_size) {
    int idx = find_node(ht, r->value);
    if (idx != -1 && r->offset == offsets[idx]) return; // Record already exists or has the wrong offset

    for (int i = 0; i < sizeof(keys)/sizeof(int) && idx == -1; ++i) {
        if (!find_node(ht, keys[i])) {
            insert_node(ht, keys[i], (Record){keys[i], r->offset, time(NULL), false});
            idx = find_node(ht, keys[i]);
        }
    }

    if (idx == -1) {
        // Handle error: too many consecutive failed attempts to find a unique key
        fprintf(stderr, "Error: Potential loop in random value generation process\n");
        return;
    }

    generate_random_record(r + idx, keys, offsets_size);
    r[idx].status = true;
}

int manage_memory(unsigned long max_records, int *offsets, int *keys, Record *records, CustomHashTable ht, char* json) {
    json_object_t *o = json_loads(json, JSON_PARSE_RELAXED);
    if (!o || !json_has_member(o, "access_token") ||
        !json_has_member(o, "expires_in") || !json_is_number(o, "expires_in") ||
        json_get_number(o, "expires_in") <= 0 ||
        !json_has_member(o, "token_type") || strcmp(json_get_string(o, "token_type"), "Bearer") != 0 ||
        !json_has_member(o, "scope") || json_count(json_get_array(o, "scope")) < 1 ||
        !json_is_string(json_get_array_element(o, "scope", 0)) || strcmp(json_get_string(json_get_array_element(o, "scope", 0)), "read:all") != 0) {
        fprintf(stderr, "Error: Invalid OAuth2 access token response\n");
        return -1;
    }

    unsigned long size = max_records + sizeof(keys)/sizeof(int);
    int *new_offsets = alloc_offsets(size);
    if (!new_offsets) return -1;

    for (unsigned long i = 0; i < offsets_size && i < max_records; ++i) {
        new_offsets[i] = offsets[i];
        process_record(records + i, &ht, keys, size);
    }

    free_arrays(offsets, keys, records);
    offsets = new_offsets;
    keys = realloc(keys, (size + 1) * sizeof(int));
    if (!keys) return -1;

    // Populate additional keys, offsets, timestamps, and status flags
    for (unsigned long i = max_records; i < size; ++i) {
        new_offsets[i] = rand() % offsets_size;
        process_record(records + i, &ht, keys, size);
    }

    return 0;
}
