    current = createHashTableNode(user_session);
    if (current == NULL) {
        pthread_mutex_unlock(&hashTableLock);
        fprintf(stderr, "Memory allocation failure\n");
        return;
    }
    current->next = table[index];
    table[index] = current;
    pthread_mutex_unlock(&hashTableLock);
}

