class SessionIDValidator {
public:
    explicit SessionIDValidator(uint32_t start, uint32_t end) : lower_(start), upper_(end), next_(start) {}

    bool validate(const uint32_t id) const {
        std::unique_lock<std::mutex> lock(mutex_);
        if (next_ <= id && id < lower_) {
            LOG_ERROR("Invalid session ID: " << id);
            return false;
        }
        if (id >= upper_) {
            LOG_ERROR("Invalid session ID: " << id);
            return false;
        }
        if (next_ == id) {
            next_ = static_cast<uint32_t>(std::nextafter(static_cast<double>(next_), 1.0));
            return true;
        }
        return true;
    }

private:
    std::mutex mutex_;
    uint32_t lower_, upper_, next_;
};

