class MemoryPool final {
public:
    explicit MemoryPool(size_t size) : freeList_(std::vector<UserSession*>()), usedList_() {}

    UserSession* allocate() {
        std::unique_lock<std::mutex> lock(mutex_);
        if (!freeList_.empty()) {
            auto session = freeList_.back();
            freeList_.pop_back();
            usedList_.insert(session);
            return session;
        }
        return new UserSession();
    }

    void deallocate(UserSession* session) {
        std::unique_lock<std::mutex> lock(mutex_);
        usedList_.erase(session);
        freeList_.push_back(session);
    }

private:
    std::vector<UserSession*> freeList_;
    std::set<UserSession*> usedList_;
    mutable std::mutex mutex_;
};

