    new_node->next = NULL;
    new_node->prev = NULL;
    return new_node;
}

void insert_head(Node** head, Node* node) {
    if (*head) {
        (*head)->prev = node;
        node->next = *head;
        *head = node;
    } else {
        *head = node;
    }
}

void insert_tail(Node** head, Node* node) {
    if (!*head) {
        *head = node;
        return;
    }
    Node* current = *head;
    while (current->next != NULL) {
        current = current->next;
    }
    current->next = node;
    node->prev = current;
}

void remove_by_tag(Node** head, RX_UE_INFORMATION_TAG tag) {
    Node* current = *head;
    while (current != NULL) {
        if (current->ue_tag == tag) {
            if (current->prev != NULL)
                current->prev->next = current->next;
            else
                *head = current->next;
            if (current->next != NULL)
                current->next->prev = current->prev;
            free(current);
            return;
        }
        current = current->next;
    }
}

Node* find_by_tag(const Node* head, RX_UE_INFORMATION_TAG tag) {
    for (Node* current = const_cast<Node*>(head); current != NULL; current = current->next) {
        if (current->ue_tag == tag)
