class DynamicArray {
private:
    std::vector<NFAPI_CRC_INDICATION_PDU_T> array;
    std::unordered_map<uint16_t, size_t> rntiToIndex;
    std::mutex mtx;

public:
    DynamicArray() { initRandom(); }

    void push_back(const NFAPI_CRC_INDICATION_PDU_T& data) {
        std::lock_guard<std::mutex> lock(mtx);
        array.push_back(data);
        rntiToIndex[data.RNTI] = array.size() - 1;
    }

    bool erase(uint16_t rnti) {
        std::lock_guard<std::mutex> lock(mtx);
        auto it = rntiToIndex.find(rnti);
        if (it == rntiToIndex.end()) return false;

        size_t index = it->second;
        array.erase(array.begin() + index);
        rntiToIndex.erase(it);
        return true;
    }

    const NFAPI_CRC_INDICATION_PDU_T* find(uint16_t rnti) const {
        std::lock_guard<std::mutex> lock(mtx);
        auto it = rntiToIndex.find(rnti);
        if (it == rntiToIndex.end()) return nullptr;

        size_t index = it->second;
        return &array[index];
    }

    void initRandom() {
        std::random_device rd;  //Will be used to obtain a seed for the random number engine
        std::mt19937 gen(rd()); //Standard mersenne_twister_engine seeded with rd()
        std::uniform_int_distribution<> dis(0, 1);

        for (auto& data : array) {
            data.CRCI.CRCFLAG = dis(gen);
            //Set other fields as needed
        }
    }
};
