#include <stdlib.h> // For malloc and free functions

// Initialize a slab for LTE PHY Layer Statistics structures
void init_slab(struct slab *slab, size_t num_objects, size_t obj_size) {
    if ((slab->slab = (struct lte_phy_stat **)mmap(NULL, num_objects * obj_size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0)) == MAP_FAILED) {
        log_error("Failed to allocate slab memory");
        exit(EXIT_FAILURE);
    }

    sem_init(&slab->lock, 0, 1);
    slab->num_objects = num_objects;
    slab->obj_size = obj_size;
}

// Allocate an object from the slab
struct lte_phy_stat* get_obj(struct slab *slab) {
    sem_wait(&slab->lock);
    struct lte_phy_stat *obj = NULL;
    if (slab->num_objects > 0) {
        obj = slab->slab[--slab->num_objects];
        memset(obj, 0, slab->obj_size);
    }
    sem_post(&slab->lock);
    return obj;
}
