#include <stdbool.h>
#include <stddef.h>
#include <stdint.h>
#include <pthread.h>
#include <semaphore.h>
#include <stdlib.h>

typedef struct UE_CONNECTION_INFO {
    uint64_t UE_ID;
    uint32_t CELL_ID;
    void* BANDWIDTH_PARTNER;
    struct UE_CONNECTION_INFO *next;
} UE_CONNECTION_INFO;

typedef struct CONCURRENT_LIST {
    UE_CONNECTION_INFO *head;
    UE_CONNECTION_INFO *tail;
    size_t count;
    sem_t add_sem;
    pthread_mutex_t list_lock;
} CONCURRENT_LIST;

CONCURRENT_LIST* concurrent_list_create() {
    CONCURRENT_LIST* list = malloc(sizeof(CONCURRENT_LIST));
    if (!list) return NULL;
    list->head = list->tail = NULL;
    list->count = 0;
    sem_init(&list->add_sem, 0, 1);
    pthread_mutex_init(&list->list_lock, NULL);
    return list;
}

UE_CONNECTION_INFO* concurrent_list_alloc() {
    UE_CONNECTION_INFO* node = malloc(sizeof(UE_CONNECTION_INFO));
    if (!node) return NULL;
    node->next = NULL;
    return node;
}

void concurrent_list_add(CONCURRENT_LIST *list, UE_CONNECTION_INFO *entry) {
    pthread_mutex_lock(&list->list_lock);
    while (list->head && list->head->UE_ID == entry->UE_ID) {
        sem_wait(&list->add_sem);
    }
    if (list->tail) {
        list->tail->next = entry;
        list->tail = entry;
    } else {
        list->head = entry;
        list->tail = list->head;
    }
    list->count++;
    pthread_mutex_unlock(&list->list_lock);
}

UE_CONNECTION_INFO* concurrent_list_find(const CONCURRENT_LIST *list, uint64_t UE_ID) {
    for (UE_CONNECTION_INFO *node = list->head; node != NULL; node = node->next) {
        if (node->UE_ID == UE_ID) return node;
    }
    return NULL;
}

void concurrent_list_remove(CONCURRENT_LIST *list, UE_CONNECTION_INFO *entry) {
    pthread_mutex_lock(&list->list_lock);
    if (list->head == entry) list->head = entry->next;
    else if (!list->tail) return; // no more elements in the list
    for (UE_CONNECTION_INFO *node = list->head; node->next != NULL; node = node->next) {
        if (node->next == entry) {
            if (entry->next) node->next = entry->next;
            else list->tail = node;
            break;
        }
    }
    free(entry);
    list->count--;
    pthread_mutex_unlock(&list->list_lock);
}
```

This code provides a concurrently-safe, thread-friendly list management for the given `UE_CONNECTION_INFO` structures. It utilizes semaphores to ensure that only one thread adds an entry at a time and minimizes lock contention by checking for duplicate UE_IDs before adding new entries. This approach helps optimize performance while considering cache coherency and lock contention implications.']

