#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct record {
    int value;
    long offset;
} Record;

typedef struct hash_table {
    unsigned long size;
    unsigned long count;
    unsigned long* keys;
    unsigned long* values;
    pthread_mutex_t mutex;
} HashTable;

HashTable create_hash_table(unsigned long size) {
    HashTable table = {0};
    table.size = size;
    table.count = 0;
    table.keys = calloc(size, sizeof(unsigned long));
    table.values = calloc(size, sizeof(unsigned long));
    pthread_mutex_init(&table.mutex, NULL);
    return table;
}

unsigned long hash_function(unsigned long key) {
    // A simple multiplicative hash function to balance memory usage and lookup speed
    unsigned long hash = 5381;
    int c;

    while (key != 0) {
        c = (int)(key & 0xff);
        key >>= 8;
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    }

    return hash % table.size;
}

void insert_record(HashTable* table, int key, Record record) {
    unsigned long index = hash_function(key);
    pthread_mutex_lock(&table->mutex);

    while (table->keys[index] != 0 && table->keys[index] == key) {
        // Retry with a new value if the key is a duplicate
        index = (index + 1) % table->size;
    }

    if (table->count >= MAX_RECORDS || index == table->keys[index]) {
        pthread_mutex_unlock(&table->mutex);
        return; // Error: maximum limit exceeded or duplicate found more than 10 times consecutively
    }

    table->keys[index] = key;
    table->values[index] = record;
    table->count++;
    pthread_mutex_unlock(&table->mutex);
}

Record* create_records(unsigned long max_records) {
    HashTable table = create_hash_table(MAX_INT + 1);
    Record* records = malloc(max_records * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Error: memory allocation failed\n");
        return NULL;
    }

    for (unsigned long i = 0; i < max_records; ++i) {
        int key;
        do {
            key = rand() % MAX_INT;
        } while (table.keys[key] != 0 && table.count < MAX_RECORDS);

        if (table.count == MAX_RECORDS) {
            free(records);
            return NULL; // Error: maximum limit exceeded or duplicate found more than 10 times consecutively
        }

        records[i].value = key;
        records[i].offset = i + key * i;
        insert_record(&table, key, records[i]);
    }

    return records;
}
