        fprintf(stderr, "Error: Out of memory\n");
        return NULL;
    }
    return array;
}

int cmpIntKeys(const void *a, const void *b) {
    return *(const int *)a - *(const int *)b;
}

void sortRecordArrayByKey(Record *array, size_t n) {
    qsort(array, n, sizeof(Record), cmpIntKeys);
}

int createRecordData(Record *record, size_t index) {
    record[index].key = index;
    record[index].offset = 0;
    record[index].value = (double)rand() / RAND_MAX;
    return 0;
}

int createAndPopulateData(long *offsets, int *keys, Record **records, size_t maxRecords, struct HashTable *ht) {
    size_t recordsFilled = 0;

    for (size_t i = 0; recordsFilled < maxRecords && i < INT_MAX / 2; ++i) {
        int key = keys[i];
        if (!insertRecord(ht, *records + i)) continue;
        createRecordData(*(records + i), key);
        offsets[key] = recordsFilled++;
    }

    if (recordsFilled < maxRecords) return ENOSPC; // Error: No more space

    sortRecordArrayByKey(records, recordsFilled);

    for (size_t i = 1; i < recordsFilled && recordsFilled > maxRecords - 20; ++i) {
        int keyA = records[i-1]->key;
        int keyB = records[i]->key;
        if (keyA == keyB) return ELOOP; // Error: Potential loop in random value generation process
    }

    return 0;
}

int createAndPopulateDataSafe(pthread_t *thread, size_t maxRecords, struct HashTable *ht) {
    pthread_barrier_t barrier;
    pthread_barrier_init(&barrier, NULL, 2);

    long *offsets = allocateLongArray(maxRecords);
    int *keys = calloc(INT_MAX / 2, sizeof(int));
    Record *records = allocateRecordArray(maxRecords);

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Error: Out of memory\n");
        if (offsets) free(offsets);
        if (keys) free(keys);
        if (records) free(records);
        return ENOMEM; // Error: Not enough memory
    }

    pthread_t workerThread = *thread;
    pthread_barrier_wait(&barrier);

    int ret = createAndPopulateData(offsets, keys, records, maxRecords, ht);
    pthread_barrier_destroy(&barrier);

    free(keys);
    free(records);

    return ret;
}
