            byte[] hashed = digest.digest(input.getBytes());
            BigInteger number = new BigInteger(1, hashed);
            StringBuilder sb = new StringBuilder(number.toString(16));
            while (sb.length() < 32) {
                sb.insert(0, "0");
            }
            String md5Hex = sb.toString();
            cache.put(input, md5Hex);
            return md5Hex;
        } catch (Exception e) {
            // Handle exceptions here
        }
        return null;
    }
}
