} Record;

struct HashTable {
    unsigned long size;
    unsigned long capacity;
    Record **table;
    pthread_mutex_t *mutexes;
};

struct HashTable *create_hash_table(unsigned long size, unsigned long capacity) {
    struct HashTable *ht = malloc(sizeof(*ht));
    ht->size = size;
    ht->capacity = capacity;
    ht->table = calloc(capacity, sizeof(Record*));
    ht->mutexes = calloc(capacity, sizeof(pthread_mutex_t));
    return ht;
}

unsigned long hash(int key) {
    unsigned long h = (unsigned long)key;
    h = (h << 5) + h; // hash * 33
    h = h ^ (h >> 2);  // hash * 5
    return h % ht->capacity;
}

bool insert(struct HashTable *ht, Record *rec) {
    unsigned long index = hash(rec->key);
    pthread_mutex_lock(&ht->mutexes[index]);
    if (ht->table[index] == NULL || ht->table[index]->key != rec->key) {
        ht->table[index] = rec;
        return true;
    }
    pthread_mutex_unlock(&ht->mutexes[index]);
    return false;
}

Record *find(struct HashTable *ht, int key) {
    unsigned long index = hash(key);
    Record *rec;
    pthread_mutex_lock(&ht->mutexes[index]);
    rec = ht->table[index];
    if (rec && rec->key == key) {
        return rec;
    }
    pthread_mutex_unlock(&ht->mutexes[index]);

    for (unsigned long i = index + 1; i < ht->capacity; ++i) {
        unsigned long j = i % ht->capacity;
        pthread_mutex_lock(&ht->mutexes[j]);
        rec = ht->table[j];
        if (rec && rec->key == key) {
            pthread_mutex_unlock(&ht->mutexes[j]);
            return rec;
        }
        pthread_mutex_unlock(&ht->mutexes[j]);
    }

    return NULL;
}

void *create_records(void *args, unsigned long max) {
    struct HashTable *ht = args;
    srand((unsigned int)time(NULL));
    for (unsigned long i = 0; i < max; ++i) {
        int key;
        do {
            key = rand() % MAX_INT;
        } while (!insert(ht, malloc(sizeof(*rec))) || find(ht, key));
        Record *rec = ht->table[key];
        rec->offset = i;
        rec->value = (double)rand() / RAND_MAX;
    }
    return NULL;
}

void free_records(struct HashTable *ht) {
    for (unsigned long i = 0; i < ht->capacity; ++i) {
        Record *rec = ht->table[i];
        if (rec) free(rec);
    }
    free(ht->table);
    free(ht->mutexes);
    free(ht);
}
