import java.security.MessageDigest;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.nio.charset.StandardCharsets;

public class MD5Hash {
    private static Map<String, String> md5Cache = new ConcurrentHashMap<>();

    public static void main(String[] args) {
        // Batch of variable-length strings
        List<String> strings = Arrays.asList("Hello", "World", "\uD83C\uDD4E", "Java", "\u0627\u0644\u0633\u06CC", "RosettaCode");

        for (String str : strings) {
            String md5 = calculateMD5(str);
            if (!md5Cache.containsKey(md5)) {
                System.out.println("Calculating MD5 for '" + str + "'...");
                md5Cache.put(str, md5);
            }
        }
    }

    private static String calculateMD5(String input) {
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] messageDigest = md.digest(input.getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder();
            for (byte b : messageDigest) {
                sb.append(String.format("%02x", b));
            }
            return sb.toString();
        } catch (Exception e) {
            throw new RuntimeException("Error calculating MD5", e);
        }
    }
}
