import java.math.BigInteger;
import java.security.MessageDigest;
import java.util.*;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicLong;
import java.util.concurrent.locks.ReentrantLock;

public class Record {
    final long offset;
    int key;
    double value;

    public Record(int key, double value) {
        this.key = key;
        this.value = value;
        this.offset = new AtomicLong().incrementAndGet();
    }
}

public class HashTable {
    private final int capacity;
    private final Map<Integer, Record> records;
    private final ReentrantLock lock;

    public HashTable(int capacity) {
        this.capacity = capacity;
        this.records = new ConcurrentHashMap<>(this.capacity);
        this.lock = new ReentrantLock();
    }

    public Record putIfAbsent(Record record) {
        while (true) {
            lock.lock();
            Record existing = records.putIfAbsent(record.key, record);
            if (existing == null) {
                lock.unlock();
                return record;
            }
            lock.unlock();
        }
    }
}

public static void main(String[] args) throws Exception {
    HashTable ht = new HashTable(1024);
    Record[] records = new Record[10];
    for (int i = 0; i < records.length; ++i) {
        records[i] = new Record(new Random().nextInt(1024), Math.random());
        ht.putIfAbsent(records[i]);
    }
}
