typedef struct {
    pthread_mutex_t lock;
    unsigned int size;
    unsigned int capacity;
    unsigned long *keys;
    int *values;
} hash_table;

unsigned long hash(const char *key, unsigned int capacity) {
    unsigned long hash = 0;
    for (int i = 0; key[i]; ++i)
        hash = (hash << 5) + hash + key[i];
    return hash % capacity;
}

void resize(hash_table *ht, unsigned int new_capacity) {
    unsigned int old_capacity = ht->capacity;
    ht->capacity = new_capacity;

    unsigned long *new_keys = (unsigned long*)realloc(ht->keys, new_capacity * sizeof(unsigned long));
    if (!new_keys) return;
    ht->keys = new_keys;

    int *new_values = (int*)realloc(ht->values, new_capacity * sizeof(int));
    if (!new_values) return;
    ht->values = new_values;

    for (int i = old_capacity; i < new_capacity; ++i) {
        ht->keys[i] = 0;
        ht->values[i] = 0;
    }
}

hash_table *init_hash_table(unsigned int capacity) {
    hash_table *ht = (hash_table*)malloc(sizeof(hash_table));
    if (!ht) return NULL;

    ht->size = 0;
    ht->capacity = capacity;
    ht->keys = (unsigned long*)calloc(capacity, sizeof(unsigned long));
    if (!ht->keys) {
        free(ht);
        return NULL;
    }
    ht->values = (int*)calloc(capacity, sizeof(int));
    if (!ht->values) {
        free(ht->keys);
        free(ht);
        return NULL;
    }

    pthread_mutex_init(&ht->lock, NULL);

    resize(ht, capacity * 2);

    return ht;
}

void put(hash_table *ht, const char *key, int value) {
    unsigned long hash = hash(key, ht->capacity);
    pthread_mutex_lock(&ht->lock);

    while (ht->keys[hash] != 0 && strcmp((const char*)&ht->keys[hash], key)) {
        ++hash %= ht->capacity;
    }

    if (ht->keys[hash] == 0) {
        ht->keys[hash] = (unsigned long)strdup(key);
        ht->values[hash] = value;
        ++ht->size;
    } else {
        ht->values[hash] = value;
    }

    if (ht->size > (ht->capacity / 2)) resize(ht, ht->capacity * 2);

    pthread_mutex_unlock(&ht->lock);
}

int get(const hash_table *ht, const char *key) {
    unsigned long hash = hash(key, ht->capacity);
    pthread_mutex_lock(&ht->lock);

    while (ht->keys[hash] != 0 && strcmp((const char*)&ht->keys[hash], key)) {
        ++hash %= ht->capacity;
    }

    int value = -1;
    if (ht->keys[hash]) value = ht->values[hash];

    pthread_mutex_unlock(&ht->lock);
    return value;
}
