typedef struct {
    time_t timestamp;
    enum { ARRIVAL, DEPARTURE } type;
    unsigned int uID;
} TrafficEvent;

typedef struct Record {
    int value;
    long offset;
} Record;

typedef struct HashNode {
    int key;
    struct HashNode* next;
} HashNode;

typedef struct HashTable {
    unsigned int capacity;
    unsigned int size;
    pthread_mutex_t lock;
    HashNode** nodes;
} HashTable;

void createHashTable(HashTable* table, unsigned int capacity) {
    table->capacity = capacity;
    table->size = 0;
    table->lock = PTHREAD_MUTEX_INITIALIZER;
    table->nodes = calloc(capacity, sizeof(HashNode*));
}

unsigned int hashFunction(const void* key) {
    return *((unsigned int*)key) % table->capacity;
}

void insertKey(HashTable* table, int key) {
    unsigned int index = hashFunction(&key);
    pthread_mutex_lock(&table->lock);
    HashNode** current = &table->nodes[index];
    while (*current != NULL) {
        if ((*current)->key == key) {
            pthread_mutex_unlock(&table->lock);
            return; // Key already exists, return without inserting
        }
        current = &((*current)->next);
    }
    *current = malloc(sizeof(HashNode));
    (*current)->key = key;
    (*current)->next = NULL;
    table->size++;
    pthread_mutex_unlock(&table->lock);
}

int findKey(const HashTable* table, int key) {
    unsigned int index = hashFunction(&key);
    pthread_mutex_lock(&table->lock);
    HashNode** current = &table->nodes[index];
    while (*current != NULL) {
        if ((*current)->key == key) {
            pthread_mutex_unlock(&table->lock);
            return true;
        }
        current = &((*current)->next);
    }
    pthread_mutex_unlock(&table->lock);
    return false;
}

TrafficEvent** initializeEvents(unsigned int maxRecords) {
    TrafficEvent** events = calloc(maxRecords, sizeof(TrafficEvent));
    if (!events) {
        fprintf(stderr, "Error: Failed to allocate memory for TrafficEvents\n");
        return NULL;
    }

    HashTable keyTable;
    createHashTable(&keyTable, maxRecords);

    unsigned int uID = 0;
    int keys[maxRecords];
    Record* records = malloc(maxRecords * sizeof(Record));
    if (!records) {
        fprintf(stderr, "Error: Failed to allocate memory for Records\n");
        free(events);
        return NULL;
    }

    long offsets[maxRecords] = { 0 };
    long totalOffset = 0;

    for (unsigned int i = 0; i < maxRecords && uID < INT_MAX; ++i) {
        uID = (uID + 1) % maxRecords;

        if (findKey(&keyTable, uID)) {
            continue; // UID already exists, retry with a new one
        }

        keys[i] = uID;
        insertKey(&keyTable, uID);

        records[i].value = rand() % INT_MAX + 1;
        long keySum = totalOffset + records[i].value * uID;
        offsets[i] = keySum;
        totalOffset += records[i].value * (uID + 1);

        events[i] = malloc(sizeof(TrafficEvent));
        if (!events[i]) {
            fprintf(stderr, "Error: Failed to allocate memory for TrafficEvent\n");
            free(records);
            free(keyTable.nodes);
            return NULL;
        }

        events[i]->timestamp = time(NULL);
        events[i]->type = (rand() % 2) == 0 ? ARRIVAL : DEPARTURE;
        events[i]->uID = uID;
    }

    free(keyTable.nodes);
    return events;
}

void freeEvents(TrafficEvent** events, unsigned int maxRecords) {
    for (unsigned int i = 0; i < maxRecords; ++i) {
        free(events[i]);
    }
    free(records);
}
