Record* create_records(size_t count, size_t key_range, size_t offset_range, size_t string_max_length) {
    Record* records = (Record*)aligned_alloc(sizeof(Record), count * sizeof(*records));
    log_allocation("Records", records, count * sizeof(*records));

    if (!records) {
        fprintf(stderr, "Failed to allocate memory for records\n");
        return NULL;
    }

    void* key_ptr = aligned_malloc(key_range * sizeof(int), 64);
    log_allocation("Keys", key_ptr, key_range * sizeof(int));

    if (!key_ptr) {
        fprintf(stderr, "Failed to allocate memory for keys\n");
        free(records);
        return NULL;
    }

    void* offset_ptr = aligned_malloc(offset_range * sizeof(long), 64);
    log_allocation("Offsets", offset_ptr, offset_range * sizeof(long));

    if (!offset_ptr) {
        fprintf(stderr, "Failed to allocate memory for offsets\n");
        free(key_ptr);
        free(records);
        return NULL;
    }

    void* string_pool = malloc(string_max_length * count);
    log_allocation("String pool", string_pool, string_max_length * count);

    if (!string_pool) {
        fprintf(stderr, "Failed to allocate memory for string pool\n");
        free(offset_ptr);
        free(key_ptr);
        free(records);
        return NULL;
    }

    for (size_t i = 0; i < count; ++i) {
        Record* record = records + i;
        record->key = *(int*)((char*)key_ptr + (rand() % key_range) * sizeof(int));
        record->offset = *(long*)((char*)offset_ptr + (rand() % offset_range) * sizeof(long));
        record->precision = (double)(rand() / (RAND_MAX / 100.0));
        record->string_length = rand() % string_max_length;
        if (record->string_length > 0) {
            char* string = (char*)((char*)string_pool + i * string_max_length + record->string_length);
            memset(string, '\0', record->string_length + 1);
            sprintf(string, "Generated string %zu", i);
        }
    }

    free(key_ptr);
    free(offset_ptr);

    return records;
}

