        field_value = va_arg(args, void*);

        if (strcmp(field_name, "key") == 0)
            record->key = *(int*)field_value;
        else if (strcmp(field_name, "offset") == 0)
            record->offset = *(long*)field_value;
        // Add more field updates as needed...
    }
    va_end(args);
}
