    };

    class RecordSystem {
        static std::vector<Record*> records;
        static std::mutex recordsMutex;
        static std::mt19937 randomGenerator;
        static Logger log;

    public:
        RecordSystem() noexcept : records(), recordsMutex(), randomGenerator(std::random_device{}()), log("record_log.txt") {}
        ~RecordSystem() { clear(); }

        void processBatch(size_t numRecords) {
            if (numRecords == 0) return;

            auto start = std::chrono::high_resolution_clock::now();

            std::vector<Record*> batch(numRecords);

            try {
                allocateRecords(batch.data(), numRecords);

                for (size_t i = 0; i < numRecords; ++i) {
