                handleException();
                clearBatch(batch.data(), numRecords);
                throw;
            }

            logAllocatedMemory();

            std::chrono::duration<double> elapsed = std::chrono::high_resolution_clock::now() - start;
            log("Batch processed in " + std::to_string(elapsed.count()) + " seconds.");
        }

    private:
