            constexpr size_t allocationSize = 1024; // adjust as needed
            size_t allocated = 0;

            for (size_t i = 0; i < num; ) {
                Record* currentBlock = nullptr;

                std::lock_guard<std::mutex> lock(recordsMutex);
                if (allocated + allocationSize > records.size()) {
                    currentBlock = static_cast<Record*>(std::aligned_alloc(sizeof(Record), allocated + allocationSize));
                    records.insert(currentBlock, currentBlock + allocationSize);
                } else {
                    currentBlock = &records[allocated];
                }

                for (size_t j = i; j < std::min(i + allocationSize, num); ++j) {
                    new (currentBlock + j - i) Record();
                    allocated++;
                }

                i += allocationSize;
            }
        }

        static void generateRecord(Record* record) noexcept {
            constexpr int minKey = 1;
            constexpr int maxKey = 100000;

            record->key = randomGenerator() % (maxKey - minKey + 1) + minKey;
            record->precision = static_cast<double>(randomGenerator()) / static_cast<double>(RAND_MAX);

            std::generate_n(record->string.data(), 256, [&]() {
                char c;

                do {
                    c = 'a' + randomGenerator() % 26;
                } while (std::find(record->string.cbegin(), record->string.cend(), c) != record->string.cend());

                return c;
            });
            record->string[255] = '\0';
        }

