        }

        static void clear() noexcept {
            std::lock_guard<std::mutex> lock(recordsMutex);
            records.clear();
        }

        static void clearBatch(Record* first, size_t num) noexcept {
            for (size_t i = 0; i < num; ++i) {
                if (first[i]) first[i]->~Record();
            }
        }

        static void handleException() noexcept {
            std::cout << "An error occurred. Freeing memory.\n";
            clearBatch(records.data(), records.size());
        }

        static void logAllocatedMemory() {
            if (records.size() > 0) {
                log("Currently allocated: " + std::to_string(records.size()) + " records.");
            } else {
                log("No records currently allocated.");
            }
