```c
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>

typedef struct {
    size_t used;
    size_t total;
    void *memory;
} MemoryPool;

MemoryPool* memory_pool_create(size_t initial_size, size_t max_size) {
    MemoryPool *pool = malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->used = 0;
    pool->total = initial_size;
    pool->memory = mmap(NULL, initial_size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (pool->memory == MAP_FAILED) {
        free(pool);
        return NULL;
    }

    pool->total = max_size > initial_size ? max_size : initial_size;
    return pool;
}

void* memory_pool_alloc(MemoryPool *pool, size_t size) {
    if (pool->used + size > pool->total) return NULL;

    void *ptr = pool->memory + pool->used;
    pool->used += size;
    return ptr;
}

void memory_pool_destroy(MemoryPool *pool) {
    munmap(pool->memory, pool->total);
    free(pool);
}
