    MemPool* pool = (MemPool*) malloc(sizeof(MemPool));
    if (!pool) {
        logError("Failed to allocate memory for the mem pool");
        return NULL;
    }

    pool->data = malloc(capacity * sizeof(void*));
    if (!pool->data) {
        logError("Failed to allocate data array in mem pool");
        free(pool);
        return NULL;
    }
    pool->capacity = capacity;
    pool->size = 0;
    sem_init(&pool->mutex, 0, 1);
    return pool;
}

void* memPoolAlloc(MemPool* pool, size_t size) {
    void* data;
    sem_wait(&pool->mutex);

    if (pool->size < pool->capacity) {
        data = pool->data[pool->size];
        pool->data[pool->size] = NULL;
        pool->size++;
    } else {
        data = calloc(1, size);
        if (!data) {
            logError("Failed to allocate memory from the system");
            sem_post(&pool->mutex);
            return NULL;
        }
    }

    sem_post(&pool->mutex);
    return data;
}

void memPoolFree(MemPool* pool, void* data) {
    sem_wait(&pool->mutex);

    if (data) {
        pool->data[--pool->size] = data;
    }

    sem_post(&pool->mutex);
}

