['```c
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>

typedef struct {
    int id;
    double temperature;
    char location[50];
    float humidity;
} environmental_data;

struct node {
    environmental_data data;
    struct node* next;
};

void create_arrays(int* ids, double* temperatures, char* locations, float* humidity, int* num_elements) {
    *ids = (int*)malloc(*num_elements * sizeof(int));
    *temperatures = (double*)malloc(*num_elements * sizeof(double));
    *locations = (char*)calloc(*num_elements, 50); // initialize to zeros
    *humidity = (float*)malloc(*num_elements * sizeof(float));
}

void push(struct node** head, environmental_data data) {
    struct node* new_node = (struct node*)malloc(sizeof(struct node));
    new_node->data = data;
    new_node->next = (*head);
    (*head) = new_node;
}

void filter_data(struct node** head, double temperature_threshold, float humidity_threshold, int* num_elements) {
    struct node *current = *head, *previous = NULL;
    int i = 0;

    while (current != NULL && i < *num_elements) {
        if (current->data.temperature > temperature_threshold && current->data.humidity > humidity_threshold) {
            previous = current;
            current = current->next;
            i++;
        } else {
            struct node* temp = current->next;
            previous->next = temp;
            current->next = NULL; // detach the node from the list
            current = NULL; // mark the current node as deleted
            i--;
        }
    }
    *num_elements = i;
}

int main() {
    const int num_elements = 1000;
    int* ids;
    double* temperatures;
    char* locations;
    float* humidity;
    int actual_elements = 0;

    create_arrays(ids, temperatures, locations, humidity, &actual_elements);

    // Assume you have a function get_realtime_data() that returns an environmental_data structure with temperature and humidity filtered.

    struct node* head = NULL;

    for (int i = 0; i < num_elements; ++i) {
        environmental_data data = get_realtime_data();
        push(&head, data);
    }

    filter_data(&head, 25.0, 60.0, &actual_elements);

    // Process the filtered data here...

    free(ids);
    free(temperatures);
    free(locations);
    free(humidity);

    struct node* current = head;
    while (current != NULL) {
        struct node* temp = current->next;
        free(current);
        current = temp;
    }

    return 0;
}
