['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <math.h>

typedef struct {
    int id;
    double temperature;
    char location[32];
    float humidity;
} environmental_data;

struct node {
    environmental_data data;
    struct node *next;
};

struct cache {
    int capacity;
    struct node** cache_array;
};

void init_cache(struct cache* cache, int capacity) {
    cache->capacity = capacity;
    cache->cache_array = calloc(cache->capacity, sizeof(struct node*));
}

int cache_index(struct cache* cache, environmental_data data) {
    int hash = (hash64((uint64_t)&data, sizeof(data)) % cache->capacity);
    for (int i = hash; i < cache->capacity; ++i) {
        if (!cache->cache_array[i]) {
            return i;
        }
        if (memcmp(&cache->cache_array[i]->data, &data, sizeof(data))) {
            continue;
        }
        return i;
    }
    for (int i = 0; i < hash; ++i) {
        if (!cache->cache_array[i]) {
            cache->cache_array[i] = malloc(sizeof(struct node));
            memcpy(&cache->cache_array[i]->data, &data, sizeof(data));
            return i;
        }
        if (memcmp(&cache->cache_array[i]->data, &data, sizeof(data))) {
            continue;
        }
        swap(cache->cache_array[hash], cache->cache_array[i]);
        return hash;
    }
    printf("Cache is full, evicting least recently used data.\n");
    // Implement LRU eviction strategy here.

    return hash;
}

void* hash64(const void *key, size_t length) {
    const uint64_t k = *(const uint64_t *)key;
    return (void*)((k >> 32) ^ k);
}

void swap(struct node *a, struct node *b) {
    struct node temp = *a;
    *a = *b;
    *b = temp;
}

void read_data_feed(double* buffer, int size, int rate_limit) {
    static int counter = 0;
    static double last_read = 0.0;
    if (counter >= rate_limit) {
        sleep(1.0 - (counter - rate_limit));
        counter = 0;
    }
    counter++;
    for (int i = 0; i < size; ++i) {
        buffer[i] = rand() / (double)RAND_MAX * 100 + last_read;
    }
    last_read += 1.0 / rate_limit;
}

void filter_data(double* temperatures, float* humidities, int size, double threshold) {
    int filtered_size = 0;
    for (int i = 0; i < size; ++i) {
        if (temperatures[i] > threshold && humidities[i] >= 0.0) {
            temperatures[filtered_size] = temperatures[i];
            humidities[filtered_size] = humidities[i];
            filtered_size++;
        }
    }
}

void create_arrays(int** ids, double** temperatures, char** locations, float* humidities, environmental_data** data) {
    *ids = malloc(5 * sizeof(int));
    *temperatures = malloc(5 * sizeof(double));
    *locations = calloc(5, 32);
    *humidities = malloc(5 * sizeof(float));
    *data = malloc(5 * sizeof(environmental_data));
}

void populate_arrays(int** ids, double* temperatures, char* locations, float* humidities, environmental_data** data) {
    struct cache cache;
    init_cache(&cache, 1024);
    int rate_limit = 1000;
    double buffer[5];
    double threshold = 80.0;

    create_arrays(ids, temperatures, locations, humidities, data);

    for (int i = 0; i < 100000; ++i) {
        read_data_feed(buffer, 5, rate_limit);
        filter_data(buffer, humidities, 5, threshold);

        struct node* current = NULL;
        for (int j = 0; j < 5; ++j) {
            int index = cache_index(&cache, data[j]);
            if (!current) {
                current = &cache.cache_array[index];
            }
            current->data = *data[j];
            current->next = malloc(sizeof(struct node));
            current = current->next;
        }
    }
}
```

