Record* createArray(size_t size) {
    if (!memoryPool) {
        memoryPool = mmap(NULL, MAX_MEMORY_USAGE, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        if (memoryPool == MAP_FAILED) {
            return NULL;
        }
    }

    size_t poolSize = MAX_MEMORY_USAGE - (bufferSize + numRecords * sizeof(Record));
    if (poolSize < size * sizeof(Record)) {
        // Reallocate memory pool when it's full or nearly full
        void* newPool = mmap(NULL, 2 * MAX_MEMORY_USAGE, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        if (newPool == MAP_FAILED) {
            return NULL;
        }
        memoryPool = newPool;
    }

    Record* array = (Record*)((char*)memoryPool + bufferSize);
    bufferSize += size * sizeof(Record);
    return array;
}

