struct MemoryPool* createMemoryPool(size_t num_records) {
    struct MemoryPool *pool = (struct MemoryPool*) malloc(sizeof(struct MemoryPool));
    pool->lock = PTHREAD_MUTEX_INITIALIZER;
    pool->total_records = 0;

    // Calculate required memory for each component
    size_t record_size = sizeof(struct Record);
    size_t offset_size = sizeof(long);
    size_t key_size = sizeof(int);

    // Allocate memory for records, offsets, and keys
    pool->records = (struct Record*) malloc(num_records * record_size);
    pool->offsets = (long*) calloc(num_records + 1, offset_size);
    pool->keys = (int*) malloc(num_records * key_size);

    // Initialize arrays with random values within a specified range
    srand(time(NULL));
    for (size_t i = 0; i < num_records; ++i) {
        pool->records[i].id = i;
        pool->records[i].offset = rand() % (num_records * 2);
        pool->records[i].value = ((double)rand() / RAND_MAX) * 100.0;
        pool->keys[i] = i;
        pool->offsets[i + 1] = pool->offsets[i] + record_size;
    }

    // Set capacity and used variables based on the number of records provided
    pool->capacity = num_records;
    pool->used = num_records;

    return pool;
}

struct Record* getRandomRecord(struct MemoryPool *pool, int key) {
    size_t index = (size_t)(key % pool->used);
    while (pool->keys[index] != key && index < pool->used)
        index = (index + 1) % pool->used;

    return &pool->records[index];
}

void freeMemoryPool(struct MemoryPool *pool) {
    free(pool->records);
    free(pool->keys);
    free(pool->offsets);
    free(pool);
}
