    config_entry* data;
    size_t capacity;
    size_t used;
};

void* mem_pool_alloc(struct mem_pool* pool, size_t size) {
    if (pool->used + size > pool->capacity) {
        void* new_data = realloc(pool->data, pool->capacity * 2);
        if (!new_data) return NULL;
        pool->data = new_data;
        pool->capacity *= 2;
    }
    void* result = &pool->data[pool->used];
    pool->used += size;
    return result;
}

void mem_pool_free(struct mem_pool* pool) {
    free(pool->data);
    pool->capacity = 0;
    pool->used = 0;
}

