    *offsets = (long*)malloc(offsetSize * sizeof(long));
    if (*offsets == NULL) {
        fprintf(stderr, "Memory allocation for offsets failed.\n");
        exit(EXIT_FAILURE);
    }

    *keys = (int*)malloc(keySize * maxRecords * sizeof(int));
    if (*keys == NULL) {
        fprintf(stderr, "Memory allocation for keys failed.\n");
        free(*offsets);
        exit(EXIT_FAILURE);
    }

    *records = (Record*)calloc(maxRecords, recordSize * sizeof(Record));
    if (*records == NULL) {
        fprintf(stderr, "Memory allocation for records failed.\n");
        free(*offsets);
        free(*keys);
        exit(EXIT_FAILURE);
    }

    srand(time(NULL));
    long currentOffset = 0;
    int recordIndex = 0;

    for (size_t i = 0; i < offsetSize; ++i) {
        (*offsets)[i] = currentOffset;
        currentOffset += maxRecords;
    }

    for (int r = 0; r < maxRecords; ++r) {
        int keyToFind = -1;
        if (!allowDuplicates) {
            do {
                keyToFind = rand() % keySize;
            } while (keyToFind == (*keys)[recordIndex]);
        }

        (*keys)[recordIndex] = keyToFind;
        records[recordIndex++]->key = keyToFind;
        records[recordIndex - 1]->value = rand() % (maxValue - minValue + 1) + minValue;
    }
}
