#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    char *name;
    int timestamp_index;
    double duration;
} Event;

void log_error(const char *message) {
    fprintf(stderr, "%s\n", message);
    exit(EXIT_FAILURE);
}

int compare_events(const void *a, const void *b) {
    return (*(Event *)a)->timestamp_index - *(Event *)b)->timestamp_index;
}

void initialize_data_structures(size_t longs, size_t strings, size_t events, size_t flags, int seed, bool allow_duplicates, Event **events, int *flags, char **strings, long *longs) {
    srand(seed);
    Event *event_array = malloc(events * sizeof(Event));
    if (!event_array) {
        log_error("Memory allocation for Event array failed.");
    }

    int *unique_names = calloc(events, sizeof(int));
    if (!unique_names) {
        log_error("Memory allocation for unique names array failed.");
    }

    for (size_t i = 0; i < events; ++i) {
        char name[256];
        sprintf(name, "%zu", i);
        Event *event = &event_array[i];
        event->name = malloc(strlen(name) + 1);
        if (!event->name) {
            log_error("Memory allocation for Event name failed.");
        }
        strcpy(event->name, name);
        unique_names[i] = i;
        event->timestamp_index = rand() % (long)longs;
        event->duration = (double)(rand() % 100 + 50) / 100.0; // Random value within [0.5, 1.5)

        if (!allow_duplicates && i != 0) {
            for (size_t j = 0; j < i; ++j) {
                if (!strcmp(event->name, event_array[j].name)) {
                    log_error("Event names must be unique.");
                }
            }
        }
    }

    qsort(event_array, events, sizeof(Event), compare_events);

    for (size_t i = 0; i < events; ++i) {
        flags[unique_names[i]] = i;
        strings[unique_names[i]] = event_array[i].name;
        longs[event_array[i].timestamp_index] = i;
    }

    free(unique_names);
}
