    sscanf(argv[3], "%zu%zu%zu%zu", &timestamp_size, &string_size, &event_size, &flag_size);

    long *timestamps = malloc(timestamp_size * sizeof(long));
    if (!timestamps) {
        perror("Error allocating memory for timestamps");
        fclose(in);
        fclose(out);
        return 1;
    }

    char **strings = malloc(string_size * sizeof(char*));
    if (!strings) {
        perror("Error allocating memory for strings");
        free(timestamps);
        fclose(in);
        fclose(out);
        return 1;
    }

    Event **events = malloc(event_size * sizeof(Event*));
    if (!events) {
        perror("Error allocating memory for events");
        free(timestamps);
        free(strings);
        fclose(in);
        fclose(out);
        return 1;
    }

    int *flags = calloc(flag_size, sizeof(int));
    if (!flags) {
        perror("Error allocating memory for flags");
        free(timestamps);
        free(strings);
        free(events);
        fclose(in);
        fclose(out);
        return 1;
    }

    srand(time(NULL));

    int events_count = 0;
    while ((c = fgetc(in)) != EOF) {
        Event new_event = {};
        parse_rule(&c, events, &events_count, flags);
        if (events_count >= event_size || events[events_count - 1]->timestamp_index == new_event.timestamp_index) {
            if (!(*(argv[4]) - '0')) {
                fprintf(stderr, "Error: Duplicate name encountered\n");
                free(timestamps);
                free(strings);
                free(events);
                free(flags);
                fclose(in);
                fclose(out);
                return 1;
            }
        } else {
            events[events_count++] = new_event;
        }
    }

    qsort(events, events_count, sizeof(Event), (int (*)(const void *, const void *))compare_events);

    for (int i = 0; i < events_count; ++i) {
        fprintf(out, "%s %ld %.6f\n", events[i]->name, events[i]->timestamp_index, events[i]->duration);
    }

    free(timestamps);
    free(strings);
    free(events);
    free(flags);
    fclose(in);
    fclose(out);

    return 0;
}

int compare_events(const void *a, const void *b) {
    Event *event_a = (Event *)a;
    Event *event_b = (Event *)b;

    if (event_a->timestamp_index < event_b->timestamp_index)
        return -1;
    else if (event_a->timestamp_index > event_b->timestamp_index)
        return 1;

    return 0;
}
