#include <pthread.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int key;
    long offset;
    double value;
} record;

struct memory_pool {
    size_t capacity;
    size_t current_allocated;
    record* records;
};

struct memory_pool* create_memory_pool(size_t num_records) {
    struct memory_pool *mp = malloc(sizeof(struct memory_pool));
    mp->capacity = num_records;
    mp->current_allocated = 0;
    mp->records = calloc(num_records, sizeof(record));
    return mp;
}

void* get_next_available_record(struct memory_pool *mp) {
    void* ret = NULL;
    pthread_mutex_lock(&mp->lock);
    for (size_t i = 0; i < mp->capacity; ++i) {
        if (!mp->records[i].key) {
            ret = &mp->records[i];
            break;
        }
    }
    pthread_mutex_unlock(&mp->lock);
    return ret;
}

void init_record(record *r, size_t idx) {
    r->key = rand() % 1000 + 1;
    r->offset = idx;
    r->value = (double)rand() / RAND_MAX;
}

void initialize_memory_arrays(size_t num_records, size_t* key_array, long* offset_array) {
    key_array = malloc(num_records * sizeof(int));
    offset_array = malloc(num_records * sizeof(long));
}

struct memory_pool* create_memory_management_system(size_t num_records) {
    struct memory_pool *mp = create_memory_pool(num_records);
    record *records = mp->records;
    size_t *key_array, *offset_array;
    initialize_memory_arrays(num_records, key_array, offset_array);

    pthread_mutex_init(&mp->lock, NULL);
    for (size_t i = 0; i < num_records; ++i) {
        init_record(&records[i], i);
        key_array[i] = records[i].key;
        offset_array[i] = records[i].offset;
    }

    return mp;
}

record* get_random_record(struct memory_pool *mp, size_t key) {
    pthread_mutex_lock(&mp->lock);
    record* ret = NULL;
    for (size_t i = 0; i < mp->capacity; ++i) {
        if (mp->records[i].key == key) {
            ret = &mp->records[i];
            break;
        }
    }
    pthread_mutex_unlock(&mp->lock);
    return ret;
}
