MemoryBlock* create_memory_block(size_t records_count) {
    MemoryBlock *memory_block = (MemoryBlock *)malloc(sizeof(MemoryBlock));
    if (!memory_block) return NULL;

    memory_block->capacity = records_count;
    memory_block->records = (Record *)calloc(records_count, sizeof(Record));
