        memory_block->records[i].id = rand() % MAX_ID;
        memory_block->records[i].timestamp = rand();
        memory_block->records[i].value = rand() / (float)(RAND_MAX + 1);
    }

    memory_block->next = NULL;

    return memory_block;
}
