2. **Dynamic Collection**

```c
#include <pthread.h>
#include <stdbool.h>

static MemoryBlock *memory_pool = NULL;
static size_t total_records = 0;
static pthread_mutex_t pool_mutex = PTHREAD_MUTEX_INITIALIZER;

MemoryBlock* get_memory_block() {
    pthread_mutex_lock(&pool_mutex);
    MemoryBlock *current = memory_pool;
    MemoryBlock *prev = NULL;

    while (current != NULL) {
        if (current->capacity == 0) {
            prev = current;
            current = current->next;
        } else {
            break;
        }
    }

    if (prev != NULL) {
        prev->next = current->next;
        current->next = memory_pool;
        memory_pool = current;
    } else {
        memory_pool = current;
    }

    pthread_mutex_unlock(&pool_mutex);

    return memory_pool;
}

Record* allocate_record(MemoryBlock *memory_block) {
    if (memory_block->capacity == 0) return NULL;

    total_records++;

    Record *record = &memory_block->records[--memory_block->capacity];
    record->id = rand() % MAX_ID;
    record->timestamp = rand();
    record->value = rand() / (float)(RAND_MAX + 1);

    return record;
}
