} Record;

// Memory pool structure
typedef struct MemoryPool {
    Record *records;
    size_t capacity;
    size_t count;
    pthread_mutex_t lock;
} MemoryPool;

// Custom memory pool functions
MemoryPool* memory_pool_init(size_t num_records) {
    MemoryPool *pool = malloc(sizeof(MemoryPool));
    pool->capacity = num_records;
    pool->count = 0;
    pool->records = malloc(num_records * sizeof(Record));
    for (size_t i = 0; i < num_records; ++i) {
