        pool->records[i].offset = i;
        pool->records[i].value = (double)(rand() % 1000 + 1) / 10.0;
    }
    pthread_mutex_init(&pool->lock, NULL);
    return pool;
}

Record* memory_pool_alloc(MemoryPool *pool) {
    if (pool->count >= pool->capacity) {
        // Handle memory allocation failures gracefully
        fprintf(stderr, "Out of memory.\n");
        return NULL;
    }

    pthread_mutex_lock(&pool->lock);
    Record* record = &pool->records[pool->count];
    ++pool->count;
    pthread_mutex_unlock(&pool->lock);

    return record;
}

void memory_pool_free(MemoryPool *pool, Record *record) {
