    pthread_mutex_lock(&pool->lock);
    // Ensure thread safety and minimizing fragmentation
    for (size_t i = record->offset + 1; i < pool->count; ++i) {
        pool->records[i - 1] = pool->records[i];
    }
    --pool->count;
    pthread_mutex_unlock(&pool->lock);
}

// Dynamic record collection structure
