    long *offsets;
    int *keys;
    MemoryPool *pool;
} RecordCollection;

RecordCollection* record_collection_init(size_t num_records) {
    RecordCollection *collection = malloc(sizeof(RecordCollection));
    collection->offsets = calloc(num_records, sizeof(long));
    collection->keys = calloc(num_records, sizeof(int));
    collection->pool = memory_pool_init(num_records);
    return collection;
}

void record_collection_add(RecordCollection *collection, Record *record) {
    size_t index = binary_search(collection->keys, collection->offsets, collection->count, record->key);
    if (index >= collection->count) {
        // Handle memory allocation failures gracefully
        fprintf(stderr, "Out of memory.\n");
        return;
    }

    pthread_mutex_lock(&collection->pool->lock);
    Record* new_record = memory_pool_alloc(collection->pool);
    if (!new_record) {
        // Handle memory allocation failures gracefully
        fprintf(stderr, "Out of memory.\n");
        pthread_mutex_unlock(&collection->pool->lock);
        return;
    }

    new_record->key = record->key;
    new_record->offset = collection->offsets[index];
    collection->keys[index] = record->key;
    collection->offsets[index] = new_record->offset;
    pthread_mutex_unlock(&collection->pool->lock);
}

Record* record_collection_get(RecordCollection *collection, int key) {
    size_t index = binary_search(collection->keys, collection->offsets, collection->count, key);
    if (index >= collection->count) return NULL;
    return &collection->pool->records[collection->offsets[index]];
}

// Helper function for finding the insertion index in a sorted array
size_t binary_search(int *array, long *indices, size_t count, int key) {
    size_t left = 0;
    size_t right = count - 1;

    while (left <= right) {
        size_t mid = (left + right) / 2;
        if (array[mid] == key) return indices[mid];

        if (array[mid] < key) left = mid + 1;
        else right = mid - 1;
    }

    return left;
}
