// Function to serialize 'records' array into a binary file
void serialize(const char *filename, const record *records, size_t num_records) {
    FILE *fp = fopen(filename, "wb");
    if (!fp) return;

    fwrite(&num_records, sizeof(size_t), 1, fp);
    for (size_t i = 0; i < num_records; ++i) {
        fwrite(&records[i].value, sizeof(int), 1, fp);
    }
    fclose(fp);
}

// Function to deserialize a binary file into 'records' array
void deserialize(const char *filename, record **records, size_t *num_records) {
    FILE *fp = fopen(filename, "rb");
    if (!fp) return;

    fread(num_records, sizeof(size_t), 1, fp);
    *num_records = *num_records < 1 ? 0 : *num_records;

    *records = malloc(*num_records * sizeof(record));
    if (!*records) {
        fprintf(stderr, "Memory allocation failure.\n");
        fclose(fp);
        return;
    }

    for (size_t i = 0; i < *num_records; ++i) {
        fread(&(*records)[i].value, sizeof(int), 1, fp);
    }
    fclose(fp);
}

// Function to initialize data structures, with concurrent support using pthreads
