        fprintf(stderr, "Memory usage exceeded.\n");
        free(records);
        return;
    }
    long *offset = malloc(offset_size);
    if (!offset) {
        fprintf(stderr, "Memory allocation failure.\n");
        free(records);
        return;
    }
    memcpy(offset, offsets, offset_size);

    int *key = (int *)((char *)offset + offset_size);
    memset(key, 0, key_size);

