import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.time.Instant;
import java.util.concurrent.*;
import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;

public class HashingUtils {
    private static final Logger LOGGER = LogManager.getLogger(HashingUtils.class);
    private static final ExecutorService EXECUTOR = Executors.newFixedThreadPool(5);
    private static final ScheduledExecutorService RATE_LIMITER = Executors.newScheduledThreadPool(1);

    // Configure hashing algorithms here, e.g.,
    private static final HashAlgorithm[] HASHING_ALGORITHMS = {HashAlgorithm.MD5, HashAlgorithm.SHA256};

    public enum HashAlgorithm {
        MD5("MessageDigest.getInstance", "digest"),
        SHA256("MessageDigest.getInstance", "digest"); // Add more algorithms here as needed

        private final String constructor;
        private final String method;

        HashAlgorithm(String constructor, String method) {
            this.constructor = constructor;
            this.method = method;
        }

        public MessageDigest getInstance() throws NoSuchAlgorithmException {
            return (MessageDigest) newInstance().getConstructor(this.constructor).newInstance();
        }

        private static Class<?> newInstance() {
            try {
                return Class.forName("java.security.MessageDigest");
            } catch (ClassNotFoundException e) {
                throw new RuntimeException(e);
            }
        }

        public byte[] digest(byte[] data) {
            try {
                MessageDigest md = this.getInstance();
                md.update(data);
                return md.digest();
            } catch (NoSuchAlgorithmException e) {
                throw new RuntimeException(e);
            }
        }
    }

    public byte[] hash(String input) {
        try {
            Instant start = Instant.now();
            HashAlgorithm algorithm = HASHING_ALGORITHMS[0]; // Use the first hashing algorithm by default

            // Rate limiting here, e.g., limit to 5 requests per second:
            RATE_LIMITER.scheduleAtFixedRate(() -> {}, Duration.ofMillis(1000), Duration.ofMillis(1000));

            ByteArrayOutputStream output = new ByteArrayOutputStream();
            for (char c : input.toCharArray()) {
                output.write(c);
            }
            byte[] data = output.toByteArray();
            return algorithm.digest(data);
        } catch (Exception e) {
            LOGGER.error("Error hashing string", e);
            throw new RuntimeException(e);
        } finally {
            Instant end = Instant.now();
            long duration = Duration.between(Instant.now(), end).toMillis();
            if (duration > 100) {
                LOGGER.warn("Slow hashing time: {}", duration);
            }
        }
    }

    // Use a testing framework like JUnit to write unit tests for this method.
}
