        record_pool.base += BLOCK_SIZE;
        record_pool.avail -= BLOCK_SIZE;
        pthread_mutex_unlock(&record_pool_mutex);
        return ret;
    }
    pthread_mutex_unlock(&record_pool_mutex);

    void* ret = malloc(BLOCK_SIZE);
    if (!ret) {
