            }
            md5Cache.putIfAbsent(input, hashtext);
            return hashtext;
        } catch (NoSuchAlgorithmException | UnsupportedEncodingException e) {
            LOGGER.error("Error calculating MD5", e);
            throw new RuntimeException(e);
        }
    }

