typedef struct Event {
    int timestamp_index;
    char *name;
} Event;

void process_dataset(size_t dataset_size, size_t *offsets, size_t *keys, size_t max_offsets, size_t max_keys, bool allow_duplicates, bool sort) {
    if (dataset_size > max_offsets || dataset_size > max_keys) {
        fprintf(stderr, "Memory limit exceeded\n");
        return;
    }

    Event *events = malloc(dataset_size * sizeof(Event));
    if (!events) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    size_t *offsets_arr = malloc(max_offsets * sizeof(size_t));
    if (!offsets_arr) {
        free(events);
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    size_t *keys_arr = malloc(max_keys * sizeof(size_t));
    if (!keys_arr) {
        free(events);
        free(offsets_arr);
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    size_t offset_index = 0;
    size_t key_index = 0;

    for (size_t i = 0; i < dataset_size; ++i) {
        events[i].timestamp_index = keys[key_index];
        events[i].name = malloc(strlen(offsets[offset_index]) + 1);
        if (!events[i].name) {
            free(events);
            free(offsets_arr);
            free(keys_arr);
            fprintf(stderr, "Memory allocation failed\n");
            return;
        }
        strcpy(events[i].name, offsets[offset_index]);

        if (key_index >= max_keys || offset_index >= max_offsets) {
            free(events);
            free(offsets_arr);
            free(keys_arr);
            fprintf(stderr, "Memory limit exceeded\n");
            return;
        }

        if (!allow_duplicates && offsets[offset_index] == offsets_arr[key_index]) {
            fprintf(stderr, "Duplicate names encountered. Names must be unique (unless allow_duplicates is set to true)\n");
            free(events);
            free(offsets_arr);
            free(keys_arr);
            return;
        }

        offsets_arr[key_index] = offsets[offset_index];
        keys_arr[key_index++] = i;
        offset_index++;
    }

    if (sort) {
        qsort(events, dataset_size, sizeof(Event), (int (*)(const void *, const void *))compare);
    }
}

int compare(const void *a, const void *b) {
    return ((Event *) a)->timestamp_index - ((Event *) b)->timestamp_index;
}
