void traverse_and_update(Node** head, double min, double max, int length) {
    for (int i = 0; *head && i < length; ++i) {
        Node* current = *head;
        *head = (*head)->next;
        current->value += ((double)rand() / RAND_MAX) * (max - min) + min;
    }
}

void free_list(Node** head) {
    if (!*head) return;
    Node *current = *head, *temp;
    while (current != NULL) {
        temp = current;
        current = current->next;
        free(temp);
    }
    *head = NULL;
}

Node* dynamic_array_to_linked_list(double* arr, int size) {
    Node *head = NULL, *current = NULL;
    for (int i = 0; i < size; ++i) {
        current = create_node(arr[i]);
        if (!head) head = current;
        else {
            current->next = head;
            head = current;
        }
    }
    return head;
}
