    table.size = size;
    table.count = 0;
    table.keys = calloc(size, sizeof(unsigned long));
    table.records = malloc(sizeof(unsigned long*) * size);
    for (int i = 0; i < size; ++i) {
        table.records[i] = NULL;
    }
    pthread_mutex_init(&table.mutex, NULL);
    return table;
}

void insert(HashTable* table, int key, Record* record) {
    unsigned long index = hash(key, table->size);
    pthread_mutex_lock(&table->mutex);
    while (table->records[index] && table->keys[table->records[index][0]] == key) {
        ++index %= table->size;
    }
    if (!table->records[index]) {
        table->count++;
    }
    table->records[index] = (unsigned long*) malloc(sizeof(unsigned long) * 2);
    table->keys[table->count - 1] = key;
    table->records[index][0] = table->count - 1;
    table->records[index][1] = (unsigned long)record;
    pthread_mutex_unlock(&table->mutex);
}

Record* find(HashTable* table, int key) {
    unsigned long index = hash(key, table->size);
    Record* record = NULL;
    pthread_mutex_lock(&table->mutex);
    for (int i = index; ; ++i %= table->size) {
        if (!table->records[i]) {
            break;
        }
        if (table->keys[table->records[i][0]] == key) {
            record = (Record*)table->records[i][1];
            break;
        }
    }
    pthread_mutex_unlock(&table->mutex);
    return record;
}

