        return NULL;
    }
    record->key = 0;
    record->offset = 0;
    record->precision_value = rand() / (double)RAND_MAX;
    return record;
}

void update(Node** head, HashTable* table, unsigned long max_records) {
    if (!head || !*head) {
        return;
    }
    Record* records[3];
    for (int i = 0; i < 3; ++i) {
        records[i] = create_record();
        if (!records[i]) {
            return;
        }
    }
    long offsets[3];
    int keys[3];
    double* precisions[3] = {NULL};
    for (int i = 0; i < 3; ++i) {
        keys[i] = rand() % max_records;
        Record* record = find(table, keys[i]);
        if (!record) {
            continue;
        }
        offsets[i] = record->offset + record->key + i;
        precisions[i] = &(record->precision_value);
    }
