        if (!records[i]) {
            continue;
        }
        records[i]->key = keys[i];
        records[i]->offset = offsets[i];
        *precisions[i] += rand() / (double)RAND_MAX;
    }
    for (int i = 0, j = 3; i < j; ++i, --j) {
        if (!records[i]) {
            continue;
        }
        Record* current = records[i];
        Node** next_node = &(*head);
        while (*next_node && (current->offset < (*next_node)->offset)) {
            next_node = &((*next_node)->next);
        }
        current->next = *next_node;
        *next_node = current;
    }
}

void free_memory(Node** head, HashTable table) {
    if (!head || !*head) {
        return;
    }
    Node* temp = NULL;
    for (Node* current = *head; current; current = temp) {
        temp = current->next;
        free(current);
    }
    for (int i = 0; i < table.size; ++i) {
        unsigned long* record = table.records[i];
        if (!record) {
            continue;
        }
        free(table.records[i]);
    }
    free(table.keys);
    free(table.records);
    pthread_mutex_destroy(&table.mutex);
}

