// Hash table structure for efficient lookup of identifiers
typedef struct {
    size_t capacity;
    size_t size;
    uint32_t *keys;
    void **values;
    pthread_mutex_t lock;
} hash_table;

void init_hash_table(hash_table *ht, size_t capacity) {
    ht->capacity = capacity;
    ht->size = 0;
    ht->keys = calloc(capacity, sizeof(uint32_t));
    ht->values = mmap(NULL, capacity * sizeof(void*), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    assert(ht->keys && ht->values);
    pthread_mutex_init(&ht->lock, NULL);
}

void destroy_hash_table(hash_table *ht) {
    munmap(ht->values, ht->capacity * sizeof(void*));
    free(ht->keys);
    pthread_mutex_destroy(&ht->lock);
}

uint32_t hash(const char *str, size_t len) {
    uint32_t hash = 5381;
    for (size_t i = 0; i < len; ++i)
        hash = ((hash << 5) + hash) + str[i];
    return hash % ht->capacity;
}

void insert_ht(hash_table *ht, const void *key, const void *value) {
    pthread_mutex_lock(&ht->lock);
    size_t index = hash((const char *) key, strlen(key));
    while (ht->keys[index] != 0 && ht->keys[index] != key) ++index %= ht->capacity;

    if (ht->keys[index] == 0) {
        ht->keys[index] = *(const uint32_t *) key;
        ht->values[index] = value;
        ht->size++;
    }
    pthread_mutex_unlock(&ht->lock);
}

const void *lookup_ht(const hash_table *ht, const void *key) {
    pthread_mutex_lock(&ht->lock);
    size_t index = hash((const char *) key, strlen(key));
    while (ht->keys[index] != 0 && ht->keys[index] != key) ++index %= ht->capacity;

    if (ht->keys[index] == *(const uint32_t *) key) {
        const void *value = ht->values[index];
        pthread_mutex_unlock(&ht->lock);
        return value;
    } else {
        pthread_mutex_unlock(&ht->lock);
        return NULL;
    }
}

// Function to update the linked list (called from a separate thread)
void update_list(entry **head, size_t max_entries) {
    entry *curr = *head;
    for (size_t i = 0; i < max_entries && curr != NULL; ++i) {
        if (!curr->status) {
            size_t len = strlen(curr->str);
            curr->status += len;
            pthread_mutex_lock(&curr->next_mutex);
            curr = curr->next;
            pthread_mutex_unlock(&curr->next_mutex);
        } else {
            curr = curr->next;
        }
    }
}

// Define the custom entry structure and functions to handle memory allocation and traversal
typedef struct entry {
    char str[128];
    int status;
    pthread_mutex_t next_mutex;
    struct entry *next;
} entry;

void init_entry(entry **entry) {
    *entry = malloc(sizeof(struct entry));
    (*entry)->status = 0;
    pthread_mutex_init(&(*entry)->next_mutex, NULL);
    (*entry)->next = NULL;
}

// Function to implement the main task
void my_function(size_t max_entries) {
    hash_table ht;
    init_hash_table(&ht, 1024);
    entry *head = NULL;
    for (size_t i = 0; i < max_entries; ) {
        entry *new_entry = malloc(sizeof(struct entry));
        if (!new_entry) {
            fprintf(stderr, "Memory allocation error\n");
            break;
        }
        init_entry(&new_entry->next);

        strcpy(new_entry->str, rand_string(10));
        new_entry->status = 0;
        pthread_mutex_init(&new_entry->next_mutex, NULL);
        new_entry->next = head;
        head = new_entry;

        void *id = lookup_ht(&ht, &new_entry->str);
        if (id) {
            free(new_entry);
            --i;
            if (!++i % 20) {
                fprintf(stderr, "Potential loop in random value generation\n");
                break;
            }
        } else {
            insert_ht(&ht, &new_entry->str, new_entry);
            ++i;
        }
    }

    pthread_t threads[max_entries];
    for (size_t i = 0; i < max_entries; ++i) {
        if (pthread_create(&threads[i], NULL, update_list, &head)) {
            fprintf(stderr, "Thread creation error\n");
            break;
        }
    }

    // Wait for all threads to finish
    for (size_t i = 0; i < max_entries; ++i) {
        pthread_join(threads[i], NULL);
    }

    destroy_hash_table(&ht);

    free(head);
}
