import json
import copy
import random
import hashlib
from collections import defaultdict
from concurrent.futures import ThreadPoolExecutor, as_completed

def rand_string(length):
    letters = 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789'
    result_str = ''.join(random.choice(letters) for _ in range(length))
    return result_str

def parse_json(json_obj, id_field='id', data_field='data'):
    id_hash = defaultdict(int)
    processed_ids = set()
    data_dict = copy.deepcopy({})

    def validate_and_process(obj):
        if isinstance(obj, dict):
            for key, value in obj.items():
                if key == id_field:
                    processed_id = hashlib.sha1(key.encode()).hexdigest()
                    if processed_id in processed_ids or id_hash[processed_id] > 0:
                        return False
                    else:
                        processed_ids.add(processed_id)
                        id_hash[processed_id] = 1
                elif validate_and_process(value):
                    data_dict[key] = value
                else:
                    return False
            return True, data_dict
        elif isinstance(obj, list):
            results = [validate_and_process(item) for item in obj]
            valid_count, merged_data = sum((res[0] for res in results)), {}
            if valid_count == len(results):
                for key, value in data_dict.items():
                    merged_data[key] = value
                for res in results:
                    if res[0]:
                        merged_data.update(res[1])
            return valid_count > 0, merged_data
        else:
            return True, obj

    return validate_and_process(json.loads(json_obj))

def process_batch(json_objects):
    data = defaultdict(list)
    with ThreadPoolExecutor() as executor:
        futures = [executor.submit(parse_json, json_obj, id_field, data_field) for json_obj in json_objects]
        for future in as_completed(futures):
            success, result = future.result()
            if success:
                data[result[id_field]].append(result[data_field])
    return dict(data)
