    return head == NULL;
}

Node* insert_at(Node** head, int pos, double val) {
    if (pos < 0) {
        fprintf(stderr, "Invalid position: should be non-negative\n");
        return NULL;
    }

    Node* new_node = create_node(val, pos);
    if (!new_node) {
        return NULL;
    }

    Node* current = *head;
    int i = 0;

    // Insert at the beginning of the list
    if (pos == 0) {
        new_node->next = current;
        *head = new_node;
        return new_node;
    }

    // Traverse the list to find the correct position for insertion
    while (current != NULL && i < pos - 1) {
        current = current->next;
        i++;
    }

    if (current == NULL) {
        fprintf(stderr, "Position out of range\n");
        free(new_node);
        return NULL;
    }

    new_node->next = current->next;
    current->next = new_node;
    return new_node;
}

