Node* create_node(double value) {
    Node* new_node = (Node*)malloc(sizeof(Node));
    if (!new_node) {
        perror("Memory allocation failed\n");
        return NULL;
    }
    new_node->value = value;
    new_node->next = NULL;
    new_node->position = -1;
    new_node->flag = 0;
    return new_node;
}

void update_nodes(Node** head, double lower, double upper, double delta) {
    srand(time(NULL));
    for (Node* current = *head; current != NULL; current = current->next) {
        if (current->value >= lower && current->value <= upper) {
            current->value += rand() / (RAND_MAX / delta + 1.0);
        }
    }
}

void insert_node(Node** head, Node* new_node) {
    if (!*head) {
        *head = new_node;
        return;
    }

    Node* current = *head;
    Node* prev = NULL;

    while (current != NULL && current->value < new_node->value) {
        prev = current;
        current = current->next;
    }

    if (prev == NULL) {
        new_node->next = *head;
        *head = new_node;
    } else {
        new_node->next = prev->next;
        prev->next = new_node;
    }
}

Node** query_range(Node* head, double lower, double upper) {
    Node* result_head = NULL;
    Node** result_tail = &result_head;

    for (Node* current = head; current != NULL; current = current->next) {
        if (current->value >= lower && current->value <= upper) {
            *result_tail = current;
            result_tail = &((*result_tail)->next);
        }
    }
    *result_tail = NULL;
    return result_head;
}

void serialize(Node* head, FILE* file) {
    for (Node* current = head; current != NULL; current = current->next) {
        fwrite(&current->value, sizeof(double), 1, file);
        fwrite(&current->position, sizeof(int), 1, file);
        fwrite(&current->flag, sizeof(int), 1, file);
    }
}

void deserialize(Node** head, FILE* file) {
    while (!feof(file)) {
        Node* new_node = create_node(0.0);
        if (!new_node) break;

        fread(&new_node->value, sizeof(double), 1, file);
        fread(&new_node->position, sizeof(int), 1, file);
        fread(&new_node->flag, sizeof(int), 1, file);

        if (*head) {
            Node* current = *head;
            Node* prev = NULL;

            while (current != NULL && current->value < new_node->value) {
                prev = current;
                current = current->next;
            }

            new_node->next = prev ? prev->next : *head;
            prev ? (prev->next = new_node) : (*head = new_node);
        } else {
            *head = new_node;
        }
    }
}
