class Node {
public:
    double value;
    Node* next;
    int index;

    Node(double v, Node* n, int i) : value(v), next(n), index(i) {}
};

class List {
private:
    std::mutex mtx;
    Node* head = nullptr;
    int size = 0;

    void insertNodeSorted(Node* newNode, int position) {
        if (position <= 0 || position > size + 1) {
            throw std::out_of_range("Invalid position for insertion.");
        }

        Node* current = head;
        for (int i = 0; i < position - 1; ++i) {
            current = current->next;
        }

        newNode->next = current->next;
        current->next = newNode;
        size++;
    }

public:
    Node* findNodeByIndex(int index) const {
        if (index < 0 || index >= size) {
            throw std::out_of_range("Invalid node index.");
        }

        Node* current = head;
        for (int i = 0; i < index; ++i) {
            current = current->next;
        }
        return current;
    }

    void updateNodeValues(double min, double max) {
        std::random_device rd;
        std::mt19937 gen(rd());
        std::uniform_real_distribution<> dis(min, max);

        Node* current = head;
        for (int i = 0; i < size; ++i) {
            current->value += dis(gen);
            current = current->next;
        }
    }

    void insertNode(double value, int position) {
        std::lock_guard<std::mutex> lock(mtx);
        Node* newNode = new Node(value, nullptr, -1);
        insertNodeSorted(newNode, position);
    }

    // Other methods for querying the list within a range, logging operations, serialization/deserialization, concurrent access management, and statistical analysis can be implemented here.
};
