};

class CacheDataSource : public DataSource {
public:
    explicit CacheDataSource(size_t cacheSize, boost::lockfree::spsc_queue<std::unique_ptr<RX_UE_INFORMATION_TAG>>& queue)
        : DataSource(), _cache(cacheSize), _queue(queue) {}

    void getUEInfo(const uint32_t rnti, std::function<void(RX_UE_INFORMATION_TAG)> callback) override {
        auto it = _cache.find(rnti);
        if (it != _cache.end()) {
            callback(std::move(*it));
            return;
        }

        auto task = std::make_unique<RX_UE_INFORMATION_TAG>();
        // Fill 'task' using an external data source...

        _queue.push(std::move(task));
    }

private:
