    boost::lockfree::spsc_queue<std::unique_ptr<RX_UE_INFORMATION_TAG>>& _queue;
};

void fillPDUs(const size_t numPDUs, std::vector<NFAPI_CRC_INDICATION_PDU_T>& pduList) {
    auto rntiQueue = boost::lockfree::spsc_queue<uint32_t>();
    CacheDataSource cacheDataSource(1000, rntiQueue);

    // Connect to an external data source and fill the queue with RNTI values.

    std::unique_ptr<RX_UE_INFORMATION_TAG> task;
    uint32_t currentRnti = 0;
    for (size_t i = 0; i < numPDUs; ++i) {
        if (!rntiQueue.pop(task)) {
            // If the queue is empty, try to fetch a new RNTI from the data source.
            cacheDataSource.getUEInfo(currentRnti++, [&](RX_UE_INFORMATION_TAG info) {
                task = std::make_unique<RX_UE_INFORMATION_TAG>(info);
                rntiQueue.push(std::move(task->rnti));
            });
        } else {
            auto crcIndicationTag = generateCRCIndication(); // Generate CRC tag...
            pduList.emplace_back(std::move(*task), currentRnti, std::move(crcIndicationTag));
        }
    }
}

