// Mutex for concurrent access
pthread_mutex_t mutex;

void init_mutex() {
    pthread_mutex_init(&mutex, NULL);
}

void destroy_mutex() {
    pthread_mutex_destroy(&mutex);
}

void lock() {
    pthread_mutex_lock(&mutex);
}

void unlock() {
    pthread_mutex_unlock(&mutex);
}

void* allocate_and_init(size_t size, void** array) {
    *array = malloc(sizeof(void*) * size);
    if (*array == NULL) {
        perror("Memory allocation failed");
        exit(1);
    }
    return *array;
}

void check_memory(size_t size, void* array) {
    if (size > capacity) {
        printf("Resizing arrays due to increased dataset size\n");
        reallocate_arrays((size_t)(size * 1.5));
    }
}

void reallocate_arrays(size_t new_capacity) {
    void* temp_offsets = allocate_and_init(new_capacity, &temp_offsets);
    void* temp_keys = allocate_and_init(new_capacity, &temp_keys);
    void* temp_timestamps = allocate_and_init(new_capacity, &temp_timestamps);

    if (offsets != NULL) {
        memcpy(temp_offsets, offsets, capacity * sizeof(int));
        free(offsets);
    }
    if (keys != NULL) {
        memcpy(temp_keys, keys, capacity * sizeof(int));
        free(keys);
    }
    if (timestamps != NULL) {
        memcpy(temp_timestamps, timestamps, capacity * sizeof(time_t));
        free(timestamps);
    }

    offsets = temp_offsets;
    keys = temp_keys;
    timestamps = temp_timestamps;

    capacity = new_capacity;
}

void process_data(const int* data, size_t size) {
    lock();
    check_memory(dataset_size + size, records);
    for (size_t i = 0; i < size; ++i) {
        Record *record = &records[dataset_size + i];
        record->value = data[i];
        record->timestamp = time(NULL);
    }
    dataset_size += size;
    unlock();
}

void cleanup() {
    if (offsets != NULL) free(offsets);
    if (keys != NULL) free(keys);
    if (timestamps != NULL) free(timestamps);
    if (records != NULL) free(records);
    destroy_mutex();
}
