    if (!ptr) {
        fprintf(stderr, "Error: Out of memory\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void* safe_realloc(void *ptr, size_t new_size, size_t type_size) {
    void *tmp = realloc(ptr, new_size * type_size);
    if (!tmp) {
        fprintf(stderr, "Error: Out of memory\n");
        exit(EXIT_FAILURE);
    }
    return tmp;
}

int process_dataset(const char* url, size_t* offsets_size, size_t* keys_size, size_t* records_size) {
    void *offsets = allocate_array(*offsets_size, sizeof(long));
    void *keys = allocate_array(*keys_size, sizeof(long));
    void *records = allocate_array(*records_size, sizeof(Record));

    // Load data from external source
    FILE* file = fopen(url, "r");
    if (!file) {
        fprintf(stderr, "Error: Could not open URL %s\n", url);
        return -1;
    }

    size_t offset_idx = 0;
    size_t key_idx = 0;
    size_t record_idx = 0;
    size_t buffer_size = 4096;
    char* buffer = malloc(buffer_size);
    ssize_t bytes_read;

    while ((bytes_read = getline(&buffer, &buffer_size, file)) != -1) {
        if (offset_idx >= *offsets_size) {
            offsets = safe_realloc(offsets, (*offsets_size *= 2), sizeof(long));
        }
        if (key_idx >= *keys_size) {
            keys = safe_realloc(keys, (*keys_size *= 2), sizeof(long));
        }
        if (record_idx >= *records_size) {
            records = safe_realloc(records, (*records_size *= 2), sizeof(Record));
        }

        // Parse and store offset, key, and record data from the line
        sscanf(buffer, "%ld %ld %d", &((long*)offsets)[offset_idx], &((long*)keys)[key_idx], &((Record*)records)[record_idx].value);

        offset_idx++;
        key_idx++;
        record_idx++;
    }
    free(buffer);
    fclose(file);

    // Ensure memory usage doesn't exceed predefined limits
    if (*offsets_size > OFFSET_MAX || *keys_size > KEY_MAX || *records_size > RECORDS_MAX) {
        fprintf(stderr, "Error: Memory limit exceeded\n");
        return -1;
    }

    // Release memory when no longer needed (for partial data retrieval)
    free(offsets);
    free(keys);

    return 0;
}
