void init_dataset(size_t offset_capacity, size_t key_capacity, size_t record_capacity,
                   long* offsets, int* keys, Record* records, int min_value, int max_value) {
    offsets = realloc(offsets, offset_capacity * sizeof(long));
    keys = realloc(keys, key_capacity * sizeof(int));
    records = realloc(records, record_capacity * sizeof(Record));

    for (size_t i = 0; i < record_capacity; ++i) {
        records[i].value = min_value + rand() % (max_value - min_value + 1);
    }

    long offset = 0;
    int key;

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    for (size_t i = 0; i < record_capacity; ++i) {
        pthread_mutex_lock(&mutex);
        while ((key = offset + records[offset].value) >= key_capacity) {
            size_t new_key_capacity = key_capacity * 2;
            keys = realloc(keys, new_key_capacity * sizeof(int));
            key_capacity = new_key_capacity;
        }
        offsets[offset] = offset;
        keys[key] = i;
        offset += records[i].value + 1;
        pthread_mutex_unlock(&mutex);
    }
}

void deinit_dataset(long* offsets, int* keys, Record* records) {
    free(offsets);
    free(keys);
    free(records);
}
