void init_market_data(struct MarketData *md, size_t initial_capacity) {
    md->instruments = (Instrument **) calloc(initial_capacity, sizeof(Instrument*));
    if (!md->instruments) return;
    md->count = 0;
    md->capacity = initial_capacity;
    md->timestamps = (time_t*) malloc(sizeof(time_t) * initial_capacity);
    if (!md->timestamps) {
        free(md->instruments);
        return;
    }
    memset(md->timestamps, 0, sizeof(time_t) * initial_capacity);
    pthread_mutex_init(&md->mutex, NULL);
}

