        size_t new_capacity = md->capacity ? md->capacity * 2 : 16;
        Instrument **new_instruments = realloc(md->instruments, sizeof(Instrument*) * new_capacity);
        if (!new_instruments) return;
        md->instruments = new_instruments;
        md->timestamps = (time_t *)realloc(md->timestamps, sizeof(time_t) * new_capacity);
        if (!md->timestamps) {
            free(md->instruments);
            return;
        }
        memset(&md->timestamps[md->count], 0, sizeof(time_t));
        md->capacity = new_capacity;
    }
    Instrument *new_instrument = (Instrument *) calloc(1, sizeof(Instrument));
    if (!new_instrument) return;
    strncpy(new_instrument->symbol, symbol, 9); // Ensure string fits in the array
    new_instrument->last_price = 0.0;
    new_instrument->volume = 0UL;
    new_instrument->last_updated = 0;
    new_instrument->next = md->instruments[md->count];
    md->instruments[md->count] = new_instrument;
    md->count++;
}

void free_market_data(struct MarketData *md) {
    if (!md) return;
    for (size_t i = 0; i < md->count; ++i) {
        Instrument *current = md->instruments[i];
        while (current != NULL) {
            Instrument *temp = current;
            current = current->next;
            free(temp);
        }
    }
    free(md->instruments);
    free(md->timestamps);
    pthread_mutex_destroy(&md->mutex);
}
```

This implementation provides a MarketData structure for managing the linked list of financial instruments. The init_market_data function initializes memory for the data structure and handles potential reallocations as needed. The add_instrument function adds new instruments to the list, ensuring that memory is allocated efficiently. The free_market_data function properly frees all allocated memory upon function exit.

