#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <stdbool.h>
#include <sys/mman.h>

typedef struct LogEntry {
    int log_level;
    time_t timestamp;
    char* message;
    int ref_count;
} LogEntry;

typedef struct HashNode {
    LogEntry entry;
    unsigned long log_id;
    struct HashNode* next;
} HashNode;

typedef struct {
    HashNode** table;
    size_t capacity;
    size_t size;
    pthread_mutex_t mutex;
    unsigned long max_log_id;
} LogTable;

void log_table_init(LogTable* table, size_t capacity) {
    table->table = mmap(NULL, sizeof(HashNode*) * capacity, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (table->table == MAP_FAILED) {
        perror("mmap failed");
        exit(EXIT_FAILURE);
    }

    table->capacity = capacity;
    table->size = 0;
    table->max_log_id = 0;
    pthread_mutex_init(&table->mutex, NULL);
}

unsigned long log_id_generator(LogTable* table) {
    return ++table->max_log_id;
}

size_t hash_function(unsigned long key, size_t capacity) {
    return key % capacity;
}

void log_entry_free(LogEntry* entry) {
    free(entry->message);
    free(entry);
}

HashNode* find_log_entry(LogTable* table, unsigned long log_id) {
    size_t index = hash_function(log_id, table->capacity);
    HashNode* current = table->table[index];

    pthread_mutex_lock(&table->mutex);
    while (current != NULL && current->log_id != log_id) {
        current = current->next;
    }
    pthread_mutex_unlock(&table->mutex);

    return current;
}

void increment_ref_count(LogEntry* entry) {
    entry->ref_count++;
}

void decrement_ref_count(LogEntry* entry) {
    if (entry->ref_count > 0) {
        entry->ref_count--;
    }
}

void insert_log_entry(LogTable* table, LogEntry* entry) {
    HashNode* new_node = malloc(sizeof(HashNode));
    if (new_node == NULL) {
        perror("malloc failed");
        exit(EXIT_FAILURE);
    }

    new_node->entry = *entry;
    new_node->log_id = log_id_generator(table);
    new_node->next = NULL;

    pthread_mutex_lock(&table->mutex);
    HashNode* current = table->table[hash_function(new_node->log_id, table->capacity)];
    if (current == NULL) {
        table->table[hash_function(new_node->log_id, table->capacity)] = new_node;
    } else {
        while (current->next != NULL) {
            current = current->next;
        }
        current->next = new_node;
    }
    pthread_mutex_unlock(&table->mutex);
}
```
