   #include <stdlib.h>
   #include <pthread.h>

   typedef struct {
       void* data;
       size_t capacity;
       size_t used;
       pthread_mutex_t lock;
   } MemoryPool;

   MemoryPool* memory_pool_create(size_t initial_capacity) {
       MemoryPool* pool = malloc(sizeof(MemoryPool));
       if (!pool) return NULL;

       pool->data = malloc(initial_capacity * sizeof(void*));
       if (!pool->data) goto error;

       pool->capacity = initial_capacity;
       pool->used = 0;
       pthread_mutex_init(&pool->lock, NULL);

       return pool;

   error:
       free(pool);
       return NULL;
   }

   void* memory_pool_alloc(MemoryPool* pool) {
       pthread_mutex_lock(&pool->lock);

       if (pool->used < pool->capacity) {
           void* result = &pool->data[pool->used++];
           pthread_mutex_unlock(&pool->lock);
           return result;
       }

       void* temp = realloc(pool->data, pool->capacity * 2 * sizeof(void*));
       if (!temp) goto error;

       pool->data = temp;
       pool->capacity *= 2;
       pthread_mutex_unlock(&pool->lock);

       return &pool->data[pool->used++];

   error:
       // Handle the error, e.g., logging or error propagation
       pthread_mutex_unlock(&pool->lock);
       return NULL;
   }
