#define MAX_RECORDS 1000
#define MAX_KEYS 100

typedef struct {
    long *ptr;
    int value;
} Record;

typedef struct {
    int key;
    Record *record;
} KeyValue;

Record* initializeRecords(int size) {
    Record *records = malloc(size * sizeof(Record));
    if (!records) {
        perror("Error: Memory allocation failed");
        return NULL;
    }

    int totalSum = 0;
    for (int i = 0; i < size; ++i) {
        records[i].ptr = malloc(sizeof(long));
        if (!records[i].ptr) {
            perror("Error: Memory allocation failed");
            return NULL;
        }
        *records[i].ptr = 0;

        int randomValue = rand() % 1001;
        totalSum += randomValue;
        if (totalSum > 10000) {
            printf("Error: Sum of random values exceeds the limit\n");
            return NULL;
        }
        records[i].value = randomValue;
    }

    return records;
}

KeyValue* initializeKeysAndValues(Record *records, int size) {
    KeyValue *keysAndValues = malloc(size * sizeof(KeyValue));
    if (!keysAndValues) {
        perror("Error: Memory allocation failed");
        return NULL;
    }

    int usedKeys[MAX_KEYS] = {0};
    for (int i = 0; i < size; ++i) {
        int key = rand() % MAX_KEYS + 1;
        while (usedKeys[key - 1]) {
            key = rand() % MAX_KEYS + 1;
        }
        usedKeys[key - 1] = 1;

        keysAndValues[i].key = key;
        keysAndValues[i].record = &records[i];
    }

    return keysAndValues;
}

char* hashString(const char *str) {
    if (!str || strlen(str) == 0) {
        return "Error: Empty or invalid input string";
    }

    unsigned char digest[MD5_DIGEST_LENGTH];
    MD5_CTX ctx;
    MD5_Init(&ctx);
    MD5_Update(&ctx, str, strlen(str));
    MD5_Final(digest, &ctx);

    static char hexDigits[] = "0123456789ABCDEF";
    char result[MD5_DIGEST_LENGTH * 2];
    for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        result[i * 2] = hexDigits[(digest[i] >> 4) & 0xF];
        result[i * 2 + 1] = hexDigits[(digest[i]) & 0xF];
    }
    return &result[0];
}

void freeMemory(Record *records, KeyValue *keysAndValues) {
    for (int i = 0; i < MAX_RECORDS; ++i) {
        if (records && records[i].ptr) {
            free(records[i].ptr);
        }
    }

    if (records) {
        free(records);
    }

    for (int i = 0; i < MAX_KEYS * MAX_RECORDS; ++i) {
        if (keysAndValues && keysAndValues[i].record->ptr) {
            free(keysAndValues[i].record->ptr);
        }
        if (keysAndValues) {
            free(keysAndValues[i].record);
        }
    }

    if (keysAndValues) {
        free(keysAndValues);
    }
}

void initializeRecordsAndHashString(Record **records, KeyValue **keysAndValues, const char *str) {
    *records = initializeRecords(MAX_RECORDS);
    if (!*records) {
        return;
    }

    *keysAndValues = initializeKeysAndValues(*records, MAX_KEYS * MAX_RECORDS);
    if (!*keysAndValues) {
        freeMemory(*records, NULL);
        return;
    }

    char *hash = hashString(str);
    if (strlen(hash) > 0 && strcmp(hash, "Error")) {
        printf("Generated MD5 hash: %s\n", hash);
    }

    freeMemory(*records, *keysAndValues);
}
