#include <openssl/md5.h>

typedef struct {
    int value;
} record;

void log_array(const char* label, const void* arr, size_t len, FILE* output) {
    if (!output) return;
    fprintf(output, "%s:\n", label);
    for (size_t i = 0; i < len; ++i) {
        fprintf(output, "[%zu] %p: %d\n", i, arr + i, *(int*)(arr + i));
    }
}

void* safe_malloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        fprintf(stderr, "Error: Out of memory\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

void free_safe(void** ptr) {
    if (*ptr) {
        free(*ptr);
        *ptr = NULL;
    }
}

unsigned char* md5_hash(const char* str, size_t len) {
    unsigned char digest[MD5_DIGEST_LENGTH];
    MD5_CTX ctx;

    if (len > 0 && !str) return NULL;

    MD5_Init(&ctx);
    MD5_Update(&ctx, str, len);
    MD5_Final(digest, &ctx);

    return digest;
}

char* stringify_md5(unsigned char* hash) {
    static const char hex_chars[] = "0123456789abcdef";
    char str[MD5_DIGEST_LENGTH * 2 + 1];

    for (int i = 0; i < MD5_DIGEST_LENGTH; ++i) {
        str[2 * i] = hex_chars[(hash[i] >> 4) & 0xf];
        str[2 * i + 1] = hex_chars[(hash[i]) & 0xf];
    }
    str[MD5_DIGEST_LENGTH * 2] = '\0';

    return str;
}

long* initialize_offsets(size_t offset_count) {
    long* offsets = safe_malloc(offset_count * sizeof(*offsets));
    memset(offsets, 0, offset_count * sizeof(*offsets));
    return offsets;
}

int* initialize_keys(size_t key_count) {
    int* keys = safe_malloc(key_count * sizeof(*keys));
    return keys;
}

record* initialize_records(size_t count, size_t min_value, size_t max_value) {
    record* records = safe_malloc(count * sizeof(*records));
    srand(time(NULL));
    for (size_t i = 0; i < count; ++i) {
        records[i].value = rand() % (max_value - min_value + 1) + min_value;
    }
    return records;
}

char* initializeRecordsAndHashString(size_t offset_count, size_t key_count, size_t record_count, size_t min_value, size_t max_value, const char* input_str, bool is_debug, FILE* output) {
    long* offsets = initialize_offsets(offset_count);
    int* keys = initialize_keys(key_count);
    record* records = initialize_records(record_count, min_value, max_value);

    unsigned char* md5_hash;
    if (is_debug) {
        log_array("offsets", offsets, offset_count, output);
        log_array("keys", keys, key_count, output);
        log_array("records", records, record_count, output);
    }

    md5_hash = md5_hash(input_str ? input_str : "", strlen(input_str ? input_str : ""));
    if (md5_hash) {
        char* str_hash = stringify_md5(md5_hash);
        if (is_debug && !(output && !!(output->tellp() % log_interval))) {
            fprintf(output, "MD5 Hash: %s\n", str_hash);
        }
        free(md5_hash);
        return str_hash;
    }

    free_safe((void**)&offsets);
    free_safe((void**)&keys);
    free_safe((void**)&records);
    return NULL;
}
