struct IndexPointers {
    int *pointers;
    size_t size;
};

// Custom error code for memory allocation failures
#define MEMORY_ERROR 1

void log(LogLevel level, const char *message, FILE *output_file) {
    if (is_logging && level <= log_level) {
        fprintf(output_file, "[%s] %s\n", get_log_level_name(level), message);
        fflush(output_file);
    }
}

struct IndexPointers* create_index_pointers(size_t index_count) {
    struct IndexPointers *ip = malloc(sizeof(*ip));
    if (!ip) return NULL;
    ip->pointers = calloc(index_count, sizeof(*(ip->pointers)));
    if (!ip->pointers) {
        free(ip);
        return NULL;
    }
    ip->size = index_count;
    return ip;
}

DataRecord* create_record(void) {
    DataRecord *record = malloc(sizeof(*record));
    if (!record) {
        log(ERROR, "Failed to allocate memory for data record.", stderr);
        return NULL;
    }
    record->name = NULL;
    record->age = 0;
    record->salary = 0.0;
    return record;
}

void read_csv(FILE *file, DataRecord **records, struct IndexPointers *index_pointers) {
    char line[256];
    size_t record_count = 0;
    while (fgets(line, sizeof(line), file)) {
        // Parse CSV row and create a new DataRecord
        DataRecord *record = create_record();
        if (!record) break;

        char *token = strtok(line, ",");
        if (!token) continue; // Skip empty lines or malformed entries

        size_t name_len = strlen(token);
        record->name = malloc(name_len + 1);
        if (!record->name) {
            free(record);
            break;
        }
        strcpy(record->name, token);

        token = strtok(NULL, ",");
        if (!token || !isdigit(*token)) continue; // Validate age input
        record->age = atoi(token);

        token = strtok(NULL, ",");
        if (!token || *token <= 0) continue; // Validate salary input
        record->salary = atof(token);

        index_pointers->pointers[record_count] = -1;
        (index_pointers->pointers)[++(index_pointers->size)] = record_count;
        ++record_count;
    }
}

struct Stats processAndAnalyzeData(FILE *file, bool is_logging, LogLevel log_level, FILE *output_file, int log_interval, int index_count) {
    struct IndexPointers *index_pointers = create_index_pointers(index_count);
    if (!index_pointers) {
        log(ERROR, "Failed to allocate memory for index pointers.", stderr);
        return (struct Stats){0};
    }

    DataRecord **records = calloc(index_count, sizeof(*records));
    if (!records) {
        free(index_pointers->pointers);
        free(index_pointers);
        log(ERROR, "Failed to allocate memory for data records.", stderr);
        return (struct Stats){0};
    }

    read_csv(file, records, index_pointers);

    struct Stats stats = compute_statistics(records, index_count);

    free_data(records, index_count);
    free(index_pointers->pointers);
    free(index_pointers);

    return stats;
}

void free_data(DataRecord **records, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        if (records[i]) {
            free(records[i]->name);
            free(records[i]);
        }
    }
    free(records);
}
