int initializeRecordsAndHashString(size_t numRecords, size_t recordSize, size_t keyRange, char** inputStrings, size_t* inputStringsLen) {
    if (*inputStringsLen == 0 || *inputStrings == NULL) {
        return -1; // invalid input string
    }

    Record* records = malloc(numRecords * sizeof(Record));
    long* offsets = calloc(recordSize, sizeof(long));
    int* keys = calloc(keyRange, sizeof(int));

    if (!records || !offsets || !keys) {
        // memory allocation failed
        free(records);
        free(offsets);
        free(keys);
        return -2;
    }

    unsigned char md5_digest[MD5_DIGEST_LENGTH];
    for (size_t i = 0; i < *inputStringsLen; ++i) {
        if (MD5((unsigned char*)(*inputStrings)[i], strlen((*inputStrings)[i]), md5_digest) != NULL) {
            // MD5 calculation successful, handle the result
            char md5_str[33];
            for (size_t j = 0; j < MD5_DIGEST_LENGTH; ++j) {
                sprintf(&md5_str[j * 2], "%02x", md5_digest[j]);
            }
            // Initialize record with random key and offset
            records[i].key = (rand() % keyRange);
            records[i].offset = rand() % recordSize;
            // Set the value field of the current record using the MD5 hash as index
            size_t idx = atoi(md5_str);
            if (idx < numRecords) {
                records[idx].value = records[i].key;
            } else {
                // Index out of bounds, handle this gracefully
            }
            // Update keys and offsets arrays
            keys[records[i].key]++;
            offsets[records[i].offset] += records[i].key;
        } else {
            // MD5 calculation failed, handle this gracefully
        }
    }

    free(records); // Free allocated memory upon completion
    free(offsets);
    free(keys);

    return 0; // Function executed successfully
}
