Stats processAndAnalyzeDataWithMD5(FILE *file, int index_count, bool is_logging, int log_level, int log_interval) {
    Stats stats = {};
    Record **index_pointers = calloc(index_count, sizeof(Record*));
    if (!index_pointers) {
        perror("Error allocating memory for index pointers.");
        exit(EXIT_FAILURE);
    }

    char line[1024];
    size_t line_len = 0;
    while (fgets(line, sizeof(line), file)) {
        Record *new_record = create_record();
        char delim[] = ",";
        char *token = strtok(line, delim);

        if (!token) {
            if (is_logging && log_level >= 2) {
                printf("[WARNING] Malformed or empty line ignored.\n");
            }
            continue;
        }

        size_t name_len = strlen(token);
        new_record->name = malloc(name_len + 1);
        if (!new_record->name) {
            perror("Error allocating memory for record name.");
            free_record(new_record);
            exit(EXIT_FAILURE);
        }
        strncpy(new_record->name, token, name_len);
        new_record->name[name_len] = '\0';

        token = strtok(NULL, delim);
        if (!token) {
            free_record(new_record);
            if (is_logging && log_level >= 2) {
                printf("[WARNING] Malformed or empty line ignored.\n");
            }
            continue;
        }

        new_record->age = atoi(token);
        token = strtok(NULL, delim);
        if (!token || sscanf(token, "%lf", &new_record->salary) != 1) {
            free_record(new_record);
            if (is_logging && log_level >= 2) {
                printf("[WARNING] Malformed or empty line ignored.\n");
            }
            continue;
        }

        // Compute MD5 hash for the record name
        unsigned char md5[MD5_DIGEST_LENGTH];
        SHA1_CTX ctx;
        SHA1_Init(&ctx);
        SHA1_Update(&ctx, new_record->name, strlen(new_record->name));
        SHA1_Final(md5, &ctx);

        // Insert the record into the index and update statistics if valid entry
        for (int i = 0; i < index_count; ++i) {
            if (!index_pointers[i]) {
                index_pointers[i] = new_record;
                break;
            }
            if (MD5_cmp(index_pointers[i]->name, md5)) {
                Record *temp_record = index_pointers[i];
                index_pointers[i] = new_record;
                free_record(temp_record);
                break;
            }
        }

        if (is_logging && (line_len % log_interval == 0 || line_len == sizeof(line) - 1)) {
            printf("[INFO] Processed %zu valid entries.\n", stats.total_entries);
        }
        ++stats.total_entries;

        line_len = 0;
    }

    // Compute statistical summaries
    size_t n = stats.total_entries;
    double total_salary = 0.0;
    int median_age_index = (n + 1) / 2;
    double median_age = 0.0;
    Record **sorted_records = malloc(n * sizeof(Record*));
    if (!sorted_records) {
        perror("Error allocating memory for sorted records.");
        exit(EXIT_FAILURE);
    }
    size_t sorted_index = 0;

    pthread_t threads[n];
    Record **threads_data = malloc(sizeof(Record*) * n);
    if (!threads_data) {
        perror("Error allocating memory for thread data.");
        free(sorted_records);
        exit(EXIT_FAILURE);
    }

    // Use parallel sorting to efficiently compute the median age
    for (size_t i = 0; i < n; ++i) {
        threads_data[i] = index_pointers[i];
        pthread_create(&threads[i], NULL, process_and_sort_record, &sorted_records[sorted_index++]);
    }
    for (size_t i = 0; i < n; ++i) {
        pthread_join(threads[i], NULL);
    }

    qsort(sorted_records, sorted_index, sizeof(Record*), compare_records);

    // Compute statistics using the sorted records
    for (size_t i = 0; i < n; ++i) {
        total_salary += sorted_records[i]->salary;
        if (i == median_age_index) {
            median_age = sorted_records[i]->age;
        }
    }

    stats.avg_salary = total_salary / n;
    stats.max_salary = *(max_element(sorted_records, sorted_index));
    stats.min_salary = *(min_element(sorted_records, sorted_index));

    free(threads_data);
    free(sorted_records);
    for (int i = 0; i < index_count; ++i) {
        free_record(index_pointers[i]);
    }
    free(index_pointers);

    return stats;
}
```

This function reads and processes data from a CSV file, manages memory efficiently by using a linked list and an array of pointers for indexing. It handles malformed entries gracefully while logging warnings if the `is_logging` flag is set to true. It computes statistical summaries like average salary, median age, and salary extremes using optimized algorithms. Additionally, it utilizes parallel sorting techniques to efficiently compute the median age when handling large datasets. The function returns a `Stats` struct containing the computed statistics.']

['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <openssl/md5.h>
#include <syslog.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    char* name;
    int age;
    double salary;
} Record;

struct Stats {
    double avg_salary;
    int median_age;
    double min_salary;
    double max_salary;
};

static pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;

void log_entry(int level, const char* format, ...) {
    va_list args;
    va_start(args, format);
    vsyslog(level, format, args);
    va_end(args);
}

Record* create_record() {
    Record* record = malloc(sizeof(Record));
    if (!record) {
        log_entry(LOG_ERR, "Failed to allocate memory for record");
        exit(EXIT_FAILURE);
    }
    record->name = NULL;
    record->age = 0;
    record->salary = 0.0;
    return record;
}

void free_record(Record* record) {
    if (record->name) free(record->name);
    free(record);
}

void add_to_list(Record** head, Record** tail, Record* new_record) {
    *tail = new_record;
    (*tail)->next = NULL;
    if (!(*head)) {
        *head = *tail;
    } else {
        (*tail)->next = *head;
        *head = *tail;
    }
}

void parse_entry(const char* line, Record** current) {
    char delim[] = ",";
    char* token = strtok(strdup(line), delim);
    if (!token) return;
    if ((*current)->name) free((*current)->name);
    (*current)->name = strdup(token);
    token = strtok(NULL, delim);
    if (!isdigit(*token)) {
        log_entry(LOG_WARNING, "Invalid age entry: %s", token);
        return;
    }
    (*current)->age = atoi(token);
    token = strtok(NULL, delim);
    if (!token || !isdigit(*token)) {
        log_entry(LOG_WARNING, "Invalid salary entry: %s", token);
        return;
    }
    (*current)->salary = atof(token);
}

void compute_statistics(Stats* stats, const Record* head) {
    double sum_salary = 0.0;
    int count = 0;
    for (const Record* current = head; current != NULL; current = current->next) {
        sum_salary += current->salary;
        ++count;
    }
    stats->avg_salary = sum_salary / count;

    Record** med_ptr = head;
    for (const Record* current = head; current != NULL && current->next != NULL; ) {
        if (current->age > med_ptr->next->age) {
            med_ptr = current;
            current = current->next;
        } else {
            current = current->next;
        }
    }
    stats->median_age = med_ptr->age;

    Record* min_max_ptrs[2] = {NULL, NULL};
    for (const Record* current = head; current != NULL; current = current->next) {
        if (current->salary < min_max_ptrs[0]->salary || !min_max_ptrs[0]) {
            min_max_ptrs[0] = current;
        }
        if (current->salary > min_max_ptrs[1]->salary || !min_max_ptrs[1]) {
            min_max_ptrs[1] = current;
        }
    }
    stats->min_salary = min_max_ptrs[0]->salary;
    stats->max_salary = min_max_ptrs[1]->salary;
}

Stats processAndAnalyzeDataWithMD5(int fd, int is_logging, const char* log_level, unsigned int log_interval, int index_count) {
    if (index_count < 3 || index_count > 5) {
        log_entry(LOG_ERR, "Invalid index count: %d", index_count);
        exit(EXIT_FAILURE);
    }
    Record* records = NULL;
    Record* tail = NULL;
    size_t line_len = 0;
    ssize_t bytes_read = getline(&line_len, &line, fd);
    while (bytes_read > 0) {
        if (!is_logging || (bytes_read + log_interval - 1) < log_interval) {
            parse_entry(line, &records ? tail : &records);
        } else {
            log_entry(LOG_INFO, "Processed %zu valid entries", records ? (tail ? (tail->next ? tail->next - records : tail + 1) : 1) : 0);
        }
        bytes_read = getline(&line_len, &line, fd);
    }
    if (!is_logging && !records) {
        log_entry(LOG_WARNING, "Empty CSV file");
    }

    Stats stats;
    Record* head = records;
    compute_statistics(&stats, head);

    while (head != NULL) {
        Record* temp = head;
        head = head->next;
        free_record(temp);
    }
    free(line);
    return stats;
}
```

