void log_memory_usage() {
    void *memory_start = mmap(NULL, 0, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    size_t memory_size = sysconf(_SC_PAGE_SIZE) * ((long long int)getpagesize(memory_start) / (1024 * 1024));

    printf("Current memory usage: %.2f MB\n", (float)memory_size / (1024.0 * 1024.0));
}

void setup(int size, int max_usage, int min, int max, FILE *config_file) {
    long offsets = custom_malloc((size + 7) / 8, "offsets");
    if (!offsets) return;
    int keys = custom_malloc(sizeof(int) * size, "keys");
    if (!keys) {
        free(offsets);
        return;
    }
    Record *records = custom_malloc(sizeof(Record) * size, "records");
    if (!records) {
        free(keys);
        free(offsets);
        return;
    }

    log_memory_usage();

    fseek(config_file, 0, SEEK_SET); // Reset file pointer to start
    int current_usage = 0;
    for (int i = 0; i < size; ++i) {
        if (fscanf(config_file, "%d %d %d", &keys[i], &(offsets[(i + 1) / 8] >> ((i + 1) % 8) * 32), &(records[i].value)) != 3) {
            fprintf(stderr, "Invalid configuration format\n");
            return;
        }

        current_usage += (sizeof(int) + sizeof(long)) + sizeof(Record);
        log_memory_usage();

        if (current_usage > max_usage) {
            fprintf(stderr, "Memory usage exceeded threshold\n");
            return;
        }
    }
}
