        try
        {
            using (var reader = XmlReader.Create(xmlPath))
            {
                var elements = await Task.WhenAll((await GetElementsByXPathAsync(reader, "//elementName")).ToArrayAsync()).ConfigureAwait(false);

                if (elements.Count() == 0)
                    throw new Exception($"No matching element '{elementName}' found in XML.");

                if (elements.Count() > 1)
                    throw new Exception($"More than one matching element '{elementName}' found in XML.");
            }

            var assembly = Assembly.LoadFile(Path.GetDirectoryName(moduleName) + Path.DirectorySeparatorChar + moduleName);
            var type = assembly.GetTypes().FirstOrDefault(t => t.Name == "Module");

            if (type == null)
                throw new Exception($"Could not find module '{moduleName}'.");

            var instance = Activator.CreateInstance(type);

            foreach (var test in tests)
            {
                blueslip.Reset();
                try
                {
                    var testFunction = (Action<Blueslip>)Delegate.CreateDelegate(typeof(Action<Blueslip>), instance.GetType().GetField("test").GetValue(instance), test.testFunction);
                    testFunction(blueslip);

                    if (!blueslip.HasErrors)
                        testResults.PassedTests++;
                    else
                        testResults.FailedTests++;
                }
                catch (Exception ex)
                {
                    Console.WriteLine($"Test '{test.name}' failed with error: {ex.Message}");
                    testResults.FailedTests++;
                }
                finally
                {
                    blueslip.Log(DateTime.Now, $"Starting test: {test.name}");
                    blueslip.Log(DateTime.Now, $"Ending test: {test.name}");
                }
            }
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error parsing XML or running tests: {ex.Message}");
        }

        return testResults;
    }

    private static async IAsyncEnumerable<XElement> GetElementsByXPathAsync(XmlReader reader, string xpath)
    {
        var document = await XDocument.LoadAsync(reader).ConfigureAwait(false);
        foreach (var element in document.Root.XPathSelectElements(xpath))
            yield return element;
    }
}

