using System;
using System.Collections.Concurrent;
using System.Linq;
using System.Xml.XPath;
using System.Reflection;
using System.Threading;
using System.Threading.Tasks;
using System.IO;
using System.Globalization;
using Microsoft.VisualStudio.TestTools.UnitTesting;
using BlueslipMockingLibrary; // Assuming you have a 'BlueslipMockingLibrary' for mocking logging and error handling

public class TestRunner
{
    public async Task<TestResults> ParseXMLAndRunTests(string xmlPath, string moduleName, Blueslip mockLogger, Test[] tests, int maxConcurrency)
    {
        var semaphore = new SemaphoreSlim(maxConcurrency);
        var results = new TestResults();

        try
        {
            using (var reader = XmlReader.Create(xmlPath))
            {
                var node = reader.Evaluate("/root/testSuite/testCase"); // Assuming your XML structure matches this
                if (!node.MoveToFirstAttribute()) throw new Exception("No test case found in the XML file.");
                if (node.Name != "name") throw new Exception("Invalid attribute name for the test case in the XML file.");

                var testCaseName = node.Value;
                if (!reader.MoveToElement()) throw new Exception($"Failed to find the test case element '{testCaseName}' in the XML file.");

                while (reader.ReadToFollowingSibling("testCase"))
                {
                    semaphore.Wait();

                    var test = tests.FirstOrDefault(t => t.name == reader.GetAttribute("name"));
                    if (test == null) throw new Exception($"Test '{reader.GetAttribute("name")}' not found in the provided test list.");

                    mockLogger.Reset();
                    dynamic module = Assembly.LoadFile(System.IO.Path.Combine(AppDomain.CurrentDomain.BaseDirectory, moduleName)).CreateInstance(test.testFunction.ReflectedType.FullName);

                    try
                    {
                        test.testFunction(mockLogger);
                        results.PassedTests++;
                    }
                    catch (Exception ex)
                    {
                        results.FailedTests++;
                        mockLogger.Error(ex.Message, ex);
                    }

                    var time = DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss", CultureInfo.InvariantCulture);
                    var testName = reader.GetAttribute("name");
                    mockLogger.Log($"Test '{testName}' started at {time}.");
                    mockLogger.Log($"Test '{testName}' completed at {time}. Result: {results.PassedTests > 0 ? "Successful" : "Failed"}.");

                    semaphore.Release();
                }
            }
        }
        catch (Exception ex)
        {
            results.FailedTests++;
            mockLogger.Error(ex.Message, ex);
        }

        return results;
    }
}

public class TestResults
{
    public int TotalTests { get; set; }
    public int PassedTests { get; set; }
    public int FailedTests { get; set; }
}
