2. Python Function (MD5 hash calculation):

```python
import hashlib
import os
import sys
import time
from concurrent.futures import ThreadPoolExecutor

def md5_hash(file_path):
    buf = None
    with open(file_path, 'rb') as f:
        buf = f.read(8192)

    while len(buf) > 0:
        hash_context = hashlib.md5()
        hash_context.update(buf)
        buf = f.read(8192)

    return hash_context.digest()

def calculate_hashes(file_list, log):
    executor = ThreadPoolExecutor(max_workers=4)
    results = []

    def log_result(res, size):
        with open(log, "a") as f:
            timestamp = time.strftime('%Y-%m-%d %H:%M:%S', time.localtime())
            filesize = os.path.getsize(res[0])
            duration = res[1] / 1000
            f.write(f"{timestamp} | {filesize} bytes | {duration:.3f} seconds\n")

    for file in file_list:
        future = executor.submit(md5_hash, file, timeout=10)
        results.append((file, future))

    for res in results:
        result = res[1].result()
        log_result(res, (result, time.time() - res[1].timestamp))

def main():
    file_list = ["large_file1.bin", "large_file2.bin"]
    log = "hash_log.txt"
    calculate_hashes(file_list, log)
