template<typename T>
class Octree {
private:
    static constexpr size_t leaf_size = 8;
    std::vector<T*> data_;
    std::unique_ptr<uint8_t[]> nodes_;
    int depth_;

public:
    Octree(float featureSize, size_t numLeafNodes, size_t dataCapacity) {
        depth_ = (unsigned)log2((size_t)1 << leaf_size);
        initialize(featureSize, numLeafNodes, dataCapacity);
    }

    ~Octree() { clear(); }

private:
    void initialize(float featureSize, size_t numLeafNodes, size_t dataCapacity) {
        nodes_ = std::make_unique<uint8_t[]>(getMemorySize(numLeafNodes));
        data_.resize(numLeafNodes);

        if (numLeafNodes > dataCapacity) {
            numLeafNodes = dataCapacity;
            depth_ = (unsigned)log2((size_t)1 << leaf_size);
        }

        float nodeSize = featureSize * featureSize * 3 + sizeof(uint8_t);
        capacity_ = static_cast<size_t>(pow(numLeafNodes, depth_)) / (leaf_size * leaf_size * 8) * nodeSize;
        nodes_.resize(capacity_);
    }

    void clear() {
        data_.clear();
        nodes_.reset();
    }

    size_t getMemorySize(size_t numLeafNodes) const {
        return (numLeafNodes / leaf_size * sizeof(T)) + (numLeafNodes * sizeof(uint8_t));
    }
};
