using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Runtime.Loader;
using System.Threading.Tasks;
using System.Xml;
using System.Xml.XPath;
using Blueslip;
using Blueslip.Extensions;
using Microsoft.CSharp;

namespace TestRunner
{
    public class ParseXMLAndRunTests
    {
        private readonly string _xmlPath;
        private readonly string _moduleName;
        private readonly IBlueslipLogger _blueslip;
        private XmlDocument _xmlDocument;

        public ParseXMLAndRunTests(string xmlPath, string moduleName, IBlueslipLogger blueslip)
        {
            _xmlPath = xmlPath;
            _moduleName = moduleName;
            _blueslip = blueslip;
        }

        public async Task ParseAndRunTestsAsync(IEnumerable<TestObject> tests)
        {
            _blueslip.Reset();

            try
            {
                await LoadXmlAsync(_xmlPath);
                var module = LoadModule(_moduleName);

                if (!IsValidModuleForTesting(module))
                {
                    _blueslip.Warn($"Skipping test suite for invalid module: {_moduleName}");
                    return;
                }

                var testFunctions = GetTestFunctionsFromModule(module);

                if (testFunctions == null || !tests.All(t => testFunctions.ContainsKey(t.name)))
                {
                    _blueslip.Warn($"Skipping invalid or missing tests");
                    return;
                }

                var watch = System.Diagnostics.Stopwatch.StartNew();

                foreach (var test in tests)
                {
                    var testFunction = testFunctions[test.name];
                    _blueslip.Info($"Running test: {test.name}");
                    await RunTestAsync(test, testFunction);
                }

                watch.Stop();
                _blueslip.Info($"Test suite completed in {watch.ElapsedMilliseconds}ms");
            }
            catch (Exception ex)
            {
                _blueslip.Error(ex, "An error occurred during test execution");
            }
        }

        private async Task LoadXmlAsync(string xmlPath)
        {
            _xmlDocument = new XmlDocument();
            try
            {
                using var stream = File.OpenRead(xmlPath);
                await Task.Run(() => _xmlDocument.Load(stream));
            }
            catch (Exception ex)
            {
                _blueslip.Warn($"Failed to load XML file: {xmlPath}. Error: {ex}");
            }
        }

        private Assembly LoadModule(string moduleName)
        {
            var assembly = AssemblyLoadContext.Default.LoadFromAssemblyPath(moduleName);
            return assembly;
        }

        private bool IsValidModuleForTesting(Assembly module)
        {
            // Check if the module contains all required test functions (e.g., TestInitialize, TestCleanup, and TestMethod attributes)
            var testInitializer = module.GetTypes().FirstOrDefault(t => t.IsClass && t.GetCustomAttributes(typeof(TestInitializeAttribute), false).Any());
            var testCleaner = module.GetTypes().FirstOrDefault(t => t.IsClass && t.GetCustomAttributes(typeof(TestCleanupAttribute), false).Any());
            var testMethods = module.GetTypes()
                .SelectMany(t => t.GetMethods())
                .Where(m => m.GetCustomAttributes(typeof(TestMethodAttribute), false).Any());

            return testInitializer != null && testCleaner != null && testMethods.Any();
        }

        private Dictionary<string, MethodInfo> GetTestFunctionsFromModule(Assembly module)
        {
            // Extract the test functions from the loaded module based on TestInitialize, TestCleanup, and TestMethod attributes
            var testInitializer = module.GetTypes().FirstOrDefault(t => t.IsClass && t.GetCustomAttributes(typeof(TestInitializeAttribute), false).Any());
            var testCleaner = module.GetTypes().FirstOrDefault(t => t.IsClass && t.GetCustomAttributes(typeof(TestCleanupAttribute), false).Any());
            var testMethods = module.GetTypes()
                .SelectMany(t => t.GetMethods())
                .Where(m => m.GetCustomAttributes(typeof(TestMethodAttribute), false).Any());

            if (testInitializer == null || testCleaner == null || !testMethods.Any())
                return new Dictionary<string, MethodInfo>();

            var testFunctionDictionary = new Dictionary<string, MethodInfo>();

            var initializerInstance = Activator.CreateInstance(testInitializer);
            var cleanupInstance = Activator.CreateInstance(testCleaner);

            testMethods.ForEach(testMethod =>
            {
                if (testFunctionDictionary.ContainsKey(testMethod.Name))
                    return;

                testFunctionDictionary[testMethod.Name] = testMethod;
            });

            var initializeInvocation = new InvocationInfo($"{testInitializer.FullName}.{nameof(IClassFixture<ITestContext>.Initialize)}");
            var cleanupInvocation = new InvocationInfo($"{testCleaner.FullName}.{nameof(IClassFixture<ITestContext>.Cleanup)}");

            testFunctionDictionary[nameof(TestInitializeAttribute)] = ReflectHelper.FindMethod(initializerInstance, initializeInvocation);
            testFunctionDictionary[nameof(TestCleanupAttribute)] = ReflectHelper.FindMethod(cleanupInstance, cleanupInvocation);

            return testFunctionDictionary;
        }

        private async Task RunTestAsync(TestObject test, MethodInfo testFunction)
        {
            using var watch = System.Diagnostics.Stopwatch.StartNew();

            try
            {
                await ReflectHelper.InvokeMethod(testFunction, null);
                _blueslip.Info($"Test: {test.name} passed");
            }
            catch (Exception ex)
            {
                _blueslip.Error(ex, $"Test: {test.name} failed");
            }

            _blueslip.Log($"Test execution time: {watch.ElapsedMilliseconds}ms");
        }
    }

    public class TestObject
    {
        public string name { get; set; }
        public Func<Task> testFunction { get; set; }
        public int timeout { get; set; }
    }
}
