using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Runtime.CompilerServices;
using System.Threading.Tasks;
using System.Text.RegularExpressions;
using log4net;

public class ProcessDocumentAndExecuteTasksResult
{
    public int TotalTasks { get; set; }
    public int CompletedTasks { get; set; }
    public int TimedOutTasks { get; set; }
}

public static async Task<ProcessDocumentAndExecuteTasksResult> ProcessDocumentAndExecuteTasks(string documentPath, string taskModule, ILog logger, Task[] taskList, int timeout, bool asyncSupport)
{
    try
    {
        if (File.Exists(documentPath))
        {
            var firstLine = await File.ReadAllLinesAsync(documentPath).ConfigureAwait(false).Where(line => Regex.IsMatch(line, "[your-pattern]")).FirstOrDefaultAsync().ConfigureAwait(false);

            if (string.IsNullOrEmpty(firstLine))
                throw new Exception($"No line found that matches the pattern.");

            if (taskList.Length > 1 && taskList.Where(t => Regex.IsMatch(t.Name, "[your-pattern]")).Count() > 1)
                throw new Exception("Multiple lines were found that match the pattern.");
        }
        else
            throw new FileNotFoundException("The document does not exist.", documentPath);

        var assembly = Assembly.LoadFrom(taskModule);
        var taskExecutor = new TaskExecutor(logger, timeout, asyncSupport);

        var result = new ProcessDocumentAndExecuteTasksResult();

        foreach (var task in taskList)
        {
            logger.InfoFormat("Starting task: {0}", task.Name);
            var executedTask = taskExecutor.Execute(task, assembly);
            result.TotalTasks++;

            if (executedTask.Result.IsCompletedSuccessfully)
                result.CompletedTasks++;

            else if (executedTask.Result.IsFaulted)
            {
                result.TimedOutTasks++;
                logger.ErrorFormat("Task '{0}' timed out.", task.Name);
            }

            logger.InfoFormat("Task '{0}' completed.", task.Name);
        }

        return result;
    }
    catch (Exception ex)
    {
        logger.Error(ex);
        throw; // Re-throw the exception to allow it to be handled by callers.
    }
}

public class TaskExecutor
{
    private readonly ILog _logger;
    private readonly TimeSpan _timeout;
    private readonly bool _asyncSupport;

    public TaskExecutor(ILog logger, TimeSpan timeout, bool asyncSupport)
    {
        _logger = logger;
        _timeout = timeout;
        _asyncSupport = asyncSupport;
    }

    public Task<object> Execute(Task task, Assembly assembly)
    {
        var timer = new System.Timers.Timer(_timeout.TotalMilliseconds);
        timer.AutoReset = false;

        Func<Task<object>, Task<object>> timeoutHandler = async t =>
        {
            timer.Stop();
            _logger.Error("Task took too long to complete.");
            throw new TimeoutException("Task timed out.");
        };

        return Task.Run(() =>
        {
            if (_asyncSupport)
                return task.Unwrap().Result; // Unwrap any outer await if present.

            timer.Elapsed += (s, e) => timeoutHandler(task);
            timer.Start();

            try
            {
                return task.Result;
            }
            catch (Exception ex)
            {
                _logger.Error(ex);
                throw; // Re-throw the exception to allow it to be handled by callers.
            }
            finally
            {
                timer.Stop();
            }
        }).ContinueWith(timeoutHandler);
    }
}
