typedef struct Node {
    int value;
    void* next;
} Node;

typedef struct Config {
    size_t listSize;
    size_t minVal, maxVal;
    size_t memThreshold;
    char allocStrategy[10]; // 'best-fit' or 'first-fit'
} Config;

void* custom_alloc(size_t size) {
    void *mem = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (mem == MAP_FAILED)
        return NULL;
    return mem;
}

Config read_config(FILE *file) {
    Config config;
    fscanf(file, "%zu%zu%zu%s", &config.listSize, &config.minVal, &config.maxVal, config.allocStrategy);
    config.memThreshold = 1024 * 1024 * 5; // 5MB threshold
    return config;
}

void log_memory(size_t used) {
    printf("Used Memory: %zu bytes\n", used);
}

Node* list_manager() {
    FILE *file = fopen("config.txt", "r");
    if (!file) return NULL;

    Config config = read_config(file);
    Node **head = (Node**)custom_alloc(sizeof(Node*) * config.listSize);
    if (!head) {
        fprintf(stderr, "Memory allocation failed.\n");
        fclose(file);
        return NULL;
    }

    for (size_t i = 0; i < config.listSize; ++i) head[i] = NULL;

    size_t used_mem = 0;
    void *allocatedMemory = NULL;

    for (size_t i = 0; i < config.listSize; ++i) {
        if (!head[i]) {
            allocatedMemory = custom_alloc(sizeof(Node));
            if (!allocatedMemory) {
                fprintf(stderr, "Memory allocation failed.\n");
                // Free memory and exit gracefully
                return NULL;
            }

            Node* node = (Node*)allocatedMemory;
            node->value = rand() % (config.maxVal - config.minVal + 1) + config.minVal;
            node->next = head[i];
            head[i] = node;

            used_mem += sizeof(Node);
        }
    }

    log_memory(used_mem);
    // Implement writing the list to a binary file here

    for (size_t i = 0; i < config.listSize; ++i) free(head[i]);
    free(head);
    fclose(file);

    return NULL; // Returning NULL indicates successful execution
}
