public async Task processConfigFileAndExecuteActions(string configPath, IEnumerable<IActionModule> actionModules, BlueslipLogger logger)
{
    var config = await JsonConvert.DeserializeObjectAsync<Configuration>(await File.ReadAllTextAsync(configPath));

    if (!config.SchemaValid())
    {
        logger.Warning("Invalid configuration schema detected.");
    }

    var actions = config.Actions;

    foreach (var action in actions)
    {
        logger.Info($"Starting action: {action.Name}");

        // Reset Blueslip instance for each action to avoid side effects
        using (var tempLogger = logger.NewChildScope())
        {
            var requiredMethods = new[] { nameof(IAction.Execute) };

            if (!VerifyActionMethodsAvailable(actionModules, action.Dependencies, requiredMethods))
            {
                tempLogger.Warning($"Missing or non-functional action method for action: {action.Name}");
                continue;
            }

            var actionInstance = Activator.CreateInstance(action.ActionType);
            var actionMethod = actionInstance.GetType().GetMethod(nameof(IAction.Execute));

            try
            {
                var startTime = DateTime.Now;
                await Task.Run(() => actionMethod?.Invoke(actionInstance, new object[] { tempLogger }));
                var elapsedTime = (DateTime.Now - startTime).TotalMilliseconds;

                tempLogger.Info($"Action: {action.Name} completed in {elapsedTime} ms.");
            }
            catch (Exception ex)
            {
                tempLogger.Error(ex, $"An error occurred while executing action: {action.Name}");
            }
        }
    }
}

public interface IAction
{
    void Execute(BlueslipLogger logger);
}

