[' ```csharp
using System;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Threading;
using System.Threading.Tasks;
using System.Xml;
using System.Xml.XPath;
using Blueslip.Mocking;

public class TestRunner
{
    private readonly SemaphoreSlim _semaphore;

    public TestRunner(int maxConcurrency)
    {
        _semaphore = new SemaphoreSlim(maxConcurrency);
    }

    public async Task<TestSummary> ParseXMLAndRunTests(string xmlPath, string moduleName, IBlueslip blueslip, Test[] tests)
    {
        var totalTests = tests.Length;
        var passedTests = 0;
        var failedTests = 0;

        var document = new XmlDocument();
        if (!File.Exists(xmlPath))
            throw new FileNotFoundException("XML file not found", xmlPath);

        try
        {
            using (var reader = XmlReader.Create(xmlPath))
                document.Load(reader);
        }
        catch (XmlException ex)
        {
            throw new Exception($"Invalid XML structure: {ex.Message}", ex);
        }

        var testElement = document.Root.SelectSingleNode("/Tests/Test[@name='" + tests.First().Name + "']");
        if (testElement == null)
            throw new Exception("Could not find the first test in the XML file.");

        var elementName = testElement.Name;
        var nodeSet = document.SelectNodes("/Tests/Test");

        if (nodeSet.Count > 1 && elementName != "Test")
            throw new Exception("Multiple test elements found with an incorrect root name.");

        async Task ExecuteTestAsync(Test test)
        {
            try
            {
                await _semaphore.WaitAsync();

                var assembly = Assembly.LoadFile(Path.GetDirectoryName(moduleName) + Path.DirectorySeparatorChar + moduleName);
                if (assembly == null)
                    throw new FileNotFoundException("Module not found", moduleName);

                var type = assembly.GetTypes().FirstOrDefault(t => t.Name == test.TestClass);
                if (type == null)
                    throw new Exception($"Could not find the specified module class: {test.TestClass}");

                var instance = Activator.CreateInstance(type);
                var testMethod = type.GetMethods().FirstOrDefault(m => m.Name == test.TestFunction);
                if (testMethod == null)
                    throw new Exception($"Could not find the specified test method: {test.TestFunction}");

                blueslip.Reset();
                var result = await (Task<bool>)testMethod.Invoke(instance, new[] { blueslip });

                if (result)
                    Interlocked.Increment(ref passedTests);
                else
                    Interlocked.Increment(ref failedTests);

                Console.WriteLine($"Test '{test.Name}' finished on {DateTime.Now}");
            }
            catch (Exception ex)
            {
                Console.WriteLine($"Test '{test.Name}' failed: {ex.Message}");
                Console.WriteLine(ex.StackTrace);
            }
            finally
            {
                _semaphore.Release();
            }
        }

        var testTasks = tests.Select(ExecuteTestAsync).ToList();

        await Task.WhenAll(testTasks);

        return new TestSummary
        {
            TotalTests = totalTests,
            PassedTests = passedTests,
            FailedTests = failedTests
        };
    }
}

public class TestSummary
{
    public int TotalTests { get; set; }
    public int PassedTests { get; set; }
    public int FailedTests { get; set; }
}
```

This code defines a `TestRunner` class that parses an XML file and runs asynchronous tests using the provided module. It creates a semaphore for managing concurrency, loads modules dynamically without requiring a full path, and resets the blueslip instance before executing each test to minimize side effects. Edge cases such as invalid XML paths, non-existent modules, and tests that fail to initialize are handled gracefully. Memory usage is minimized by using `Interlocked` operations for incrementing counters. The function returns a summary object containing the total number of tests run, the number of passed tests, and the number of failed tests.']

