#define MAX_NUM_PDUS 10000
#define MAX_BUFFER_SIZE 65536

typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint16_t CRC_INDICATION_REL8_TAG;
    uint16_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_pdus(uint32_t num_pdds) {
    if (num_pdds <= 0 || num_pdds > MAX_NUM_PDUS) {
        fprintf(stderr, "Invalid number of PDUs: should be between 1 and %d\n", MAX_NUM_PDUS);
        return NULL;
    }

    size_t size = sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_pdds;

    if (size > MAX_BUFFER_SIZE) {
        fprintf(stderr, "Allocation size exceeded the maximum buffer size of %d\n", MAX_BUFFER_SIZE);
        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_T* pdu_array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(size);

    if (!pdu_array) {
        fprintf(stderr, "Memory allocation failed\n");
        return NULL;
    }

    uint32_t seed = time(NULL);
    for (uint32_t i = 0; i < num_pdds; ++i) {
        pdu_array[i].RX_UE_INFORMATION_TAG = i;
        pdu_array[i].RNTI = hashFunction(i, MAX_NUM_PDUS) + 1; // +1 because the returned value is between 0 and MAX_NUM_PDUS-1
        pdu_array[i].CRC_INDICATION_REL8_TAG = rand_r(&seed);
    }

    return pdu_array;
}

uint32_t hashFunction(uint32_t key, uint32_t max_size) {
    uint32_t hash = 5381;
    uint32_t i;

    for (i = 0; i < key && key <= max_size; ++i)
        hash = ((hash << 5) + hash) + key; /* hash * 33 + key */

    return hash % max_size;
}

void free_pdus(NFAPI_CRC_INDICATION_PDU_T* pdu_array, uint32_t num_pdds) {
    if (pdu_array) {
        free(pdu_array);
    }
}
