    } else {
        array = realloc(array, ((index + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T)));
    }
    if (!array) return NULL;

    for (int i = index; i >= 0; --i) {
        pthread_mutex_lock(&array_mutex);
        array[i] = *data++;
        pthread_mutex_unlock(&array_mutex);
    }

    return array;
}

void populate_and_manage_array(int entries) {
    NFAPI_CRC_INDICATION_PDU_T* array = NULL;
    int thread_count = (entries > MAX_THREADS) ? MAX_THREADS : entries;

    pthread_t threads[MAX_THREADS];
