        int *arg = malloc(sizeof(int));
        *arg = i;
        if (pthread_create(&threads[i], NULL, populate_array, arg)) {
            fprintf(stderr, "Error creating thread\n");
            exit(EXIT_FAILURE);
        }
    }

    for (int i = 0; i < thread_count; ++i) {
        void *result;
        if (pthread_join(threads[i], &result)) {
            fprintf(stderr, "Error joining thread\n");
            exit(EXIT_FAILURE);
        }
        if (!result) continue; // If the thread failed to get data or allocate memory

        NFAPI_CRC_INDICATION_PDU_T *tmp = (NFAPI_CRC_INDICATION_PDU_T*) result;
        for (int j = 0; j < i + 1; ++j) {
            pthread_mutex_lock(&array_mutex);
            if (!array) array = tmp;
            else memcpy(array + j, tmp + j, sizeof(NFAPI_CRC_INDICATION_PDU_T));
            pthread_mutex_unlock(&array_mutex);
        }
    }
}
