    using System;
    using System.Collections.Concurrent;
    using System.IO;
    using System.Linq;
    using System.Reflection;
    using System.Xml;
    using System.Xml.XPath;
    using System.Threading;
    using System.Threading.Tasks;
    using Microsoft.VisualStudio.TestTools.UnitTesting;
    using BlueslipMock;

    public class TestRunner
    {
        private XmlDocument _xmlDocument;
        private IBlueslip _blueslip;
        private ConcurrentQueue<Func<IBlueslip, Test>> _tests;
        private SemaphoreSlim _semaphore;
        private int _totalTests;
        private int _passedTests;

        public async Task<TestResult> parseXMLAndRunTests(string xmlPath, string moduleName, IBlueslip blueslip, Test[] tests, int maxConcurrency, bool useMemoryEfficientParsing)
        {
            _tests = new ConcurrentQueue<Func<IBlipeshop.IBlueslip, Test>>(tests);
            _semaphore = new SemaphoreSlim(maxConcurrency);

            try
            {
                XmlReaderSettings settings = useMemoryEfficientParsing ? new XmlReaderSettings() : new XmlReaderSettings();
                settings.DtdProcessing = DtdProcessing.Parse;
                using (XmlReader reader = XmlReader.Create(xmlPath, settings))
                {
                    _xmlDocument = new XmlDocument();
                    _xmlDocument.Load(reader);
                }

                var rootElement = _xmlDocument.DocumentElement;
                if (rootElement == null)
                {
                    throw new Exception($"Invalid XML file: no root element found.");
                }

                string testNameXPath = "/TestSuite/TestCase[@name]";
                var testNodes = rootElement.SelectNodes(testNameXPath);

                if (testNodes == null || testNodes.Count > 1)
                {
                    throw new Exception($"Invalid XML file: more than one test found with the given name.");
                }

                XPathNavigator navigator = rootElement.CreateNavigator();
                var currentTestNode = navigator.SelectSingleNode(testNameXPath);
                string testName = currentTestNode.GetAttributeValue("name", null);

                _blueslip = blueslip;
                _totalTests++;
                _semaphore.Wait();

                Func<IBlipeshop.IBlueslip, Test> testFunction = () => tests.First(t => t.name == testName).testFunction;
                var currentTest = new Test(_blueslip) { Name = testName };
                _tests.Enqueue(testFunction);

                Task.Run(() => RunTestAsync(currentTest));

                while (_tests.Count > 0 && _semaphore.CurrentCount < maxConcurrency)
                {
                    _semaphore.Release();
                }

                return new TestResult() { TotalTests = _totalTests, PassedTests = _passedTests };
            }
            catch (Exception ex)
            {
                var errorMessage = $"Error occurred while parsing XML or running tests: {ex.Message}";
                _blueslip.Error(errorMessage);
                return new TestResult() { TotalTests = _totalTests, PassedTests = 0 };
            }
        }

        private void RunTestAsync(Test currentTest)
        {
            try
            {
                var assembly = Assembly.LoadFile(Path.Combine(AppDomain.CurrentDomain.BaseDirectory, moduleName));
                Type testType = assembly.GetTypes().FirstOrDefault(t => t.Namespace == null || t.Namespace.Contains(moduleName));

                if (testType == null)
                {
                    throw new Exception($"Error loading module: '{moduleName}' not found or invalid.");
                }

                var testInstance = Activator.CreateInstance(testType);
                var testMethodInfo = testType.GetMethod("Initialize");
                if (testMethodInfo != null)
                {
                    testMethodInfo.Invoke(testInstance, new object[] { _blueslip });
                }

                dynamic testClass = testInstance;
                dynamic testFunction = testClass.TestFunction;
                currentTest.TestFunction = testFunction;

                var startTime = DateTime.Now;
                _blueslip.Info($"Starting Test: {currentTest.Name} at {startTime}");

                try
                {
                    testFunction(_blueslip);
                    _passedTests++;
                }
                catch (Exception ex)
                {
                    var errorMessage = $"Error during Test '{currentTest.Name}': {ex.Message}";
                    _blueslip.Error(errorMessage);
                }

                var endTime = DateTime.Now;
                _blueslip.Info($"Finished Test: {currentTest.Name} at {endTime}, took {endTime - startTime:c}");
            }
            catch (Exception ex)
            {
                var errorMessage = $"Error during TestRunner for Test '{currentTest.Name}': {ex.Message}";
                _blueslip.Error(errorMessage);
            }
        }
    }

    public class Test
    {
        public string Name { get; set; }
        public Func<IBlipeshop.IBlueslip, Task> TestFunction { get; set; }

        private IBlipeshop.IBlueslip _blueslip;
        public Test(IBlipeshop.IBlueslip blueslip) => _blueslip = blueslip;
    }

    public class TestResult
    {
        public int TotalTests { get; set; }
        public int PassedTests { get; set; }
    }

    // Custom BlueslipMock library for logging and error handling
    public interface IBlipeshop.IBlueslip
    {
        void Info(string message);
        void Error(string message);
    }

    public class Blueslip : IBlipeshop.IBlueslip
    {
        private readonly TextWriter _writer;

        public Blueslip(TextWriter writer) => _writer = writer ?? throw new ArgumentNullException(nameof(writer));

        public void Info(string message) => _writer.WriteLine($"[Info] {message}");
        public void Error(string message) => _writer.WriteLine($"[Error] {message}");
    }
