} NFAPI_CRC_INDICATION_PDU_T;

typedef struct _entry_log {
    time_t timestamp;
    int sourceId;
    bool isValidData;
    char anomalyDetails[256];
} EntryLog;

static NFAPI_CRC_INDICATION_PDU_T* dataArray = NULL;
static size_t dataSize = 0;
static size_t maxDataSize = 0;
static pthread_mutex_t arrayLock = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t notFull = PTHREAD_COND_INITIALIZER;
static pthread_cond_t notEmpty = PTHREAD_COND_INITIALIZER;
static EntryLog* logArray = NULL;
static size_t logSize = 0;
static size_t maxLogSize = 0;

void init(size_t capacity) {
    if (capacity == 0) return;

    dataArray = malloc(capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    logArray = malloc(capacity * sizeof(EntryLog));
    maxDataSize = capacity;
    maxLogSize = capacity;
}

void destroy() {
    free(dataArray);
    free(logArray);
    dataArray = NULL;
    logArray = NULL;
    maxDataSize = 0;
    maxLogSize = 0;
}

bool enqueue(NFAPI_CRC_INDICATION_PDU_T* entry, int sourceId) {
    pthread_mutex_lock(&arrayLock);

    // Handle the case of a full array
    if (dataSize == maxDataSize) {
        pthread_cond_wait(&notFull, &arrayLock);
    }

    // Check data integrity and handle anomalies gracefully
    // ... (Assuming you have a function to check data integrity)
    EntryLog* logEntry = &logArray[dataSize];
    logEntry->timestamp = time(NULL);
    logEntry->sourceId = sourceId;
    logEntry->isValidData = true;
    // Populate the details of the anomaly if any encountered

    dataArray[dataSize] = *entry;
    dataSize++;
    pthread_mutex_unlock(&arrayLock);

    // Signal that a new slot is available for insertion
    pthread_cond_signal(&notEmpty);
    return true;
}

int dequeue(EntryLog* log) {
    pthread_mutex_lock(&arrayLock);

    // Handle the case of an empty array
    if (dataSize == 0) {
        pthread_cond_wait(&notEmpty, &arrayLock);
    }

    // Populate the details of the dequeued entry
    *log = logArray[dataSize - 1];
    NFAPI_CRC_INDICATION_PDU_T dataEntry = dataArray[dataSize - 1];

    memcpy(&dataArray[dataSize - 1], &dataArray[dataSize - 2], sizeof(NFAPI_CRC_INDICATION_PDU_T));
    dataSize--;
    pthread_mutex_unlock(&arrayLock);

    // Signal that a slot is now empty and can be filled again
    pthread_cond_signal(&notFull);
    return 0;
}

void report() {
    printf("Report:\n");
    printf("Number of successful insertions: %zu\n", dataSize);
    printf("Number of failed insertions due to anomalies: %zu\n", dataSize - logSize);
}
```

