#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

typedef struct {
    RX_UE_INFORMATION_TAG tag;
    int rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

static pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

void generate_crcflag(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    // Set CRCFLAG value based on the current time for debugging purposes.
    pdu->crc_indication.crcflag = (unsigned char)(time(NULL) & 0xFF);
}

void validate_crc(NFAPI_CRC_INDICATION_PDU_T* pdu, const unsigned char expected_crc[]) {
    // Validate CRC against a predefined set of expected values.
    if (pdu->crc_indication.crcflag != expected_crc[0] &&
        pdu->crc_indication.crcflag != expected_crc[1] &&
        pdu->crc_indication.crcflag != expected_crc[2]) {
        printf("CRC validation failed for PDU with RNTI %d\n", pdu->rnti);
    }
}

void create_and_populate_list(NFAPI_CRC_INDICATION_PDU_T** list, int num_elements) {
    *list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!(*list)) {
        perror("Failed to allocate memory");
        return;
    }

    pthread_mutex_lock(&list_mutex);
    for (int i = 0; i < num_elements; ++i) {
        (*list + i)->tag = RX_UE_INFORMATION_TAG_UE_INFO; // Set UE_INFO tag value
        (*list + i)->rnti = i + 1;                        // Assign increasing RNTI values
        generate_crcflag((*list + i));                   // Generate CRCFLAG value for each PDU
    }
    pthread_mutex_unlock(&list_mutex);
}

void free_list(NFAPI_CRC_INDICATION_PDU_T** list, int num_elements) {
    if (!(*list)) {
        return;
    }

    pthread_mutex_lock(&list_mutex);
    for (int i = 0; i < num_elements; ++i) {
        free((*list + i));
    }
    free(*list);
    *list = NULL;
    pthread_mutex_unlock(&list_mutex);
}
```

This code creates a function `create_and_populate_list()` that generates and populates a dynamically allocated linked list of `NFAPI_CRC_INDICATION_PDU_T` structures. The function locks the provided mutex before iterating through the list to ensure thread safety in multi-threaded environments. It also includes helper functions for generating the CRC flag values, validating CRC indications, and freeing the allocated memory when no longer needed.']

