    uint16_t RNTI;
    uint32_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    void *offset;
    void *key;
    void *access_token;
} MANAGEMENT_DATA_T;

void* create_record(size_t size) {
    NFAPI_CRC_INDICATION_PDU_T *record = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!record) return NULL;

    record->RX_UE_INFORMATION_TAG = rand();
    record->RNTI = rand() % 65536;
    record->CRC_INDICATION_REL8_TAG = rand();
    record->CRCFLAG = (rand() % 2) + 1;

    return record;
}

void* create_management_data(size_t size) {
    MANAGEMENT_DATA_T *data = malloc(sizeof(MANAGEMENT_DATA_T));
    if (!data) return NULL;

    data->offset = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (data->offset == MAP_FAILED) {
        free(data);
        return NULL;
    }

    data->key = malloc(sizeof(uint8_t) * size);
    if (!data->key) {
        munmap(data->offset, size);
        free(data);
        return NULL;
    }

    data->access_token = json_tokener_parse((char *)calloc(size, sizeof(char)));
    if (!data->access_token) {
        free(data->key);
        munmap(data->offset, size);
        free(data);
        return NULL;
    }

    return data;
}

void destroy_record(NFAPI_CRC_INDICATION_PDU_T *record) {
    if (!record) return;
    free(record);
}

void destroy_management_data(MANAGEMENT_DATA_T *data) {
    if (!data) return;

    json_free(data->access_token);
    munmap(data->offset, data->size);
    free(data->key);
    free(data);
}

