typedef struct log_entry {
    time_t timestamp;
    int level;
    const char* format;
    va_list args;
} log_entry;

struct log_queue {
    size_t capacity;
    size_t count;
    log_entry* data;
};

void log_init(struct log_queue* queue, size_t capacity) {
    queue->capacity = capacity;
    queue->count = 0;
    queue->data = malloc(queue->capacity * sizeof(log_entry));
}

void log_push(struct log_queue* queue, int level, const char* format, ...) {
    if (queue->count >= queue->capacity) return;

    va_list args;
    va_start(args, format);

    time_t now = time(NULL);

    log_entry* entry = &queue->data[queue->count];
    entry->timestamp = now;
    entry->level = level;
    entry->format = format;
    entry->args = args;

    queue->count++;
}

void log_flush(struct log_queue* queue) {
    for (size_t i = 0; i < queue->count; ++i) {
        log_entry* entry = &queue->data[i];
        vfprintf(stderr, entry->format, entry->args);
    }
    queue->count = 0;
}

