#include <stdio.h>
#include <stdarg.h>
#include <pthread.h>
#include <time.h>
#include <sys/stat.h>
#include <sys/mman.h>
#include <unistd.h>
#include <fcntl.h>

typedef enum { DEBUG, INFO, WARNING, ERROR } Severity;

struct Logger {
    char* log_file;
    int verbosity;
    struct Backend* backend;
    pthread_mutex_t lock;
    pthread_cond_t cond;
    time_t last_log[4];
};

struct Backend {
    void (*log)(struct Logger*, Severity, const char*, ...);
    // Add other backend-specific properties here
};

void logger_init(struct Logger* logger, const char* log_file, struct Backend* backend) {
    logger->log_file = strdup(log_file);
    logger->backend = backend;
    pthread_mutex_init(&logger->lock, NULL);
    pthread_cond_init(&logger->cond, NULL);
}

void logger_destroy(struct Logger* logger) {
    free(logger->log_file);
    pthread_mutex_destroy(&logger->lock);
    pthread_cond_destroy(&logger->cond);
}

void log_message(struct Logger* logger, Severity severity, const char* format, ...) {
    va_list args;
    time_t now = time(NULL);

    // Lock to ensure thread safety
    pthread_mutex_lock(&logger->lock);

    if (now - logger->last_log[severity] >= 1) {
        logger->last_log[severity] = now;

        // Conditional unlock, notify and log the message
        pthread_cond_signal(&logger->cond);
    } else {
        pthread_cond_wait(&logger->cond, &logger->lock);
    }

    // Perform logging with proper formatting
    va_start(args, format);
    vfprintf(logger->backend->log(logger, severity), format, args);
    va_end(args);

    pthread_mutex_unlock(&logger->lock);
}

// Extensible logging backend example using FILE* for simplicity.
void simple_log_backend_func(struct Logger*, Severity, const char*, ...) {
    FILE *fp = fopen(logger->log_file, "a");
    va_list args;
    time_t now = time(NULL);
    char time_str[20];
    struct tm *tm = localtime(&now);

    strftime(time_str, sizeof(time_str), "%Y-%m-%d %H:%M:%S", tm);
    vfprintf(fp, "[%s] [%s] : ", time_str, severity_strings[severity]);
    va_start(args, severity);
    vfprintf(fp, va_arg(args, char*), args);
    va_end(args);
    fputc('\n', fp);
    fclose(fp);
}

int main() {
    // Initialize logger with desired configuration
    struct Logger logger;
    logger_init(&logger, "logfile.txt", &simple_log_backend);

    // Use the logger in your application's code
    log_message(&logger, INFO, "Starting the application.");

    // ... other code here ...

    // Cleanup resources when done
    logger_destroy(&logger);

    return 0;
}
