['```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <limits.h>
#include <time.h>
#include <sys/mman.h>
#include <openssl/md5.h>
#include <pthread.h>
#include <zlib.h>

typedef struct {
    char *name;
    int age;
    double salary;
} Record;

typedef struct Stats {
    double avg_salary;
    int median_age;
    double min_salary;
    double max_salary;
} Stats;

enum LogLevel { DEBUG, INFO, WARN, ERROR };
pthread_mutex_t log_mutex = PTHREAD_MUTEX_INITIALIZER;
static const char *logfile = "data_analysis.log";
static int log_level = INFO;
static int log_interval = 1000;
static bool is_logging = true;

Stats processAndAnalyzeDataWithMD5(FILE *fp, int index_count, int log_level, bool is_logging) {
    static pthread_once_t once_control = PTHREAD_ONCE_INIT;
    static gzFile gzfp = NULL;

    if (pthread_once(&once_control, init_log_handler) != 0) {
        perror("Error initializing log handler");
        exit(EXIT_FAILURE);
    }

    gzfp = gzdeflateInit(gzfp, Z_DEFAULT_COMPRESSION);
    if (gzfp == NULL) {
        perror("Error initializing gzip compression");
        exit(EXIT_FAILURE);
    }

    Record **records = calloc(index_count, sizeof(Record*));
    int *index_pointers = malloc(index_count * sizeof(int));
    if (!records || !index_pointers) {
        perror("Error allocating memory");
        exit(EXIT_FAILURE);
    }

    unsigned char md5[MD5_DIGEST_LENGTH];
    size_t nread = 0;
    int valid_entries = 0, total_entries = 0;
    Record *current_record;
    Stats stats = {0};

    clock_t start = clock();

    while ((nread = getline(&current_record->name, &nread, fp)) != -1) {
        if (nread == 0 || current_record->name[0] == '#') {
            continue;
        }

        char *token = strtok(current_record->name, ",");
        int field_count = 0;

        while (token != NULL) {
            if (field_count++ >= index_count + 1) {
                pthread_mutex_lock(&log_mutex);
                if (is_logging) {
                    fprintf(stderr, "Warning: Malformed record skipped\n");
                }
                pthread_mutex_unlock(&log_mutex);
                free(current_record->name);
                current_record = NULL;
                continue;
            }

            token[strcspn(token, "\r\n")] = '\0';

            if (field_count == 1) { // Name
                current_record->name = realloc(current_record->name, nread + 1);
                if (!current_record->name) {
                    perror("Error allocating memory");
                    exit(EXIT_FAILURE);
                }
            } else if (field_count <= index_count && isdigit(*token)) { // Age, Salary
                char *endptr;
                long value = strtol(token, &endptr, 10);

                if (*endptr != '\0') {
                    pthread_mutex_lock(&log_mutex);
                    if (is_logging) {
                        fprintf(stderr, "Warning: Invalid entry skipped\n");
                    }
                    pthread_mutex_unlock(&log_mutex);
                    free(current_record->name);
                    current_record = NULL;
                    continue;
                }

                if (field_count == 2) { // Age
                    current_record->age = value;
                } else { // Salary
                    current_record->salary = (double)value;
                }
            }

            token = strtok(NULL, ",");
        }

        if (current_record != NULL) {
            index_pointers[current_record->age]++;

            if (field_count == index_count + 1) { // Valid entry
                stats.avg_salary += current_record->salary;
                total_entries++;

                if (total_entries % log_interval == 0 || total_entries == 1) {
                    pthread_mutex_lock(&log_mutex);
                    if (is_logging && log_level <= DEBUG) {
                        fprintf(stderr, "Processed: %d valid, %d invalid\n", valid_entries, total_entries - valid_entries);
                    }
                    pthread_mutex_unlock(&log_mutex);
                }

                current_record->name = realloc(current_record->name, nread + 1);
                if (!current_record->name) {
                    perror("Error allocating memory");
                    exit(EXIT_FAILURE);
                }

                MD5_CTX ctx;
                MD5_Init(&ctx);
                MD5_Update(&ctx, current_record->name, nread);
                MD5_Final(md5, &ctx);

                if (field_count < index_count) { // Record is incomplete but valid, save it for later
                    records[index_pointers[field_count]] = current_record;
                } else { // Record is complete, increment counter and continue processing next record
                    valid_entries++;
                    current_record = NULL;
                }
            }
        }
    }

    fclose(fp);
    gzdeflateEnd(gzfp, Z_STREAM_END);

    clock_t end = clock();
    double execution_time = (double)(end - start) / CLOCKS_PER_SEC;

    if (valid_entries > 0) {
        stats.avg_salary /= valid_entries;
        qsort(records, valid_entries, sizeof(Record*), compare_records);

        Stats partial_stats = {0};
        int middle_index = valid_entries / 2;

        for (int i = 0; i < middle_index; i++) {
            partial_stats.avg_salary += records[i]->salary;
        }

        if (valid_entries % 2 == 1) {
            partial_stats.avg_salary -= records[middle_index]->salary;
        }

        partial_stats.avg_salary /= middle_index * 2;
        stats.median_age = records[middle_index]->age;

        for (int i = 0; i < valid_entries; i++) {
            if (records[i]->salary < stats.min_salary || i == 0) {
                stats.min_salary = records[i]->salary;
            }

            if (records[i]->salary > stats.max_salary || i == valid_entries - 1) {
                stats.max_salary = records[i]->salary;
            }
        }
    }

    for (int i = 0; i < index_count; i++) {
        free(records[i]->name);
        free(records[i]);
    }
    free(records);
    free(index_pointers);

    Stats result = stats;
    result.execution_time = execution_time;

    return result;
}

static void init_log_handler(void) {
    FILE *logfp = fopen(logfile, "w");
    if (logfp == NULL) {
        perror("Error opening log file");
        exit(EXIT_FAILURE);
    }

    setvbuf(logfp, NULL, _IONBF, 0);
}

static int compare_records(const void *a, const void *b) {
    Record *r1 = *(Record**)a;
    Record *r2 = *(Record**)b;

    if (r1->salary < r2->salary) {
        return -1;
    } else if (r1->salary > r2->salary) {
        return 1;
    } else {
        return 0;
    }
}
```

