public async Task ProcessConfigFileAndExecuteActions(string configPath, IEnumerable<ActionModule> actionModules)
{
    var jsonSchema = JsonSchema.Parse(File.ReadAllText("config-schema.json")); // Adjust schema file path as needed

    try
    {
        var configuration = await JsonDocument.ParseAsync(await File.ReadFromJsonAsync<JsonElement>(configPath)).ConfigureAwait(false);

        if (!configuration.RootElement.TryGetProperty("actions", out JsonArray actions))
        {
            Logger.Warn($"Invalid JSON structure in configuration file: missing 'actions' property.");
            return;
        }

        var actionObjects = new List<ActionObject>();

        foreach (var action in actions)
        {
            if (!action.TryGetProperty("name", out JsonElement nameElement) || !action.TryGetProperty("actionMethod", out JsonElement methodElement))
            {
                Logger.Warn($"Invalid JSON structure for an action: missing 'name' or 'actionMethod' property.");
                continue;
            }

            var actionName = nameElement.GetString();
            var actionType = Type.GetType($"ActionNamespace.{actionName}"); // Adjust namespace as needed

            if (actionType == null)
            {
                Logger.Warn($"Invalid action type specified: '{actionName}'.");
                continue;
            }

            var constructor = actionType.GetConstructor(Type.EmptyTypes);

            if (constructor == null)
            {
                Logger.Warn($"Unable to find a parameterless constructor for action type '{actionType.FullName}'.");
                continue;
            }

            var actionObject = constructor.Invoke(null) as ActionObject;
            actionObject.ActionType = actionType;

            foreach (var property in actionType.GetProperties())
            {
                if (!property.CanWrite || !configuration.RootElement.TryGetProperty(property.Name, out JsonElement element))
                    continue;

                property.SetValue(actionObject, JsonSerializer.Deserialize(element.GetString(), property.PropertyType));
            }

            actionObjects.Add(actionObject);
        }

        var actionsToExecute = new List<Action>();

        foreach (var actionObject in actionObjects)
        {
            var actionInstance = Activator.CreateInstance(actionObject.ActionType, actionObject);
            var action = actionInstance as IAction;

            if (action == null)
            {
                Logger.Warn($"Unable to create an instance of action type '{actionObject.ActionType.FullName}'.");
                continue;
            }

            actionsToExecute.Add(action);
        }

        var context = new ActionContext { Logger = Logger };

        var tasks = actionsToExecute.Select(a => a.ExecuteAsync(context)).ToList();

        await Task.WhenAll(tasks).ConfigureAwait(false);
    }
    catch (Exception ex)
    {
        Logger.Error(ex, "An error occurred while processing the configuration file.");
    }
}
