    entry->pdcch.random_check = rand(); // Example of randomizing PDCCH data for simplicity
}

void push_log(struct log_entry *entry) {
    pthread_mutex_lock(&log_mutex);

    if (current_log_index >= LOG_ARRAY_SIZE) {
        printf("Log array overflow\n");
        pthread_mutex_unlock(&log_mutex);
        return;
    }

    log[current_log_index] = *entry;
    current_log_index++;
    pthread_mutex_unlock(&log_mutex);
}

void process_data(MAC_CONTEXT_T **array, size_t *entries, unsigned int concurrency) {
    MAC_CONTEXT_T *contexts = malloc(*entries * sizeof(MAC_CONTEXT_T));
    if (!contexts) {
        fprintf(stderr, "Memory allocation failed\n");
        return;
    }

    size_t chunk_size = *entries / concurrency;
    pthread_t threads[concurrency];
    struct source_metadata sources[concurrency];

    for (int i = 0; i < concurrency; ++i) {
        // Initialize each thread with data retrieval and entry validation functions
        void* ret = pthread_create(&threads[i], NULL, data_source, &sources[i]);
        if (ret != 0) {
            fprintf(stderr, "Thread creation failed: %s\n", strerror(ret));
            // Handle thread creation failure
        }
    }

    for (int i = 0; i < concurrency; ++i) {
        void* ret = pthread_join(threads[i], NULL);
        if (ret != 0) {
            fprintf(stderr, "Thread termination failed: %s\n", strerror(ret));
            // Handle thread termination failure
        }

        if (sources[i].id >= MAX_ID) {
            continue; // Skip sources that have exceeded the maximum ID limit
        }

        MAC_CONTEXT_T entry;
        validate_and_insert(&entry, &sources[i]);
        contexts[*entries - (concurrency - i)] = entry;
    }

    *array = contexts;
    *entries = concurrency;
}

void print_report() {
    printf("\nReport:\n");
    printf("Successful insertions: %zu\n", current_log_index - count_failed());
    printf("Failed insertions: %zu\n", count_failed());
}

size_t count_failed() {
    pthread_mutex_lock(&log_mutex);
    size_t count = 0;
    for (size_t i = 0; i < current_log_index; ++i) {
        if (!log[i].validated || !log[i].complete) {
            ++count;
        }
    }
    pthread_mutex_unlock(&log_mutex);
    return count;
}
