    SCHED_REQ_ID sched_req_id;
    MCS mcs;
    QOS_LEVEL qos_level;
};

class NetworkTrafficManager {
private:
    std::vector<MAC_CONTEXT_T> macContexts;
    std::mutex dataMutex;
    std::condition_variable dataCV;
    int maxSize = 0;
    unsigned long long successfulInsertions = 0;
    unsigned long long failedInsertions = 0;
    std::list<MAC_CONTEXT_T> staleEntries;
    std::unordered_map<std::string, TrafficType*> trafficTypes;
    std::vector<std::thread> threads;

public:
    NetworkTrafficManager(int maxSize);
    ~NetworkTrafficManager();
    void addTrafficType(const std::string& name, TrafficType* type);
    bool insertMacContext(MAC_CONTEXT_T context);
    void start();
    void stop();
    void clearStaleEntries();
    void printReport();
};

NetworkTrafficManager::NetworkTrafficManager(int maxSize)
    : maxSize(maxSize), macContexts(maxSize) {}

NetworkTrafficManager::~NetworkTrafficManager() {
    stop();
}

void NetworkTrafficManager::addTrafficType(const std::string& name, TrafficType* type) {
    trafficTypes[name] = type;
}

bool NetworkTrafficManager::insertMacContext(MAC_CONTEXT_T context) {
    // Validate data integrity and handle partial delivery

    if (isDataIntegrityValid(context)) {
        std::unique_lock<std::mutex> lock(dataMutex);
        macContexts.push_back(context);
        lock.unlock();
        successfulInsertions++;
        return true;
    } else {
        failedInsertions++;
        return false;
    }
}

void NetworkTrafficManager::start() {
    for (int i = 0; i < threads.size(); ++i) {
        threads.emplace_back([this]() {
            while (!isStopped()) {
                MAC_CONTEXT_T context;
                // Retrieve data from external source

                if (retrieveData(context)) {
                    insertMacContext(context);
                }
                std::this_thread::sleep_for(std::chrono::milliseconds(10));
            }
        });
    }
}

void NetworkTrafficManager::stop() {
    isStopped() = true;
    dataCV.notify_all();
    for (auto& t : threads) {
        t.join();
    }
}

void NetworkTrafficManager::clearStaleEntries() {
    std::unique_lock<std::mutex> lock(dataMutex);
    auto it = macContexts.begin();
    while (it != macContexts.end()) {
        if ((std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::system_clock::now().time_since_epoch()).count() - it->timestamp) > MAX_STALE_TIME) {
            staleEntries.push_back(*it);
            macContexts.erase(it);
            ++it;
        } else {
            ++it;
        }
    }
}

void NetworkTrafficManager::printReport() {
    std::cout << "Successful insertions: " << successfulInsertions << "\n";
    std::cout << "Failed insertions: " << failedInsertions << "\n";
}
