// Thread-safe random number generator with caching mechanism
std::unordered_map<unsigned int, unsigned long> randCache;
pthread_mutex_t randMutex = PTHREAD_MUTEX_INITIALIZER;

unsigned long getRand(unsigned int min, unsigned int max) {
    pthread_mutex_lock(&randMutex);
    auto it = randCache.find(min + (max - min));
    if (it != randCache.end()) {
        unsigned long ret = it->second;
        if (ret >= min && ret <= max) {
            randCache[min + (max - min)]++;
        } else {
            randCache.erase(it);
        }
        pthread_mutex_unlock(&randMutex);
        return ret;
    }
    unsigned long seed = time(NULL);
    if (!it) it = randCache.insert({min + (max - min), RAND_MAX}).first;
    it->second = RAND_MAX * (seed % (max - min + 1)) + min;
    pthread_mutex_unlock(&randMutex);
    return it->second;
}

