pthread_mutex_t md5Mutex = PTHREAD_MUTEX_INITIALIZER;

unsigned char* computeMD5(const unsigned char* data, size_t length) {
    pthread_mutex_lock(&md5Mutex);
    auto it = md5Cache.find(std::string((char*)data, length));
    if (it != md5Cache.end()) {
        pthread_mutex_unlock(&md5Mutex);
        return it->second;
    }
    unsigned char* result = static_cast<unsigned char*>(customMalloc(MD5_DIGEST_LENGTH));
    SHA1_CTX ctx;
    SHA1_Init(&ctx);
    SHA1_Update(&ctx, data, length);
    SHA1_Final(result, &ctx);
    md5Cache[std::string((char*)data, length)] = *result;
    pthread_mutex_unlock(&md5Mutex);
    return result;
}

