#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    char name[100];
    int start_time;
    int end_time;
} Task;

void initialize_tasks(Task** tasks, int num_tasks, int min_duration, int max_duration) {
    for (int i = 0; i < num_tasks; ++i) {
        *tasks = realloc(*tasks, sizeof(Task) * (i + 1));

        // Initialize task with random start and end times
        (*tasks)[i].start_time = rand() % max_duration + min_duration;
        (*tasks)[i].end_time = rand() % max_duration + min_duration;
    }
}

void validate_tasks(Task* tasks, int num_tasks) {
    qsort(tasks, num_tasks, sizeof(Task), compare_tasks);

    for (int i = 0; i < num_tasks - 1; ++i) {
        if ((tasks[i].end_time > tasks[i + 1].start_time) && (tasks[i].end_time >= tasks[i + 1].end_time)) {
            tasks[i].end_time -= tasks[i + 1].end_time - tasks[i + 1].start_time;
            tasks[i + 1].start_time += tasks[i].end_time;
        }
    }
}

int compare_tasks(const void* a, const void* b) {
    return ((Task*)a)->start_time - ((Task*)b)->start_time;
}

void print_tasks(Task* tasks, int num_tasks) {
    for (int i = 0; i < num_tasks; ++i) {
        printf("Task %d:\n", i + 1);
        printf("- Name: %s\n", tasks[i].name);
        printf("- Start time: %d\n", tasks[i].start_time);
        printf("- End time: %d\n", tasks[i].end_time);
        printf("\n");
    }
}

int main() {
    srand(time(NULL));

    int num_tasks = 5;
    int min_duration = 10, max_duration = 200;

    Task* tasks = NULL;
    initialize_tasks(&tasks, num_tasks, min_duration, max_duration);
    validate_tasks(tasks, num_tasks);
    print_tasks(tasks, num_tasks);

    free(tasks);
    return 0;
}
```
