#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <openssl/sha.h>
#include <openssl/aes.h>
#include <openssl/rand.h>

typedef struct {
    char name[100];
    int start, end;
} Task;

void initialize_cipher(unsigned char *key, const unsigned char *password, size_t length) {
    SHA1_CTX ctx;
    SHA1_Init(&ctx);
    SHA1_Update(&ctx, password, length);

    for (size_t i = 0; i < (length - 32); ++i) {
        SHA1_Update(&ctx, "\0", 1);
    }

    unsigned char hash[SHA_DIGEST_LENGTH];
    SHA1_Final(hash, &ctx);

    for (int i = 0; i < 32; ++i) {
        key[i] = hash[i];
    }
}

AES_KEY aes_ctx;
void initialize_aes(const unsigned char *password) {
    unsigned char key[32];
    initialize_cipher(key, password, strlen((char*)password));
    AES_set_encrypt_key(key, 256, &aes_ctx);
    AES_iv_length(&aes_ctx, AES_BLOCK_SIZE);
}

Task* create_tasks(size_t num_tasks, int start_range, int end_range) {
    Task *tasks = (Task*)malloc(num_tasks * sizeof(Task));
    if (!tasks) return NULL;

    srand(time(NULL));

    for (size_t i = 0; i < num_tasks; ++i) {
        int start = rand() % end_range + start_range;
        int end = rand() % (end_range - start + 1) + start;
        Task *task = &tasks[i];
        snprintf(task->name, sizeof(task->name), "Task %zu", i);
        task->start = start;
        task->end = end;

        for (size_t j = 0; j < i; ++j) {
            if ((tasks[i].start <= tasks[j].end) && (tasks[i].end >= tasks[j].start)) {
                // Overlap detected, adjust end time of the conflicting task
                task->end = rand() % (end_range - start + 1) + start;
            }
        }
    }

    return tasks;
}

void print_tasks(const Task *tasks, size_t num_tasks) {
    for (size_t i = 0; i < num_tasks; ++i) {
        printf("Task %zu: name=%s, start=%d, end=%d\n", i, tasks[i].name, tasks[i].start, tasks[i].end);
    }
}

void cleanup_aes() {
    AES_free_key(&aes_ctx);
}

int main() {
    unsigned char password[64];
    printf("Enter your password (max 64 chars): ");
    scanf("%s", password);

    initialize_aes(password);

    size_t num_tasks = 5;
    int start_range = 10, end_range = 100;
    Task *tasks = create_tasks(num_tasks, start_range, end_range);

    if (tasks) {
        print_tasks(tasks, num_tasks);
        free(tasks);
        cleanup_aes();
    }

    return 0;
}
```

