#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <openssl/aes.h>
#include <resolv.h>

typedef struct {
    char name[100];
    int start, end;
} Task;

struct aes_ctx {
    AES_KEY ctx;
    u_char iv[AES_BLOCK_SIZE];
};

int initialize(int num_tasks, int start_range, int end_range, const char* password, int* error) {
    Task *tasks = malloc(num_tasks * sizeof(Task));
    if (!tasks) {
        *error = 1;
        return 0;
    }

    struct aes_ctx *aes = calloc(1, sizeof(*aes));
    if (!aes) {
        free(tasks);
        *error = 2;
        return 0;
    }

    AES_set_encrypt_key((const unsigned char *)SHA1((const unsigned char*)password, strlen(password), SHA1_DIGEST_LENGTH), &aes->ctx, AES_KEY_LEN);

    u_char ip[NI_MAXHOST];
    int res = getnameinfo(gethostbyname("dns.server"), Ni_NoFlags, ip, NI_MAXHOST, 0, 0, 0);
    if (res != 0) {
        *error = 3;
        goto cleanup;
    }

    int index = 0;
    time_t start_time = time(NULL);
    for (int i = 0; i < num_tasks; ++i) {
        tasks[index].start = start_range + rand() % ((end_range - start_range) + 1);
        tasks[index].end = start_time + (tasks[index].start + rand() % ((end_range - start_range) + 1));

        bool valid = true;
        for (int j = 0; j < index; ++j) {
            if (tasks[i].start >= tasks[j].start && tasks[i].start <= tasks[j].end) {
                tasks[i].end += rand() % ((end_range - start_range) + 1);
                valid = false;
            }
            if (tasks[i].end > tasks[j].start && tasks[i].end <= tasks[j].end) {
                tasks[i].end += rand() % ((end_range - start_range) + 1);
                valid = false;
            }
        }
        if (valid) ++index;
    }

    printf("Task details:\n");
    for (int i = 0; i < index; ++i) {
        printf("Name: %s, Start Time: %d, End Time: %d\n", tasks[i].name, tasks[i].start, tasks[i].end);

cleanup:
    free(aes->iv);
    free(aes);
    free(tasks);
    return index;
}

int encrypt(const char* data, size_t length, const char* password, u_char** out, int* error) {
    struct aes_ctx *aes = calloc(1, sizeof(*aes));
    if (!aes) {
        *error = 1;
        return 0;
    }

    AES_set_encrypt_key((const unsigned char *)SHA1((const unsigned char*)password, strlen(password), SHA1_DIGEST_LENGTH), &aes->ctx, AES_KEY_LEN);

    u_char* encrypted = malloc(length + AES_BLOCK_SIZE);
    if (!encrypted) {
        free(aes);
        *error = 2;
        return 0;
    }

    int len = 0;
    AES_cbc_encrypt((const unsigned char *)data, (unsigned char *)encrypted, length, &aes->ctx, aes->iv, AES_ENCRYPT);
    len = strlen((char*)encrypted);
    *out = realloc(*out, len + 1);
    memcpy(*out, encrypted, len);
    (*out)[len] = '\0';
    free(aes->iv);
    free(aes);
    return len;
}

void disable_cipher(u_char* cipher) {
    free(cipher);
}
