#include <iostream>
#include <fstream>
#include <chrono>
#include <thread>
#include <mutex>
#include <condition_variable>
#include <map>
#include <string>
#include <functional>

std::mutex mtx; // Mutex for synchronization
std::condition_variable cv; // Condition variable for waiting on cooldown expiration

// Network response class
class NetworkResponse {
public:
    bool connected = false;
    std::function<bool(const std::string&)> getAttackAvailability; // Function to check attack availability
};

// Attack execution function
void executeAttack(const std::string& attackType, NetworkResponse& network, const std::string& logFile) {
    std::lock_guard<std::mutex> lock(mtx);

    if (!network.connected || isOnCooldown(attackType))
        return;

    // Execute the attack and update the cooldown timer
    bool success = network.getAttackAvailability(attackType);
    if (success) {
        std::cout << "Successfully executed " << attackType << std::endl;
        logAttack(logFile, attackType);
    } else {
        std::cout << "Attack failed: " << attackType << std::endl;
    }

    // Set cooldown timer for the given attack type
    setCooldown(attackType);
}

// Check if an attack is on cooldown
bool isOnCooldown(const std::string& attackType) {
    auto now = std::chrono::system_clock::now().time_since_epoch().count();
    auto cooldownDuration = std::stoll(std::getenv("COOLDOWN_DURATION")) * 1000; // Convert seconds to milliseconds

    auto cooldownTimer = attackCooldowns.find(attackType);
    if (cooldownTimer == attackCooldowns.end()) {
        cooldownTimer = std::make_pair(now, cooldownDuration);
        attackCooldowns[attackType] = cooldownTimer;
        return false;
    }

    if ((now - cooldownTimer->first) < cooldownTimer->second) {
        auto remainingTime = cooldownTimer->second - (now - cooldownTimer->first);
        std::unique_lock<std::mutex> lock(mtx);
        cv.wait_for(lock, std::chrono::milliseconds(remainingTime));
    }

    attackCooldowns[attackType] = {now, cooldownDuration};
    return true;
}

// Set the cooldown timer for an attack type
void setCooldown(const std::string& attackType) {
    auto now = std::chrono::system_clock::now().time_since_epoch().count();
    attackCooldowns[attackType] = {now, std::stoll(std::getenv("COOLDOWN_DURATION")) * 1000};
}

// Log an attack to a file
void logAttack(const std::string& logFile, const std::string& attackType) {
    std::ofstream log;
    log.open(logFile, std::ios_base::app);
    log << attackType << " - " << std::chrono::system_clock::to_time_t(std::chrono::system_clock::now()) << std::endl;
    log.close();
}

// Main function to handle multiple concurrent instances gracefully without introducing race conditions or data corruption
void mainFunction() {
    NetworkResponse network;
    // Initialize network connection here (e.g., using sockets)

    while (true) {
        executeAttack("attack1", network, "attacks.log");
        executeAttack("attack2", network, "attacks.log");

        // Handle other game logic or wait for external events here

        // Periodically check network connection and attempt to reconnect if necessary
        std::this_thread::sleep_for(std::chrono::seconds(5));
    }
}
