using System;
using System.Collections.Generic;
using System.Linq;
using System.Xml;
using System.Reflection;
using System.Threading.Tasks;
using System.IO;
using System.Diagnostics;
using BlueslipMockingLibrary; // Assuming the Blueslip mocking library is located in this namespace.

public async Task<TestResult> parseXMLAndRunTests(string xmlPath, string moduleName, Blueslip blueslip, List<TestObject> tests, int executionTimeout)
{
    XmlDocument document = await XDocument.LoadAsync(xmlPath).ConfigureAwait(false).ContinueWith(task => task.Result.Root.Element("root") ?? throw new FileNotFoundException()); // Parse XML asynchronously.
    var element = document.SelectSingleNode($"/root/{string.Join(",", tests.Select(t => t.name))}"); // Select the matching XPath nodes.
    if (element == null)
        throw new ArgumentException("No matching XML elements were found."); // If no element is found, throw an exception.
    else if (element.ParentNode.ChildNodes.Count > 1)
        throw new ArgumentException("More than one matching XML elements were found."); // If multiple elements are found, throw an exception.

    Assembly assembly = Assembly.LoadFile(Path.GetFileNameWithoutExtension(moduleName)); // Load the specified module.
    Type testType = assembly.GetTypes().FirstOrDefault(t => t.Name == moduleName); // Get the type of the specified module.
    if (testType == null)
        throw new ArgumentException("The specified module was not found."); // If the module is not found, throw an exception.

    ConcurrentDictionary<string, Stopwatch> stopwatches = new ConcurrentDictionary<string, Stopwatch>(); // Create a dictionary to store the stopwatches for each test.

    Task[] tasks = tests.Select(test =>
        Task.Run(() =>
        {
            blueslip.Reset(); // Reset the Blueslip instance before running each test.
            var sw = Stopwatch.StartNew(); // Start a stopwatch for the current test.
            stopwatches[test.name] = sw; // Add the stopwatch to the dictionary.
            try
            {
                var testInstance = Activator.CreateInstance(testType); // Create an instance of the test class.
                var testMethod = testType.GetMethod(test.testFunction); // Get the test method.
                testMethod.Invoke(testInstance, new[] { blueslip }); // Invoke the test method and pass the Blueslip instance as a dependency.
            }
            catch (Exception ex)
            {
                blueslip.Error($"Test '{test.name}' failed with error: {ex.Message}"); // Log the exception if it occurs during test execution.
            }
            finally
            {
                sw.Stop(); // Stop the stopwatch for the current test.
                TimeSpan duration = sw.Elapsed; // Get the duration of the test.
                blueslip.Log($"Test '{test.name}' completed in {duration.TotalMilliseconds:F3}ms at {DateTime.Now}"); // Log the completion of the test, including its duration.
            }
        })).ToArray()).WaitAll(); // Wait for all tests to complete.

    var results = tasks.Select((t, i) => new TestResult(i + 1, t.IsFaulted ? TestStatus.Failed : TestStatus.Passed, t.Exception?.Message ?? string.Empty, stopwatches[tests[i].name].Elapsed)).ToList(); // Create a list of TestResult objects.
    int totalTests = results.Count;
    int passedTests = results.Count(r => r.Status == TestStatus.Passed);
    int failedTests = totalTests - passedTests;

    return new TestResult { TotalTests = totalTests, PassedTests = passedTests, FailedTests = failedTests, TestResults = results }; // Return the final result object.
}

public class TestObject
{
    public string name { get; set; }
    public string testFunction { get; set; }
}

public class TestResult
{
    public int TotalTests { get; set; }
    public int PassedTests { get; set; }
    public int FailedTests { get; set; }
    public List<TestResult> TestResults { get; set; }

    public TestResult(int index, TestStatus status, string errorMessage, TimeSpan duration)
    {
        Index = index;
        Status = status;
        ErrorMessage = errorMessage;
        Duration = duration;
    }

    public int Index { get; set; }
    public TestStatus Status { get; set; }
    public string ErrorMessage { get; set; }
    public TimeSpan Duration { get; set; }
}

public enum TestStatus
{
    Passed,
    Failed
}
