// Custom memory pool for efficient management
typedef struct MemoryPool {
    void* data;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} MemoryPool;

void* customMalloc(size_t size, MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);
    if (pool->capacity - pool->size >= size) {
        void* result = pool->data + pool->size;
        pool->size += size;
        pthread_mutex_unlock(&pool->lock);
        return result;
    }
    void* result = realloc(pool->data, pool->capacity * 2);
    if (!result) {
        printf("Out of memory\n");
        exit(1);
    }
    pool->data = result;
    pool->capacity *= 2;
    pthread_mutex_unlock(&pool->lock);
    return pool->data + pool->size;
}

void customFree(void* ptr, MemoryPool* pool) {
    pthread_mutex_lock(&pool->lock);
    if (ptr >= pool->data && ptr < pool->data + pool->size) {
        memmove(ptr - size_t(1), ptr, sizeof(char) * size_t(pool->size - sizeof(char)*(ptr-pool->data)));
        pool->size -= sizeof(char);
    }
    pthread_mutex_unlock(&pool->lock);
}

// Thread-safe random number generator
typedef struct RandomNumberCache {
    int min, max;
    MemoryPool* cachePool;
    void** cache;
    size_t capacity;
    size_t size;
    pthread_mutex_t lock;
} RandomNumberCache;

int randomFromRange(RandomNumberCache* rnc, int min, int max) {
    if (!rnc->min || !rnc->max) {
        rnc->min = min;
        rnc->max = max;
    }
    pthread_mutex_lock(&rnc->lock);
    if (rnc->size <= rnc->capacity) {
        void* cacheEntry = customMalloc(sizeof(int), rnc->cachePool);
        *((int*)cacheEntry) = rand() % (max - min + 1) + min;
        rnc->size++;
    }
    pthread_mutex_unlock(&rnc->lock);
    return *(int*)customMalloc(sizeof(int), rnc->cachePool);
}

// Custom hash table for storing MD5 hashes
typedef struct HashTable {
    size_t capacity;
    int* keys;
    unsigned char** values;
    pthread_mutex_t lock;
} HashTable;

HashTable createHashTable(size_t capacity) {
    HashTable table;
    table.capacity = capacity;
    table.keys = (int*)customMalloc(sizeof(int) * capacity, &table);
    table.values = (unsigned char**[])customMalloc(sizeof(void*) * capacity, &table);
    table.lock = PTHREAD_MUTEX_INITIALIZER;
    return table;
}

bool hashTableInsert(HashTable* table, const char* key, unsigned char* value) {
    pthread_mutex_lock(&table->lock);
    size_t index = SHA1((unsigned char*)key, strlen(key), NULL) % table->capacity;
    for (int i = index; i < table->capacity; ++i) {
        if (!table->keys[i]) {
            table->keys[i] = atoi(key);
            table->values[i] = value;
            pthread_mutex_unlock(&table->lock);
            return true;
        }
    }
    for (int i = 0; i < index; ++i) {
        if (!table->keys[i]) {
            table->keys[i] = atoi(key);
            table->values[i] = value;
            pthread_mutex_unlock(&table->lock);
            return true;
        }
    }
    pthread_mutex_unlock(&table->lock);
    return false;
}

unsigned char* hashTableLookup(HashTable* table, const char* key) {
    pthread_mutex_lock(&table->lock);
    size_t index = SHA1((unsigned char*)key, strlen(key), NULL) % table->capacity;
    for (int i = index; i < table->capacity; ++i) {
        if (table->keys[i] == atoi(key)) {
            unsigned char* result = table->values[i];
            pthread_mutex_unlock(&table->lock);
            return result;
        }
    }
    for (int i = 0; i < index; ++i) {
        if (table->keys[i] == atoi(key)) {
            unsigned char* result = table->values[i];
            pthread_mutex_unlock(&table->lock);
            return result;
        }
    }
    pthread_mutex_unlock(&table->lock);
    return NULL;
}

