        log("Failed to allocate memory for data structures.");
        return;
    }

    sem_init(&sem_mutex, 0, 1); // Initialize the mutex for synchronization
    sem_init(&sem_queue, 0, count); // Initialize the queue for tracking available entries

    for (int i = 0; i < count; ++i) {
        retrieve_data(&data[i]);
    }

    pthread_t threads[count]; // Array to store thread IDs

    for (int i = 0; i < count; ++i) {
        pthread_create(&threads[i], NULL, &worker, (void*)&data[i]);
    }

    // Wait for all worker threads to finish processing the data structures
    for (int i = 0; i < count; ++i) {
        pthread_join(threads[i], NULL);
    }

    free(data); // Free the allocated memory
}

void* worker(void* arg) {
    NFAPI_CRC_INDICATION_PDU_T* entry = (NFAPI_CRC_INDICATION_PDU_T*)arg;
