    sem_wait(&sem_mutex); // Acquire the mutex to prevent data corruption during updating
    entry->crc_tag.value = num_entries; // Update the CRC tag with the current entry index
    sem_post(&sem_mutex); // Release the mutex after updating the CRC tag

    log("Processed and validated a new data entry.");

    return NULL;
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        printf("Usage: %s <number_of_entries>\n", argv[0]);
        return -1;
    }

    manage_entries(atoi(argv[1]));

    return 0;
}
