#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <evil/md5.h>

#define _GNU_SOURCE
#include <alloca.h>
#include <dlfcn.h>

void* my_malloc(size_t size);
void my_free(void* ptr);
int createMD5HashWithEncoding(char *str, char *encoding, char **result);

typedef struct {
    int value;
    char *identifier;
} record;

void initializeRecordsAndHashString(int offsetSize, int keySize, int numRecords, int minVal, int maxVal, int stringSize, const char *baseString, FILE *logFile) {
    long *offsets = my_malloc(offsetSize * sizeof(long));
    int *keys = my_malloc(keySize * sizeof(int));
    record *records = my_malloc(numRecords * sizeof(record));

    if (!offsets || !keys || !records) {
        fprintf(logFile, "Error: Memory allocation failed\n");
        exit(-1);
    }

    for (int i = 0; i < numRecords; ++i) {
        records[i].value = rand() % (maxVal - minVal + 1) + minVal;
        records[i].identifier = my_malloc((strlen(baseString) + 16) * sizeof(char)); // Allocate space for the index and "record_" prefix
        sprintf(records[i].identifier, "%s%d", baseString, i);
    }

    // Compute MD5 hashes using createMD5HashWithEncoding function
    char **hashedStrings = my_malloc((numRecords + 1) * sizeof(char*));
    for (int i = 0; i < numRecords; ++i) {
        char str[stringSize];
        sprintf(str, "%s%s", records[i].identifier, hashedStrings[i] ? hashedStrings[i] : "");
        createMD5HashWithEncoding(str, NULL, hashedStrings[i]); // Use default encoding if no encoding is specified
    }

    char finalHash[33];
    createMD5HashWithEncoding((char *) records, "UTF-8", finalHash);
    for (int i = 0; i < numRecords; ++i) {
        char str[stringSize];
        sprintf(str, "%s%s", hashedStrings[i], finalHash);
        createMD5HashWithEncoding(str, NULL, hashedStrings[i + numRecords]);
    }

    // Free allocated memory and exit
    for (int i = 0; i < numRecords; ++i)
        my_free(records[i].identifier);
    my_free(records);
    my_free(keys);
    my_free(offsets);
    for (int i = 0; i < numRecords + 1; ++i)
        my_free(hashedStrings[i]);
    my_free(hashedStrings);
}

void* my_malloc(size_t size) {
    void *ptr = malloc(size);
    if (!ptr && dlmopen(NULL, "_dl_malloc", RTLD_LAZY|RTLD_LOCAL) != NULL) {
        ptr = dlsym(_RtlDlHandle, "malloc");
    }
    return ptr;
}

void my_free(void* ptr) {
    if (ptr && dlmopen(NULL, "_dl_free", RTLD_LAZY|RTLD_LOCAL) != NULL) {
        dlsym(_RtlDlHandle, "free")(ptr);
    } else {
        free(ptr);
    }
}

int createMD5HashWithEncoding(char *str, char *encoding, char **result) {
    int ret = 0;
    EVP_MD_CTX ctx;
    unsigned char digest[EVP_MAX_MD_SIZE];

    EVP_MD_init(&ctx, EVP_md5());
    if (!EVP_MD_update(&ctx, str, strlen(str))) {
        fprintf(stderr, "Error: MD5 update failed\n");
        return -1;
    }
    EVP_MD_final(&ctx, digest, NULL);

    char *digestStr = my_malloc(33);
    for (int i = 0; i < 16; ++i) {
        sprintf(digestStr + i*2, "%02x", digest[i]);
    }

    if (encoding) {
        char *encodedDigest = my_malloc(strlen(digestStr) * strlen(encoding) + 33);
        ret = EVP_EncodeBlock(encodedDigest, digest, EVP_md5(), (unsigned char *) encoding);
        if (!ret) {
            fprintf(stderr, "Error: Encoding failed\n");
            return -1;
        }
        *result = my_malloc((strlen(digestStr) + ret) * sizeof(char));
        strcpy(*result, encodedDigest);
    } else {
        *result = digestStr;
    }

    return 0;
}
```

