**dynamic_list.c:**

```c
#include "dynamic_list.h"
#include <sys/mman.h>
#include <time.h>

static size_t total_allocated = 0;
static Object *head = NULL;
static const size_t MAX_OBJECTS = 5000;

Object *create_dynamic_list(size_t n, size_t max_objects) {
    if (n <= 0 || max_objects <= 0 || n > max_objects) {
        fprintf(stderr, "Invalid parameters.\n");
        return NULL;
    }

    Object *new_head = mmap(NULL, sizeof(Object) * n, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (new_head == MAP_FAILED) {
        perror("mmap failed");
        return NULL;
    }

    total_allocated += sizeof(Object) * n;
    if (total_allocated > (1ULL << 24)) { // 16 MB limit
        fprintf(stderr, "Memory allocation exceeded the specified limit.\n");
        munmap(new_head, sizeof(Object) * n);
        return NULL;
    }

    srand((unsigned int)time(NULL));
    for (size_t i = 0; i < n; ++i) {
        Object *obj = new_head + i;
        memset(obj, 0, sizeof(*obj));
        obj->int_val = rand() % RAND_MAX / 10;
    }

    if (head != NULL) { // If there is an existing list, link the new objects.
        Object *current = head;
        for (size_t i = n - 1; i > 0; --i)
            current->next = new_head + i;
        head->next = new_head;
        head = new_head;
    } else {
        head = new_head; // If this is the first list, set head to the new list.
    }

    return head;
}

void destroy_dynamic_list(Object *head) {
    if (head == NULL || total_allocated == 0)
        return;

    Object *current = head;
    while (current != NULL) {
        Object *next = current->next;
        free(current);
        current = next;
    }
    total_allocated = 0;
}
```

