#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>
#include <sys/mman.h>
#include <string.h>
#include <stdbool.h>

typedef struct {
    long offset;
    int key;
    char *str;
    int value;
    void *ptr; // pointer to another object within the list
    enum { PENDING, COMPLETED } state;
    struct record record;
} Object;

typedef struct Node {
    Object obj;
    struct Node *next;
} Node;

// Hash table for quick access based on object identifiers
typedef struct {
    unsigned long capacity;
    unsigned long size;
    Node **table;
    pthread_mutex_t mutex;
} HashTable;

void init_hash_table(HashTable *ht, unsigned long capacity) {
    ht->capacity = capacity;
    ht->size = 0;
    ht->table = calloc((size_t)capacity, sizeof(Node*));
    if (!ht->table) return;
    pthread_mutex_init(&ht->mutex, NULL);
}

// Hash function for object identifiers
unsigned long hash(long key) {
    return key % ht->capacity;
}

void resize_hash_table(HashTable *ht) {
    unsigned long old_capacity = ht->capacity;
    unsigned long new_capacity = old_capacity * 2;
    Node **old_table = ht->table;

    // Reallocate hash table and copy elements to the new one
    ht->table = calloc((size_t)new_capacity, sizeof(Node*));
    if (!ht->table) return;

    for (unsigned long i = 0; i < old_capacity; ++i) {
        Node *node = old_table[i];
        while (node != NULL) {
            Node *next = node->next;
            Object obj = node->obj;
            unsigned long h = hash(obj.key);
            node->next = ht->table[h];
            ht->table[h] = node;
            node = next;
        }
    }
    free(old_table);
    ht->capacity = new_capacity;
}

void mark_object_pending(Object *obj) {
    pthread_mutex_lock(&obj->obj.ptr->ht.mutex);
    obj->obj.state = PENDING;
    pthread_mutex_unlock(&obj->obj.ptr->ht.mutex);
}

void mark_object_completed(Object *obj) {
    pthread_mutex_lock(&obj->obj.ptr->ht.mutex);
    obj->obj.state = COMPLETED;
    pthread_mutex_unlock(&obj->obj.ptr->ht.mutex);
}

void create_objects(HashTable *ht, size_t n, long capacity) {
    if (n <= 0 || n > 16777216 / sizeof(Object)) return; // Ensure n is within reasonable range

    Object *memory_pool = mmap(NULL, capacity * sizeof(Object), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (memory_pool == MAP_FAILED) return;

    for (size_t i = 0; i < n; ++i) {
        Object *obj = memory_pool + i;
        obj->str = "";
        obj->value = rand() % 100;
        obj->ptr = NULL;
        obj->state = PENDING;
    }

    size_t used = n * sizeof(Object);
    while (used > capacity) {
        resize_hash_table(ht);
        used -= n * sizeof(Object);
        n >>= 1;
    }

    Object **objects = calloc((size_t)n, sizeof(Object*));
    for (size_t i = 0; i < n; ++i) objects[i] = memory_pool + i;

    // Insert objects into the hash table and linked list
    pthread_mutex_lock(&ht->mutex);
    for (size_t i = 0; i < n; ++i) {
        Object *obj = objects[i];
        unsigned long h = hash(obj->key);
        obj->next = ht->table[h];
        ht->table[h] = obj;
    }
    pthread_mutex_unlock(&ht->mutex);
}

void free_objects(HashTable *ht, size_t n) {
    for (size_t i = 0; i < n; ++i) {
        Object *obj = ht->table[i];
        while (obj != NULL) {
            Node *next = obj->next;
            free(obj);
            obj = next;
        }
    }
    free(ht->table);
    munmap(ht->memory_pool, ht->capacity * sizeof(Object));
}
