    ComplexObject *obj;
    struct HashEntry *next;
} HashEntry;

#define HASH_SIZE 1024
ComplexObject *head = NULL;
HashEntry hash[HASH_SIZE];
pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;

void init_hash() {
    for (int i = 0; i < HASH_SIZE; ++i) {
        hash[i].obj = NULL;
        hash[i].next = &hash[i + 1];
    }
}

ComplexObject* create_complex_object(void) {
    ComplexObject *obj = malloc(sizeof(ComplexObject) + MAX_STR_LEN);
    if (!obj) return NULL;
    obj->str[0] = '\0';
    obj->val = rand() % 1000;
    obj->record.value = 0;
    pthread_mutex_init(&obj->mutex, NULL);
    obj->offset = (long)obj - (long)head;
    obj->key = -1;
    obj->next = obj->prev = NULL;
    obj->state = PENDING;
    return obj;
}

void insert_complex_object(ComplexObject *obj) {
    pthread_mutex_lock(&list_mutex);
    HashEntry **entry = &hash[obj->offset % HASH_SIZE];
    while (*entry && (*entry)->obj->offset < obj->offset) {
        entry = &(*entry)->next;
    }
    obj->next = *entry ? (*entry)->obj : head;
    if (head) head->prev = obj;
    else head = obj;
    obj->prev = *entry;
    if (entry && *entry) (*entry)->next = obj;
    *entry = &((HashEntry){.obj = obj, .next = NULL});
    pthread_mutex_unlock(&list_mutex);
}

ComplexObject* find_complex_object(long offset) {
    pthread_mutex_lock(&list_mutex);
    HashEntry *entry = &hash[offset % HASH_SIZE];
    while (entry->obj && entry->obj->offset < offset) {
        entry = entry->next;
    }
    ComplexObject* obj = NULL;
    if (entry->obj && entry->obj->offset == offset) {
        obj = entry->obj;
    }
    pthread_mutex_unlock(&list_mutex);
    return obj;
}

void destroy_complex_object(ComplexObject *obj) {
    pthread_mutex_lock(&obj->mutex);
    if (obj->next) obj->next->prev = obj->prev;
    if (obj->prev) obj->prev->next = obj->next;
    if (head == obj) head = obj->next;
    free(obj);
    pthread_mutex_unlock(&obj->mutex);
}

void mark_complex_object(ComplexObject *obj, enum { PENDING, COMPLETED } state) {
    pthread_mutex_lock(&obj->mutex);
    obj->state = state;
    pthread_mutex_unlock(&obj->mutex);
}

int list_memory_usage() {
    int used = 0;
    ComplexObject *obj;
    pthread_mutex_lock(&list_mutex);
    for (ComplexObject *node = head; node; node = node->next) {
        ++used;
        obj = node;
    }
    pthread_mutex_unlock(&list_mutex);
    return used * sizeof(ComplexObject);
}

void reset_list() {
    ComplexObject* obj, *next;
    while (head) {
        obj = head;
        head = head->next;
        next = obj->prev;
        destroy_complex_object(obj);
    }
    init_hash();
}
