struct cache_entry {
    unsigned int min, max, next_uid;
};

// Hybrid random number generator using xoroshiro128+ and a simple linear congruential method.
unsigned int hybrid_rand(struct cache_entry* entry) {
    const uint64_t xorshifted = entry->next_uid * 0x5DEECE66D + 0xBLL;
    unsigned long shift = (xorshifted >> 127) ^ (xorshifted >> 95) ^ (xorshifted >> 64);
    entry->next_uid = xorshifted - shift;
    return entry->min + (entry->max - entry->min) * (entry->next_uid / UINT32_MAX);
}

struct cache {
    struct cache_entry* entries;
    size_t size, capacity;
};

void init_cache(struct cache* c, unsigned int min, unsigned int max, size_t initial_capacity) {
    c->entries = calloc(initial_capacity, sizeof(struct cache_entry));
    if (!c->entries) exit(EXIT_FAILURE);
    c->size = 0;
    c->capacity = initial_capacity;

    for (size_t i = 0; i < initial_capacity; ++i) {
        struct cache_entry* ce = &c->entries[i];
        ce->min = min, ce->max = max, ce->next_uid = hybrid_rand(ce);
    }
}

void resize_cache(struct cache* c, size_t new_capacity) {
    if (new_capacity <= c->capacity) return;

    struct cache_entry* new_entries = realloc(c->entries, new_capacity * sizeof(struct cache_entry));
    if (!new_entries) exit(EXIT_FAILURE);

    c->entries = new_entries;
    c->capacity = new_capacity;
}

void free_cache(struct cache* c) {
    free(c->entries);
}

