#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

typedef struct {
    long file_offset;
    int key;
} record;

void manage_memory(int num_files, char** filenames, int min_rand, int max_rand) {
    long* file_offsets = malloc(num_files * sizeof(long));
    memset(file_offsets, 0, num_files * sizeof(long));
    int* keys = malloc(num_files * sizeof(int));
    record* records = malloc(num_files * sizeof(record));

    // Generate unique keys based on filenames
    for (int i = 0; i < num_files; ++i) {
        int key = hash(filenames[i]);
        while (i != key) {
            keys[key] = -1; // mark key as used to avoid duplicate keys
            key = hash(filenames[i]);
        }
        keys[key] = i;
    }

    // Associate file offsets and keys with records
    for (int i = 0; i < num_files; ++i) {
        long file_offset = file_offsets[i];
        int key = keys[i];
        records[i].file_offset = file_offset;
        records[i].key = key;
    }

    // Set the value of each record's int field to a random number within the specified range
    srand(time(NULL));
    for (int i = 0; i < num_files; ++i) {
        records[i].int_field = min_rand + rand() % (max_rand - min_rand + 1);
    }

    // Sort the records based on their file offsets using a efficient sorting algorithm (e.g. quicksort or mergesort)
    qsort(records, num_files, sizeof(record), compare_long);

    free(file_offsets);
    free(keys);
}

int hash(char* filename) {
    unsigned long hash = 5381;
    int c;
    while ((c = *filename++))
        hash = ((hash << 5) + hash) + c; // hash * 33 + c
    return hash % num_files;
}

int compare_long(const void* a, const void* b) {
    return (*(const long*)a - *(const long*)b);
}
