typedef struct State {
    int id;
    void* transition_rules; // Replace with desired data structure for transition rules
    struct State* next;
    enum { PENDING, COMPLETED } state;
} State;

#define MAX_STATES 10000
#define MIN_STATES 500
#define MEMORY_LIMIT (16 * 1024 * 1024) // 16 MB

State* create_state_list(int n) {
    if (n <= 0 || n > MAX_STATES) {
        fprintf(stderr, "Invalid number of states: should be between 1 and %d\n", MAX_STATES);
        return NULL;
    }

    pthread_mutex_t memory_mutex = PTHREAD_MUTEX_INITIALIZER;
    size_t state_size = sizeof(State);
    size_t list_size = n * state_size;

    if (list_size > MEMORY_LIMIT) {
        fprintf(stderr, "Requested number of states (%d) exceeds the maximum memory limit (%llu bytes)\n", n, MEMORY_LIMIT);
        return NULL;
    }

    void* memory = malloc(list_size);
    if (!memory) {
        fprintf(stderr, "Failed to allocate memory for %d states\n", n);
        pthread_mutex_destroy(&memory_mutex);
        return NULL;
    }

    State* head = (State*)memory;
    State* tail = head;
    for (int i = 0; i < n - 1; ++i) {
        tail->next = (State*)((char*)tail + state_size);
        tail = tail->next;
        memset(tail, 0, state_size);
    }

    // Seed random number generator with time to ensure deterministic behavior
    srand((unsigned)time(NULL));

    for (State* state = head; state != NULL && state < tail; ++state) {
        state->id = rand() % 1000000; // Replace with desired range for state IDs
        state->transition_rules = calloc(1, sizeof(void*));
        if (!state->transition_rules) {
            perror("Failed to allocate memory for transition rules");
            break;
        }
    }

    return head;
}

// ... Add functions to handle pending/completed states and query state status by ID.
