}

// Function to allocate memory aligned on a specified boundary
void* align_memory(size_t size, size_t alignment) {
    size_t new_size = ((size + alignment - 1) / alignment) * alignment;
    void *aligned_ptr = mmap(NULL, new_size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (aligned_ptr == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }
    return aligned_to(aligned_ptr, alignment);
}

// Function to align a pointer to a specified boundary
void* align_to(void *ptr, size_t alignment) {
    return (void*)(((size_t)ptr + alignment - 1) & ~(alignment - 1));
}

void init_data_structures(int n, int m, int p, struct MemoryPool *mp) {
    // Validate input parameters
    if (n <= 0 || m <= 0 || p < 0 || p > 10000 || n*m > 1000000) {
        fprintf(stderr, "Invalid input parameters. n, m and the product of n and m should be positive integers within a reasonable range.\n");
        exit(EXIT_FAILURE);
    }

    // Allocate memory for offsets, keys, and records using the custom memory pool manager (if provided) or default malloc() function
    long* offsets = (long*)mp->alloc(sizeof(long)*n);
    int* keys = (int*)mp->alloc(sizeof(int)*m);
    Record *records = (Record*)mp->alloc(sizeof(Record)*p);

    // Initialize offsets and keys to zero and set a seed for the random number generator
    for (int i = 0; i < n; ++i) {
        offsets[i] = 0;
    }
    for (int i = 0; i < m; ++i) {
        keys[i] = 0;
    }

    // Set the values of the record structures to random integers within a specified range
    srand(time(NULL));
    for (int i = 0; i < p; ++i) {
        records[i].value = rand() % 100;
    }

    // Free memory upon successful completion or error
    if (mp != NULL) {
        mp->free(offsets);
        mp->free(keys);
        mp->free(records);
    } else {
        free(offsets);
        free(keys);
        free(records);
    }
}

// Documentation comments for the function
/**
