    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint16_t CRC_INDICATION_REL8_TAG;
    uint16_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

#define MAX_BUFFER_SIZE 1024 // adjust as needed
#define MAX_NUM_PDUS 1000
#define K 10 // adjustable sliding window size for tag check
#define THRESHOLD_RESIZES 5
#define RNTI_RANGE (65536 - 1)
#define SEED_OFFSET 139168 // adjust as needed

static uint32_t tags[MAX_NUM_PDUS] = {0};
static uint16_t rntis[MAX_NUM_PDUS] = {0};
static size_t buffer_size = 0;
static size_t num_resizes = 0;
static time_t last_seed = 0;

void manage_pdds(NFAPI_CRC_INDICATION_PDU_T** pdds, uint32_t num_pdds) {
    if (num_pdds <= 0 || num_pdds > MAX_NUM_PDUS) {
        fprintf(stderr, "Invalid number of PDDs: should be in the range [1, %d]\n", MAX_NUM_PDUS);
        return;
    }

    if (buffer_size < num_pdds) {
        size_t new_size = buffer_size ? buffer_size * 2 : MAX_BUFFER_SIZE;
        if (new_size < num_pdds) new_size = num_pdds;

        NFAPI_CRC_INDICATION_PDU_T* temp_buffer = realloc(*pdds, new_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!temp_buffer) {
            fprintf(stderr, "Memory allocation failed\n");
            return;
        }

        buffer_size = new_size;
        *pdds = temp_buffer;
        num_resizes++;
        if (num_resizes > THRESHOLD_RESIZES) {
            fprintf(stderr, "Buffer resized too many times, potential memory leak or excessive PDD usage\n");
        }
    }

    for (size_t i = buffer_size; i < num_pdds; ++i) {
        (*pdds)[i].RX_UE_INFORMATION_TAG = hash(i);

        // Check uniqueness within the sliding window
        size_t j;
        for (j = i - K >= 0 ? i - K : 0; j < i; ++j) {
            if ((*pdds)[j].RX_UE_INFORMATION_TAG == (*pdds)[i].RX_UE_INFORMATION_TAG) break;
        }
        if (j != i) continue; // Retry with a different tag value

        // Validate tag within acceptable range
        if ((*pdds)[i].RX_UE_INFORMATION_TAG >= MAX_NUM_PDUS || (*pdds)[i].RX_UE_INFORMATION_TAG > 10000) {
            fprintf(stderr, "Invalid RX UE INFORMATION TAG: %u\n", (*pdds)[i].RX_UE_INFORMATION_TAG);
            continue;
        }

        // Assign RNTI and CRCFLAG values
        (*pdds)[i].RNTI = hash(i * (RNTI_RANGE + 1)) % RNTI_RANGE + 1;
        while (find_rnti((*pdds), i, (*pdds)[i].RNTI)) {
            (*pdds)[i].RNTI = hash(i * (RNTI_RANGE + 1)) % RNTI_RANGE + 1;
        }

        time_t now = time(NULL);
        if (now - last_seed > 60) { // Seed random number generator every minute
            srand((unsigned)now * SEED_OFFSET);
            last_seed = now;
        }
        (*pdds)[i].CRCFLAG = rand() % 16;
    }
}

uint32_t hash(uint32_t key) {
    // Custom hash function to ensure even distribution and minimize collisions
    uint32_t a = 0xdeadbeef, b = 0xfedcba98;
    uint64_t k = (uint64_t)key * 0x1badc00d + 0xd76aa478;

    k = ((k << 32) | (k >> 32)) ^ a; a = b;
    k = ((k << 32) | (k >> 32)) ^ a; a = b;
    k = ((k << 32) | (k >> 32)) ^ a; a = b;
    k = ((k << 32) | (k >> 32)) ^ a; a = b;
    return k;
}

bool find_rnti(const NFAPI_CRC_INDICATION_PDU_T* buffer, size_t index, uint16_t rnti) {
    for (size_t i = 0; i < buffer_size; ++i) {
        if (i == index) continue;
        if ((buffer[i].RNTI == rnti) && (index - i <= K)) return true;
    }
    return false;
}
