// Custom memory allocator with best-fit and worst-fit strategies
typedef struct MemBlock {
    size_t size;
    struct MemBlock* next;
} MemBlock;

MemBlock* freeList = NULL;
MemBlock* usedList = NULL;

void initAllocator(size_t initialSize) {
    MemBlock* block = (MemBlock*)malloc(initialSize);
    block->size = initialSize;
    block->next = NULL;
    freeList = block;
}

MemBlock* allocate(size_t size, int strategy) {
    MemBlock* current = freeList;
    MemBlock* bestFit = NULL;
    MemBlock* worstFit = NULL;

    while (current != NULL) {
        if (strategy == 1 && current->size >= size) { // Best-fit
            if (!bestFit || (bestFit->size > current->size)) {
                bestFit = current;
            }
        } else if (strategy == 0 || !worstFit || (current->size <= worstFit->size)) { // Worst-fit
            worstFit = current;
        }
        current = current->next;
    }

    if (bestFit) {
        if (bestFit->size == size) {
            bestFit->next = freeList;
            freeList = bestFit;
            return bestFit;
        } else {
            MemBlock* newBlock = (MemBlock*)malloc(size);
            memcpy(newBlock, bestFit, size);
            bestFit->size -= size;
            if (bestFit->size == 0) {
                freeList = bestFit->next;
            }
            newBlock->next = bestFit->next;
            bestFit->next = newBlock;
            return newBlock;
        }
    } else if (worstFit) {
        size_t remainingSize = worstFit->size - size;
        if (remainingSize > size) {
            worstFit->size -= size;
            return worstFit + size;
        } else {
            MemBlock* newBlock = (MemBlock*)malloc(size);
            memcpy(newBlock, worstFit, size);
            free(worstFit);
            worstFit = newBlock;
            return newBlock;
        }
    }

    return NULL; // Out of memory
}

// NFAPI_CRC_INDICATION_PDU_T structure definition
typedef struct {
