int dataSourceDelay = 10; // in milliseconds

void* fillBuffer(void* arg) {
    srand((unsigned int)time(NULL));

    for (int i = 0; i < BUFFER_SIZE; ++i) {
        buffer[i].rxTag.tag = rand() % 256;
        buffer[i].rnti.length = 1 + (rand() % 4);
        buffer[i].rnti.value[0] = rand() % 256;
        buffer[i].crcIndicationTag.tag = rand() % 256;
        buffer[i].crcFlag = rand() % 2;

        usleep(dataSourceDelay * 1000); // simulate delay
    }
}

void correctInconsistencies(NFAPI_CRC_INDICATION_PDU_T* pdu) {
    if (pdu->rxTag.tag > 255 || pdu->rxTag.tag < 0) {
        pdu->rxTag.tag = (pdu->rxTag.tag + 256) % 256;
    }

    if (pdu->rnti.length <= 0 || pdu->rnti.length > 4) {
        pdu->rnti.length = 1;
    }

    if (pdu->rnti.value[0] > 255 || pdu->rnti.value[0] < 0) {
        pdu->rnti.value[0] = (pdu->rnti.value[0] + 256) % 256;
    }
}

void populateBuffer(int numEntries) {
    pthread_t threads[numEntries];

    for (int i = 0; i < numEntries; ++i) {
        pthread_create(&threads[i], NULL, fillBuffer, NULL);
    }

    for (int i = 0; i < numEntries; ++i) {
        pthread_join(threads[i], NULL);
    }

    pthread_mutex_lock(&mutex);

    int bufferIndex = 0;
    for (int i = 0; i < numEntries; ++i) {
        correctInconsistencies(&buffer[bufferIndex]);
        ++bufferIndex;
    }

    pthread_mutex_unlock(&mutex);
}

