        MD5_Init(&ctx);
        MD5_Update(&ctx, input, strlen(input));
        MD5_Final(digest, &ctx);
        memcpy(entry->hash, digest, sizeof(entry->hash));
        for (size_t j = 0; j < MD5_DIGEST_LENGTH; ++j) {
            snprintf(&hash_str[2 * j], 3, "%02x", entry->hash[j]);
        }
        entry->timestamp = time(NULL);
    }

    // Free allocated resources and close the function
    free(keys);
    free(records);
    munmap(offsets, array_size * sizeof(long));
    free(hash_table);
    pthread_mutex_destroy(&mempool.mutex);
    free(mempool.blocks[0].data);
    free(mempool.blocks);
}
