#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <sys/time.h>
#include <string.h>
#include <stdbool.h>

typedef struct {
    uint16_t sequence_number;
    uint16_t tx_ue_id;
    char ccch_message[256];
} UL_CCCH_MESSAGE_T;

typedef struct {
    UL_CCCH_MESSAGE_T* messages;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} NFAPI_UL_CCCH_MESSAGE_LIST_T;

NFAPI_UL_CCCH_MESSAGE_LIST_T* initialize_message_list(size_t num_messages) {
    NFAPI_UL_CCCH_MESSAGE_LIST_T* list = malloc(sizeof(NFAPI_UL_CCCH_MESSAGE_LIST_T));
    list->capacity = num_messages;
    list->count = 0;
    list->messages = calloc(num_messages, sizeof(UL_CCCH_MESSAGE_T));
    pthread_mutex_init(&list->mutex, NULL);
    return list;
}

void add_message(NFAPI_UL_CCCH_MESSAGE_LIST_T* list, UL_CCCH_MESSAGE_T message) {
    pthread_mutex_lock(&list->mutex);
    if (list->count < list->capacity) {
        memcpy((void*)&list->messages[list->count], &message, sizeof(UL_CCCH_MESSAGE_T));
        list->count++;
    }
    pthread_mutex_unlock(&list->mutex);
}

bool validate_tx_ue_id(uint16_t tx_ue_id) {
    return tx_ue_id >= 1 && tx_ue_id <= 65535;
}

UL_CCCH_MESSAGE_T generate_message() {
    struct timeval tv;
    gettimeofday(&tv, NULL);
    unsigned long seed = (unsigned long)tv.tv_usec * ((unsigned long)gettid()) + tv.tv_sec;
    srand(seed);
    UL_CCCH_MESSAGE_T message;
    memset(&message, 0, sizeof(UL_CCCH_MESSAGE_T));
    sprintf(message.ccch_message, "%lu", rand() % 1000000);
    message.tx_ue_id = rand() % 65536;
    return message;
}

void* process_line(void* arg) {
    FILE* file = (FILE*)arg;
    char line[4096];
    UL_CCCH_MESSAGE_LIST_T* list = initialize_message_list(1024); // Adjust the number of messages as needed

    while (fgets(line, sizeof(line), file)) {
        char* token = strtok(line, ",");
        size_t i = 0;
        UL_CCCH_MESSAGE_T message;

        while (token != NULL) {
            if (i == 1) {
                message.tx_ue_id = atoi(token);
                if (!validate_tx_ue_id(message.tx_ue_id)) {
                    fprintf(stderr, "Invalid TX_UE_ID: %u\n", message.tx_ue_id);
                    continue;
                }
            } else if (i == 2) {
                strcpy(message.ccch_message, token);
            }

            if (++i >= 3) {
                add_message(list, message);
                i = 0;
            }

            token = strtok(NULL, ",");
        }
    }

    fclose(file);

    for (size_t i = 0; i < list->count; ++i) {
        printf("%s", list->messages[i].ccch_message);
        if (i != list->count - 1) {
            printf(", ");
        }
    }
    printf(", %.2f\n", ((float)(list->messages[list->count - 1].tx_ue_id + list->messages[list->count - 2].tx_ue_id)) / 2.0);

    free(list->messages);
    free(list);
}

int main(int argc, char* argv[]) {
    if (argc < 2) {
        fprintf(stderr, "Usage: %s [inputfile]\n", argv[0]);
        return -1;
    }

    FILE* file = fopen(argv[1], "r");
    if (!file) {
        perror("Error opening input file");
        return -1;
    }

    pthread_t threads[4]; // Adjust the number of threads as needed

    for (size_t i = 0; i < sizeof(threads) / sizeof(threads[0]); ++i) {
        if (pthread_create(&threads[i], NULL, process_line, file)) {
            perror("Error creating thread");
            return -1;
        }
    }

    for (size_t i = 0; i < sizeof(threads) / sizeof(threads[0]); ++i) {
        if (pthread_join(threads[i], NULL)) {
            perror("Error joining thread");
            return -1;
        }
    }

    fclose(file);
    return 0;
}
