        auto it = strings.begin();
        if (it != strings.end()) {
            for (int i = 0; it != strings.end() && i < targetSequenceNumber; ++i, ++it);
            it = it != strings.end() ? it : strings.end();
            if (it != strings.end()) {
                *it = insertString1 + *it;
                auto nextIt = std::next(it);
                if (nextIt != strings.end()) {
                    *nextIt = *nextIt + insertString2;
                } else {
                    strings.push_back(insertString2);
                }
