        std::string ccchMessage;
        for (int i = 0; i < rand() % (128 - 8 + 1) + 8; ++i) {
            ccchMessage += alphanum[rand() % (sizeof(alphanum) - 1)];
        }
        return encrypt(ccchMessage);
    }

    std::string encrypt(const std::string& plaintext) {
        EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
        EVP_EncryptInit_ex(ctx, cipher, nullptr, reinterpret_cast<unsigned char*>(&plaintext[0]), nullptr);
        std::vector<unsigned char> encrypted;
        unsigned int encryptedSize = 0;
        while ((encryptedSize = EVP_EncryptUpdate(ctx, &encrypted.front(), encrypted.size(), reinterpret_cast<const unsigned char*>(&plaintext[0]), plaintext.size())) > 0) {
            encrypted.resize(encryptedSize);
        }
        unsigned int finalSize = 0;
        encrypted.resize(encryptedSize + EVP_EncryptFinal_ex(ctx, &encrypted.back(), &finalSize));
        std::string ciphertext;
        ciphertext.insert(ciphertext.end(), encrypted.begin(), encrypted.end());
        EVP_CIPHER_CTX_free(ctx);
        return ciphertext;
    }

