            std::random_device rd;
            std::generate_n(key, EVP_CIPHER_key_length(cipher), std::bind(std::uniform_int_distribution<unsigned int>(0, 255), std::default_random_engine(randomSeed)));
            if (1 != EVP_CIPHER_set_key(cipher, key, key)) {
                cipher = nullptr;
            }
        }
    }
