typedef struct {
    uint16_t sequence_number;
    uint16_t tx_ue_id;
    char ccch_message[256]; // Adjust size as needed
} UL_CCCH_MESSAGE_T;

typedef struct {
    UL_CCCH_MESSAGE_T* messages;
    size_t num_messages;
    size_t message_size;
    pthread_mutex_t lock;
    pthread_t tid; // Thread ID for UE_ID generation
    int* available_ids; // Pool of available UE IDs
    size_t max_ids;
} UL_CCCH_MESSAGE_CTX;

UL_CCCH_MESSAGE_CTX* ul_ccch_message_init(size_t num_messages, size_t message_size) {
    UL_CCCH_MESSAGE_CTX* ctx = malloc(sizeof(UL_CCCH_MESSAGE_CTX));
    if (!ctx) return NULL;

    ctx->num_messages = num_messages;
    ctx->message_size = message_size;
    ctx->messages = calloc(num_messages, message_size);
    if (!ctx->messages) goto error;

    ctx->lock = PTHREAD_MUTEX_INITIALIZER;

    // Initialize available ID pool
    ctx->max_ids = 65536;
    ctx->available_ids = calloc(ctx->max_ids, sizeof(int));
    for (size_t i = 0; i < ctx->max_ids; ++i) ctx->available_ids[i] = i;

    return ctx;
error:
    free(ctx);
    return NULL;
}

void* generate_ue_id(void* arg) {
    UL_CCCH_MESSAGE_CTX* ctx = arg;

    // Generate UE ID using pseudo-random number generator
    int seed = (long)time(NULL) * pthread_self();
    int random = abs((seed % ctx->max_ids));

    pthread_mutex_lock(&ctx->lock);
    for (size_t i = 0; i < ctx->num_messages; ++i) {
        while (true) {
            size_t j = (random + i) % ctx->max_ids;
            if (!ctx->available_ids[j]) {
                ctx->available_ids[j] = 1;
                break;
            }
        }
    }
    pthread_mutex_unlock(&ctx->lock);

    return NULL;
}

void ul_ccch_message_fill(UL_CCCH_MESSAGE_CTX* ctx) {
    if (pthread_create(&ctx->tid, NULL, generate_ue_id, ctx)) {
        fprintf(stderr, "Failed to create thread for UE ID generation\n");
        return;
    }

    pthread_mutex_lock(&ctx->lock);
    // Fill structures with unique sequence numbers and UE IDs
    for (size_t i = 0; i < ctx->num_messages; ++i) {
        UL_CCCH_MESSAGE_T* msg = &ctx->messages[i];
        msg->sequence_number = i;
        msg->tx_ue_id = ctx->available_ids[(i + pthread_self()) % ctx->max_ids];

        // Generate CCCH_MESSAGE content
        time_t now = time(NULL);
        struct tm* tm = localtime(&now);
        snprintf(msg->ccch_message, sizeof(msg->ccch_message),
                 "%04d-%02d-%02d %02d:%02d:%02d.%03d",
                 1900 + tm->tm_year, tm->tm_mon + 1, tm->tm_mday,
                 tm->tm_hour, tm->tm_min, tm->tm_sec, (int)(now % 1000));
    }
    pthread_mutex_unlock(&ctx->lock);

    // Wait for thread to finish generating UE IDs
    pthread_join(ctx->tid, NULL);
}

void ul_ccch_message_free(UL_CCCH_MESSAGE_CTX** ctx) {
    if (!ctx || !*ctx) return;

    free((*ctx)->available_ids);
    free(*ctx);
    *ctx = NULL;
}
