#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct {
    int value;
} record;

// Function to allocate memory for long offsets and int keys based on user-provided sizes.
long* allocate_offsets(size_t size) {
    return calloc(size, sizeof(long));
}

int* allocate_keys(size_t size) {
    return malloc(size * sizeof(int));
}

// Function to create and initialize an array of record structures.
record* allocate_records(size_t size) {
    // Use pthread_mutexattr_t for mutex-based synchronization
    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_RECURSIVE);
    record* records = (record*) malloc(size * sizeof(record));
    for (size_t i = 0; i < size; ++i) {
        pthread_mutex_init(&records[i].lock, &attr);
    }
    return records;
}

// Function to populate each record's int field with a random value within a specified range.
void populate(record* records, size_t size, int min, int max) {
    for (size_t i = 0; i < size; ++i) {
        records[i].value = rand() % (max - min + 1) + min;
    }
}

// Function to serialize the array of records into a binary format.
void serialize(const record* records, size_t size, FILE* fp) {
    fwrite(records, sizeof(record), size, fp);
}

int main() {
    // Allocate and initialize user-provided sizes for offsets, keys, and records.
    size_t offset_size = 1024;
    size_t key_size = 64;
    size_t record_size = 256;

    long* offsets = allocate_offsets(offset_size);
    int* keys = allocate_keys(key_size);
    record* records = allocate_records(record_size);

    // Initialize the array of records with random values.
    populate(records, record_size, 0, RAND_MAX);

    // Serialize the array of records into a binary file.
    FILE *fp;
    fp = fopen("output.bin", "wb");
    serialize(records, record_size, fp);
    fclose(fp);

    // Deallocate memory when no longer needed.
    free(offsets);
    free(keys);
    for (size_t i = 0; i < record_size; ++i) {
        pthread_mutex_destroy(&records[i].lock);
    }
    free(records);

    return 0;
}
