struct node {
    Task task;
    stree_node_t* rbtree_node;
};

stree_t* red_black_tree = NULL;
pthread_mutex_t tree_mutex = PTHREAD_MUTEX_INITIALIZER;

void init_task(struct node *node) {
    node->task.name = malloc(RANDOM_NAME_LENGTH);
    strcpy(node->task.name, generate_random_string());
    node->task.priority = rand() % MAX_PRIORITY;
    node->task.due_date = time(NULL) + (rand() % DUE_DATE_RANGE);
}

void cleanup() {
    stree_destroy(red_black_tree);
    free(red_black_tree);
    pthread_mutex_destroy(&tree_mutex);
}

struct node* create_node() {
    struct node *node = malloc(sizeof(struct node));
    if (!node) return NULL;
    init_task(node);
    return node;
}

void add_to_list(struct node **head, struct node *node) {
    pthread_mutex_lock(&tree_mutex);
    stree_insert(red_black_tree, &node->rbtree_node, &node->task.priority);
    pthread_mutex_unlock(&tree_mutex);

    node->rbtree_node->parent->data = node;
    node->rbtree_node->left = *head;
    if (*head) (*head)->rbtree_node->right = node;
    *head = node;
}

void* worker(void *arg) {
    struct node* node = create_node();
    if (node) add_to_list(&task_list, node);
    return NULL;
}

int main() {
