[' Here's an example implementation using Node.js, Express, and TypeORM (a popular ORM for TypeScript). I've separated the SQL functions into two files: `updateEmployee.sql` and `deleteEmployee.sql`.

First, install required dependencies:

```bash
npm init -y
npm install express @types/express typeorm sqltypeorm reflection-metadata dotenv
```

Create a `.env` file to store your database connection information:

```ini
DB_TYPE=postgres
DB_HOST=localhost
DB_PORT=5432
DB_USER=myuser
DB_PASSWORD=mypassword
DB_DATABASE=mydatabase
DB_CONNECTION_LIMIT=10
DB_SYNC=true
```

Create an `index.ts` file for your API:

```typescript
import express from 'express';
import { createConnection, getConnection, CreateConnectionOptions } from "typeorm";
import { readFileSync } from 'fs';

const app = express();
const dbConfig = readFileSync('.env').toString().split('\n');
const options: CreateConnectionOptions = {};
dbConfig.forEach((line) => {
  if (line.startsWith('DB_')) {
    const [key, value] = line.slice(4).trim().split('=');
    options[key] = value;
  }
});
createConnection(options).then(async () => {
  app.use((req, res, next) => {
    getConnection()
      .createQueryBuilder('employee', 'e') // Assuming the employee table name is 'employee'
      .setOptions({ raw: true })
      .leftJoinAndSelect('e.address', 'a')
      .where('e.id = :id', { id: req.params.id })
      .getOne()
      .then((employee) => {
        if (!employee) {
          return res.status(404).send({ error: "Employee not found" });
        }
        next();
      })
      .catch(() => {
        res.status(500).send({ error: "Internal server error" });
      });
  });

  app.put('/employees/:id', async (req, res) => {
    const updatedData = req.body;
    await getConnection()
      .createQueryBuilder('employee', 'e')
      .update(updatedData)
      .setDoSelect(false) // To optimize performance by preventing selecting all fields
      .where('id = :id', { id: req.params.id })
      .execute();
    res.send(updatedData);
  });

  app.delete('/employees/:id', async (req, res) => {
    await getConnection()
      .createQueryBuilder('employee', 'e')
      .setOptions({ raw: true })
      .delete()
      .where('id = :id', { id: req.params.id })
      .execute();
    res.send({ name: "John Doe", city: "", address: "" }); // Default values for the employee fields
  });

  app.listen(3000, () => console.log('Server is running on port 3000'));
});
```

Create a `updateEmployee.sql` file with your SQL function:

```sql
UPDATE employees SET name = :name, city = :city, address = :address WHERE id = :id;
```

Create a `deleteEmployee.sql` file with your SQL function:

```sql
DELETE FROM employees WHERE id = :id;
```']

