    dir->name = strdup(name);
    if (!dir->name) {
        free(dir);
        return NULL;
    }

    dir->files = calloc(max_files, sizeof(file_metadata *));
    if (!dir->files) {
        free(dir->name);
        free(dir);
        return NULL;
    }

    return dir;
}

void addFileToDirectory(directory **dir, file_metadata *fm) {
    size_t array_size = 0;
    while (array_size < (*dir)->max_files && isUniqueHash((*dir->files[array_size])->hash, (*dir)->files, array_size)) ++array_size;

    if (array_size == (*dir)->max_files) {
        size_t new_size = (*dir)->max_files * 2;
        file_metadata **new_array = realloc((*dir)->files, new_size * sizeof(file_metadata *));
        if (!new_array) {
            fprintf(stderr, "Error: Memory allocation failure.\n");
            return;
        }
        (*dir)->files = new_array;
        (*dir)->max_files = new_size;
    }

    (*(*dir->files + array_size)) = fm;
}

void addElementToArray(void **array, size_t *array_size, void *item) {
    if (*array_size == 0) {
        *array = malloc(sizeof(**array));
        if (!*array) {
            fprintf(stderr, "Error: Memory allocation failure.\n");
            return;
        }
    } else {
        void **new_array = realloc(*array, (*array_size + 1) * sizeof(**array));
        if (!new_array) {
            fprintf(stderr, "Error: Memory allocation failure.\n");
            return;
        }
        *array = new_array;
    }

    (*(*array + *array_size)) = item;
    ++(*array_size);
}

void removeElementAtIndex(void **array, size_t *array_size, size_t index) {
    if (index >= *array_size || index < 0) return;

    memmove((*array + index), (*array + index + 1), (*array_size - index - 1) * sizeof(**array));
    --(*array_size);
}

void getElementByIndex(void **array, size_t array_size, size_t index, void **out) {
    if (index >= array_size || index < 0) return;
    *out = (*array + index);
}
