#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct lte_ue_context {
    uint32_t cell_id;
    uint64_t ue_id;
    time_t last_reported_timestamp;
} context_t;

int allocate_contexts(size_t num_contexts, size_t* allocated, size_t* failed) {
    context_t** contexts = NULL;
    size_t i = 0;
    *allocated = *failed = 0;

    contexts = calloc(num_contexts, sizeof(context_t*));
    if (!contexts) {
        fprintf(stderr, "Failed to allocate memory for context list.\n");
        *failed = num_contexts;
        return -1;
    }

    for (i = 0; i < num_contexts; ++i) {
        contexts[i] = malloc(sizeof(context_t));
        if (!contexts[i]) {
            fprintf(stderr, "Failed to allocate memory for context %zu.\n", i);
            (*failed)++;
            continue;
        }
        memset(contexts[i], 0, sizeof(context_t));
        ++(*allocated);
    }

    return 0;
}

void update_timestamp(size_t index, context_t** contexts, time_t current_time) {
    if (index >= *((size_t*)contexts)) {
        fprintf(stderr, "Invalid index for context list.\n");
        return;
    }
    (*contexts[index]).last_reported_timestamp = current_time;
}
```

