void init_dynamic_array(dynamic_array* arr, size_t initial_capacity) {
    arr->data = malloc(initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!arr->data) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    arr->capacity = initial_capacity;
    arr->size = 0;
    pthread_mutex_init(&arr->mutex, NULL);
