void resize_dynamic_array(dynamic_array* arr) {
    NFAPI_CRC_INDICATION_PDU_T* new_data;
    size_t new_capacity = (arr->capacity * 2 > 10000) ? 10000 : arr->capacity * 2;
    if (!(new_data = realloc(arr->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T)))) {
        perror("Memory allocation failed");
        exit(EXIT_FAILURE);
    }
    arr->data = new_data;
    arr->capacity = new_capacity;
}

void push_dynamic_array(dynamic_array* arr) {
    pthread_mutex_lock(&arr->mutex);
    if (arr->size >= arr->capacity) resize_dynamic_array(arr);
    arr->data[arr->size++] = (NFAPI_CRC_INDICATION_PDU_T){
        .rx_ue_information_tag = {.value = rand() % 0xFFFF},
        .rnti = {.value = rand() % 0xFFFFFFFF},
        .crc_indication_rel8_tag.crcflag = rand() % 2
    };
    pthread_mutex_unlock(&arr->mutex);
}

NFAPI_CRC_INDICATION_PDU_T* dynamic_array_pop(dynamic_array* arr) {
    NFAPI_CRC_INDICATION_PDU_T* result = NULL;
    pthread_mutex_lock(&arr->mutex);
    if (arr->size > 0) {
        result = &arr->data[--arr->size];
    }
    pthread_mutex_unlock(&arr->mutex);
    return result;
}
