typedef struct {
    int DEVICE_ID;
    char CURRENT_IP_ADDRESS[256];
    time_t LAST_SEEN_TIMESTAMP;
    int CONNECTIVITY_STATUS;
} NETWORK_DEVICE_INFO_T;

#define MAX_DEVICES N
static NETWORK_DEVICE_INFO_T devices[MAX_DEVICES];
static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static int num_devices = 0;

void add_device(int device_id, char* ip_address, int connectivity_status) {
    if (num_devices >= MAX_DEVICES) {
        printf("Error: Maximum number of devices reached\n");
        return;
    }

    pthread_mutex_lock(&mutex);
    devices[num_devices].DEVICE_ID = device_id;
    strcpy(devices[num_devices].CURRENT_IP_ADDRESS, ip_address);
    devices[num_devices].CONNECTIVITY_STATUS = connectivity_status;
    devices[num_devices].LAST_SEEN_TIMESTAMP = time(NULL);
    num_devices++;
    pthread_mutex_unlock(&mutex);
}

NETWORK_DEVICE_INFO_T* get_device(int device_id) {
    if (device_id >= MAX_DEVICES || device_id < 0) {
        printf("Error: Device id out of range\n");
        return NULL;
    }

    pthread_mutex_lock(&mutex);
    NETWORK_DEVICE_INFO_T* device = &devices[device_id];
    pthread_mutex_unlock(&mutex);
    return device;
}

void log_device_info(NETWORK_DEVICE_INFO_T* device) {
    printf("Device ID: %d\n", device->DEVICE_ID);
    printf("Current IP Address: %s\n", device->CURRENT_IP_ADDRESS);
    printf("Last Seen Timestamp: %ld\n", device->LAST_SEEN_TIMESTAMP);
    printf("Connectivity Status: %d\n", device->CONNECTIVITY_STATUS);
}
