#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#include <semaphore.h>
#include <sys/mman.h>

#define UE_CONTEXT_COUNT 4096

typedef struct {
    uint32_t ue_id;
    uint8_t mac_pdu[1500];
    uint8_t nas_pdu[1500];
} lte_ue_context_t;

struct lte_context_manager {
    lte_ue_context_t *contexts;
    size_t capacity;
    size_t count;
    sem_t mutex;
};

void init_context_manager(struct lte_context_manager **manager) {
    *manager = malloc(sizeof(struct lte_context_manager));
    (*manager)->capacity = UE_CONTEXT_COUNT;
    (*manager)->count = 0;
    (*manager)->contexts = mmap(NULL, sizeof(lte_ue_context_t) * (*manager)->capacity, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    sem_init(&(*manager)->mutex, 0, 1);
}

void lte_ue_context_add(struct lte_context_manager *manager, uint32_t ue_id, const uint8_t *mac_pdu, const uint8_t *nas_pdu) {
    sem_wait(&manager->mutex);
    size_t i;
    for (i = 0; i < manager->count && manager->contexts[i].ue_id != ue_id; ++i);
    if (i == manager->count) {
        if (manager->count >= manager->capacity) {
            void *temp_mem = realloc(manager->contexts, sizeof(lte_ue_context_t) * (manager->capacity << 1));
            if (!temp_mem) {
                fprintf(stderr, "Failed to allocate memory for context expansion\n");
                sem_post(&manager->mutex);
                return;
            }
            manager->contexts = temp_mem;
            manager->capacity <<= 1;
        }
        memcpy(&manager->contexts[manager->count], &((const lte_ue_context_t){.ue_id = ue_id, .mac_pdu = {*mac_pdu}, .nas_pdu = {*nas_pdu}}), sizeof(lte_ue_context_t));
        manager->count++;
    }
    sem_post(&manager->mutex);
}

void lte_ue_context_remove(struct lte_context_manager *manager, uint32_t ue_id) {
    sem_wait(&manager->mutex);
    size_t i;
    for (i = 0; i < manager->count; ++i) {
        if (manager->contexts[i].ue_id == ue_id) {
            memmove(&manager->contexts[i], &manager->contexts[i+1], sizeof(lte_ue_context_t) * (manager->count - i - 1));
            manager->count--;
            break;
        }
    }
    sem_post(&manager->mutex);
}

void lte_ue_context_update(struct lte_context_manager *manager, uint32_t ue_id, const uint8_t *mac_pdu, const uint8_t *nas_pdu) {
    sem_wait(&manager->mutex);
    size_t i;
    for (i = 0; i < manager->count; ++i) {
        if (manager->contexts[i].ue_id == ue_id) {
            memcpy(&manager->contexts[i].mac_pdu, mac_pdu, sizeof(uint8_t) * 1500);
            memcpy(&manager->contexts[i].nas_pdu, nas_pdu, sizeof(uint8_t) * 1500);
            break;
        }
    }
    sem_post(&manager->mutex);
}

void lte_ue_context_serialize(const struct lte_context_manager *manager, uint8_t *buffer) {
    size_t i, buffer_size = 0;
    for (i = 0; i < manager->count; ++i) {
        memcpy(&buffer[buffer_size], &manager->contexts[i].ue_id, sizeof(uint32_t));
        buffer_size += sizeof(uint32_t);
        memcpy(&buffer[buffer_size], manager->contexts[i].mac_pdu, sizeof(manager->contexts[i].mac_pdu));
        buffer_size += sizeof(manager->contexts[i].mac_pdu);
        memcpy(&buffer[buffer_size], manager->contexts[i].nas_pdu, sizeof(manager->contexts[i].nas_pdu));
        buffer_size += sizeof(manager->contexts[i].nas_pdu);
    }
}
```
