NETWORK_DEVICE_INFO_T* ListManager_GetDeviceByID(struct ListManager* manager, int device_id) {
    NETWORK_DEVICE_INFO_T* device = NULL;
    if (manager->num_devices == 0) return NULL;

    pthread_mutex_lock(&manager->list_lock);

    if (manager->cache && manager->cache->device.DEVICE_ID == device_id) {
        device = &manager->cache->device;
    } else {
        for (int i = 0; i < manager->num_devices; ++i) {
            if (manager->devices[i].DEVICE_ID == device_id) {
                if (manager->cache && manager->cache->device.DEVICE_ID == device_id) {
                    manager->cache = manager->cache->next;
                }
                device = &manager->devices[i];
                break;
            }
        }

        // Cache the device if not already cached and cache is not full.
        if (manager->cache && manager->cache_size < manager->cache_capacity) {
            manager->cache->next = &manager->devices[0] + (device - &manager->devices[0]);
            manager->cache = manager->cache->next;
            device = &manager->cache->device;
        }
    }

    pthread_mutex_unlock(&manager->list_lock);

    return device;
}

