void init_arrays(double **data, unsigned long **ids, item ***items, size_t *capacity) {
    *data = malloc(*capacity * sizeof(double));
    *ids = malloc(*capacity * sizeof(unsigned long));
    *items = malloc(*capacity * sizeof(item*));

    for (size_t i = 0; i < *capacity; ++i) {
        (*data)[i] = 0.0;
        (*ids)[i] = i + 1;
        (*items)[i] = malloc(sizeof(item));
        (*items)[i]->buffer = malloc((i + 10) * sizeof(char));
        snprintf((*items)[i]->buffer, (i + 10), "Item %lu", (*ids)[i]);
        (*items)[i]->length = strlen((*items)[i]->buffer);
    }
}

void resize_items(item ***items, size_t *capacity, size_t new_capacity) {
    item **new_items = realloc(*items, new_capacity * sizeof(item*));

    if (new_items != NULL) {
        for (size_t i = *capacity; i < new_capacity; ++i)
            new_items[i] = malloc(sizeof(item));
        *items = new_items;
        *capacity = new_capacity;
    }
}

void free_arrays(double **data, unsigned long **ids, item ***items, size_t capacity) {
    for (size_t i = 0; i < capacity; ++i) {
        free((*data)[i]);
        free((*items)[i]->buffer);
        free((*items)[i]);
    }
    free(*data);
    free(*ids);
    free(*items);
}
