public class HashMapper {
    private static final int MAX_CONCURRENT_REQUESTS = 10;
    private static final ExecutorService executor = Executors.newFixedThreadPool(MAX_CONCURRENT_REQUESTS);
    private static final Logger logger = ... // Your logging framework's Logger instance

    public Map<String, String> hashStrings(List<String> strings, HashingAlgorithm algorithm) {
        if (strings == null || strings.isEmpty()) return Collections.emptyMap();

        Map<String, String> result = new HashMap<>();
        Queue<String> queue = new LinkedBlockingQueue<>(MAX_CONCURRENT_REQUESTS);

        Runnable hashingTask = str -> {
            try {
                String hash;
                switch (algorithm) {
                    case SHA_256:
                        MessageDigest md = MessageDigest.getInstance("SHA-256");
                        md.update(str.getBytes(StandardCharsets.UTF_8));
                        hash = new BigInteger(1, md.digest()).toString(16);
                        while (hash.length() < 64) hash = "0" + hash;
                        break;
                    // Add more hashing algorithms here
                    default:
                        throw new IllegalArgumentException("Unsupported HashingAlgorithm: " + algorithm);
                }
                result.put(str, hash);
            } catch (NoSuchAlgorithmException e) {
                logger.error("Unable to execute hash algorithm", e);
            }
        };

        strings.stream().forEach(queue::add);

        long startTime = System.currentTimeMillis();
        while (!queue.isEmpty() || !result.keySet().equals(strings)) {
            if (executor.getActiveCount() < MAX_CONCURRENT_REQUESTS) {
                executor.submit(hashingTask, queue.poll());
            }
        }
        long elapsedTime = System.currentTimeMillis() - startTime;
        logger.info("Hashed strings in " + elapsedTime + " ms");

        return result;
    }

    // Define HashingAlgorithm enum here...
}
