class RandomNumberCache {
public:
    using engine_type = boost::mt19937;
    using distribution_type = boost::uniform_int_distribution<>;

    explicit RandomNumberCache(unsigned int min, unsigned int max)
        : generator_(min, max), queue_(256) {}

    int get() {
        auto randomValue = generator_(generator_);
        if (!queue_.pop(randomValue)) {
            queue_.push(randomValue);
        }
        return randomValue;
    }

private:
    engine_type generator_;
    boost::lockfree::spsc_queue<int> queue_;
};

// Allocate and initialize memory for long offset values, int keys, and records
class MemoryPool {
public:
    template <typename T>
    T* alloc(size_t n) {
        char* data = static_cast<char*>(::operator new[](n * sizeof(T)));
        return reinterpret_cast<T*>(data);
    }
};

void allocateMemory(MemoryPool& pool, size_t offsetSize, size_t keySize, size_t recordCount) {
    auto offsets = pool.alloc<long>(offsetSize * recordCount);
    auto keys = pool.alloc<int>(keySize * recordCount);
    std::vector<boost::intrusive_ptr<Record>> records(recordCount);

    for (auto& record : records) {
        record.reset(new Record());
    }
}

