 double historicalMeanTemp = resultSet.next() ? resultSet.getDouble("mean_temp") : 0;

 switch (query) {
 case "temperature":
 return "Current temperature: " + currentTemperature + "\n" +
 "Historical average temperature: " + historicalMeanTemp + "\n" +
 "7-day forecast:\n" + forecastData.toString();
