 "7-day forecast:\n" + forecastData.toString();
 case "wind_speed":
 return "Current wind speed: " + currentWindSpeed + " km/h\n" +
 "7-day forecast:\n" + forecastData.toString();
 default:
 return "Invalid query. Please use 'temperature', 'humidity', or 'wind_speed'.";
 }
}
}
