    public <T> T fetchData(String url, Class<T> dataModelClass) throws IOException {
        if (!isValidUrl(url)) {
            throw new IllegalArgumentException("Invalid URL: " + url);
        }

        URL apiUrl = null;
        try {
            apiUrl = new URL(url);
        } catch (MalformedURLException e) {
            LOGGER.error("Error creating URL object for: {}", url, e);
            throw new RuntimeException(e);
        }

        String apiType = determineApiType(apiUrl);
        ApiClient apiClient = getApiClientForType(apiType);
        JsonObject jsonResponse = apiClient.fetch(apiUrl);

        if (jsonResponse == null) {
            throw new IOException("Empty response from API");
        }

        T dataModel;
        try {
            dataModel = mapJsonToDataModel(jsonResponse, dataModelClass);
        } catch (Exception e) {
            LOGGER.error("Error parsing JSON: {}", jsonResponse.toString(), e);
            throw new RuntimeException(e);
        }

        if (debugLogging) {
            LOGGER.debug("Request headers: {}", apiClient.getRequestHeaders());
            LOGGER.debug("Response headers: {}", apiClient.getResponseHeaders());
            LOGGER.debug("Data model: {}", dataModel);
        }

        return dataModel;
    }

