#include <iostream>
#include <random>
#include <memory>
#include <pair>
#include <utility>
#include <vector>

namespace RandomGenerator {

struct MTGenerator {
    std::unique_ptr<std::mt19937> engine;
    std::uniform_int_distribution<> distribution;

    static std::unique_ptr<MTGenerator> instance;

    MTGenerator(unsigned long seed, const std::pair<unsigned int, unsigned int>& range) {
        if (seed <= 0) {
            throw std::invalid_argument("Seed value should be positive.");
        }
        if (range.first > range.second) {
            throw std::invalid_argument("Start value should not be greater than end value in the range.");
        }
        engine = std::make_unique<std::mt19937>(seed);
        distribution = std::uniform_int_distribution<>(range.first, range.second);
    }

    ~MTGenerator() = default;

    unsigned int getRandomNumber() {
        return distribution(*engine);
    }

    static void reset(unsigned long newSeed) {
        if (instance) {
            instance->engine->seed(newSeed);
        }
    }
};

std::unique_ptr<MTGenerator> RandomGenerator::instance;

int main() {
    try {
        unsigned long seed = 123456789;
        std::pair<unsigned int, unsigned int> range{0, 100};
        if (!RandomGenerator::instance) {
            RandomGenerator::instance.reset(seed);
            RandomGenerator::instance->distribution.max() = range.second;
            RandomGenerator::instance->distribution.min() = range.first;
        } else {
            RandomGenerator::instance->engine->seed(seed);
            RandomGenerator::instance->distribution.max() = range.second;
            RandomGenerator::instance->distribution.min() = range.first;
        }
        std::vector<unsigned int> numbers(10);
        for (auto &number : numbers) {
            number = RandomGenerator::instance->getRandomNumber();
        }
        for (const auto &number : numbers) {
            std::cout << number << ", ";
        }
    } catch (const std::exception& e) {
        std::cerr << "Error: " << e.what() << '\n';
    }
    return 0;
}
```

