        _assetsLoading[path] = new AssetInfo(path, type);

        await _assetLoadingSemaphore.WaitAsync();
        try
        {
            var assetTask = Task.Run(() => LoadAsset(path, type));
            _assetsLoading[path].LoadTask = assetTask;
        }
        finally
        {
            _assetLoadingSemaphore.Release();
        }
    }

    private T LoadAsset<T>(string path, string type) where T : Object
    {
