import com.fasterxml.jackson.databind.ObjectMapper;
import org.apache.commons.io.FileUtils;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.stereotype.Service;
import java.io.*;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ExecutorService;
import java.util.concurrent.Executors;
import java.util.concurrent.TimeUnit;

@Service
public class MostStateLoader {
    private static final Logger LOGGER = LoggerFactory.getLogger(MostStateLoader.class);
    private static final long MAX_FILE_SIZE = 1L * (1024 * 1024 * 1024); // 1GB
    private static final ObjectMapper objectMapper = new ObjectMapper();
    private final ConcurrentHashMap<String, MoSTState> cache;
    private final ExecutorService executor = Executors.newCachedThreadPool();

    public MostStateLoader() {
        this.cache = new ConcurrentHashMap<>();
    }

    public MoSTState loadState(String filePath) throws InvalidFormatException, TimeoutException, IOException, JsonProcessingException {
        Path path = Paths.get(filePath);
        if (!Files.isReadable(path)) {
            throw new FileNotFoundException("File not found: " + filePath);
        }

        String extension = Files.probeContentType(path).split("/")[1];
        if (extension.equalsIgnoreCase("bin")) {
            try (ObjectInputStream in = new ObjectInputStream(new BufferedReader(new FileReader(filePath)))) {
                return (MoSTState) in.readObject();
            } catch (ClassNotFoundException e) {
                throw new InvalidFormatException("Invalid binary format", e);
            }
        } else if (extension.equalsIgnoreCase("json")) {
            try {
                return objectMapper.readValue(new File(filePath), MoSTState.class);
            } catch (JsonProcessingException e) {
                throw new InvalidFormatException("Invalid JSON format", e);
            }
        } else {
            throw new InvalidFormatException("Unsupported file extension: " + extension);
        }
    }

    public MoSTState loadFromCache(String filePath) {
        return cache.getOrDefault(filePath, null);
    }

    public void saveToCache(String filePath, MoSTState state) {
        if (state != null && !cache.containsKey(filePath)) {
            cache.putIfAbsent(filePath, state);
        }
    }

    public void loadStateFromFile(String filePath) throws InvalidFormatException, TimeoutException, IOException, JsonProcessingException {
        long startTime = System.currentTimeMillis();
        try {
            MoSTState state = loadState(filePath);
            logLoadDetails(startTime, filePath);
            saveToCache(filePath, state);
            return;
        } catch (IOException e) {
            if (e.getCause() instanceof FileNotFoundException && !shouldRetryLoad(filePath)) {
                throw new TimeoutException("Timeout while loading state from file: " + filePath, e);
            }
        }

        logLoadFailureDetails(startTime, filePath);
    }

    private void logLoadDetails(long startTime, String filePath) {
        LOGGER.info("Start loading MoSTState from {} at {}", filePath, System.currentTimeMillis());
        // Asynchronously send logs to external logging service here using SLF4J MDC or an appropriate library
    }

    private void logLoadFailureDetails(long startTime, String filePath) {
        LOGGER.error("Failed to load MoSTState from {} at {}, retrying...", filePath, System.currentTimeMillis(), e);
        // Implement backoff strategy for retries in case of failed log sends here
    }

    private boolean shouldRetryLoad(String filePath) {
        return Files.isReadable(Paths.get(filePath)) && !circuitBreakerIsOpen(filePath);
    }

    private boolean circuitBreakerIsOpen(String filePath) {
        // Implement circuit breaker pattern here using Hystrix or an appropriate library
    }
}
