```javascript
const fs = require('fs');
const path = require('path');
const express = require('express');
const { promisify } = require('util');
const app = express();
const log4js = require('log4js');

// Configure logger with custom levels and appenders
const logger = log4js.getLogger();
logger.level = 'DEBUG'; // Change the default level as needed (INFO, WARN, ERROR, etc.)

// Function to handle configuration loading
async function loadConfig() {
  const configFilePath = path.join(__dirname, '.config.json'); // Update this with your desired directory path

  let isFirstLoad = true;
  let configData = {};

  // Poll for configuration updates every 10 seconds (adjust as needed)
  const pollInterval = 10000;

  function checkForUpdates() {
    if (!isFirstLoad) return;

    fs.readFile(configFilePath, 'utf8', async (err, data) => {
      if (err) {
        logger.error(`Error reading configuration file: ${err}`);
        setTimeout(checkForUpdates, pollInterval); // Retry after the poll interval
        return;
      }

      try {
        configData = JSON.parse(data);
      } catch (e) {
        logger.error(`Invalid configuration format: ${e}`);
        setTimeout(checkForUpdates, pollInterval); // Retry after the poll interval
        return;
      }

      isFirstLoad = false;
      onConfigLoaded(configData);
    });
  }

  checkForUpdates();

  // Handle configuration updates synchronously and asynchronously
  app.get('/config', (req, res) => {
    res.send(configData);
  });

  function onConfigLoaded(data) {
    logger.info('Configuration loaded successfully');
    // Trigger any necessary event listeners or callbacks here
  }
}

// Wrap fs.readFile and fs.writeFile with promisify for easier async usage
const readFile = promisify(fs.readFile);
const writeFile = promisify(fs.writeFile);

// Utilize the loadConfig function where needed in your application
loadConfig().catch((err) => {
  logger.error(`Fatal error initializing configuration system: ${err}`);
});
