import java.text.SimpleDateFormat;
import java.util.concurrent.TimeUnit;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import com.fasterxml.jackson.databind.ObjectMapper;

public class FileSummaryReport {
    private static final Logger LOGGER = LoggerFactory.getLogger(FileSummaryReport.class);
    private static final ObjectMapper OBJECT_MAPPER = new ObjectMapper();
    private static final long TIMEOUT_MILLIS = getPropertyAsLong("timeoutMillis");
    private static final boolean SKIP_DIRECTORIES = getPropertyAsBoolean("skipDirectories");
    private static final int LARGE_FILE_THRESHOLD = getPropertyAsInt("largeFileThreshold");

    public static Report generateReport(List<String> filePaths) throws IOException {
        long totalTime = 0;
        int filesChecked = 0, executableFilesCount = 0;
        int symbolicLinksCount = 0;

        SimpleDateFormat dateFormat = new SimpleDateFormat("yyyy-MM-dd'T'HH:mm:ss.SSSXXX");

        for (String filePath : filePaths) {
            try {
                Path path = Paths.get(filePath);
                if (!Files.isRegularFile(path)) continue;
                if (SKIP_DIRECTORIES && Files.isDirectory(path)) continue;

                long startTime = System.nanoTime();
                boolean isExecutable = checkExecutionPermission(path);
                long endTime = System.nanoTime();
                long execTime = TimeUnit.MILLISECONDS.convert(endTime - startTime, TimeUnit.NANOSECONDS);

                if (isExecutable) {
                    executableFilesCount++;
                }

                if (Files.isSymbolicLink(path)) {
                    symbolicLinksCount++;
                }

                totalTime += execTime;
                filesChecked++;

                logPermissionCheckResult(filePath, isExecutable, execTime);
            } catch (IOException e) {
                LOGGER.error("Error while processing file {}", filePath, e);
            }
        }

        return new Report(filesChecked, executableFilesCount, totalTime, symbolicLinksCount);
    }

    private static boolean checkExecutionPermission(Path path) throws IOException {
        try {
            if (!Files.isExecutable(path)) return false;
            Process process = new ProcessBuilder().command(Arrays.asList("sh", "-c", "touch "+path.toString()+" 2>/dev/null")).start();
            process.waitFor(TIMEOUT_MILLIS, TimeUnit.MILLISECONDS);
            return true;
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
            throw new IOException("Interrupted while checking execution permission", e);
        }
    }

    private static void logPermissionCheckResult(String filePath, boolean isExecutable, long execTime) {
        Map<String, Object> logEntry = new HashMap<>();
        logEntry.put("filePath", filePath);
        logEntry.put("isExecutable", isExecutable);
        logEntry.put("executionTimeMillis", execTime);
        logEntry.put("timestamp", dateFormat.format(System.currentTimeMillis()));

        String json = OBJECT_MAPPER.writerWithDefaultPrettyPrinter().writeValueAsString(logEntry);
        // Implement integration with your logging service here
    }

