import java.util.*;
import java.util.concurrent.*;
import java.security.MessageDigest;
import java.math.BigInteger;
import java.nio.file.*;
import java.time.*;
import java.io.*;

class Record implements Comparable<Record> {
    long offset;
    int key;
    int value;

    public Record(long offset, int key, int value) {
        this.offset = offset;
        this.key = key;
        this.value = value;
    }

    @Override
    public int compareTo(Record other) {
        return Long.compare(this.offset, other.offset);
    }
}

public class DataPipeline {
    private static final int THREAD_COUNT = 4;
    private ExecutorService executor;
    private List<Record> records;

    public DataPipeline(int fileCount, String[] filenames, int minOffset, int maxOffset, int range) throws IOException {
        MessageDigest md = MessageDigest.getInstance("MD5");
        executor = Executors.newFixedThreadPool(THREAD_COUNT);
        records = new ArrayList<>();

        AtomicInteger keyCounter = new AtomicInteger();
        for (int i = 0; i < fileCount; i++) {
            Path filePath = Files.createTempFile("data-file", ".tmp");
            try (RandomAccessFile raf = new RandomAccessFile(filePath.toString(), "rw")) {
                raf.setLength(Math.abs(maxOffset - minOffset) + 1);
                long[] offsets = new long[raf.length()];
                int[] keys = new int[offsets.length];

                for (long j = 0; j < offsets.length; j++) {
                    offsets[(int)j] = minOffset + j;
                }

                Callable<Record[]> callable = () -> {
                    Record[] result = new Record[offsets.length];
                    for (int k = 0; k < offsets.length; k++) {
                        int key = keyCounter.getAndIncrement();
                        long hashCode = md.digest(filenames[i].getBytes()).abs() & Integer.MAX_VALUE;
                        if (key == hashCode) {
                            key++;
                        }

                        result[k] = new Record(offsets[k], key, new Random().nextInt(range));
                    }

                    Arrays.sort(result);
                    return result;
                };

                Future<Record[]> future = executor.submit(callable);
                try {
                    Record[] results = future.get();
                    records.addAll(Arrays.asList(results));
                } catch (ExecutionException | InterruptedException e) {
                    // Handle exceptions here for fault tolerance
                }
            }
        }
    }

    public void processData() throws InterruptedException, ExecutionException {
        List<Future<Void>> futures = new ArrayList<>();
        int batchSize = records.size() / THREAD_COUNT;

        for (int i = 0; i < THREAD_COUNT; i++) {
            int startIndex = i * batchSize;
            int endIndex = Math.min((i + 1) * batchSize, records.size());
            Callable<Void> callable = () -> processBatch(records.subList(startIndex, endIndex));
            futures.add(executor.submit(callable));
        }

        for (Future<Void> future : futures) {
            future.get();
        }

        executor.shutdown();
    }

    private void processBatch(List<Record> batch) {
        // Implement logic to process the given batch of records here, including load balancing and monitoring performance metrics.
    }
}
```

