    req.session.destroy((err) => {
        if (err) console.error(err);
        res.redirect('/');
    });
});

const cleanUp = async () => {
    const sessionKeys = await redisClient.keys('sid:*');
    const now = moment();

    for (let key of sessionKeys) {
        const sessionData = JSON.parse(await redisClient.get(key));
        if (!sessionData || now.diff(moment(sessionData.updated), 'minutes') > retentionPeriod / 60) {
            await redisClient.del(key);
        }
    }
};

setInterval(() => cleanUp(), retentionPeriod * 1000);
