['```java
import java.time.LocalDate;
import java.util.*;
import java.util.function.Predicate;
import static java.util.stream.Collectors.toList;

class Account {
    private String username, email;
    private int age;
    private LocalDate lastLoggedIn;

    public Account(String username, String email, int age) {
        this.username = validateUsername(username);
        this.email = validateEmail(email);
        this.age = Math.min(age, 150);
        this.lastLoggedIn = LocalDate.now();
    }

    private String validateUsername(String username) {
        if (!username.matches("^[a-zA-Z0-9_]{3,30}$")) throw new IllegalArgumentException("Invalid username");
        return username;
    }

    private String validateEmail(String email) {
        if (!email.matches("\\b[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Z|a-z]{2,}\\b")) throw new IllegalArgumentException("Invalid email");
        return email;
    }

    // getters and setters for lastLoggedIn and age
}

class AccountManager {
    private TreeMap<String, Account> accounts = new TreeMap<>();

    public void add(Account account) {
        String username = account.getUsername();
        if (accounts.containsKey(username)) {
            accounts.get(username).setLastLoggedIn(LocalDate.now());
        } else {
            accounts.put(username, account);
        }
    }

    public void remove(String username) {
        if (!accounts.containsKey(username)) throw new IllegalArgumentException("User not found");
        accounts.remove(username);
    }

    public Account get(String username) {
        return accounts.getOrDefault(username, null);
    }

    public void calculateAverageAge() {
        int totalActiveUsers = 0;
        long totalAgeSum = 0L;
        for (Account account : accounts.values()) {
            if (account.getLastLoggedIn().plusDays(30).isAfter(LocalDate.now())) {
                totalActiveUsers++;
                totalAgeSum += account.getAge();
            }
        }

        double averageAge = (double)totalAgeSum / totalActiveUsers;
        System.out.printf("Average age: %.2f\n", averageAge);
    }

    public void generateSummaryReport() {
        if (accounts.size() > 100_000) {
            int activeUsers = (int) accounts.entrySet().stream()
                    .filter(e -> e.getValue().getLastLoggedIn().plusDays(30).isAfter(LocalDate.now()))
                    .count();
            int inactiveUsers = accounts.size() - activeUsers;

            System.out.printf("Summary report:\nActive users: %d\nInactive users: %d\n", activeUsers, inactiveUsers);
        }
    }
}

public static void main(String[] args) {
    AccountManager manager = new AccountManager();
    Scanner scanner = new Scanner(System.in);
    Predicate<String> inputIsValid = s -> !s.isEmpty();

    while (true) {
        String line = scanner.nextLine();
        if (!inputIsValid.test(line)) continue;

        String[] parts = line.split("\\s+");
        String action = parts[0];

        switch (action) {
            case "add":
                Account accountToAdd = new Account(parts[1], parts[2], Integer.parseInt(parts[3]));
                manager.add(accountToAdd);
                break;
            case "remove":
                manager.remove(parts[1]);
                break;
            case "retrieve":
                Account retrievedAccount = manager.get(parts[1]);
                if (retrievedAccount != null) {
                    System.out.println(retrievedAccount);
                } else {
                    System.out.println("User not found");
                }
                break;
            case "average":
                manager.calculateAverageAge();
                break;
            case "summary":
                manager.generateSummaryReport();
                break;
            default:
                System.out.println("Invalid command");
        }
    }
}
```']

