<?php

// 1. Sets environment variables for a web application based on a dynamically generated environment file
if (file_exists($envFile = getcwd() . '/' . getenv('ENVIRONMENT_FILE', '.env')) && is_readable($envFile)) {
    $envArray = array_combine(array_map('strtolower', file(trim($envFile)), ['key']), array_map('trim', file(trim($envFile), FILE_IGNORE_NEW_LINES)));
    foreach ($envArray as $key => $value) {
        putenv("{$key}={$value}");
    }
}

// 2. Loads a vendor autoloader from a directory structure that may contain multiple vendor folders, selecting the correct one based on environment variables
$composerJsonPath = getcwd() . '/' . ($envArray['vendor_folder'] ?? 'vendor/autoload.php');
if (file_exists($composerJsonPath)) {
    require $composerJsonPath;
}

// 3. Configures the application using a configuration file that may reference external resources, requiring error handling for missing or corrupted files
$configFile = getcwd() . '/' . ($envArray['config_file'] ?? 'config.php');
if (file_exists($configFile) && is_readable($configFile)) {
    require $configFile;
} else {
    echo "Error: Unable to load configuration file.";
    exit(1);
}

// 4. Implements a logging mechanism that writes to a specified log directory, which must be checked for write permissions before logging. The logging function should also limit the size of log files to prevent excessive disk usage.
$logDir = $envArray['log_dir'] ?? getcwd() . '/logs';
if (is_writable($logDir)) {
    function log($message) {
        $fileName = $logDir . '/' . date('Y-m-d') . '.log';
        if (filesize($fileName) > 10485760) { // 10MB file size limit
            rename($fileName, $fileName . '.' . time());
        }
        file_put_contents($fileName, $message . PHP_EOL, FILE_APPEND);
    }
} else {
    echo "Error: Log directory is not writable.";
    exit(1);
}

// 5. Includes a command-line interface (CLI) script that can perform the above tasks without a web server, allowing for local development and testing
if ($argv[1] === 'run') {
    // Perform main functionality here
} else if ($argv[1] === 'env') {
    echo implode("\n", array_map(function ($item) { return $item['key'] . "=" . $item['value']; }, $envArray));
} else {
    echo "Usage: php script.php [run|env]";
}
