// modularized HTTP client library in Rust

pub mod config {
    pub struct HttpClientConfig {
        pub base_url: String,
        pub disable_certificate_validation: bool,
        pub max_retries: u32,
        pub retry_delay: std::time::Duration,
        pub headers: Vec<(String, String)>,
    }
}

pub mod request {
    use super::config::HttpClientConfig;

    pub enum Method {
        Get,
        Post,
        // Add additional HTTP methods here
    }

    pub struct Request {
        method: Method,
        url: String,
        headers: Vec<(String, String)>,
        body: Option<Vec<u8>>,
    }
}

pub mod response {
    use super::request::Request;

    #[derive(Debug)]
    pub struct HttpResponse {
        status_code: u16,
        headers: HeaderMap,
        body: Vec<u8>,
    }

    impl Request {
        pub fn new(method: Method, url: String, headers: Vec<(String, String)>, body: Option<Vec<u8>>) -> Self {
            Self { method, url, headers, body }
        }
    }
}

pub mod client {
    use std::sync::Arc;
    use reqwest::{Client, HeaderMap};
    use log::*;
    use super::config::HttpClientConfig;

    pub struct HttpClient {
        config: Arc<HttpClientConfig>,
        client: Client,
    }

    impl HttpClient {
        pub fn new(config: HttpClientConfig) -> Self {
            let headers = HeaderMap::new();
            for (k, v) in &config.headers {
                headers.insert(k, v);
            }

            Self {
                config: Arc::new(config),
                client: Client::builder()
                    .user_agent("My-App/1.0")
                    .default_headers(headers)
                    .build()
                    .expect("Failed to create reqwest client"),
            }
        }

        pub async fn send(&self, request: Request) -> Result<HttpResponse, reqwest::Error> {
            let mut req = match request.method {
                Method::Get => self.client.get(request.url).build(),
                Method::Post(_) => {
                    let mut buf = Vec::new();
                    request.body.as_ref().unwrap().write_to(&mut buf)?;
                    self.client
                        .post(request.url)
                        .headers(request.headers)
                        .body(buf)
                        .build()?
                }
            };

            if !self.config.disable_certificate_validation {
                req.ssl_mut().set_dangerous_accept_invalid_certs(false);
            }

            let retries = self.config.max_retries as u8;
            for i in 0..retries {
                match req.send().await {
                    Ok(res) => return Ok(res.into()),
                    Err(e) => {
                        if i + 1 < retries {
                            let delay = self.config.retry_delay * (i as u64 + 1);
                            info!(
                                "Request failed with error {}, retrying in {:?}",
                                e, delay
                            );
                            tokio::time::sleep(delay).await;
                        } else {
                            error!("Max retries reached");
                            return Err(e);
                        }
                    }
                }
            }

            unreachable!();
        }
    }
}
```

