#define ALIGN(x) ((sizeof(NFAPI_CRC_INDICATION_PDU_T) + (x) - 1) & ~(x - 1))

typedef struct _NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

sem_t log_mutex;
size_t total_created = 0;
size_t max_elements = 10000;

NFAPI_CRC_INDICATION_PDU_T* create_pdus() {
    NFAPI_CRC_INDICATION_PDU_T *pdus;
    size_t alignment = ALIGN(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    size_t size = max_elements * alignment;

    pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(size);
    if (!pdus) {
        sem_post(&log_mutex);
        perror("Out of memory");
        return NULL;
    }

    memset(pdus, 0, size);

    for (size_t i = 0; i < max_elements; i += alignment) {
        NFAPI_CRC_INDICATION_PDU_T *pdu_ptr = (NFAPI_CRC_INDICATION_PDU_T*)((uintptr_t)pdus + i);

        pdu_ptr->tag.value = rand(); // Set RX_UE_INFORMATION_TAG value
        pdu_ptr->rnti.value = rand(); // Set RNTI value (RNTI validation should be done externally)
        pdu_ptr->crc_indication.crcflag = rand() % 2; // Set CRC_INDICATION_REL8_TAG with random CRCFLAG
    }

    total_created += max_elements / alignment;
    sem_post(&log_mutex);

    return pdus;
}

int main() {
    srandom(time(NULL));
    sem_init(&log_mutex, 0, 1);

    NFAPI_CRC_INDICATION_PDU_T *pdus = create_pdus();

    if (pdus) {
        // Use the dynamically allocated structures here
        // External RNTI validation and logging services would be called here
    }

    free(pdus);

    return 0;
}
