void init_network(Network* network, size_t num_nodes, size_t buffer_size) {
    network->num_nodes = num_nodes;
    network->buffer_size = buffer_size;
    network->backup_data = mmap(NULL, buffer_size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANON, -1, 0);
    network->mutex = sem_init(sem_uninitialized, 1, 1);
}

void cleanup_network(Network* network) {
    munmap(network->backup_data, network->buffer_size);
    sem_destroy(&network->mutex);
}

Network* create_network(size_t num_nodes, size_t buffer_size) {
    Network* network = malloc(sizeof(Network));
    init_network(network, num_nodes, buffer_size);
    return network;
}

void destroy_network(Network* network) {
    cleanup_network(network);
    free(network);
