fn manage_states(state_nodes: &mut Vec<StateNode>, total_states: usize, fsa: &Fsa, last_state: usize) -> Option<Box<StateNode>> {
    let mut selected_states = HashMap::new();
    for i in 0..total_states {
        if matches_criteria(i, fsa) {
            selected_states.insert(i, state_nodes[i].clone());
        }
    }

    let head = match selected_states.into_iter().collect::<Vec<_>>() {
        [] => None,
        nodes => {
            let mut new_head = Box::new(nodes[0]);
            for node in nodes {
                node.next = Some(Box::new(node));
                match new_head.next.take() {
                    Some(current_head) => current_head.next = Some(node),
                    None => head = Some(node),
                }
            }
            head
        }
    };

    if let Some(new_list_head) = head {
        state_nodes[last_state].next = Some(new_list_head);
        Some(Box::new(selected_states))
    } else {
        None
    }
}

