    void BulkLoadData(std::vector<DataPoint> dataPoints) {
        std::future<void> tasks[8] = {};
        auto loadTask = [&](size_t index, auto&&... args) -> decltype(auto) {
            return std::async(std::launch::async, [=, &](args... argList) mutex_ {
                root_->InsertDataPoint(argList...);
                RecursiveBulkLoad(index * 2 + 1, argList...);
                if (index % 2 == 0) RecursiveBulkLoad(index * 2 + 3, argList...);
            }, index);
        };
        for (size_t i = 0; i < dataPoints.size(); ++i) {
            tasks[i % 8] = loadTask(i, dataPoints[i]); // divide bulk loading into 8 parallel tasks to improve performance
        }
        for (auto& task : tasks) task.wait(); // wait for all tasks to complete before continuing
    }

private:
    void RecursiveBulkLoad(size_t nodeIndex, const DataPoint& data) {
        if (nodeIndex > 7) return; // base case for recursion

        OctreeNode* currentNode = root_->GetChild(nodeIndex);
        if (!currentNode) {
            auto newNode = OctreeNodeMemoryPool::GetInstance().Alloc();
            root_->SetChild(nodeIndex, newNode);
            currentNode = newNode.get();
        }
        currentNode->InsertDataPoint(data);

        RecursiveBulkLoad(2 * nodeIndex + 1, data);
        if (nodeIndex % 2 == 0) RecursiveBulkLoad(2 * nodeIndex + 3, data);
    }

    OctreeNode* root_;
    const AABB bounds_;
    std::mutex mutex_; // for thread safety and synchronization during concurrent access
};
