typedef struct {
    uint64_t id;
    uint32_t size;
    uint16_t protocol;
    uint64_t timestamp;
} Packet;

struct sliding_window {
    uint64_t start;
    uint64_t end;
    Packet packets[5];
    int count;
};

struct data {
    struct sliding_window window;
    double score_factor;
    uint64_t total_packets;
    double avg_packet_size;
    double cumulative_score;
};

void process_packet(Packet packet, struct data* data) {
    if (packet.timestamp - data->window.start > 10) return; // Timestamp filter

    if (data->window.count >= 5) data->window.start += 1; // Update sliding window start
    memcpy(data->window.packets, data->window.packets + 1, sizeof(Packet) * (data->window.count - 1)); // Shift packets in window
    data->window.packets[4] = packet;
    data->window.count++;

    double score = calculate_score(packet, &data->score_factor);
    data->cumulative_score += score;
    data->total_packets++;
    data->avg_packet_size += packet.size / (double)data->total_packets;
}

Packet find_max_scored_packet(struct data* data) {
    Packet max_packet = data->window.packets[0];
    double max_score = max_score_in_sliding_window(&data->window);

    for (int i = 1; i < data->window.count; ++i) {
        if (data->window.packets[i].score > max_score) {
            max_packet = data->window.packets[i];
            max_score = data->window.packets[i].score;
        }
    }

    return max_packet;
}

double max_score_in_sliding_window(struct sliding_window* window) {
    double max_score = 0;

    for (int i = 0; i < window->count; ++i) {
        if (window->packets[i].score > max_score)
            max_score = window->packets[i].score;
    }

    return max_score;
}

double calculate_score(Packet packet, double* score_factor) {
    // Implement the scoring mechanism considering factors like packet size and protocol type
    *score_factor *= 0.995; // Decaying factor for score_factor
    return packet.size + (*score_factor * (double)(packet.protocol)) / 100;
}

void* process_packets(void* arg) {
    struct data* data = arg;
    while (1) {
        Packet packet;
        // Read a network packet into 'packet' from somewhere

        process_packet(packet, data);

        if (!data->total_packets % 10000) { // Update metrics every 10k packets or so
            printf("Packet ID: %llu Score: %lf Average Packet Size: %.2f Cumulative Score: %.2f\n", data->max_scored_packet.id, data->max_scored_packet.score, data->avg_packet_size, data->cumulative_score);
        }
    }
}
