#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <limits.h>

#define MAX_LENGTH 255
#define DEFAULT_EXT ".txt"

typedef struct {
    char *filename;
    char extension[10]; // Maximum of 9 characters for the identifier + '.ext'
} FileData;

void get_identifier(const char *input, char *output) {
    int length = strlen(input);
    for (int i = 0; i < length; ++i) {
        if (!isdigit(input[i])) output[i] = input[i];
        else break;
    }
    // If no digit found, use default identifier
    if (output[0] == '\0') strcpy(output, "0");
}

FileData *modify_filename(const char *input_filename) {
    FileData *file_data = malloc(sizeof(FileData));
    if (!file_data) return NULL;

    // Handle edge case where input_filename is empty or exceeds the maximum allowed length
    if (strlen(input_filename) == 0 || strlen(input_filename) > MAX_LENGTH) {
        free(file_data);
        return NULL;
    }

    int length = strlen(input_filename);
    char identifier[10]; // Maximum of 9 characters for the identifier + '.ext'
    get_identifier(input_filename, identifier);

    int extension_index = length - 1;
    while (extension_index >= 0 && input_filename[extension_index] != '.') --extension_index;

    char *output_filename = malloc((strlen(input_filename) + strlen(identifier) + strlen(DEFAULT_EXT) + 1) * sizeof(char));
    if (!output_filename) {
        free(file_data);
        return NULL;
    }

    // Copy input filename up to the extension, then append the identifier and default extension
    int i = 0;
    for (; extension_index != INT32_MIN && i < length; ++i, ++extension_index) {
        output_filename[i] = toupper(input_filename[extension_index]);
    }

    if (extension_index != INT32_MIN) { // If there is an extension, skip it
        extension_index++;
    }

    for (; i < strlen(identifier); ++i, ++extension_index) {
        output_filename[extension_index] = identifier[i];
    }

    strcat(output_filename, DEFAULT_EXT);

    file_data->filename = output_filename;
    strcpy(file_data->extension, DEFAULT_EXT); // Save the default extension for later use

    return file_data;
}
