class NFApiCRCIndicationPduManager : boost::noncopyable {
public:
    using FactoryMap = std::map<int, std::function<std::unique_ptr<NFApiCRCIndicationPduManager>()>;
    static NFApiCRCIndicationPduManager& getInstance() {
        static NFApiCRCIndicationPduManager instance;
        return instance;
    }

    void registerFactory(int id, std::function<std::unique_ptr<NFApiCRCIndicationPduManager>()> factory) {
        factories[id] = std::move(factory);
    }

    template<typename Derived>
    void registerSubclassFactory() {
        static_assert(std::is_base_of<NFApiCRCIndicationPduManager, Derived>::value, "Derived must be a subclass of NFApiCRCIndicationPduManager");
        auto id = static_cast<int>(std::type_index(typeid(Derived)).hash_code() % 1000);
        registerFactory(id, [=]() { return std::make_unique<Derived>(); });
    }

    std::unique_ptr<NFApiCRCIndicationPduManager> createInstance(int id) const {
        auto it = factories.find(id);
        if (it == factories.end()) throw std::runtime_error("Invalid factory ID");
        return it->second();
    }

    void serializeToJson(nlohmann::json& j) const {
        // Implement serialization here
    }

    void deserializeFromJson(const nlohmann::json& j) {
        // Implement deserialization here
    }

private:
    struct MemoryPool {
        std::vector<NFAPI_CRC_INDICATION_PDU_T> pool;
        size_t capacity, curIndex;
        mutable std::mutex lock;

        MemoryPool(size_t initialSize) : pool(initialSize), capacity(initialSize), curIndex(0) {}

        NFAPI_CRC_INDICATION_PDU_T alloc() {
            if (curIndex == capacity) expand();
            auto ret = pool[curIndex++];
            return ret;
        }

        void free(NFAPI_CRC_INDICATION_PDU_T data) {
            if (curIndex > 0) --curIndex;
        }

        void expand() {
            size_t newCapacity = capacity * 2 + 1024;
            std::vector<NFAPI_CRC_INDICATION_PDU_T> newPool(newCapacity);
            std::copy(pool.begin(), pool.end(), newPool.begin());
            pool.swap(newPool);
            capacity = newCapacity;
        }
    };

    MemoryPool memoryPool;
    boost::atomic<size_t> activeCount;
    mutable std::mutex dataMutex, logMutex;
    FactoryMap factories;

    NFApiCRCIndicationPduManager() : activeCount(0) {}

    void log(const char* message, const NFAPI_CRC_INDICATION_PDU_T& data) const {
        std::time_t now = std::time(nullptr);
        std::string logMsg = std::string(now == -1 ? "" : ctime(&now)) + message;
        std::lock_guard<std::mutex> lock(logMutex);
        std::cout << logMsg << "Structure ID: " << data.RNTI << ": " << data.RNTI >= 1 && data.RNTI <= 65535 ? "Valid" : "Invalid RNTI" << "\n";
    }

public:
    void addData(const NFAPI_CRC_INDICATION_PDU_T& data) {
        if (data.RNTI >= 1 && data.RNTI <= 65535) {
            std::lock_guard<std::mutex> lock(dataMutex);
            auto pdum = memoryPool.alloc();
            pdum.RX_UE_INFORMATION_TAG = data.RX_UE_INFORMATION_TAG;
            pdum.RNTI = data.RNTI;
            pdum.CRC_INDICATION_REL8_TAG = data.CRC_INDICATION_REL8_TAG;
            pdum.CRCFLAG = static_cast<bool>(rand() % 2);
            activeCount++;
            log("Added", pdum);
        }
    }

