    node_t *head = malloc(sizeof(node_t));
    head->next = NULL;
    return head;
}

void add_instrument(node_t **head, const char *symbol, double last_price, unsigned long volume) {
    node_t *new_node = malloc(sizeof(node_t));
    new_node->data.last_price = last_price;
    new_node->data.volume = volume;
    strcpy(new_node->data.symbol, symbol);
    new_node->data.update_timestamp = time(NULL);
    new_node->next = *head->next;
    *head->next = new_node;
