    // Initialize performance monitoring
    start_performance_monitoring();

    pthread_mutex_t rnti_lock = PTHREAD_MUTEX_INITIALIZER;

    for (size_t i = 0; i < n && used < n; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* entry = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!entry) {
            error_log("Out of memory");
            continue;
        }

        pthread_mutex_lock(&rnti_lock);
        while (used > 0 && current_rnti == list[used - 1]->rnti) {
