static CONFIG_PROFILE_T* active_profile = NULL;
static UL_CCCH_MESSAGE_T** messages = NULL;
static size_t num_messages = 0;

void init(CONFIG_PROFILE_T* profile) {
    active_profile = profile;
    messages = calloc(profile->num_mappings, sizeof(UL_CCCH_MESSAGE_T*));
    for (size_t i = 0; i < profile->num_mappings; ++i)
        messages[i] = malloc(sizeof(UL_CCCH_MESSAGE_T));
}

void deinit() {
    for (size_t i = 0; i < num_messages; ++i)
        free(messages[i]);
    free(messages);
    active_profile = NULL;
}

UL_CCCH_MESSAGE_T* add_message(uint64_t tx_ue_id) {
    if (num_messages >= active_profile->num_mappings) return NULL;

    pthread_mutex_lock(&mutex);
    while (1) {
        uint32_t sequence_number = num_messages;
        UL_CCCH_MESSAGE_T* message = messages[sequence_number];
        if (!message) break;
        ++num_messages;
    }

    UL_CCCH_MESSAGE_T* new_message = messages[num_messages - 1];
    new_message->sequence_number = num_messages - 1;
    new_message->tx_ue_id = tx_ue_id;
    time_t rawtime;
    struct tm * timeinfo;
    time(&rawtime);
    timeinfo = localtime(&rawtime);
    srand((unsigned int)pthread_self());
    char ccch_message[MAX_CCCH_MESSAGE_LEN];
    strftime(ccch_message, sizeof(ccch_message), "%Y%m%d-%H:%M:%S", timeinfo);
    snprintf(new_message->ccch_message, MAX_CCCH_MESSAGE_LEN, "%s-%.6ld", ccch_message, (long)pthread_self());

    pthread_mutex_unlock(&mutex);

    return new_message;
}

