// Custom memory allocator and pool
typedef struct MemBlock {
    void* data;
    size_t size;
    struct MemBlock* next;
} MemBlock;

MemBlock* mem_pool = NULL;

void* mem_alloc(size_t size) {
    if (!mem_pool) {
        mem_pool = mmap(NULL, 4096, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANON, -1, 0);
        if (mem_pool == MAP_FAILED) {
            perror("mmap");
            exit(EXIT_FAILURE);
        }
    }

    MemBlock* current = mem_pool;
    while (current->next && current->next->size >= size) {
        current = current->next;
    }

    if (!current->next) {
        current->next = malloc(sizeof(MemBlock));
        if (!current->next) {
            perror("malloc");
            exit(EXIT_FAILURE);
        }
        current->next->data = NULL;
        current->next->size = 0;
        current->next->next = mem_pool;
        mem_pool = current->next;
    }

    MemBlock* new_block = current->next;
    current->next = new_block->next;
    new_block->data = malloc(size);
    if (!new_block->data) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    new_block->size = size;
    return new_block->data;
}

void mem_free(void* ptr) {
    MemBlock* block = (MemBlock*)((char*)ptr - offsetof(MemBlock, data));
    block->data = NULL;
    block->size = 0;
    if (block->next) {
        block->next->data = mem_alloc(block->next->size);
        memcpy(block->next->data, block, sizeof(*block));
        free(block);
    } else {
        free(block);
        mem_pool = NULL;
    }
}

// File reader using a buffer
ssize_t readline(int fd, void* buf, size_t count) {
    ssize_t bytes_read;
    if (count == 0) return 0;

    char* data = buf;
    while ((bytes_read = read(fd, data, count)) > 0) {
        data += bytes_read;
        count -= bytes_read;
        if (count <= 1 && *data == '\n') { // Found a newline character
            break;
        }
    }

    return data - (char*)buf;
}

