void hash_func(char *filename, int *key) {
    unsigned long hash = 5381;
    int c;

    for (c = 0; *(filename + c); ++c) {
        hash += (hash << 5) + hash + *(filename + c);
    }

    *key = abs(hash % INT_MAX);
}

