pid_t run_command_in_background(const char *command) {
    pid_t pid = fork();

    if (pid == -1) {
        return 0;
    } else if (pid > 0) {
        // Parent process
        return pid;
    } else {
        // Child process
        printf("Background command: %s\n", command);
        if (execl("/bin/bash", "/bin/bash", "-c", command, NULL) < 0) {
            return 0;
        }
    }
}

int process_files(int num_files, char **filenames, int range_start, int range_end, char *command) {
    if (!num_files || !filenames) {
        fprintf(stderr, "Invalid input\n");
        return 0;
    }

    int *keys = calloc(num_files, sizeof(int));
    long *offsets = calloc(num_files, sizeof(long));
    record **records = malloc(num_files * sizeof(record*));

    for (int i = 0; i < num_files; ++i) {
        hash_func(filenames[i], &keys[i]);
        records[i] = malloc(sizeof(record));
        records[i]->offset = offsets[i] = 0;
        records[i]->key = keys[i];
    }

    // Populate the records with random values and sort them based on their long integer fields.
    // ...

    pid_t background_pid = run_command_in_background(command);

    if (!background_pid) {
        return 0;
    }

    for (int i = 0; i < num_files; ++i) {
        // Open the file using the record's key and manipulate it as needed.
        // ...
    }

    for (int i = 0; i < num_files; ++i) {
        free(records[i]);
    }
    free(records);
    free(keys);
    free(offsets);

    waitpid(background_pid, NULL, 0);

    return 1;
}
