#include <jansson/jansson.h>
#include <pthread.h>
#include <stdbool.h>
#include <stdio.h>
#include <stdlib.h>
#include <sys/time.h>

typedef struct {
    time_t expiration;
    char token[256];
    char type[32];
    char refresh_token[256];
} Token;

static Token cached_token = {0};
static pthread_mutex_t cache_mutex = PTHREAD_MUTEX_INITIALIZER;
static time_t cache_expiration = 0;

bool process_oauth2_response(const char* json) {
    json_t *root, *access_token, *expires_in, *token_type, *refresh_token;
    int rc;

    if (!json || !json_is_valid(json)) {
        return false;
    }

    root = json_loads(json, 0, NULL);
    if (!root) {
        perror("Invalid JSON format");
        return false;
    }

    access_token = json_object_get(root, "access_token");
    expires_in = json_object_get(root, "expires_in");
    token_type = json_object_get(root, "token_type");
    refresh_token = json_object_get(root, "refresh_token");

    if (!access_token || !json_is_string(access_token) ||
        !expires_in || !json_is_integer(expires_in) ||
        (json_value_get(expires_in) < 0)) {
        json_decref(root);
        return false;
    }

    if (!token_type || !strcmp(json_string_value(token_type), "Bearer")) {
        // Refresh token is optional
        if (refresh_token) {
            if (!json_is_string(refresh_token)) {
                json_decref(root);
                return false;
            }
        }
    } else {
        json_decref(root);
        return false;
    }

    pthread_mutex_lock(&cache_mutex);
    time_t now = time(NULL);

    if (!cached_token.expiration || (now > cached_token.expiration)) {
        if (now <= cache_expiration) {
            json_decref(root);
            pthread_mutex_unlock(&cache_mutex);
            return true;
        }

        strncpy(cached_token.token, json_string_value(access_token), sizeof(cached_token.token));
        strncpy(cached_token.type, json_string_value(token_type), sizeof(cached_token.type));
        cached_token.expiration = now + (time_t)json_integer_value(expires_in);
        cache_expiration = cached_token.expiration + 5; // Cache for 5 seconds
    }

    pthread_mutex_unlock(&cache_mutex);

    return true;
}
```

This code uses the JSON for Modern C library (jansson) for parsing JSON and includes a simple cache mechanism using a mutex. The function handles potential JSON parsing errors, invalid formats, and missing or incorrect fields in the response. It also caches valid access tokens for a short period to reduce network calls frequency.']

