using System;
using System.Collections.Concurrent;
using System.Linq;
using System.Security.Cryptography;
using System.Data;
using System.Threading.Tasks;

public class Record
{
    public byte[] ByteArray { get; set; }
    public int IntegerValue { get; set; }
    public long Offset { get; private set; }
    public double DoubleValue { get; set; }
}

public async Task<DataTableReader> CreateRecordsAsync(int maxRecords)
{
    var md5Cache = new ConcurrentDictionary<string, string>();
    var records = new List<Record>();

    // MD5 cache for strings
    Func<string, Task<string>> CalculateMd5Hash = async str =>
    {
        if (md5Cache.TryGetValue(str, out string hash))
            return hash;

        using (var md5 = MD5.Create())
        {
            var data = Encoding.ASCII.GetBytes(str);
            var hashValue = md5.ComputeHash(data);
            hash = BitConverter.ToString(hashValue).Replace("-", "").ToLower();
            md5Cache[str] = hash;
        }

        return hash;
    };

    // Random number generator
    Func<Random, T> RandomNumberGenerator<T>(Func<Random, T> getter, T minValue, T maxValue) =>
        random => getter(random)(new System.Globalization.CultureInfo("en-US")).NextDouble() < (maxValue - minValue) / 2.0 ? getter(random)(minValue + (maxValue - minValue) * (random.NextDouble())) : minValue;

    var random = new Random();

    var hashTable = new ConcurrentHashSet<int>();

    for (int i = 0; i < maxRecords; i++)
    {
        int key;

        do
        {
            // Generate a unique integer key
            key = RandomNumberGenerator(random, 1, int.MaxValue).Invoke(random);
        } while (hashTable.Contains(key));

        hashTable.Add(key);

        var record = new Record()
        {
            ByteArray = new byte[RandomNumberGenerator(random, 0, 1024).Invoke(random)],
            IntegerValue = key,
            Offset = records.Select((r, index) => r.IntegerKey + r.ByteArray.Length * index).Sum(),
            DoubleValue = RandomNumberGenerator(random, double.MinValue, double.MaxValue).Invoke(random)
        };

        records.Add(record);
    }

    // ... You should continue with sending the byte array to a database server and querying the result here ...

    return null; // Replace this with your implementation for returning a DataTableReader object
}
