using System;
using System.Security.Cryptography;
using System.Text;
using System.Runtime.InteropServices;

public class FileMetadata
{
    public int FileSize { get; set; }
    public long LastModifiedTimestamp { get; set; }
    public string FileContentHash { get; set; }
}

[StructLayout(LayoutKind.Sequential)]
class FilePathString
{
    [MarshalAs(UnmanagedType.LPStr)]
    public String Str;
}

public string DecryptAndInitializeFiles(string encryptedMessage, byte[] key, byte[] iv)
{
    using (TripleDES algorithm = TripleDES.Create())
    {
        algorithm.Key = key;
        algorithm.IV = iv;

        ICryptoTransform transform = algorithm.CreateDecryptor();
        byte[] decryptedBytes = transform.TransformFinalBlock(Convert.FromBase64String(encryptedMessage), 0, encryptedMessage.Length);
        string decryptedMessage = Encoding.UTF8.GetString(decryptedBytes);

        double[] floatArray = null;
        IntPtr floatPointer = Marshal.AllocHGlobal(floatArray.Length * sizeof(double));
        try
        {
            if (floatPointer == IntPtr.Zero)
                throw new OutOfMemoryException("Failed to allocate memory for float array.");

            floatArray = new double[decryptedMessage.Split(' ').Length];
            Marshal.Copy(floatPointer, floatArray, 0, floatArray.Length);
        }
        catch (OutOfMemoryException)
        {
            if (floatArray != null)
                Marshal.FreeHGlobal(floatPointer);
            throw;
        }

        FilePathString[] filePaths = new FilePathString[decryptedMessage.Split(' ').Length];
        IntPtr filePathsPointer = Marshal.AllocHGlobal(filePaths.Length * sizeof(FilePathString));
        try
        {
            if (filePathsPointer == IntPtr.Zero)
                throw new OutOfMemoryException("Failed to allocate memory for file path array.");

            for (int i = 0; i < decryptedMessage.Split(' ').Length; i++)
            {
                if (floatPointer == IntPtr.Zero || filePathsPointer == IntPtr.Zero)
                    throw new OutOfMemoryException("Failed to allocate memory for additional arrays.");

                filePaths[i].Str = decryptedMessage.Split(' ')[i];
            }
        }
        catch (OutOfMemoryException)
        {
            if (floatArray != null)
                Marshal.FreeHGlobal(floatPointer);
            if (filePaths != null)
                Marshal.FreeHGlobal(filePathsPointer);
            throw;
        }

        FileMetadata[] fileMetadatas = new FileMetadata[decryptedMessage.Split(' ').Length];
        IntPtr fileMetadatasPointer = Marshal.AllocHGlobal(fileMetadatas.Length * sizeof(FileMetadata));
        try
        {
            if (fileMetadatasPointer == IntPtr.Zero)
                throw new OutOfMemoryException("Failed to allocate memory for file metadata array.");

            for (int i = 0; i < decryptedMessage.Split(' ').Length; i++)
            {
                if (floatPointer == IntPtr.Zero || filePathsPointer == IntPtr.Zero || fileMetadatasPointer == IntPtr.Zero)
                    throw new OutOfMemoryException("Failed to allocate memory for additional arrays.");

                fileMetadatas[i] = new FileMetadata()
                {
                    FileSize = (int)(new Random().NextDouble() * 1000000), // Generate a positive integer up to 1,000,000
                    LastModifiedTimestamp = (long)DateTime.UtcNow.Subtract(new DateTime(1970, 1, 1)).TotalSeconds, // Validate Unix epoch time
                    FileContentHash = SHA256.Create().ComputeHash(Encoding.UTF8.GetBytes(filePaths[i].Str)) // Generate a unique hash based on the file path
                };
            }
        }
        catch (OutOfMemoryException)
        {
            if (floatArray != null)
                Marshal.FreeHGlobal(floatPointer);
            if (filePaths != null)
                Marshal.FreeHGlobal(filePathsPointer);
            throw;
        }

        // Clean up allocated memory and return the decrypted message
        if (floatArray != null)
            Marshal.FreeHGlobal(floatPointer);
        if (filePaths != null)
            Marshal.FreeHGlobal(filePathsPointer);
        if (fileMetadatas != null)
            Marshal.FreeHGlobal(fileMetadatasPointer);

        return decryptedMessage;
    }
}
