class SignalQueueManager {
private:
    std::list<PHY_RX_STATS_T> signalQueue; // The dynamically allocated linked list
    std::mutex queueMutex; // Mutex for safe access to the queue
    std::shared_ptr<Thresholds> thresholds; // A shared pointer to the threshold values
    std::unordered_map<int, std::unique_ptr<std::atomic<bool>>> stopThreads; // Flag to stop signal reception threads when necessary
    int interval = 1000; // Update interval for threshold and rule data
    int granularity = 500; // Granularity of anomaly detection (in milliseconds)

public:
    SignalQueueManager(const Thresholds& initialThresholds) : thresholds(std::make_shared<Thresholds>(initialThresholds)) {}

    void addSignal(const PHY_RX_STATS_T& signal) {
        std::scoped_lock<std::mutex> lock(queueMutex); // Acquire the lock before adding a new signal
        signalQueue.push_back(signal);
    }

    void setThreshold(int minRSSI, int maxRSSI) {
        thresholds->min_RSSI = std::max(-100, minRSSI);
        thresholds->max_RSSI = std::min(0, maxRSSI);
    }

    void startThread(int threadID) {
        stopThreads[threadID] = std::make_unique<std::atomic<bool>>(false);
        // Start the signal reception thread here...
    }

    void stopThread(int threadID) {
        stopThreads[threadID]->store(true);
    }

    void updateRulesAndThresholds() {
        std::unique_lock<std::shared_mutex> lock(thresholds->mutex()); // Acquire the shared lock to modify the thresholds
        // Update the threshold values and anomaly detection rules here...
    }
};
```

This implementation utilizes `std::list` for the linked list management, `std::mutex`, and `std::shared_mutex` for thread safety. The signal reception threads can be started using the `startThread()` method, and stopped with the `stopThread()` method. Anomaly detection is not implemented directly in this code snippet, but you can replace the comments in `updateRulesAndThresholds()` with your custom anomaly detection logic.

