```javascript
const neo4j = require('neo4j-driver');
const axios = require('axios');
const { promisify } = require('util');
const fs = require('fs');
const path = require('path');
const chalk = require('chalk');
const moment = require('moment');

// Initialize Neo4j driver
const driver = neo4j.driver(
  'neo4j://username:password@localhost',
  neo4j.auth.basic('username', 'password')
);
const session = driver.session();

const MAX_VERTS = 1000;
const MAX_EDGES = 5000;
const MAX_RETRIES = 3;
const LOG_FILE = path.join(__dirname, 'logs', `graph-operations.log`);

// Utility function to create a timestamp string for logging
function logTimestamp() {
  return moment().format('YYYY-MM-DD HH:mm:ss.SSS');
}

async function addVerticesAndEdges(verticesCount, edgesCount) {
  let retries = MAX_RETRIES;
  while (retries > 0) {
    try {
      // Add vertices and edges to the graph
      const vertices = Array.from({ length: verticesCount }, () => createVertex());
      const edges = createEdges(vertices, edgesCount);

      await session.run(`
        LOAD csv WITH * as row
        CREATE (r:Vertex { id: toInt(row[0]), prop1: row[1], prop2: row[2] })
        FOREACH (r IN Relationships(vertices, 'KNOWS')) SET r.prop = row[3]
      `, { vertices, edges });

      return;
    } catch (error) {
      retries--;
      if (retries === 0) throw error;
      console.log(`Error adding vertices and edges, retrying in ${MAX_RETRIES - retries} attempts...`);
    }
  }

  throw new Error('Failed to add vertices and edges');
}

function createVertex() {
  // Generate random properties for the vertex
  return { id: Math.floor(Math.random() * MAX_VERTS), prop1: Math.random(), prop2: Math.random() };
}

function createEdges(vertices, edgesCount) {
  const edges = [];
  while (edges.length < edgesCount) {
    // Create an edge between two random vertices
    const vertex1Index = Math.floor(Math.random() * vertices.length);
    const vertex2Index = (vertex1Index + 1) % vertices.length;

    edges.push({ source: vertices[vertex1Index], target: vertices[vertex2Index] });
  }

  return edges;
}

// Logging function
function log(level, message) {
  fs.appendFileSync(LOG_FILE, `${logTimestamp()} [${level}] ${message}\n`, 'utf8');
}

addVerticesAndEdges(Math.floor(Math.random() * MAX_VERTS), Math.floor(Math.random() * MAX_EDGES));
```

