["```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    uint32_t PDCP_SN;
    uint16_t PDCP_SEQ;
    uint8_t *PDCP_PDU_DATA;
    size_t PDCP_PDU_LENGTH;
    size_t fragment_index;
} LTE_PDCP_PDU;

#define MAX_FRAGMENTS 1024
#define FRAGMENT_THRESHOLD 512
#define MAX_MEMORY 50 * (1024 * 1024) // 50 MB

static size_t total_allocated = 0;
static size_t num_pdus = 0;

LTE_PDCP_PDU* allocate_pdus(size_t num_pdus_required) {
    LTE_PDCP_PDU *pdus = malloc(num_pdus_required * sizeof(LTE_PDCP_PDU));
    if (!pdus) return NULL;

    for (size_t i = 0; i < num_pdus_required; ++i) {
        pdus[i].PDCP_SN = i;
        pdus[i].PDCP_SEQ = 0;
        pdus[i].PDCP_PDU_DATA = NULL;
    }

    total_allocated += num_pdus_required * sizeof(LTE_PDCP_PDU);

    if (total_allocated > MAX_MEMORY) {
        free(pdus);
        return NULL;
    }

    size_t current_pdu = 0;
    for (size_t i = 0; i < num_pdus_required; ++i) {
        size_t data_len = rand() % 1024 + 1;
        if (data_len <= FRAGMENT_THRESHOLD) {
            pdus[i].PDCP_PDU_DATA = malloc(data_len);
            if (!pdus[i].PDCP_PDU_DATA) {
                free(pdus);
                return NULL;
            }
            total_allocated += data_len;
            pdus[i].PDCP_PDU_LENGTH = data_len;
        } else {
            size_t num_fragments = (data_len + FRAGMENT_THRESHOLD - 1) / FRAGMENT_THRESHOLD;
            for (size_t j = 0; j < num_fragments; ++j) {
                pdus[current_pdu++].PDCP_PDU_DATA = malloc(FRAGMENT_THRESHOLD);
                if (!pdus[current_pdu - 1].PDCP_PDU_DATA) {
                    free_and_reset(pdus, current_pdu);
                    return NULL;
                }
                total_allocated += FRAGMENT_THRESHOLD;
                pdus[current_pdu - 1].PDCP_PDU_LENGTH = FRAGMENT_THRESHOLD;
            }
        }
    }

    return pdus;
}

void free_and_reset(LTE_PDCP_PDU *pdus, size_t num_pdus) {
    for (size_t i = 0; i < num_pdus; ++i) {
        if (pdus[i].PDCP_PDU_DATA) free(pdus[i].PDCP_PDU_DATA);
    }
    total_allocated -= num_pdus * sizeof(LTE_PDCP_PDU);
    memset(pdus, 0, num_pdus * sizeof(LTE_PDCP_PDU));
}
