use actix_web::{dev::Payload, web, App, HttpRequest, HttpResponse, Responder};
use futures::stream::StreamExt;
use std::sync::Arc;
use tokio::sync::RwLock;
use warp::{Filter, WebSocket};

type Database = Arc<RwLock<dyn Send + Sync>>;

struct HandlerRegistry {
    http_handlers: Vec<Box<dyn HttpHandler + Send + Sync>>,
    websocket_handlers: Vec<Box<dyn WebSocketHandler + Send + Sync>>,
}

trait HttpHandler: Send + Sync + 'static {
    async fn handle(&self, req: HttpRequest) -> impl Responder;
}

trait WebSocketHandler: Send + Sync + 'static {
    async fn handle(self: Box<Self>, ws: WebSocket) -> Result<(), warp::error::Custom>;
}

impl HandlerRegistry {
    async fn select_handler(&self, req: &HttpRequest) -> Option<Box<dyn HttpHandler>> {
        self.http_handlers.iter().find(|h| h.can_handle(req))
    }

    async fn websocket_handler(&self, ws: WebSocket) -> Result<(), warp::error::Custom> {
        if let Some(h) = self.websocket_handlers.iter().find(|h| h.can_handle(&ws)) {
            h.handle(ws).await
        } else {
            Err(warp::error::custom("No suitable WebSocket handler found"))
        }
    }
}

async fn http_handler<H: HttpHandler>(registry: &Arc<RwLock<HandlerRegistry>>, handler: H) -> impl Responder {
    move |req| {
        let registry = registry.read().await;
        let handler = registry.select_handler(&req).unwrap();
        handler.handle(req).into_response()
    }
}

async fn websocket_handler<H: WebSocketHandler>(registry: &Arc<RwLock<HandlerRegistry>>, handler: H) -> impl Responder {
    warp::ws().and(move |ws| {
        let registry = registry.read().await;
        async move {
            match registry.websocket_handler(ws).await {
                Ok(_) => ws.on_upgrade(Box::new(handler)),
                Err(e) => {
                    log::error!("WebSocket connection error: {}", e);
                    HttpResponse::internal_server_error().finish()
                }
            }
        }
    })
}

// Integrate with an external data source for real-time updates
