    let handlers = HandlerRegistry {
        http_handlers: vec![
            Box::new(|req| async move {
                // Your HTTP request handler implementation.
                HttpResponse::Ok().finish()
            }),
            // Add more HTTP handlers as needed...
        ],
        websocket_handlers: vec![
            Box::new(|ws| async move {
                // Your WebSocket connection handler implementation.
            }),
            // Add more WebSocket handlers as needed...
        ],
    };

    let registry = Arc::new(RwLock::new(handlers));

    tokio::spawn(fetch_data(&db).into_future());

    let http_routes = warp::path!("api").and(http_handler(&registry, ...)).route();
    let websocket_routes = warp::path!("ws").and(websocket_handler(&registry, ...));

    let app = warp::serve(
        http_routes.or(websocket_routes)
    )
    .run(([127, 0, 0, 1], 8080))
    .await;

    log::info!("Server started on :8080");

    app.await
}
