use std::sync::Mutex;

const DATA_STORAGE_ENV: &str = "DATA_STORAGE_PATH";
const LOG_FILE: &str = "data_storage.log";

static MUTEX: Mutex<()> = Mutex::new(());
static FIRST_RUN: AtomicBool = AtomicBool::new(true);

fn setup_data_directory(dir_name: &str) -> Result<PathBuf, Box<dyn Error>> {
    let mut guard = MUTEX.lock().unwrap();
    if FIRST_RUN.swap(false, Ordering::Relaxed) {
        if !env::var_os(DATA_STORAGE_ENV).is_none() {
            return Ok(env::var_os(DATA_STORAGE_ENV)?);
        }
    }

    let data_storage = if dir_name.is_empty() {
        "data_storage"
    } else {
        validate_directory_name(&dir_name)
            .map(|_| dir_name)
            .unwrap_or_else(|e| panic!("Invalid directory name: {}", e))
    };

    let data_path = fs::canonicalize(PathBuf::from(".")).map_err(|e| {
        log_and_return::<(), Box<dyn Error>>(format!(
            "Error getting current working directory: {}",
            e
        ))
    })?;
    let data_storage_path = data_path.join(data_storage);

    if !data_storage_path.exists() {
        create_dir_all(&data_storage_path)?;
        env::set_var(DATA_STORAGE_ENV, data_storage_path.to_str().unwrap());
    }

    Ok(data_storage_path)
}

fn log_and_return<T, E: Error>(message: T) -> Result<T, E> {
    let _ = writeln!(
        log::info!("{}", message),
        std::fs::OpenOptions::new()
            .write(true)
            .append(true)
            .create_new(true)
            .open(LOG_FILE)?
    );
    Ok(message)
}

fn validate_directory_name(dir_name: &str) -> Result<(), Box<dyn Error>> {
    if dir_name.chars().all(|c| c.is_alphanumeric() || c == '-' || c == '_' || c == '.') {
        Ok(())
    } else {
        Err(Box::new(format!(
            "Invalid directory name: {} contains special characters",
            dir_name
        )))
    }
}

