typedef struct {
    long offset;
    int key;
} record;

record* init_arrays(size_t size) {
    long *offsets = (long*) malloc(size * sizeof(long));
    if (!offsets) {
        fprintf(stderr, "Error: Unable to allocate memory for offsets\n");
        exit(EXIT_FAILURE);
    }

    int *keys = (int*) malloc(size * sizeof(int));
    if (!keys) {
        fprintf(stderr, "Error: Unable to allocate memory for keys\n");
        free(offsets);
        exit(EXIT_FAILURE);
    }

    record* records = (record*) malloc(size * sizeof(record));
    if (!records) {
        fprintf(stderr, "Error: Unable to allocate memory for records\n");
        free(offsets);
        free(keys);
        exit(EXIT_FAILURE);
    }

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    for (size_t i = 0; i < size; ++i) {
        records[i].offset = offsets[i];
        records[i].key = rand() % RANDOM_RANGE + RANDOM_MIN;
        offsets[i] = -1; // mark as used for thread-safety
    }

    return records;
}

void free_arrays(record* records, size_t size, pthread_mutex_t mutex) {
    for (size_t i = 0; i < size; ++i) {
        pthread_mutex_lock(&mutex);
        if (records[i].offset != -1) {
            free((void*) &records[i]);
        }
        pthread_mutex_unlock(&mutex);
    }

    free(records);
    free(records + size); // free the extra space allocated by the loop
    free(records + 2 * size); // free the space for offsets and keys
}
