void error_log(const char *msg) {
    FILE *log_file = fopen("error_log.txt", "a");
    if (log_file != NULL) {
        fprintf(log_file, "%s\n", msg);
        fclose(log_file);
    }
}

void* init_arrays(long *offsets, int *keys, record **records, size_t num) {
    offsets = calloc(num, sizeof(long));
    if (offsets == NULL) {
        error_log("Error allocating memory for offset array");
        return NULL;
    }

    keys = calloc(num, sizeof(int));
    if (keys == NULL) {
        error_log("Error allocating memory for key array");
        free(offsets);
        return NULL;
    }

    records = malloc(num * sizeof(record));
    if (records == NULL) {
        error_log("Error allocating memory for record array");
        free(offsets);
        free(keys);
        return NULL;
    }

    for (size_t i = 0; i < num; ++i) {
        records[i] = malloc(sizeof(record));
        if (records[i] == NULL) {
            error_log("Error allocating memory for record structure");
            free(offsets);
            free(keys);
            free(records);
            return NULL;
