void process_line(char *line, long *offsets, int *keys, record **records, size_t num, FILE *log_file) {
    char *token = strtok(line, ",");
    long total = 0;
    size_t index = num - 3;

    while (token != NULL && index >= 0) {
        if (sscanf(token, "%ld", &offsets[index]) == 1) {
            total += offsets[index];
            --index;
        }
        token = strtok(NULL, ",");
    }

    double avg = (total / 3.0);
    snprintf(token, sizeof(char) * strlen(token), "%f", avg);
    strcat(line, token);

    for (size_t i = num - 3; i < num; ++i) {
        records[i]->key = rand_in_range(0, 100); // Modify this line to set the key field as per your requirements.
        snprintf(token, sizeof(char) * strlen(token), "%d", records[i]->key);
        strcat(line, token);
    }

    fputs(line, log_file);
}

