#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct Record {
    long offset;
    int key;
    float value;
} Record;

struct Cache {
    size_t capacity;
    size_t size;
    Record* records;
    time_t last_access;
};

Record* create_record() {
    Record* record = malloc(sizeof(Record));
    if (!record) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    return record;
}

struct Cache* create_cache(size_t capacity) {
    struct Cache* cache = malloc(sizeof(struct Cache));
    if (!cache) {
        perror("malloc");
        exit(EXIT_FAILURE);
    }
    cache->capacity = capacity;
    cache->size = 0;
    cache->records = NULL;
    cache->last_access = time(NULL);
    return cache;
}

void destroy_cache(struct Cache* cache) {
    for (size_t i = 0; i < cache->size; ++i) {
        free(cache->records[i].value);
        free(cache->records + i);
    }
    free(cache->records);
    free(cache);
}

void evict_old_records(struct Cache* cache) {
    time_t current = time(NULL);
    if (difftime(current, cache->last_access) > 60) { // Evict records not accessed for 60 seconds
        for (size_t i = 1; i < cache->size; ++i) {
            if (difftime(cache->records[i - 1].key, cache->records[i].key) > 1) { // Evict records with a gap of more than 1 in their keys
                free(cache->records[i].value);
                free(cache->records + i);
                memmove(cache->records + i - 1, cache->records + i, sizeof(Record) * (--cache->size - i + 1));
            }
        }
    }
    cache->last_access = current;
}

void reset_cache(struct Cache* cache) {
    if (!cache->size) return;
    evict_old_records(cache);
    cache->size = 0;
    cache->last_access = time(NULL);
}

int main() {
    long (*offset_generator)(void);
    int (*key_generator)(void);
    float (*value_generator)(long, int);
    size_t capacity;

    scanf("%ld %d %p %ld", &offset_generator, &capacity, &key_generator, &value_generator);

    struct Cache* cache = create_cache(capacity);
    long* offsets = malloc(sizeof(long) * cache->capacity);
    int* keys = malloc(sizeof(int) * cache->capacity);
    Record* records = malloc(sizeof(Record) * cache->capacity);

    for (size_t i = 0; i < cache->capacity; ++i) {
        records[i].offset = offset_generator();
        records[i].key = key_generator();
        records[i].value = value_generator(records[i].offset, records[i].key);
        if (!cache->size) {
            cache->records = records;
        } else if (cache->size < cache->capacity && difftime(time(NULL), cache->last_access) > 60) {
            reset_cache(cache);
            evict_old_records(cache);
        }
        if (cache->size >= cache->capacity) {
            evict_old_records(cache);
        }
        offsets[cache->size] = records[i].offset;
        keys[cache->size] = records[i].key;
        ++cache->size;
    }

    free(offsets);
    free(keys);
    destroy_cache(cache);
    return 0;
}
