    (*value_generator)(&list->elements[0].value);
}

void resize_list(struct list* list, void (*realloc_func)(struct list*, size_t)) {
    if (list->size >= list->capacity * THRESHOLD) {
        realloc_func(list, list->capacity *= 2);
    }
}

void compact_list(struct list* list, void (*compact_func)(struct list*)) {
    time_t current_time = time(NULL);
    if (current_time - list->elements[0].timestamp > 60) {
        compact_func(list);
    }
}

void serialize_list(const struct list* list, FILE* file) {
    fwrite(&list->capacity, sizeof(size_t), 1, file);
    for (size_t i = 0; i < list->size; ++i) {
        fwrite(&list->elements[i].timestamp, sizeof(time_t), 1, file);
        fwrite(&list->elements[i].id, sizeof(int), 1, file);
        fwrite(&list->elements[i].value, sizeof(double), 1, file);
    }
}

void deserialize_list(struct list* list, FILE* file) {
