    uint32_t rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = malloc(sizeof(Node));
    if (new_node == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    new_node->data = data;
    new_node->next = NULL;

    return new_node;
}

void push_back(Node** head_ref, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = create_node(data);

    if (*head_ref == NULL) {
        *head_ref = new_node;
        return;
    }

    Node* last = *head_ref;
    while (last->next != NULL)
        last = last->next;

    last->next = new_node;
}

NFAPI_CRC_INDICATION_PDU_T pop_front(Node** head_ref) {
    if (*head_ref == NULL) {
        fprintf(stderr, "List is empty.\n");
        exit(EXIT_FAILURE);
    }

    NFAPI_CRC_INDICATION_PDU_T ret = (*head_ref)->data;
    Node* temp = *head_ref;
    *head_ref = (*head_ref)->next;
    free(temp);

    return ret;
}

NFAPI_CRC_INDICATION_PDU_T remove_by_rnti(Node** head, uint32_t rnti) {
    if (*head == NULL) {
        fprintf(stderr, "List is empty.\n");
        exit(EXIT_FAILURE);
    }

    Node* current = *head;
    NFAPI_CRC_INDICATION_PDU_T data;

    if (current->data.rnti == rnti) {
        data = current->data;
        free(current);
        *head = current->next;
        return data;
    }

    for (Node* last = *head; last->next != NULL; last = last->next) {
        if (last->next->data.rnti == rnti) {
            data = last->next->data;
            Node* temp = last->next;
            last->next = last->next->next;
            free(temp);
            return data;
        }
    }

    fprintf(stderr, "Element not found.\n");
    exit(EXIT_FAILURE);
}

void iterate(Node* node) {
    for (; node != NULL; node = node->next) {
        printf("RX_UE_INFORMATION_TAG: %d\n", node->data.rx_ue_information_tag);
        printf("RNTI: %u\n", node->data.rnti);
