// Macro for calculating the size of each structure
#define SIZEOF(type) ((size_t) &((type){0}) - (size_t)&(((type*)0)->0))

typedef struct _DynamicArray {
    NFAPI_CRC_INDICATION_PDU_T *data;
    size_t capacity;
    size_t length;
} DynamicArray;

// Function to initialize the dynamic array with a given capacity
void da_init(DynamicArray *da, size_t capacity) {
    if (capacity == 0) {
        return;
    }

    da->data = malloc(capacity * SIZEOF(NFAPI_CRC_INDICATION_PDU_T));
    if (!da->data) {
        fprintf(stderr, "Error: Failed to allocate memory for dynamic array.\n");
        exit(EXIT_FAILURE);
    }

    da->capacity = capacity;
    da->length = 0;
}

// Function to add a new entry to the dynamic array
void da_push(DynamicArray *da, const NFAPI_CRC_INDICATION_PDU_T *entry) {
    if (da->length >= da->capacity) {
        size_t new_capacity = da->capacity * 2;
        void *new_data = realloc(da->data, new_capacity * SIZEOF(NFAPI_CRC_INDICATION_PDU_T));

        if (!new_data) {
            fprintf(stderr, "Error: Failed to reallocate memory for dynamic array.\n");
            exit(EXIT_FAILURE);
        }

        da->data = new_data;
        da->capacity = new_capacity;
    }

    memcpy((void *)(da->data + da->length), (const void *)entry, SIZEOF(*entry));
    da->length++;
}

// Function to remove an entry based on RNTI
bool da_remove(DynamicArray *da, unsigned int rnti) {
    for (size_t i = 0; i < da->length; ++i) {
        if (da->data[i].rnti == rnti) {
            memmove((void *)(&(da->data[i])), &(da->data[i + 1]), (da->length - i - 1) * SIZEOF(*entry));
            da->length--;
            return true;
        }
    }
    return false;
}

// Function to iterate over all entries in the dynamic array
void da_iterate(const DynamicArray *da, void (*callback)(NFAPI_CRC_INDICATION_PDU_T *)) {
    for (size_t i = 0; i < da->length; ++i) {
        callback(&(da->data[i]));
    }
