namespace MySystem {

class Record {
public:
    explicit Record(long offset, int key, double value) : offset_(offset), key_(key), value_(value), data_{'\0', 256} {}
    long offset_;
    int key_;
    double value_;
    std::string data_;
};

class MemoryManager {
private:
    static std::random_device rd;
    static std::mt19937 gen;
    static constexpr size_t maxRecordsPerBatch = 10000;
    static constexpr size_t charCheckSize = 256;
    static constexpr size_t recordSize = sizeof(Record);
    static constexpr size_t fragmentsThreshold = 1000000; // in bytes
    static constexpr size_t maxMemoryUsage = 50 * 1024 * 1024; // 50 MB
    static size_t memoryUsage_;
    static std::vector<std::unique_ptr<Record[]>> records_;
    static std::unique_ptr<LTE_PDCP_PDU[]> pdus_;
    static size_t numFragments_;
    static size_t bytesAllocated_;

public:
    MemoryManager() : memoryUsage_(0), numFragments_(0), bytesAllocated_(0) {}

    ~MemoryManager() {
        for (auto& batch : records_) {
            if (!batch) continue;
            for (auto record : *batch) delete &record; // Delete array elements
            batch.reset();
        }
        if (pdus_) {
            for (LTE_PDCP_PDU* pdu : *pdus_) delete pdu; // Delete PDU fragments
            pdus_.reset();
        }
    }

    void initialize() {
        std::uniform_int_distribution<> distInt(0, INT32_MAX);
        std::uniform_real_distribution<> distReal(0.0, 1.0);

        records_.resize(maxRecordsPerBatch);
        for (auto& batch : records_) {
            if (!batch) {
                try {
                    batch.reset(new Record[maxRecordsPerBatch]);
                } catch (const std::bad_alloc&) {
                    std::cerr << "Error allocating memory for a batch" << std::endl;
                    return;
                }
            }
            for (auto& record : *batch) {
                auto offset = static_cast<long>(std::distance(records_.data(), &record));
                auto key = distInt(gen);
                record.offset_ = offset;
                record.key_ = key;
                record.value_ = distReal(gen);

                for (size_t i = 0; i < charCheckSize - 1; ++i) {
                    if (record.data_[i] == record.data_[i + 1]) {
                        do {
                            std::fill(std::begin(record.data_), std::end(record.data_), '\0');
                            record.data_[rand() % charCheckSize] = 'A' + rand() % 26;
                            record.data_[rand() % (charCheckSize - 1)] = 'A' + rand() % 26;
                        } while (std::adjacent_find(std::begin(record.data_), std::end(record.data_)) != std::end(record.data_));
                    }
                }
                record.data_[charCheckSize] = '\0';
            }
        }

        pdus_.reset(new LTE_PDCP_PDU[fragmentsThreshold]);
        numFragments_ = 0;
        bytesAllocated_ = recordSize * maxRecordsPerBatch + fragmentsThreshold;
    }

    void processBatch() {
        if (bytesAllocated_ > maxMemoryUsage) {
            std::cerr << "Error: Memory usage exceeds the limit. Cannot process batch." << std::endl;
            return;
        }

        size_t numProcessed = 0;
        for (size_t i = 0, j = 0; i < maxRecordsPerBatch && j < records_.size(); ++i) {
            if (!records_[j]) continue;

            auto record = &records_[j][i];

            // Process the record and generate PDUs as needed
            // ...

            numProcessed++;
            if (++numFragments_ >= fragmentsThreshold / sizeof(LTE_PDCP_PDU)) {
                bytesAllocated_ += recordSize * maxRecordsPerBatch + fragmentsThreshold;
                pdus_.reset(new LTE_PDCP_PDU[fragmentsThreshold]);
                numFragments_ = 0;
            }
        }
    }

private:
    void checkMemoryUsage() const {
        if (bytesAllocated_ > maxMemoryUsage) {
            std::cerr << "Error: Memory usage exceeds the limit. Cannot process more data." << std::endl;
            throw std::system_error(std::errc::resource_deadlock, std::generic_category());
        }
    }
};

std::random_device MySystem::rd;
std::mt19937 MySystem::gen(MySystem::rd());
size_t MySystem::memoryUsage_ = 0;
std::vector<std::unique_ptr<Record[]>> MySystem::records_;
std::unique_ptr<LTE_PDCP_PDU[]> MySystem::pdus_;
size_t MySystem::numFragments_ = 0;
size_t MySystem::bytesAllocated_ = 0;

} // namespace MySystem
