```c
#define ALLOCATOR_BLOCK_SIZE 4096 // Choose an appropriate size
typedef struct _allocator {
    void *freelist;
} Allocator;

Allocator* allocator_init(size_t size) {
    Allocator* alloc = malloc(sizeof(Allocator));
    if (!alloc) return NULL;
    alloc->freelist = malloc(ALLOCATOR_BLOCK_SIZE * size);
    if (!alloc->freelist) {
        free(alloc);
        return NULL;
    }
    for (size_t i = 0; i < ALLOCATOR_BLOCK_SIZE * size - sizeof(void*); ++i)
        ((void**)alloc->freelist)[i] = (((char*)alloc->freelist) + (i + 1) * sizeof(void*));
    return alloc;
}

void* allocator_malloc(Allocator* alloc, size_t size) {
    if (!alloc || !size) return NULL;
    void *ptr = alloc->freelist;
    if (ptr) {
        alloc->freelist = *(void**)ptr;
        return ptr;
    }
    // Handle out-of-memory case
    return NULL;
}

void allocator_free(Allocator* alloc, void *ptr) {
    if (!alloc || !ptr) return;
    *(void**)ptr = alloc->freelist;
    alloc->freelist = ptr;
}
