    array->data = allocator_malloc(array->allocator.freelist, initial_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!array->data) {
        free(array);
        return NULL;
    }
    return array;
}

void dynamic_array_destroy(DynamicArray* array) {
    if (!array) return;
    pthread_mutex_destroy(&array->mutex);
    allocator_free(array->allocator.freelist, array->data);
    free(array);
}

