using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Reflection;
using System.Runtime.CompilerServices;
using System.Xml;
using System.Threading;
using System.Threading.Tasks;
using System.Text;
using System.Diagnostics;
using Blueslip.Mocking;
using XDocument = System.Xml.Linq.XDocument;

public class TestResult
{
    public int TotalTests { get; set; }
    public int PassedTests { get; set; }
    public int FailedTests { get; set; }
}

public async Task<TestResult> ParseXMLAndRunTests(string xmlPath, string moduleName, IBlueslip blueslip, List<TestObject> tests, int maxConcurrency)
{
    var semaphore = new SemaphoreSlim(maxConcurrency);
    var totalTests = 0;
    var passedTests = 0;
    var failedTests = 0;

    await Task.Run(() =>
    {
        using (var reader = XmlReader.Create(xmlPath))
        {
            XDocument doc = LoadXmlAsync(reader).Result;
            var testElement = doc.Root.Element("test");
            if (testElement == null)
                throw new Exception($"No matching test element found in the XML file.");

            foreach (var test in tests)
            {
                semaphore.Wait();

                try
                {
                    totalTests++;

                    // Reset blueslip for each test to avoid side effects
                    blueslip.Reset();

                    dynamic assembly = Assembly.LoadFile(AppDomain.CurrentDomain.BaseDirectory + moduleName);
                    Type testType = assembly.GetTypes().FirstOrDefault(t => t.Name == test.testFunction.Method.ReflectedType.Name);
                    if (testType == null)
                        throw new Exception($"Could not find the specified type in the loaded module.");

                    ConstructorInfo constructor = testType.GetConstructors().FirstOrDefault();
                    if (constructor == null)
                        throw new Exception($"No constructors found for the specified type in the loaded module.");

                    var testInstance = constructor.Invoke(Array.Empty<object>());
                    Action<IBlueslip> runTest = RunTestFunction(test, testInstance);

                    // Run the test asynchronously and log its execution
                    Task.Run(() =>
                    {
                        var stopwatch = Stopwatch.StartNew();
                        runTest(blueslip);
                        stopwatch.Stop();

                        blueslip.Log($"Test '{test.name}' started at {DateTime.Now}");
                        blueslip.Log($"Test '{test.name}' completed in {stopwatch.ElapsedMilliseconds}ms");

                        if (testInstance is ITestResult testResult)
                        {
                            if (testResult.Passed)
                                passedTests++;
                            else
                                failedTests++;
                        }
                    });
                }
                catch (Exception ex)
                {
                    blueslip.LogError(ex);
                    failedTests++;
                }
                finally
                {
                    semaphore.Release();
                }
            }
        }
    });

    return new TestResult { TotalTests = totalTests, PassedTests = passedTests, FailedTests = failedTests };

    static Action<IBlueslip> RunTestFunction(TestObject test, object testInstance)
    {
        var methodInfo = typeof(object).GetMethod(test.testFunction.Name);
        if (methodInfo == null)
            throw new Exception($"Could not find the specified test function.");

        if (!methodInfo.IsStatic && !(testInstance is ITestResult))
            throw new Exception("The test instance should implement ITestResult when running non-static tests.");

        return (IBlueslip blueslip) => methodInfo.Invoke(testInstance, new[] { blueslip });
    }

    static async Task<XDocument> LoadXmlAsync(XmlReader reader)
    {
        var builder = new XDocument();
        await foreach (var element in XElement.Load(reader).Descendants())
            builder.Add(element);

        return builder;
    }
}

public class TestObject
{
    public string name { get; set; }
    public Func<IBlueslip, Task> testFunction { get; set; }
}

public interface ITestResult
{
    bool Passed { get; }
}
