<?php

class DAO {
    private $db;
    private $lockTable;
    private $cache;
    private $passwordStrengthService;
    private $logger;
    private $activityTracker;

    public function __construct(PDO $db, LockTable $lockTable, Cache $cache, PasswordStrengthService $passwordStrengthService, Logger $logger, ActivityTracker $activityTracker) {
        $this->db = $db;
        $this->lockTable = $lockTable;
        $this->cache = $cache;
        $this->passwordStrengthService = $passwordStrengthService;
        $this->logger = $logger;
        $this->activityTracker = $activityTracker;
    }

    public function updatePassword($userId, $newPassword) {
        try {
            // Attempt to acquire a lock on the user's record.
            if (!$this->lockTable->acquireLock($userId)) {
                throw new Exception("Failed to acquire lock for user.");
            }

            // Check password strength locally, using caching when available.
            $cachedStrengthCheck = $this->cache->get('password_strength_check_' . $newPassword);
            if (empty($cachedStrengthCheck)) {
                $strengthResult = $this->passwordStrengthService->validate($newPassword);
                $this->cache->save('password_strength_check_' . $newPassword, $strengthResult, 60);
            } else {
                $strengthResult = unserialize($cachedStrengthCheck);
            }

            if (!$strengthResult['valid']) {
                throw new Exception("Invalid password strength.");
            }

            // Attempt to update the user's password in the primary database.
            DB::query('UPDATE users SET password = ? WHERE id = ?', [$newPassword, $userId]);

            // Record the password change in the activity log and release the lock.
            $this->activityTracker->logPasswordChange($userId, $newPassword);
            $this->lockTable->releaseLock($userId);
        } catch (Exception $e) {
            $this->logger->error('Failed to update user password: ' . $e->getMessage());

            // If a race condition occurred or an external service was unavailable, retry the operation.
            if (strpos($e->getMessage(), 'race condition') !== false || strpos($e->getMessage(), 'unavailable') !== false) {
                usleep(rand(100000, 500000)); // Add some random delay to avoid contention.
                $this->updatePassword($userId, $newPassword);
            } else {
                // Otherwise, provide user-friendly feedback and log the error.
                echo 'An error occurred while updating your password. Please try again later.';
                $this->logger->error('User password update failed: ' . $e->getMessage());
            }
        }
    }
}
