struct mem_pool {
    size_t capacity;
    size_t count;
    NFAPI_CRC_INDICATION_PDU_T* data;
    pthread_mutex_t mutex;
};

void* mem_pool_init() {
    struct mem_pool* pool = malloc(sizeof(struct mem_pool));
    if (!pool) return NULL;
    pool->capacity = 0;
    pool->count = 0;
    pool->data = NULL;
    pthread_mutex_init(&pool->mutex, NULL);
    return pool;
}

void mem_pool_deinit(struct mem_pool* pool) {
    if (pool) {
        free(pool->data);
        pthread_mutex_destroy(&pool->mutex);
        free(pool);
    }
}

int mem_pool_push(struct mem_pool* pool, NFAPI_CRC_INDICATION_PDU_T data) {
