        NFAPI_CRC_INDICATION_PDU_T* temp_data = realloc(pool->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!temp_data) {
            pthread_mutex_unlock(&pool->mutex);
            return -1; // Memory allocation failed
        }
        pool->capacity = new_capacity;
        pool->data = temp_data;
    }
    pool->data[pool->count] = data;
    pool->count++;
    pthread_mutex_unlock(&pool->mutex);
    return 0;
}

void mem_pool_pop(struct mem_pool* pool, NFAPI_CRC_INDICATION_PDU_T* data) {
    if (pool->count <= 0) return; // Empty pool
    pthread_mutex_lock(&pool->mutex);
    *data = pool->data[--pool->count];
