    unsigned char concatenated_hashes[num_pdus * SHA256_DIGEST_LENGTH];
    for (size_t i = 0; i < num_pdus; ++i) {
        // Hash the current processor's string identifier
        SHA256_CTX processor_sha_ctx;
        SHA256_Init(&processor_sha_ctx);
        SHA256_Update(&processor_sha_ctx, processors[i]->id, strlen(processors[i]->id));
        unsigned char processor_digest[SHA256_DIGEST_LENGTH];
        SHA256_Final(processor_digest, &processor_sha_ctx);

        // Concatenate the current processor's hash with the previous concatenated hashes
        memcpy(&concatenated_hashes[i * SHA256_DIGEST_LENGTH], processor_digest, SHA256_DIGEST_LENGTH);
        if (i + 1 < num_pdus) {
            memcpy(&concatenated_hashes[(i + 1) * SHA256_DIGEST_LENGTH], concatenated_hashes + i * SHA256_DIGEST_LENGTH, SHA256_DIGEST_LENGTH);
