#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <sys/mman.h>
#include <unistd.h>

typedef struct {
    int key;
    long offset;
    double value;
    char *data;
} record;

struct memory_pool {
    void *base;
    size_t size;
    size_t capacity;
    pthread_mutex_t lock;
};

void *memory_pool_alloc(struct memory_pool *pool, size_t size) {
    if ((char *)pool->base + pool->size < (char *)pool->base + pool->capacity) {
        void *ptr = pool->base + pool->size;
        pool->size += size;
        return ptr;
    } else {
        void *new_block = mmap(NULL, pool->capacity + PAGE_SIZE, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        if (new_block == MAP_FAILED) {
            fprintf(stderr, "Memory allocation failed\n");
            exit(EXIT_FAILURE);
        }

        pool->capacity += PAGE_SIZE;
        return new_block;
    }
}

void *memory_pool_calloc(struct memory_pool *pool, size_t nmemb, size_t size) {
    void *ptr = memory_pool_alloc(pool, nmemb * size);
    memset(ptr, 0, nmemb * size);
    return ptr;
}

struct record_collection {
    struct memory_pool keys;
    struct memory_pool offsets;
    struct memory_pool keys_hash;
    struct memory_pool records;
    size_t num_records;
    size_t record_size;
    pthread_mutex_t lock;
};

void record_collection_init(struct record_collection *rc, size_t num_records, size_t record_size) {
    rc->num_records = 0;
    rc->record_size = record_size;

    pthread_mutex_init(&rc->lock, NULL);
    rc->keys.base = memory_pool_calloc(&rc->keys, num_records, sizeof(int));
    rc->offsets.base = memory_pool_calloc(&rc->offsets, num_records, sizeof(long));
    rc->keys_hash.base = calloc(num_records, sizeof(unsigned long));
    rc->records.base = memory_pool_calloc(&rc->records, num_records * record_size, 1);
}

void record_collection_push(struct record_collection *rc, int key, double value) {
    pthread_mutex_lock(&rc->lock);

    size_t i;
    for (i = 0; i < rc->num_records; ++i) {
        if (rc->keys[i] == key) {
            fprintf(stderr, "Duplicate key encountered\n");
            pthread_mutex_unlock(&rc->lock);
            return;
        }
    }

    memcpy((char *)rc->records.base + rc->num_records * rc->record_size, &key, sizeof(int));
    memcpy((char *)rc->records.base + rc->num_records * rc->record_size + sizeof(int), &((long)malloc(sizeof(value))), sizeof(long));
    memcpy((char *)rc->records.base + rc->num_records * rc->record_size + sizeof(int) + sizeof(long), &value, sizeof(double));

    rc->keys[rc->num_records] = key;
    rc->offsets[rc->num_records] = (long)malloc(sizeof(value));
    memcpy((char *)rc->keys_hash.base + (unsigned long)key, &rc->num_records, sizeof(size_t));

    rc->num_records++;

    pthread_mutex_unlock(&rc->lock);
}

int record_collection_random_get(struct record_collection *rc, unsigned int key) {
    unsigned long hash = key % rc->keys_hash.size;
    size_t i = (char *)rc->keys_hash.base + hash - (char *)&rc->num_records;

    if (*(size_t *)i >= rc->num_records || *(size_t *)(i + 1) != key) {
        for (i++; i < rc->keys_hash.size; i += rc->keys_hash.size) {
            if (*(size_t *)i == key) {
                break;
            }
        }
    }

    if (i >= rc->keys_hash.size || *(size_t *)i >= rc->num_records || *(size_t *)(i + 1) != key) {
        return -1; // not found
    }

    record *r = (record *)((char *)rc->records.base + (*(size_t *)i * rc->record_size));
    free(*(void **)((char *)r + sizeof(int) + sizeof(long)));

    return r->key;
}
