#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>

// Custom memory pool manager for reducing overhead
typedef struct _Pool {
    void *start, *end;
    size_t size;
} Pool;

void* Pool_alloc(Pool *pool, size_t size) {
    if (pool->size <= 0) return NULL;
    void *ptr = pool->start;
    pool->start += size;
    if (pool->start > pool->end) {
        pool->start = pool->end;
        pool->size -= size;
    }
    return ptr;
}

void Pool_free(Pool *pool, void *ptr) {
    if (!ptr || !pool->size) return;
    memmove(ptr, (char*)ptr + sizeof(void*), pool->size - sizeof(void*));
    pool->size += sizeof(void*);
}

// User-defined data structures
typedef struct _NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct _RECORD {
    int value;
} RECORD;

// Function to create and populate a list of NFAPI_CRC_INDICATION_PDU_T structures
void create_data_structures(int n, int m, int p, Pool *mem_pool) {
    if (n <= 0 || m <= 0 || p <= 0 || n*m > 1000000 || n > 10000 || p != 10000) {
        fprintf(stderr, "Invalid input. Expected positive integers with constraints.\n");
        exit(EXIT_FAILURE);
    }

    int *offsets = calloc(n, sizeof(int));
    if (!offsets) {
        perror("Error allocating memory for offsets.");
        exit(EXIT_FAILURE);
    }
    mempool_init(mem_pool, sizeof(int)*m); // Initialize custom memory pool for keys
    int *keys = (int*)mempool_alloc(mem_pool, n*sizeof(int));
    if (!keys) {
        perror("Error allocating memory for keys.");
        exit(EXIT_FAILURE);
    }

    RECORD records[p];
    memset(records, 0, sizeof(RECORD)*p); // Initialize records with zero values

    srand(time(NULL));
    for (int i = 0; i < p; ++i) {
        records[i].value = rand() % 100 + 1; // Set record value between 1 and 100
    }

    NFAPI_CRC_INDICATION_PDU_T *pdus = malloc(p*sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdus) {
        perror("Error allocating memory for PDUs.");
        exit(EXIT_FAILURE);
    }

    // Populate PDUs with random values and set CRCFLAG randomly
    for (int i = 0; i < p; ++i) {
        pdus[i].tag.ueId = keys[offsets[i]];
        pdus[i].rnti.length = rand() % 16 + 8; // Set RNTI length between 8 and 16
        pdus[i].rnti.value = mempool_alloc(mem_pool, pdus[i].rnti.length);
        if (!pdus[i].rnti.value) {
            perror("Error allocating memory for RNTI.");
            exit(EXIT_FAILURE);
        }
        memcpy(pdus[i].rnti.value, "\0", pdus[i].rnti.length); // Initialize RNTI with zero value

        pdus[i].crc_indication.length = sizeof(CRC_INDICATION_REL8_TAG) - 2; // Set CRC length without CRC and flag
        pdus[i].crc_indication.crc = rand() % (1 << (pdus[i].crc_indication.length - 2)); // Set CRC value randomly
        pdus[i].crc_indication.flag = rand() % 2; // Set CRC flag randomly
    }

    // Free memory upon successful completion or error
    free(offsets);
    mempool_free(mem_pool, keys);
    free(pdus);
}

// Function to serialize and deserialize the data structures to/from disk
void serialize_to_disk(const char *filename, const NFAPI_CRC_INDICATION_PDU_T *pdus, int p) {
    FILE *file = fopen(filename, "wb");
    if (!file) {
        perror("Error opening file.");
        return;
    }
    fwrite(pdus, sizeof(NFAPI_CRC_INDICATION_PDU_T), p, file);
    fclose(file);
}

void *deserialize_from_disk(const char *filename) {
    FILE *file = fopen(filename, "rb");
    if (!file) {
        perror("Error opening file.");
        return NULL;
    }
    size_t p = (size_t)fgetc(file);
    p = (p <= 0 || feof(file)) ? 0 : p*sizeof(NFAPI_CRC_INDICATION_PDU_T);
    NFAPI_CRC_INDICATION_PDU_T *pdus = malloc(p);
    if (!pdus) {
        perror("Error allocating memory for PDUs.");
        fclose(file);
        return NULL;
    }
    size_t read = fread(pdus, sizeof(NFAPI_CRC_INDICATION_PDU_T), p/sizeof(NFAPI_CRC_INDICATION_PDU_T), file);
    if (read != p) {
        perror("Error reading from file.");
        free(pdus);
        fclose(file);
        return NULL;
    }
    fclose(file);
    return pdus;
}
