[' ```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <stdbool.h>
#include <sys/mman.h>

typedef struct {
    char name[64];
    int start, end;
} Task;

struct task_list {
    size_t count;
    size_t capacity;
    Task *tasks;
    pthread_mutex_t lock;
};

struct task_list *create_task_list(size_t initial_capacity) {
    struct task_list *list = mmap(NULL, sizeof(*list), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (list == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }
    pthread_mutex_init(&list->lock, NULL);
    list->count = 0;
    list->capacity = initial_capacity;
    list->tasks = calloc(initial_capacity, sizeof(Task));
    if (!list->tasks) {
        perror("calloc");
        munmap(list, sizeof(*list));
        exit(EXIT_FAILURE);
    }
    return list;
}

void destroy_task_list(struct task_list *list) {
    free(list->tasks);
    pthread_mutex_destroy(&list->lock);
    munmap(list, sizeof(*list));
}

void resize_task_list(struct task_list *list) {
    if (list->count == list->capacity) {
        size_t new_capacity = list->capacity ? list->capacity * 2 : INITIAL_CAPACITY;
        Task *new_tasks = realloc(list->tasks, new_capacity * sizeof(Task));
        if (!new_tasks) {
            perror("realloc");
            return;
        }
        list->tasks = new_tasks;
        list->capacity = new_capacity;
    }
}

bool add_task(struct task_list *list, const char *name, int start, int end) {
    pthread_mutex_lock(&list->lock);

    if (list->count == list->capacity) {
        resize_task_list(list);
    }

    for (size_t i = 0; i < list->count; ++i) {
        const int this_start = list->tasks[i].start, this_end = list->tasks[i].end;
        if ((start >= this_start && start < this_end) || (end > this_start && end <= this_end)) {
            // Adjust conflicting task's end time to avoid overlap
            list->tasks[i].end = max(list->tasks[i].end, end);
            printf("Adjusted task %s with new duration [%d, %d]\n", list->tasks[i].name, this_start, list->tasks[i].end);
        }
    }

    snprintf(list->tasks[list->count].name, sizeof(list->tasks[0].name), "%s", name);
    list->tasks[list->count].start = start + rand() % (end - start + 1);
    list->tasks[list->count].end = list->tasks[list->count].start + rand() % ((end - start + 1) * 2) + 1;
    printf("Added task %s with duration [%d, %d]\n", list->tasks[list->count].name, list->tasks[list->count].start, list->tasks[list->count].end);

    ++list->count;

    pthread_mutex_unlock(&list->lock);
    return true;
}

void print_task_details(const struct task_list *list) {
    for (size_t i = 0; i < list->count; ++i) {
        printf("Task %zu: %s, [%d, %d]\n", i, list->tasks[i].name, list->tasks[i].start, list->tasks[i].end);
    }
}
```

