['```c
#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <string.h>

typedef struct Task {
    char name[50];
    int start;
    int end;
} Task;

int compare_tasks(const void *a, const void *b) {
    return (*(Task *)a).start - *(Task *)b)->start;
}

void adjust_end(Task* task, int duration) {
    task->end += duration;
}

void log_tasks(bool print_attempts, Task tasks[], int length) {
    printf("Tasks:\n");
    for (int i = 0; i < length; ++i) {
        if (!print_attempts || tasks[i].start <= tasks[i].end) {
            printf("- Name: %s, Start: %d, End: %d\n", tasks[i].name, tasks[i].start, tasks[i].end);
        }
    }
}

Task* create_tasks(int capacity, int min_start, int max_end, bool print_attempts) {
    Task *tasks = malloc(capacity * sizeof(Task));
    qsort(tasks, 0, capacity, compare_tasks);
    int filled = 0;

    for (int i = 0; i < capacity; ++i) {
        tasks[i].start = min_start + filled++;
        tasks[i].end = max_end;

        for (int j = i - 1; j >= 0 && tasks[j].start < tasks[i].end; --j) {
            if (tasks[j].end > tasks[i].start) {
                adjust_end(&tasks[i], tasks[j].end - tasks[i].start);
                adjust_end(&tasks[j], tasks[j].end + tasks[i].end - tasks[j].start);
            }
        }
    }

    int actual = 0;
    for (int i = 0; i < capacity; ++i) {
        if (tasks[i].start <= tasks[i].end) {
            tasks[actual++] = tasks[i];
        }
    }

    log_tasks(print_attempts, tasks, actual);

    return realloc(tasks, actual * sizeof(Task));
}
```

