typedef struct {
    time_t timestamp;
    int id;
    int type;
} NetworkEvent;

struct NetworkEventsManager {
    size_t capacity;
    size_t count;
    NetworkEvent* events;
};

NetworkEventsManager* newNetworkEventsManager(size_t initialCapacity) {
    NetworkEventsManager* manager = malloc(sizeof(NetworkEventsManager));
    manager->capacity = initialCapacity;
    manager->count = 0;
    manager->events = calloc(initialCapacity, sizeof(NetworkEvent));
    return manager;
}

void addNetworkEvent(NetworkEventsManager* manager, const NetworkEvent* event) {
    if (manager->count >= manager->capacity) {
        manager->capacity *= 2;
        manager->events = realloc(manager->events, manager->capacity * sizeof(NetworkEvent));
    }

    // Handle edge case: duplicate IDs
    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->events[i].id == event->id) {
            fprintf(stderr, "Duplicate ID encountered while adding network event\n");
            return;
        }
    }

    // Handle edge case: invalid timestamps
    if (!time_t_valid(event->timestamp)) {
        fprintf(stderr, "Invalid timestamp encountered while adding network event\n");
        return;
    }

    manager->events[manager->count++] = *event;
}

bool time_t_valid(const time_t t) {
    return (t > 0);
}

void removeNetworkEventById(NetworkEventsManager* manager, int id) {
    size_t index;
    for (index = 0; index < manager->count; ++index) {
        if (manager->events[index].id == id) {
            break;
        }
    }

    // Handle edge case: event not found
    if (index >= manager->count) {
        fprintf(stderr, "Event with ID %d not found\n", id);
        return;
    }

    for (size_t i = index + 1; i < manager->count; ++i) {
        manager->events[i - 1] = manager->events[i];
    }
    --manager->count;
}

void getNetworkEventsInRange(const NetworkEventsManager* manager, time_t startTime, time_t endTime, NetworkEvent events[]) {
    size_t eventsCount = 0;

    for (size_t i = 0; i < manager->count; ++i) {
        if (manager->events[i].timestamp >= startTime && manager->events[i].timestamp <= endTime) {
            events[eventsCount++] = manager->events[i];
        }
    }

    // Shrink the array to the actual number of elements
    events = realloc(events, eventsCount * sizeof(NetworkEvent));
}
