// Function to generate a random number within a specified range
unsigned int random_number(unsigned int min, unsigned int max) {
    static unsigned long seed = 0;
    if (!seed) {
        struct timespec ts;
        clock_gettime(CLOCK_REALTIME, &ts);
        seed = (unsigned long)ts.tv_sec * (unsigned long)ts.tv_nsec + getpid();
    }
    return rand_r(&seed) % (max - min + 1) + min;
}

void init_list(Object*** list, size_t* offsets, size_t* keys, size_t n) {
    *list = malloc(n * sizeof(Object*));
    if (!*list) {
        fprintf(stderr, "Failed to allocate memory for objects\n");
        exit(EXIT_FAILURE);
    }
    *offsets = calloc(n, sizeof(size_t));
    if (!*offsets) {
        fprintf(stderr, "Failed to allocate memory for offsets\n");
        free(*list);
        exit(EXIT_FAILURE);
    }
    *keys = malloc(n * sizeof(size_t));
    if (!*keys) {
        fprintf(stderr, "Failed to allocate memory for keys\n");
        free(*list);
        free(*offsets);
        exit(EXIT_FAILURE);
    }
}

void free_list(Object** list, size_t offsets[], size_t keys[], size_t n) {
    for (size_t i = 0; i < n; ++i) {
        Object* obj = list[keys[i]];
        if (obj) {
            free(obj->str);
            free(obj);
        }
    }
    free(list);
    free(offsets);
    free(keys);
}

