        ht_slot = malloc(sizeof(struct resource_bundle));
        memset(ht_slot, 0, sizeof(struct resource_bundle));
        hash_table_put(ht, hash, ht_slot);
    }
    struct resource_bundle *rb = ht_slot;

    rb->num_items = num_items;
    json_object_get(items, "items", &rb->items); // Transfer ownership of 'items' to 'rb'

    return num_items;
}

