struct cmd_data {
    char *cmd;
    char **envp;
    rlim_t rlim;
    struct rusage usage;
};

pid_t exec_command(struct cmd_data *data) {
    pid_t pid = fork();

    if (pid == 0) { // child process
        setrlimit(RLIMIT_DATA, &{data->rlim});
        setenvp(data->envp);
        execvp(data->cmd, data->cmd);
        perror("execvp failed");
        exit(EXIT_FAILURE);
    } else if (pid > 0) { // parent process
        return pid;
    } else { // fork failure
        perror("fork failed");
        return -1;
    }
}

void cleanup_child(pid_t pid) {
    int status;
    waitpid(pid, &status, WNOHANG);

    if (WIFEXITED(status)) {
        // handle exit status here
    } else if (WIFSIGNALED(status)) {
        // handle signal here
    } else {
        perror("waitpid failed");
    }
}

int run_commands(char **commands, char **envp, rlim_t rlim, size_t ncmds) {
    int num_active = 0;
    struct cmd_data *cmd_list = malloc(ncmds * sizeof(struct cmd_data));
    pid_t *pids = malloc(ncmds * sizeof(pid_t));

    for (size_t i = 0; i < ncmds; ++i) {
        struct cmd_data *data = &cmd_list[i];
        data->cmd = commands[i];
        data->envp = envp;
        data->rlim = rlim;
    }

    for (size_t i = 0; i < ncmds; ++i) {
        pid_t pid = exec_command(&cmd_list[i]);

        if (pid > 0) {
            pids[num_active++] = pid;
        } else if (pid == -1) {
            free(cmd_list);
            free(pids);
            return -1;
        }
    }

    // Dynamically adjust the number of concurrent processes based on system load
    // This requires a mechanism for monitoring system load, which is not provided here

    for (int i = 0; i < num_active; ++i) {
        cleanup_child(pids[i]);
    }

    free(cmd_list);
    free(pids);

    if (num_active == 0) return 1; // all commands are successfully started

    return 0; // at least one command failed
}
```

This code defines a function `run_commands()` that takes an array of commands, an environment variable array, resource limit, and number of commands as arguments. It uses fork and execvp system calls to execute each command in its own isolated environment and resource space. The function returns 1 if all commands are successfully started, 0 if any command fails, or -1 if the resource limit is exceeded.

The cleanup_child function is used to handle child processes when they terminate. This implementation does not dynamically adjust the number of concurrent processes based on system load, as that would require a mechanism for monitoring system load which was not specified in the problem statement. To add this functionality, you would need to integrate a system load monitoring library or API.

