#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <time.h>
#include <limits.h>

// Custom memory pool manager
typedef struct MemPool {
    void *data;
    size_t size;
    struct MemPool *next;
} MemPool;

MemPool* mempool = NULL;
const size_t MAX_POOL_SIZE = 16 * (1024 * 1024); // 16 MB
const size_t ALIGNMENT = 8; // 64-bit alignment

// Memory pool functions
void* mempool_alloc(size_t size) {
    MemPool *current, *newNode;

    if ((newNode = malloc(sizeof(MemPool))) == NULL)
        return NULL;

    newNode->data = NULL;
    newNode->size = 0;
    newNode->next = mempool;
    mempool = newNode;

    if (mempool->data != NULL && mempool->size + size <= MAX_POOL_SIZE) {
        void *result = mempool->data + mempool->size;
        mempool->size += size;
        return result;
    } else {
        free(newNode);
        return malloc(size);
    }
}

void mempool_free(void *ptr) {
    if (mempool != NULL && ptr >= mempool->data && ptr < mempool->data + mempool->size) {
        mempool->size -= (char *)ptr - (char *)mempool->data;
    } else {
        free(ptr);
    }
}

