void serialize(const DATA_ROOT_T** data_roots, const char* filename) {
    FILE* file = fopen(filename, "wb");

    if (!file) return; // Error handling

    for (int i = 0; i < 10000; ++i) {
        fwrite(data_roots[i]->data, sizeof(DATA_RECORD_T), 1, file);
    }

    fclose(file);
}

DATA_ROOT_T** deserialize(const char* filename) {
    FILE* file = fopen(filename, "rb");

    if (!file) return NULL; // Error handling

    DATA_ROOT_T** data_roots = calloc(10000, sizeof(DATA_ROOT_T));

    for (int i = 0; i < 10000; ++i) {
        data_roots[i] = malloc(sizeof(RECORD_T) + sizeof(MEMORY_MAP_T));
        fread(data_roots[i]->data, sizeof(DATA_RECORD_T), 1, file);
    }

    return data_roots;
}
