    struct entry* new_entry = malloc(sizeof(entry));
    new_entry->string = strdup(string);
    new_entry->priority = priority;
    new_entry->time_created = time(NULL);
    sem_wait(&cache_mutex);
    if (cache_count < cache_capacity) {
        cache[cache_count++] = new_entry;
    } else {
        free(new_entry);
    }
    sem_post(&cache_mutex);

    if (list->head == NULL) {
        list->head = new_entry;
        list->tail = new_entry;
    } else {
        list->tail->next = new_entry;
        list->tail = new_entry;
    }
    ++(list->size);
}

