void* mempool_alloc(struct MemoryPool* pool, size_t size) {
    if (pool->free_size >= size) {
        void* ptr = pool->memory + pool->free_size;
        pool->free_size -= size;
        return ptr;
    } else {
        void* ptr = realloc(pool->memory, pool->allocated_size * 2);
        if (!ptr) {
            // Handle memory allocation error
