    if (!*pdu) {
        fprintf(stderr, "Error: Failed to allocate memory for PDUs\n");
        exit(EXIT_FAILURE);
    }

    pthread_mutexattr_t attr;
    pthread_mutexattr_init(&attr);
    pthread_mutexattr_settype(&attr, PTHREAD_MUTEX_RECURSIVE_NP);

    for (size_t i = 0; i < num_pdus; ++i) {
        (*pdu)[i].RX_UE_INFORMATION_TAG = (uint32_t)(i + 1);
        (*pdu)[i].RNTI = i * 1000; // Example RNTI assignment logic
        char tag[max_tag_len];
