NFAPI_CRC_INDICATION_PDU_T* get_available_pdu(NFAPI_CRC_INDICATION_PDU_T** pdus, size_t num_pdus) {
    for (size_t i = 0; i < num_pdus; ++i) {
        pthread_mutex_lock(&pdus[i]->mutex);
        if (!pdus[i]->CRC_INDICATION_REL8_TAG || !strchr(pdus[i]->CRC_INDICATION_REL8_TAG, ',')) { // Available PDU
            pdus[i]->CRC_INDICATION_REL8_TAG = strdup(","); // Mark it as used temporarily
            pthread_mutex_unlock(&pdus[i]->mutex);
            return pdus[i];
        }
        pthread_mutex_unlock(&pdus[i]->mutex);
    }

    // If no available PDU found, allocate a new one
    NFAPI_CRC_INDICATION_PDU_T* new_pdu = calloc(1, sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!new_pdu) {
        fprintf(stderr, "Error: Failed to allocate memory for a new PDU\n");
        exit(EXIT_FAILURE);
