#define MAX_FILES 64
#define BUFFER_SIZE 1024 * 16
#define LOG_FILE "log.txt"

typedef struct file_info {
    char *filename;
    int fd;
    size_t lines;
} file_info;

file_info files[MAX_FILES];
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
int num_files = 0;

void log_error(const char *msg) {
    FILE *log_fp = fopen(LOG_FILE, "a");
    if (log_fp) {
        fprintf(log_fp, "%s: %s\n", __TIME__, msg);
        fclose(log_fp);
    }
}

void *count_lines(void *arg) {
    file_info *file = arg;
    char buffer[BUFFER_SIZE];
    ssize_t read;
    size_t lines = 0;

    while ((read = read(file->fd, buffer, sizeof(buffer))) > 0) {
        for (ssize_t i = 0; i < read; ++i) {
            if (buffer[i] == '\n')
                ++lines;
        }
        file->lines += lines;
        memset(buffer, 0, sizeof(buffer));
        lines = 0;
    }

    if (read == -1 && errno != EINTR) {
        log_error("Error reading file");
    }

    return NULL;
}

void parse_args(int argc, char *argv[]) {
    int opt = 0;
    char *output_file = NULL;

    while ((opt = getopt(argc, argv, "h?mman:o:")) != -1) {
        switch (opt) {
            case 'n':
                // no action needed for --no-manpage
                break;
            case 'm':
                printf("Usage:\n %s [--manpage] [-cs | -o output_file] file1 [file2 ...]\n", argv[0]);
                exit(EXIT_SUCCESS);
            case 'a':
                // no action needed for --manpage
                break;
            case 'o':
                output_file = optarg;
                break;
            case '?':
                if (optopt == 'n' || optopt == 'm') {
                    printf("Try '%s --help' for more information.\n", argv[0]);
                    exit(EXIT_FAILURE);
                }
                /* if the character is optional, this code block will not be executed */
                fprintf(stderr, "Unknown option '-%c'.\n", optopt);
                exit(EXIT_FAILURE);
            default:
                abort();
        }
    }

    if (output_file) {
        freopen(output_file, "w", stdout);
    }
}

int main(int argc, char *argv[]) {
    parse_args(argc, argv);

    for (int i = optind; i < argc; ++i) {
        file_info *new_file = &files[num_files];
        new_file->filename = argv[i];
        new_file->fd = open(argv[i], O_RDONLY);
        if (new_file->fd == -1) {
            log_error("Error opening file");
            return EXIT_FAILURE;
        }

        pthread_t thread;
        int ret = pthread_create(&thread, NULL, count_lines, new_file);
        if (ret != 0) {
            perror("pthread_create");
            exit(EXIT_FAILURE);
        }

        ++num_files;
    }

    // Wait for all threads to finish and calculate the cumulative line count
    pthread_t *threads = malloc(num_files * sizeof(pthread_t));
    for (int i = 0; i < num_files; ++i) {
        pthread_join(threads[i], NULL);
    }

    size_t total_lines = 0;
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < num_files; ++i) {
        total_lines += files[i].lines;
    }
    pthread_mutex_unlock(&mutex);

    printf("Total lines: %zu\n", total_lines);

    return EXIT_SUCCESS;
}
