unsigned int generate_unique_id(unsigned long seed, unsigned int max) {
    unsigned long hash = seed;
    for (int i = 0; i < max * 2; ++i)
        hash = hash * 16777619UL + 1;
    return (unsigned int)(hash % max);
}

// Function to validate IP address and set default value if invalid
void validate_ip_address(const char* ip, sockaddr_in* addr) {
    memset(addr, 0, sizeof(*addr));

    struct in_addr in;
    if (inet_pton(AF_INET, ip, &in) <= 0)
        *addr = (sockaddr_in){ .sin_addr.s_addr = INADDR_LOOPBACK };
