};

// Mutex for thread safety
pthread_mutex_t record_array_mutex = PTHREAD_MUTEX_INITIALIZER;
struct Record* record_array; // Dynamic array of Records
size_t capacity;             // Current capacity
size_t size;                 // Current number of elements

void init_record_array(size_t max_records, int min_key, int max_key) {
    pthread_mutex_lock(&record_array_mutex);
    if (!(record_array = realloc(record_array, sizeof(struct Record) * max_records))) {
        fprintf(stderr, "Memory allocation failed\n");
        pthread_mutex_unlock(&record_array_mutex);
        exit(EXIT_FAILURE);
    }
    capacity = max_records;
    size = 0;

    // Initialize offset fields with sequential numbers starting from 0
    for (size_t i = 0; i < capacity; ++i) {
        record_array[i].offset = i;
    }

    pthread_mutex_unlock(&record_array_mutex);

    // Initialize key fields with random integers within the specified range
    srand(time(NULL));
    for (size_t i = 0; i < size; ++i) {
        record_array[i].key = rand() % (max_key - min_key + 1) + min_key;
    }
}
```

2. Add, update and delete functions:

```c
// Find the index of a record with the given key
size_t find(int key) {
    pthread_mutex_lock(&record_array_mutex);
    for (size_t i = 0; i < size; ++i) {
        if (record_array[i].key == key) {
            pthread_mutex_unlock(&record_array_mutex);
            return i;
        }
    }
    pthread_mutex_unlock(&record_array_mutex);
    return -1; // Key not found
}

// Add a new record with the given key and offset
void add(int key, long offset) {
    size_t index = find(key);

    if (index != -1) {
        // Update the offset if the key already exists
        pthread_mutex_lock(&record_array_mutex);
        record_array[index].offset = offset;
        pthread_mutex_unlock(&record_array_mutex);
    } else {
        // Add a new record if the key does not exist yet
        if (size == capacity) {
            void* old_array = record_array;
            capacity *= 2;
            record_array = realloc(old_array, sizeof(struct Record) * capacity);
        }

        pthread_mutex_lock(&record_array_mutex);
        record_array[size].key = key;
        record_array[size].offset = offset;
        size++;
        pthread_mutex_unlock(&record_array_mutex);
    }
}

// Delete a record with the given key (move the last element to replace the deleted one)
void delete(int key) {
    size_t index = find(key);

    if (index != -1) {
        pthread_mutex_lock(&record_array_mutex);
        // Move the last element to replace the deleted one
        record_array[index] = record_array[--size];
        pthread_mutex_unlock(&record_array_mutex);
    }
}
