[' Here is a C++ implementation using a hash table (unordered_map) for efficient lookup and a dynamic array to manage memory efficiently with minimal fragmentation. The function is designed to be thread-safe using mutual exclusion locks and supports different types of values, including integers, floating-point numbers, booleans, and strings.

```cpp
#include <iostream>
#include <unordered_map>
#include <vector>
#include <pthread.h>
#include <cstring>
#include <stdexcept>

struct ConfigSetting {
    std::string key;
    union Value {
        int i;
        double d;
        bool b;
        char* str;
    } value;
};

class Configuration {
private:
    std::vector<ConfigSetting> settings_;
    unsigned int max_settings_;
    std::unordered_map<std::string, size_t> setting_indices_;
    pthread_mutex_t lock_;

public:
    Configuration(unsigned int max_settings) : max_settings_(max_settings), lock_() {
        settings_.reserve(max_settings);
        for (size_t i = 0; i < max_settings_; ++i)
            settings_[i].value.str = nullptr;
    }

    ConfigSetting& add_or_update(const std::string& key, const char* value, int type) {
        pthread_mutex_lock(&lock_);
        size_t index = setting_indices_.find(key) != setting_indices_.end() ?
            setting_indices_[key] : settings_.size();
        if (index >= max_settings_) throw std::runtime_error("Too many configuration settings");

        ConfigSetting& setting = settings_[index];
        setting.key = key;
        switch (type) {
            case 0: // integer
                setting.value.i = atoi(value);
                break;
            case 1: // floating-point number
                setting.value.d = atof(value);
                break;
            case 2: // boolean
                setting.value.b = strcmp(value, "true") == 0;
                break;
            case 3: // string
                setting.value.str = new char[strlen(value) + 1];
                strcpy(setting.value.str, value);
                break;
        }
        setting_indices_[key] = index;
        pthread_mutex_unlock(&lock_);
        return setting;
    }

    const ConfigSetting* find(const std::string& key) const {
        auto it = setting_indices_.find(key);
        if (it == setting_indices_.end())
            return nullptr;
        pthread_mutex_lock(&lock_);
        size_t index = it->second;
        pthread_mutex_unlock(&lock_);
        return &settings_[index];
    }

    ~Configuration() {
        for (auto& setting : settings_)
            delete [] setting.value.str;
    }
};
