typedef struct {
    int value;
    char password[256]; // Adjust the size as needed
} record;

int random_in_range(int min, int max) {
    return rand() % (max - min + 1) + min;
}

char* generate_complex_password(size_t length) {
    char *password = malloc(length);
    if (!password) return NULL;

    for (size_t i = 0; i < length; ++i) {
        password[i] = random() % 36 + 48; // 0-9 A-Z a-z and special characters !"#$%&'()*+,-./:;<=>?@[\]^_`{|}~
        if (i < length - 1 && (password[i] >= 'a' && password[i] <= 'z')) {
            password[i + 1] = random() % 26 + 'A'; // Ensure uppercase letter follows lowercase one
        }
    }
    return password;
}

void hash_password(const char* password, int algorithm, char *hashed_password, size_t hashed_password_size) {
    if (algorithm == SHA256) {
        SHA256_CTX ctx;
        SHA256_Init(&ctx);
        SHA256_Update(&ctx, password, strlen(password));
        SHA256_Final((unsigned char *)hashed_password, &ctx);
    } else if (algorithm == BCrypt) {
        size_t bcrypt_salt_size;
        char salt[BCRYPT_MAX_SALT_SIZE];
        char *hashed_password_with_salt = malloc(BCRYPT_MAX_STRENGTH + BCRYPT_MAX_SALT_SIZE);
        bcrypt((const char *)password, salt, hashed_password_with_salt, sizeof(hashed_password_with_salt), NULL, 0);
        strncpy(hashed_password, hashed_password_with_salt, hashed_password_size);
    }
}

record* create_record_array(size_t size) {
    record *records = malloc(sizeof(record) * size);
    if (!records) return NULL;

    for (size_t i = 0; i < size; ++i) {
        records[i].value = random_in_range(MIN_INT, MAX_INT);
        memset(records[i].password, 0, sizeof(records[i].password)); // Clear the password field on initialization
    }
    return records;
}

void set_password(record *record, const char* password) {
    strncpy(record->password, password, sizeof(record->password));
}

char* get_hashed_password(const record *record, int algorithm) {
    char hashed_password[BCRYPT_MAX_STRENGTH];
    hash_password(record->password, algorithm, hashed_password, sizeof(hashed_password));
    return hashed_password;
}

