typedef struct Record {
    int value;
} Record;

Record* init_records(size_t num_records, long min_offset, long max_offset, bool load_data, const char *filename) {
    size_t key_size = num_records + 1, offset_size = num_records + 1;
    long *offsets = malloc(sizeof(long) * offset_size);
    int *keys = malloc(sizeof(int) * num_records);
    Record *records = malloc(sizeof(Record) * num_records);

    if (!offsets || !keys || !records) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }

    srand(time(NULL));

    for (size_t i = 0; i < num_records; ++i) {
        keys[i] = rand() % (max_offset - min_offset + 1) + min_offset;
        records[i].value = rand() % INT_MAX;

        offsets[i + 1] = offsets[i] + 1;
    }

    offset_size--;
    if (load_data && filename) {
        FILE *file = fopen(filename, "r");
        if (!file) {
            fprintf(stderr, "Error: Unable to open file '%s'.\n", filename);
            return records;
        }

        size_t record_count = 0;
        long cur_offset;
        int cur_key;

        while (fscanf(file, "%ld,%d\n", &cur_offset, &cur_key) == 2) {
            if (record_count >= num_records) break;
            if (cur_offset < offsets[0] || cur_offset > offsets[offset_size]) continue;

            for (size_t i = 1; i <= offset_size; ++i) {
                if (cur_offset == offsets[i]) {
                    records[record_count].value = cur_key;
                    keys[record_count] = cur_key;
                    offsets[i + 1]++;
                    record_count++;
                    break;
                }
            }
        }

        if (ferror(file)) {
            fprintf(stderr, "Error: Error reading file '%s'.\n", filename);
        }

        fclose(file);
    }

    return records;
}
