void initialize_records(int num_records, int min, int max, int load_data, int max_csv_lines) {
    MemoryBlock* memory_pool = NULL;
    size_t total_allocated = 0;
    Record* records = NULL;
    FILE* csv_file = NULL;

    // Allocate dynamic arrays
    if (num_records > MAX_RECORDS || (MAX_RECORDS * sizeof(MemoryBlock) + MAX_RECORDS * sizeof(Record)) / (1024 * 1024) > 8) {
        fprintf(stderr, "Error: The requested number of records exceeds the maximum allowed.\n");
        return;
    }

    memory_pool = mem_alloc((MAX_RECORDS + 1) * sizeof(MemoryBlock));
    records = (Record*)mem_alloc(MAX_RECORDS * sizeof(Record));
    total_allocated += memory_pool->size + records->size;

    // Allocate and initialize long offsets array
    MemoryBlock* offsets_block = memory_pool;
    offsets_block->next = mem_alloc((MAX_RECORDS + 1) * sizeof(MemoryBlock));
    offsets_block = offsets_block->next;
    offsets_block->size = (MAX_RECORDS + 1) * sizeof(long);
    offsets_block->next = NULL;

    // Allocate and initialize int keys array
    MemoryBlock* keys_block = memory_pool;
    keys_block->next = mem_alloc((MAX_RECORDS + 1) * sizeof(MemoryBlock));
    keys_block = keys_block->next;
    keys_block->size = (MAX_RECORDS + 1) * sizeof(int);
    keys_block->next = NULL;

    // Initialize records with random values
    srand((unsigned int)time(NULL));
    for (int i = 0; i < num_records; ++i) {
        records[i].offset = *(long*)(offsets_block->start + i);
        records[i].key = rand() % (max - min + 1) + min;
    }

    if (load_data && (csv_file = fopen("data.csv", "r")) != NULL) {
        char line[MAX_CSV_LINES][MAX_RECORDS * 20]; // Assuming each CSV record has at most 20 digits for long offsets and int keys
        size_t lines_read = 0;
        while (lines_read < max_csv_lines && fgets(line[lines_read], sizeof(line[lines_read]), csv_file) != NULL) {
            char* token = strtok(line[lines_read], ",");
            if (!token || sscanf(token, "%ld,%d", &records[lines_read].offset, &records[lines_read].key) != 2) {
                fprintf(stderr, "Error: Invalid CSV format.\n");
                fclose(csv_file);
                break;
            }
            ++lines_read;
        }
        if (lines_read > 0) {
            memcpy((Record*)offsets_block->start, records, lines_read * sizeof(Record));
            total_allocated -= offsets_block->size + records->size;
        }
        fclose(csv_file);
    }

    // Logging and cleanup
    printf("Initialized %d records with random values. Loaded data from external source: %s\n", num_records, load_data ? "true" : "false");
    if (load_data && lines_read > 0) {
        printf("Loaded %d records from CSV file.\n", lines_read);
    }
    mem_free(memory_pool);
    mem_free(records);
}
