#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>
#include <string.h>
#include <limits.h>

typedef struct Record {
    double value;
    int key;
    long offset;
    char* string_ptr;
    short identifier;
} Record;

typedef void (*RecordCallback)(Record*);

struct MemoryPool {
    size_t total_allocated = 0;
    size_t total_freed = 0;
    size_t peak_memory = 0;
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    RecordCallback callback;
    void* log_handler = nullptr;
    void* mem_monitor = nullptr;
};

struct MemoryPool* memory_pool_init(RecordCallback cb, void* log_h, void* mem_m) {
    struct MemoryPool* pool = malloc(sizeof(struct MemoryPool));
    if (!pool) {
        fprintf(stderr, "Failed to allocate memory for the memory pool\n");
        return nullptr;
    }

    pool->callback = cb;
    pool->log_handler = log_h;
    pool->mem_monitor = mem_m;

    return pool;
}

Record* memory_pool_alloc(struct MemoryPool* pool) {
    pthread_mutex_lock(&pool->mutex);
    Record* record = nullptr;
    if (pool->peak_memory < pool->total_allocated + sizeof(Record))
        pool->peak_memory = pool->total_allocated + sizeof(Record);

    if (!pool->total_freed) {
        void* memory = malloc(pool->total_allocated + sizeof(Record));
        if (memory) {
            record = (Record*)memory;
            memset(record, 0, sizeof(Record));
            pool->total_allocated += sizeof(Record);
            if (pool->log_handler)
                ((void (*)(const char*))pool->log_handler)("Allocated memory for record");
        } else {
            fprintf(stderr, "Failed to allocate memory for a new record\n");
            pthread_mutex_unlock(&pool->mutex);
            return nullptr;
        }
    } else {
        Record* freed = (Record*)pool->total_freed;
        pool->total_freed -= sizeof(Record);
        record = freed;
        if (pool->log_handler)
            ((void (*)(const char*))pool->log_handler)("Reused memory for a record");
    }

    // Initialize record fields with random values within specified ranges
    record->value = (double)rand() / RAND_MAX * 100;
    record->key = rand() % INT_MAX;
    record->offset = rand() % LONG_MAX;
    record->identifier = (short)rand() % SHRT_MAX;

    // Allocate and set string pointers to pre-allocated string literals with unique identifiers
    size_t len = 10 + record->identifier;
    record->string_ptr = malloc(len);
    if (record->string_ptr) {
        sprintf(record->string_ptr, "String %ld", record->identifier);
        if (pool->mem_monitor)
            ((void (*)(const void*, const char*, size_t))pool->mem_monitor)(record->string_ptr, len, MEM_ALLOC);
    } else {
        fprintf(stderr, "Failed to allocate memory for record string pointer\n");
        free(record);
        pthread_mutex_unlock(&pool->mutex);
        return nullptr;
    }

    if (pool->callback)
        pool->callback(record);

    pthread_mutex_unlock(&pool->mutex);
    return record;
}

void memory_pool_dealloc(struct MemoryPool* pool, Record* record) {
    pthread_mutex_lock(&pool->mutex);
    if (pool->mem_monitor)
        ((void (*)(const void*, const char*, size_t))pool->mem_monitor)(record->string_ptr, strlen(record->string_ptr), MEM_FREE);
    free(record->string_ptr);

    pool->total_allocated -= sizeof(Record);
    pool->total_freed += sizeof(Record);
    if (pool->log_handler)
        ((void (*)(const char*))pool->log_handler)("Deallocated memory for record");
    pthread_mutex_unlock(&pool->mutex);
}

