// Cleanup function that adheres to specific API contract
void cleanup(void** offsets, void** keys, void** records) {
    if (offsets) free(*offsets);
    if (keys) free(*keys);
    if (records) free(*records);
}

int* allocate_offsets(size_t size) {
    int* offsets = malloc(sizeof(int) * size);
    if (!offsets) {
        perror("Error allocating offsets");
        exit(1);
    }
    return offsets;
}

int* allocate_keys(size_t size) {
    int* keys = malloc(sizeof(int) * size);
    if (!keys) {
        perror("Error allocating keys");
        exit(1);
    }
    return keys;
}

record* allocate_records(size_t size) {
    record* records = malloc(sizeof(record) * size);
    if (!records) {
        perror("Error allocating records");
        exit(1);
    }
    return records;
}

void initialize(size_t offsets_size, size_t keys_size, size_t records_size, void** offsets, void** keys, void** records) {
    LOG("Allocating memory blocks:", offsets_size, "bytes for offsets", keys_size, "bytes for keys", records_size * sizeof(record), "bytes for records");

    *offsets = allocate_offsets(offsets_size);
    *keys = allocate_keys(keys_size);
    *records = allocate_records(records_size);

    srand(time(NULL));

    int* curr_key = *keys;
    bool value_used[INT_MAX] = {false};

    for (size_t i = 0; i < records_size; ++i) {
        int random_value;
        do {
            random_value = rand() % INT_MAX;
        } while (curr_key[random_value] || value_used[random_value]);

        value_used[random_value] = true;
        curr_key[random_value] = i;
        (*records + i)->value = random_value;
    }

    for (size_t i = 0; i < INT_MAX; ++i) {
        if (value_used[i]) continue;

        int j = rand() % records_size;
        (*records + j)->value = i;
        value_used[i] = true;
    }
}
