void processAndFindMax(bool verbose, size_t* offsets, size_t* keys, struct record** records, size_t maxRecords) {
    // Allocate memory for arrays and struct pointers
    *offsets = malloc(MAX_OFFSETS * sizeof(size_t));
    if (!offsets) {
        fprintf(stderr, "Failed to allocate memory for offsets.\n");
        exit(EXIT_FAILURE);
    }

    *keys = malloc(MAX_KEYS * sizeof(int));
    if (!keys) {
        fprintf(stderr, "Failed to allocate memory for keys.\n");
        free(*offsets);
        exit(EXIT_FAILURE);
    }

    *records = malloc(maxRecords * sizeof(struct record));
    if (!*records) {
        fprintf(stderr, "Failed to allocate memory for records.\n");
        free(*keys);
        free(*offsets);
        exit(EXIT_FAILURE);
    }

    // Initialize arrays and struct pointers with random values
    int max = verbose ? 100 : 50;
    srand((unsigned)time(NULL));
    for (size_t i = 0; i < maxRecords; ++i) {
        bool foundDuplicate = true;
        while (foundDuplicate) {
            (*records + i)->value = rand() % max;
            foundDuplicate = false;
            for (size_t j = 0; j < i; ++j) {
                if ((*records + i)->value == (*records + j)->value) {
                    foundDuplicate = true;
                    break;
                }
            }
        }
        (*keys)[i] = i;
        (*offsets)[i] = rand() % (MAX_OFFSETS - i);

        if (verbose) {
            printf("Record[%lu]: Value=%d, Key=%d, Offset=%ld\n", i, (*records + i)->value, i, *((*offsets + i)));
        }
    }
}

void cleanup(size_t* offsets, int* keys, struct record** records) {
    free(*offsets);
    free(*keys);
    free(*records);
}

void readAndFindMax(bool verbose) {
    int n;
    printf("Enter the number of integers: ");
    scanf("%d", &n);

    int* numbers = malloc(n * sizeof(int));
    if (!numbers) {
        fprintf(stderr, "Failed to allocate memory for numbers.\n");
        exit(EXIT_FAILURE);
    }

    printf("Enter %d integers:\n", n);
    for (size_t i = 0; i < n; ++i) {
        scanf("%d", numbers + i);
    }

    int max = *std::max_element(numbers, numbers + n);
    if (verbose) {
        printf("Maximum number: %d\n", max);
    }

    free(numbers);
}
