#include <stdio.h>
#include <stdlib.h>
#include <time.h>

// Function prototype for generating random number within a specified range
unsigned int rand_range(unsigned int min, unsigned int max);

typedef struct {
    double value;
    int timestamp;
} data_point;

typedef struct node {
    data_point dp;
    struct node *next;
} node;

node* initialize_linked_list() {
    node* head = malloc(sizeof(node));
    if (!head) {
        fprintf(stderr, "Error: Failed to allocate memory for linked list.\n");
        return NULL;
    }

    head->next = NULL;
    return head;
}

void add_data_point(node** head, data_point dp) {
    node* new_node = malloc(sizeof(node));
    if (!new_node) {
        fprintf(stderr, "Error: Failed to allocate memory for new node.\n");
        return;
    }

    new_node->dp = dp;
    new_node->next = *head->next;
    *head->next = new_node;
}

data_point get_random_data_point(unsigned int min_value, unsigned int max_value) {
    double value = (double)rand_range(min_value, max_value);
    int timestamp = time(NULL);
    return (data_point){value, timestamp};
}

unsigned int rand_range(unsigned int min, unsigned int max) {
    // Seed the random number generator with current time to minimize predictability and performance impact
    srand((unsigned int)time(NULL));
    return (unsigned int)((double)rand() / RAND_MAX * (max - min + 1) + min);
}

void log_operation(const char* operation, data_point dp) {
    printf("%s performed at timestamp %d with value %.2f\n", operation, dp.timestamp, dp.value);
}

void free_linked_list(node** head) {
    node* temp;
    while (*head != NULL) {
        temp = *head;
        *head = (*head)->next;
        free(temp);
    }
}
