typedef struct sensor_reading {
    float value;
    int timestamp;
    enum sensor_type {TEMPERATURE, HUMIDITY, PRESSURE} sensor_type;
} sensor_reading;

typedef struct sensor_device {
    sensor_reading* readings;
    int id;
    char* name;
    struct sensor_device* children;
    struct sensor_device* parent;
    int num_children;
} sensor_device;

sensor_device* root = NULL;

void init_tree(int num_devices, int num_readings) {
    root = (sensor_device*) malloc(sizeof(sensor_device));
    root->id = 0;
    root->name = strdup("Root");
    root->children = NULL;
    root->parent = NULL;
    root->num_children = 0;

    root->readings = (sensor_reading*) malloc(num_readings * sizeof(sensor_reading));

    for (int i = 0; i < num_readings; ++i) {
        root->readings[i].value = rand() / (float) RAND_MAX * 100.0f;
        root->readings[i].timestamp = time(NULL);
        root->readings[i].sensor_type = TEMPERATURE; // Assuming all readings are temperature for simplicity
    }

    for (int i = 1; i < num_devices; ++i) {
        sensor_device* device = (sensor_device*) malloc(sizeof(sensor_device));
        device->id = i;
        device->name = strdup("Device");
        device->children = NULL;
        device->parent = root;
        device->num_children = 0;

        device->readings = (sensor_reading*) malloc(num_readings * sizeof(sensor_reading));

        for (int j = 0; j < num_readings; ++j) {
            device->readings[j].value = rand() / (float) RAND_MAX * 100.0f;
            device->readings[j].timestamp = time(NULL);
            device->readings[j].sensor_type = TEMPERATURE; // Assuming all readings are temperature for simplicity
        }

        root->children = realloc(root->children, (root->num_children + 1) * sizeof(sensor_device*));
        root->children[root->num_children] = device;
        root->num_children++;
    }
}

void free_tree(sensor_device* node) {
    for (int i = 0; i < node->num_children; ++i)
        free_tree(node->children[i]);

    free(node->name);
    free(node->readings);
    free(node);
}

void serialize(sensor_device* node, FILE* file) {
    fwrite(&node->id, sizeof(int), 1, file);
    fwrite(node->name, strlen(node->name) + 1, 1, file);
    fwrite(&node->num_children, sizeof(int), 1, file);

    for (int i = 0; i < node->num_children; ++i) {
        fwrite(&node->children[i]->id, sizeof(int), 1, file);
        serialize(node->children[i], file);
    }

    for (int i = 0; i < node->num_readings; ++i) {
        fwrite(&node->readings[i].value, sizeof(float), 1, file);
        fwrite(&node->readings[i].timestamp, sizeof(int), 1, file);
        fwrite(&node->readings[i].sensor_type, sizeof(enum sensor_type), 1, file);
    }
}

void deserialize(sensor_device* node, FILE* file) {
    fread(&node->id, sizeof(int), 1, file);
    fread(node->name, strlen(node->name) + 1, 1, file);
    fread(&node->num_children, sizeof(int), 1, file);

    node->readings = (sensor_reading*) malloc(node->num_children * sizeof(sensor_reading));

    for (int i = 0; i < node->num_children; ++i) {
        sensor_device* child = (sensor_device*) malloc(sizeof(sensor_device));
        deserialize(child, file);
        node->children = realloc(node->children, (node->num_children + 1) * sizeof(sensor_device*));
        node->children[node->num_children] = child;
        node->num_children++;
    }

    for (int i = 0; i < node->num_readings; ++i) {
        fread(&node->readings[i].value, sizeof(float), 1, file);
        fread(&node->readings[i].timestamp, sizeof(int), 1, file);
        fread(&node->readings[i].sensor_type, sizeof(enum sensor_type), 1, file);
    }
}
