    printf("%s\n", msg);
}

int initialize_memory(size_t num_offsets, size_t num_keys, size_t num_records, size_t *offsets, int *keys, Record **records, int min_value, int max_value, size_t *error_info) {
    void *offset_mem = NULL, *key_mem = NULL, *record_mem = NULL;
    offset_mem = malloc(num_offsets * sizeof(*offsets));
    key_mem = malloc(num_keys * sizeof(*keys));
    record_mem = calloc(num_records, sizeof(*records));

    if (!offset_mem || !key_mem || !record_mem) {
        log_message("Error: Failed to allocate memory.");
        free(offset_mem);
        free(key_mem);
        free(record_mem);
        *error_info = 1;
        return -1;
    }

    log_message("Successfully allocated memory.");
    log_message("  Offsets:   size = ");
    log_message((void *)offset_mem);
    log_message("  Keys:      size = ");
    log_message((void *)key_mem);
    log_message("  Records:  size = ");
    log_message((void *)record_mem);

    *error_info = 0;

    srand(time(NULL));

    for (size_t i = 0; i < num_records; ++i) {
        Record *record = &(*(Record*)record_mem + i);
        record->value = min_value + rand() % ((max_value - min_value) + 1);

        if (!record->value || (record->value < min_value || record->value > max_value)) {
            log_message("Error: Invalid value in Record structure.");
            *error_info = 2;
            goto clean_up;
        }
    }

    for (size_t i = 0; i < num_offsets; ++i) {
        if (((*offsets + i) == NULL)) {
            log_message("Error: Offset array is missing an element.");
            *error_info = 3;
            goto clean_up;
        }
    }

    for (size_t i = 0; i < num_keys; ++i) {
        if (*(keys + i) <= 0) {
            log_message("Error: Key must be greater than zero.");
            *error_info = 4;
            goto clean_up;
        }
    }

    *offsets = offset_mem;
    *keys = key_mem;
    *records = record_mem;

    return 0;

clean_up:
    free(record_mem);
    if (num_offsets && offset_mem) free(offset_mem);
    if (num_keys && key_mem) free(key_mem);
    return -1;
}
