#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <pthread.h>
#include <sys/mman.h>

typedef struct Record {
    double value;
    int key;
    char *str;
} Record;

typedef struct MemoryPool {
    void (*callback)(Record*);
    size_t allocated, freed, peak;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    Record **records;
    size_t record_capacity, record_size, growth_threshold;
    char *memory_pool;
} MemoryPool;

void init_memory_pool(MemoryPool *pool, size_t capacity, size_t record_size, size_t growth_threshold) {
    memset(pool, 0, sizeof(MemoryPool));
    pool->record_capacity = capacity;
    pool->record_size = record_size;
    pool->growth_threshold = growth_threshold;
    pool->memory_pool = mmap(NULL, 4096 * growth_threshold, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (pool->memory_pool == MAP_FAILED) {
        fprintf(stderr, "Error: Failed to allocate memory pool\n");
        exit(EXIT_FAILURE);
    }
    pool->records = (Record **) pool->memory_pool;
}

Record *allocate_record(MemoryPool *pool) {
    Record *record;
    pthread_mutex_lock(&pool->mutex);
    if (pool->peak < pool->allocated) pool->peak = pool->allocated;
    while ((pool->records + pool->record_capacity - 1) >= pool->records && pool->allocated < pool->record_capacity) {
        record = pool->records + pool->allocated++;
        memset(record, 0, pool->record_size);
        pthread_mutex_unlock(&pool->mutex);
        return record;
    }
    if (pool->allocated >= pool->record_capacity) {
        size_t new_capacity = pool->record_capacity + (pool->growth_threshold * 2);
        Record **new_records = realloc(pool->records, new_capacity * sizeof(Record *));
        if (!new_records) {
            fprintf(stderr, "Error: Failed to allocate additional memory for records\n");
            pthread_mutex_unlock(&pool->mutex);
            exit(EXIT_FAILURE);
        }
        pool->records = new_records;
        pool->record_capacity = new_capacity;
    }
    record = pool->records + pool->allocated++;
    memset(record, 0, pool->record_size);
    pthread_mutex_unlock(&pool->mutex);
    return record;
}

void free_record(MemoryPool *pool, Record *record) {
    pthread_mutex_lock(&pool->mutex);
    pool->freed++;
    if (pool->records == record) pool->records++;
    pthread_mutex_unlock(&pool->mutex);
}

void log_memory(MemoryPool *pool) {
    printf("Allocation: %ld, Freed: %ld, Peak: %ld\n", pool->allocated - pool->freed, pool->allocated, pool->peak);
}

// Custom processing callback function example
void process_record(Record *record) {
    record->value *= 2.0;
    char buffer[10];
    sprintf(buffer, "%d", record->key);
    record->str = strdup(buffer);
}

int main() {
    MemoryPool pool;
    init_memory_pool(&pool, 10000, sizeof(Record), 100);
    pool.callback = process_record;
    srand(time(NULL));
    for (size_t i = 0; i < 50000; ++i) {
        Record *record = allocate_record(&pool);
        record->value = (double) rand() / RAND_MAX * 10.0;
        record->key = rand() % 100000;
    }
    log_memory(&pool);
    // Free and reallocate memory as necessary
    for (size_t i = 0; i < 50000; ++i) {
        free_record(&pool, pool.records[i]);
    }
    log_memory(&pool);
    munmap(pool.memory_pool, 4096 * pool.growth_threshold);
    return 0;
}
