// Function to process and find the maximum CRCFLAG, dynamically allocating memory for an array of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* processAndFindMax(size_t numThreads, size_t numElementsPerThread, bool verbose) {
    // Seed random number generator
    srand(time(NULL));

    // Allocate memory for a single structure
    NFAPI_CRC_INDICATION_PDU_T* singleStructure = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!singleStructure) {
        fprintf(stderr, "Failed to allocate memory for a single structure\n");
        return NULL;
    }

    // Set up the structure
    singleStructure->RX_UE_INFORMATION_TAG = 0x0123;
    singleStructure->RNTI = 0x4567;
    singleStructure->CRC_INDICATION_REL8_TAG = 0x89AB;
    singleStructure->CRCFLAG = rand() % (numElementsPerThread * 2 + 1); // Ensure no two consecutive structures have the same CRCFLAG

    // Allocate memory for an array of structures and create a thread pool
    size_t numStructures = numThreads * numElementsPerThread;
    NFAPI_CRC_INDICATION_PDU_T* structures = (NFAPI_CRC_INDICATION_PDU_T*)malloc(numStructures * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!structures) {
        fprintf(stderr, "Failed to allocate memory for the array of structures\n");
        free(singleStructure);
        return NULL;
    }

    pthread_t threads[numThreads];
    pthread_attr_t attr;
    pthread_attr_init(&attr);
    pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_JOINABLE); // Allow joining threads for error handling and logging

    int elementCounter = 0;
    size_t threadData[numThreads][numElementsPerThread]; // Store the index of the next structure to process for each thread

    // Initialize the thread pool
    for (size_t i = 0; i < numThreads; ++i) {
        threadData[i][elementCounter] = i * numElementsPerThread + elementCounter;
        if (pthread_create(&threads[i], &attr, processOneStructures, (void*)&structures[threadData[i][elementCounter]])) {
            fprintf(stderr, "Failed to create thread %zu\n", i);
            // Cleanup and exit early to avoid resource leaks
            for (size_t j = 0; j < i; ++j) {
                pthread_join(threads[j], NULL);
            }
            free(singleStructure);
            free(structures);
            return NULL;
        }
    }

    // Join the threads and find the maximum CRCFLAG value
    for (size_t i = 0; i < numThreads; ++i) {
        pthread_join(threads[i], NULL);
    }

    int maxCRCFLAG = structures[0].CRCFLAG;
    for (size_t i = 1; i < numStructures; ++i) {
        if (structures[i].CRCFLAG > maxCRCFLAG && structures[i].CRCFLAG != structures[i - 1].CRCFLAG) {
            maxCRCFLAG = structures[i].CRCFLAG;
        }
    }

    // Logging and cleanup
    if (verbose) {
        printf("Number of allocated structures: %zu\n", numStructures);
        printf("Maximum CRCFLAG value: %d\n", maxCRCFLAG);
    } else {
        fprintf(stderr, "Allocated %zu structures, maximum CRCFLAG: %d\n", numStructures, maxCRCFLAG);
    }

    free(singleStructure);
    free(structures);

    return NULL; // The function does not need to return anything as it is a utility function
}

// Helper function for each thread in the pool, processing one structure at a time
void* processOneStructures(void* data) {
    NFAPI_CRC_INDICATION_PDU_T* currentStructure = (NFAPI_CRC_INDICATION_PDU_T*)data;
    currentStructure->RX_UE_INFORMATION_TAG = rand() % 0xFFFF; // Set a random RX_UE_INFORMATION_TAG for each structure
    currentStructure->RNTI = rand() % 0xFFFF; // Set a random RNTI for each structure
    currentStructure->CRCFLAG += elementCounter++; // Increment the CRCFLAG by the current counter to ensure no two consecutive structures have the same CRCFLAG

    return NULL; // The thread does not need to return anything as it is a utility function
}
