// An adaptive memory pool for various data types.
template<typename T>
class MemoryPool {
public:
    void* allocate(size_t n) {
        if (free_.empty()) {
            auto p = std::make_unique<std::vector<T>>();
            allocated_++;
            p->reserve(n + pooled_);
            return p->data();
        }

        void* result = free_.back().data();
        free_.pop_back();
        pooled_ -= n;
        if (pooled_ <= 10 * size_) {
            auto p = std::make_unique<std::vector<T>>();
            allocated_++;
            p->insert(p->end(), free_.begin(), free_.end());
            free_.swap(std::move(*p));
        }
        return result;
    }

    void deallocate(void* p, size_t n) {
        auto q = static_cast<T*>(p);
        free_.emplace_back(q, q + n);
        pooled_ += n;
    }

private:
    size_t size_;
    std::atomic<size_t> allocated_{0};
    std::vector<std::vector<T>> free_;
    size_t pooled_{0};
};

// A concurrent-safe logging class.
class Logger {
public:
    void log(const std::string& message) {
        if (log_) {
            log_->log(message);
        } else {
            std::cerr << "Logging disabled: [ " << message << " ]\n";
        }
    }

