public async Task<JObject> parseXMLAndRunTests(string xmlPath, string moduleName, Blueslip blueslipInstance, JArray tests, int maxConcurrency)
{
    var semaphore = new SemaphoreSlim(maxConcurrency);
    var parsedXmlCache = new ConcurrentDictionary<string, XmlDocument>();

    // Validate XML file format and structure.
    if (!File.Exists(xmlPath))
        throw new FileNotFoundException("XML file not found.", xmlPath);

    var xmlStream = new FileStream(xmlPath, FileMode.Open);
    var xmlReader = XmlReader.Create(xmlStream);

    // Parse XML document asynchronously and cache the result.
    if (!parsedXmlCache.TryGetValue(xmlPath, out var parsedXml))
    {
        parsedXml = new XmlDocument();
        await Task.Run(() => parsedXml.LoadAsync(xmlReader));
        parsedXmlCache[xmlPath] = parsedXml;
    }

    // Extract the first matching element based on the given name from the XML document.
    var matchingElement = GetMatchingElement(parsedXml, xmlPath);
    if (matchingElement == null)
        throw new Exception($"No or multiple elements found with the specified name.");

    // Load the module dynamically and reset the Blueslip instance for each test.
    var assembly = Assembly.LoadFile(Path.GetFileNameWithoutExtension(moduleName) + ".dll");
    if (assembly == null)
        throw new Exception($"Failed to load the specified module.");

    dynamic module = Activator.CreateInstance(assembly.GetTypes().FirstOrDefault(t => t.FullName.EndsWith(moduleName)));
    var blueslip = blueslipInstance;

    // Execute tests concurrently, limited by maxConcurrency.
    var completedTests = new ConcurrentBag<JObject>();
    var testTasks = tests.Select(test => Task.Run(() =>
    {
        semaphore.Wait();
        blueslip.Reset();

        // Log the start of each test.
        LogTestStart(blueslip, test.name, DateTime.Now);

        try
        {
            var result = test.testFunction(blueslip);

            // Log the completion of each test and add the result to the list of completed tests.
            LogTestCompletion(blueslip, test.name, DateTime.Now, result);
            completedTests.Add(JObject.FromObject(result));
        }
        catch (Exception ex)
        {
            // Log exceptions and continue with other tests.
            LogException(blueslip, ex, test.name);
        }

        semaphore.Release();
    }));

    await Task.WhenAll(testTasks);

    return JObject.FromObject(completedTests.ToArray());
}

private static XmlNode GetMatchingElement(XmlDocument xml, string xpath)
{
    try
    {
        var node = xml.SelectSingleNode(xpath);
        if (node == null)
            throw new Exception($"No element found with the specified path.");

        return node;
    }
    catch (Exception ex)
    {
        if (xml.DocumentElement.ChildNodes.Count > 1)
            throw new Exception($"Multiple elements found with the specified path.");

        throw ex;
    }
}

private static void LogTestStart(Blueslip blueslip, string testName, DateTime timestamp) => blueslip.LogMessage($"Test started: {testName}, {timestamp}");
private static void LogTestCompletion(Blueslip blueslip, string testName, DateTime timestamp, object result) => blueslip.LogMessage($"Test completed: {testName}, {result}, {timestamp}");
private static void LogException(Blueslip blueslip, Exception exception, string testName) => blueslip.LogError(exception, $"Test failed: {testName}");
```

