static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
static size_t allocated = 0;
static size_t max_allocated = 0;
static NFAPI_CRC_INDICATION_PDU_T *structures = NULL;

NFAPI_CRC_INDICATION_PDU_T* allocate_and_populate() {
    pthread_mutex_lock(&mutex);
    size_t new_allocated = allocated + 1;
    if (new_allocated > max_allocated) {
        void *temp_structures = realloc(structures, new_allocated * STRUCTURE_SIZE);
        if (!temp_structures) {
            pthread_mutex_unlock(&mutex);
            return NULL;
        }
        structures = temp_structures;
        max_allocated = new_allocated;
