    NFAPI_CRC_INDICATION_PDU_T *current_structure = &structures[allocated];

    current_structure->rx_ue_information_tag.value = rand();
    current_structure->rnti.value = rand();
    current_structure->crc_indication_rel8_tag.crcflag = (rand() % 2);

    allocated++;
    pthread_mutex_unlock(&mutex);
    return current_structure;
}

// Function to report memory usage and allocation failures
