typedef struct LTE_ENB_TASK {
    int k, l, q; // number of logical channels, MAC entities, and transport channel descriptors
    pthread_mutex_t mutex;
    uint8_t* logical_channels;
    uint8_t* mac_entities;
    struct TC_DESCRIPTOR* tc_descriptors;
    size_t mem_used;
} LTE_ENB_TASK;

struct TC_DESCRIPTOR {
    void* mac_entity;
    int ref_count;
};

void lte_enb_task_init(LTE_ENB_TASK* task, int k, int l, int q) {
    if (k <= 0 || l <= 0 || q <= 0 || k * l > MAX_KL_PRODUCT || q > MAX_Q) {
        fprintf(stderr, "Invalid input: k=%d, l=%d, q=%d\n", k, l, q);
        exit(1);
    }

    task->k = k;
    task->l = l;
    task->q = q;

    task->logical_channels = custom_memory_pool_manager_allocate(k * sizeof(uint8_t), &task->mem_used);
    memset(task->logical_channels, 0, k * sizeof(uint8_t));

    task->mac_entities = custom_memory_pool_manager_allocate(l * sizeof(uint8_t), &task->mem_used);
    memset(task->mac_entities, 0, l * sizeof(uint8_t));

    task->tc_descriptors = malloc(q * sizeof(struct TC_DESCRIPTOR));
    for (int i = 0; i < q; ++i) {
        task->tc_descriptors[i].mac_entity = NULL;
        task->tc_descriptors[i].ref_count = 1;
    }

    pthread_mutex_init(&task->mutex, NULL);
}

void lte_enb_task_destroy(LTE_ENB_TASK* task) {
    free(task->tc_descriptors);
    custom_memory_pool_manager_free(task->logical_channels, task->mem_used);
    custom_memory_pool_manager_free(task->mac_entities, task->mem_used);
    pthread_mutex_destroy(&task->mutex);
}

void inc_ref_count(struct TC_DESCRIPTOR* tc_desc) {
    if (tc_desc != NULL && tc_desc->ref_count < INT_MAX) {
        ++tc_desc->ref_count;
    }
}

void dec_ref_count(struct TC_DESCRIPTOR* tc_desc) {
    if (tc_desc != NULL && tc_desc->ref_count > 0) {
        --tc_desc->ref_count;
        if (tc_desc->ref_count == 0) {
            // free memory associated with this transport channel descriptor here
        }
    }
}

