#include <ctype.hash/md5.h>
#include <pthread.h>

typedef struct {
    void* data;
    int key;
} entry_t;

typedef struct {
    entry_t* entries;
    size_t capacity;
    size_t count;
    pthread_mutex_t mutex;
} collection_t;

static unsigned int hash(const char* key) {
    MD5_CTX ctx;
    MD5_Init(&ctx);
    MD5_Update(&ctx, key, strlen(key));
    return MD5_Final((unsigned char*)&key, &ctx)[3];
}

static void resize(collection_t* coll) {
    entry_t* new_entries = realloc(coll->entries, (coll->capacity * 2 + 1) * sizeof(entry_t));
    if (!new_entries) {
        fprintf(stderr, "Failed to allocate memory for collection resizing.\n");
        return;
    }
    coll->entries = new_entries;
    coll->capacity *= 2;
}

static int compare_offsets(const void* a, const void* b) {
    return *(const off_t*)a - *(const off_t*)b;
}

void init_collection(collection_t* coll, size_t initial_capacity) {
    coll->entries = malloc(initial_capacity * sizeof(entry_t));
    if (!coll->entries) {
        fprintf(stderr, "Failed to allocate memory for the collection.\n");
        return;
    }
    coll->capacity = initial_capacity;
    coll->count = 0;
    pthread_mutex_init(&coll->mutex, NULL);
}

void add_entry(collection_t* coll, void* data) {
    pthread_mutex_lock(&coll->mutex);
    if (coll->count >= coll->capacity) resize(coll);
    entry_t* entry = &coll->entries[coll->count];
    entry->data = data;
    entry->key = hash((char*)data) + coll->count;
    qsort(&coll->entries[0], coll->count, sizeof(entry_t), compare_offsets);
    coll->count++;
    pthread_mutex_unlock(&coll->mutex);
}

void* get_data_by_key(const collection_t* coll, int key) {
    size_t low = 0;
    size_t high = coll->count;
    while (low < high) {
        size_t mid = (low + high) / 2;
        if (coll->entries[mid].key == key) return coll->entries[mid].data;
        if (coll->entries[mid].key < key) low = mid + 1;
        else high = mid;
    }
    return NULL;
}

void deinit_collection(collection_t* coll) {
    pthread_mutex_destroy(&coll->mutex);
    free(coll->entries);
}
