    public ConnectionManager(Map<String, Object> config, CollectorRegistry prometheusRegistry) {
        this.prometheusRegistry = prometheusRegistry;
        this.connectionsGauge = Gauge.build("connection_manager_connections", "Number of connections").register(this.prometheusRegistry);

