    public SocketChannel getConnection(String serverName) throws IOException {
        Preconditions.checkNotNull(serverName, "Server name must not be null");

        Selector selector = selectors.computeIfAbsent(serverName, this::createSelector);

        while (true) {
            SocketChannel socketChannel = selector.selector().selectNow();
            if (!socketChannel.isOpen()) {
                LOGGER.debug("Attempting to reconnect to server: {}", serverName);
                SocketChannel newSocketChannel = connectToEndpoint(serverName);
                if (newSocketChannel != null) {
                    registerConnection(selector, newSocketChannel);
                } else {
                    if (fallbackEndpoints.isEmpty()) {
                        LOGGER.warn("All endpoints for server {} are unavailable", serverName);
                        throw new IOException("All endpoints for server " + serverName + " are unavailable");
                    }
                    serverName = fallbackEndpoints.poll();
                }
            } else {
                return socketChannel;
            }
        }
    }

    private SocketChannel connectToEndpoint(String serverName) throws IOException {
        // Implement connection logic, error handling, and load balancing here
    }

    private Selector createSelector(String serverName) throws IOException {
        // Implement selector creation and error handling here
    }

    private void registerConnection(Selector selector, SocketChannel socketChannel) {
        connectionsGauge.inc();
        selector.registrar().register(socketChannel);
        executor.submit(() -> handleConnection(selector, socketChannel));
    }

    private void handleConnection(Selector selector, SocketChannel socketChannel) {
        try {
            // Implement data handling and error handling logic here
        } catch (Exception e) {
            LOGGER.error("Error handling connection: {}", socketChannel, e);
            cleanupConnection(selector, socketChannel);
        }
    }

    private void cleanupConnection(Selector selector, SocketChannel socketChannel) {
        connectionsGauge.dec();
        selector.registrar().deregister(socketChannel);
        socketChannel.close();
    }

    public void shutdown() throws InterruptedException {
        executor.shutdownNow();
        while (!executor.isTerminated()) {
            Thread.sleep(100);
        }

