char* hash_password(const char *password, int algorithm) {
    if (algorithm == SHA256) {
        unsigned char digest[SHA256_DIGEST_LENGTH];
        SHA256_CTX ctx;
        SHA256_Init(&ctx);
        SHA256_Update(&ctx, password, strlen(password));
        SHA256_Final(digest, &ctx);

        char *hashed = malloc(SHA256_DIGEST_LENGTH * 2 + 1);
        if (!hashed) return NULL;

        for (size_t i = 0; i < SHA256_DIGEST_LENGTH; ++i) {
            sprintf(&(hashed[i * 2]), "%02x", digest[i]);
        }
        hashed[SHA256_DIGEST_LENGTH * 2] = '\0';
        return hashed;
    } else if (algorithm == BCrypt) {
        size_t saltLen = BCrypt_get_salt_len();
        char *salt = malloc(saltLen);
        if (!salt) return NULL;

        BCrypt_rand(salt, saltLen);
