struct MemoryPool {
    size_t capacity;
    size_t used;
    char* data;
};

void initMemoryPool(struct MemoryPool* pool, size_t size) {
    pool->capacity = size;
    pool->used = 0;
    pool->data = mmap(NULL, size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
}

char* allocFromMemoryPool(struct MemoryPool* pool) {
    char* ptr;
    if (pool->used < pool->capacity) {
        ptr = &pool->data[pool->used];
        pool->used++;
    } else {
        fprintf(stderr, "Out of memory in the pool\n");
    }
    return ptr;
}

