struct hash_table {
    void **keys;
    void *values[]; // Replace with appropriate data type
    unsigned long size;
    unsigned long mask;
};

void init_hash(struct hash_table* table, unsigned long size) {
    table->size = size;
    table->mask = size - 1;
    table->keys = malloc(sizeof(*table->keys) * size);
}

unsigned long hash(const char* key, unsigned long size) {
    unsigned long hash = 5381;
    int c;
    while ((c = *key++))
        hash = ((hash << 5) + hash) + c; /* hash * 33 + c */
    return hash % size;
}

void put_hash(struct hash_table* table, const char* key, void* value) {
    unsigned long h = hash(key, table->size);
    pthread_mutex_lock(&table->keys[h]);
    if (!table->keys[h]) {
        table->keys[h] = malloc(sizeof(*table->keys));
        *table->keys[h] = 0;
    }
    int slot = *table->keys[h];
    while (slot != -1) {
        unsigned long h2 = hash(key + slot, table->size);
        if (h2 == h) {
            assert(table->values[slot] == 0);
            table->values[slot] = value;
            return;
        }
        slot = (slot + 1) & table->mask;
    }
    *table->keys[h] = -1;
    table->keys[h]->next = malloc(sizeof(*table->keys));
    table->keys[h]->next->key = slot;
    table->keys[h] = table->keys[h]->next;
    table->values[slot] = value;
    pthread_mutex_unlock(&table->keys[h]);
}

void* get_hash(struct hash_table* table, const char* key) {
    unsigned long h = hash(key, table->size);
    void *value = 0;
    pthread_mutex_lock(&table->keys[h]);
    if (table->keys[h]) {
        int slot = *table->keys[h];
        while ((slot != -1) && !value) {
            unsigned long h2 = hash(key + slot, table->size);
            if (h2 == h) {
                value = table->values[slot];
            } else {
                slot = (slot + 1) & table->mask;
            }
        }
    }
    pthread_mutex_unlock(&table->keys[h]);
    return value;
}

