['1. Resource Bundle Function (`load_bundle.c`):

```c
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <stdbool.h>
#include <sys/mman.h>
#include <semaphore.h>

#define LOG_LEVEL (your_logging_macro)
#define BUFFER_SIZE 1024 * 64

typedef struct Bundle {
    size_t num_items;
    void* data;
    pthread_mutex_t mutex;
    sem_t cache_sem;
} Bundle;

Bundle* load_bundle(const char* path) {
    FILE* file = fopen(path, "rb");
    if (!file) {
        LOG_ERROR("Failed to open bundle: %s", path);
        return NULL;
    }

    fseek(file, 0, SEEK_END);
    size_t size = ftell(file);
    void* data = mmap(NULL, size, PROT_READ, MAP_PRIVATE, fileno(file), 0);
    if (data == MAP_FAILED) {
        LOG_ERROR("Failed to map bundle: %s", path);
        fclose(file);
        return NULL;
    }
    fseek(file, 0, SEEK_SET);

    Bundle* bundle = malloc(sizeof(Bundle));
    if (!bundle) {
        LOG_ERROR("Failed to allocate memory for bundle");
        munmap(data, size);
        fclose(file);
        return NULL;
    }

    bundle->num_items = 0;
    bundle->data = data;
    pthread_mutex_init(&bundle->mutex, NULL);
    sem_init(&bundle->cache_sem, 0, 1);

    return bundle;
}
```

