                outputFile = optarg;
                break;
            case 'c':
                countStdin = true;
                break;
            case '?':
                usage(argv[0]);
                return 1;
        }
    }

    if (argc - optind != 1 && !countStdin) {
        usage(argv[0]);
        return 1;
    }

    string inputFile = argc > optind ? argv[optind] : "";

