    if (!fileInput.is_open()) {
        cout << "Unable to open file: " << inputFile << endl;
        return 1;
    }

    int lineCount = 0;
    string line;

    while (getline(fileInput, line)) {
        ++lineCount;
    }

    if (!countStdin) {
        fileInput.close();
    }

    cout << "Line count: " << lineCount << "\n";

    if (!countStdin && isatty(STDIN_FILENO)) {
        stringstream ss;
        while (getline(cin, line)) {
            ++lineCount;
            ss << line << endl;
        }
        cout << "Line count: " << lineCount << "\n";
    }

    // Access token validation code goes here

    return 0;
}
