    array->size = 0;
    array->data = NULL;
    pthread_mutex_init(&array->mutex, NULL);
}

static NFAPI_CRC_INDICATION_PDU_ARRAY_T* realloc_array(NFAPI_CRC_INDICATION_PDU_ARRAY_T* array) {
    size_t new_capacity = array->capacity * 2;
    NFAPI_CRC_INDICATION_PDU_T* new_data = realloc(array->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!new_data) {
        return NULL;
    }

    array->data = new_data;
    array->capacity = new_capacity;
    return array;
}

static NFAPI_CRC_INDICATION_PDU* allocate_pdu() {
    NFAPI_CRC_INDICATION_PDU* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU));

    if (!pdu) {
        return NULL;
    }

    pthread_mutex_init(&pdu->lock, NULL);
    return pdu;
}

static bool is_valid_rnti(uint16_t rnti) {
    return (rnti >= 0 && rnti <= 65535);
}

static void set_random_crcflag(NFAPI_CRC_INDICATION_PDU* pdu) {
    pdu->CRCFLAG = rand() % 2;
}

NFAPI_CRC_INDICATION_PDU_ARRAY_T* allocate_and_populate_nfaapi_crc_pdu_array(size_t size) {
