        return NULL;
    }

    NFAPI_CRC_INDICATION_PDU_ARRAY_T* array = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_ARRAY_T));

    if (!array) {
        return NULL;
    }

    init_array(array);

    pthread_mutex_lock(&array->mutex);
    for (size_t i = 0; i < size; ++i) {
        NFAPI_CRC_INDICATION_PDU* pdu = allocate_pdu();

        if (!pdu) {
            free(array);
            pthread_mutex_unlock(&array->mutex);
            return NULL;
        }

        uint16_t rnti = rand() % 65536;

        while (!is_valid_rnti(rnti)) {
            rnti = rand() % 65536;
        }

        pdu->RX_UE_INFORMATION_TAG = (uint16_t)(rand() & 0xffff);
        pdu->CRC_INDICATION_REL8_TAG = (uint16_t)(rand() & 0xffff);
        pdu->RNTI = rnti;
        set_random_crcflag(pdu);

        if (!array->data) {
            array->data = pdu;
        } else {
            NFAPI_CRC_INDICATION_PDU* last_element = &array->data[array->size - 1];
            pthread_mutex_lock(&last_element->lock);
            last_element->next = pdu;
            pthread_mutex_unlock(&last_element->lock);
        }

        ++array->size;
    }
    pthread_mutex_unlock(&array->mutex);

    return array;
}
