#include <stdbool.h>
#include <time.h>

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct _ue_list {
    size_t capacity;
    size_t size;
    NFAPI_CRC_INDICATION_PDU_T *elements;
    size_t allocations;
    size_t deallocations;
} ue_list;

ue_list* create_ue_list(size_t initial_capacity) {
    if (initial_capacity > 1024)
        initial_capacity = 1024;
    ue_list *list = (ue_list *)malloc(sizeof(ue_list));
    list->capacity = initial_capacity;
    list->size = 0;
    list->elements = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->allocations = 1;
    return list;
}

void resize_ue_list(ue_list *list) {
    size_t new_capacity = list->capacity * 2;
    if (new_capacity > 1024)
        new_capacity = 1024;
    NFAPI_CRC_INDICATION_PDU_T *new_elements = realloc(list->elements, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_elements != NULL) {
        list->capacity = new_capacity;
        list->elements = new_elements;
    } else {
        printf("Error: Failed to reallocate memory.\n");
        exit(EXIT_FAILURE);
    }
}

bool unique_ue_information_tag(const ue_list *list, size_t start_index, size_t element_count) {
    for (size_t i = 0; i < element_count; ++i) {
        for (size_t j = start_index + 1; j < start_index + element_count; ++j) {
            if (i != j && list->elements[i].RX_UE_INFORMATION_TAG == list->elements[j].RX_UE_INFORMATION_TAG)
                return false;
        }
    }
    return true;
}

bool add_ue(ue_list *list, uint32_t RX_UE_INFORMATION_TAG, uint16_t RNTI, uint8_t CRC_INDICATION_REL8_TAG) {
    if (list->size == list->capacity) {
        resize_ue_list(list);
    }
    if (!unique_ue_information_tag(list, 0, list->size)) {
        return false;
    }
    list->elements[list->size].RX_UE_INFORMATION_TAG = RX_UE_INFORMATION_TAG;
    list->elements[list->size].RNTI = RNTI;
    list->elements[list->size++].CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
    list->allocations++;
    return true;
}

void print_stats(ue_list *list) {
    printf("Allocation count: %zu\n", list->allocations);
    printf("Deallocation count: %zu\n", list->deallocations);
    printf("Current capacity: %zu\n", list->capacity);
}

void deallocate_ue(ue_list *list, size_t index) {
    if (index >= list->size) {
        fprintf(stderr, "Error: Index out of range.\n");
        return;
    }
    free((void*)&list->elements[index]);
    memmove(&list->elements[index], &list->elements[index + 1], (list->size - index - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    list->size--;
    list->deallocations++;
}

void destroy_ue_list(ue_list **list_ptr) {
    if (*list_ptr == NULL)
        return;
    for (size_t i = 0; i < (*list_ptr)->size; ++i) {
        deallocate_ue(*list_ptr, i);
    }
    free((*list_ptr));
    *list_ptr = NULL;
}
```

This code defines a `ue_list` struct that contains the list elements, capacity, size, allocations and deallocations. The function `create_ue_list()` initializes a new list with the given initial capacity (up to 1024). The `resize_ue_list()` function resizes the array when it's full. The `add_ue()` function adds an element to the list, ensuring uniqueness of RX_UE_INFORMATION_TAG and validating that the list hasn't reached its maximum capacity. The `print_stats()` function provides feedback on the memory management strategy's efficiency. The `deallocate_ue()` function deallocates an element at the given index, moving subsequent elements to fill the gap, and the `destroy_ue_list()` function frees all memory associated with the list.']

