HashNode *hash_table[1024]; // Change the number based on system architecture and desired hash table size

void init() {
    memset(hash_table, 0, sizeof(hash_table));
    mempool.base = mmap(NULL, 16 * (1024 * 1024), PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    if (mempool.base == MAP_FAILED) {
        perror("mmap");
        exit(EXIT_FAILURE);
    }
    mempool.alloc = mempool.used = 0;
    pthread_mutex_init(&mempool.mutex, NULL);
}

CustomObject* create_custom_object() {
    if (mempool.used + sizeof(CustomObject) > mempool.alloc) {
        size_t new_size = mempool.alloc ? mempool.alloc * 2 : 16 * (1024 * 1024);
        void *new_base = mmap(NULL, new_size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
        if (new_base == MAP_FAILED) {
            perror("mmap");
            exit(EXIT_FAILURE);
        }
        mempool.base = new_base;
        mempool.alloc = new_size;
    }

    CustomObject *obj = (CustomObject*)((char*)mempool.base + mempool.used);
    memset(obj, 0, sizeof(CustomObject));
    obj->record.int_val = rand(); // Seed random number generator
    mempool.used += sizeof(CustomObject);
    return obj;
}

void free_custom_object(CustomObject *obj) {
    mempool.used -= sizeof(CustomObject);
    madvise((char*)obj, sizeof(CustomObject), MADV_DONTNEED); // Advise OS to free memory when possible
}

HashNode* find_or_create(CustomObject **list, const void *key) {
    unsigned long hash = MurmurHash3_x64_8(&(*(const uint64_t*)key), key_length(key));
    int index = (int)(hash % 1024);
    HashNode *node = hash_table[index];
    while (node) {
        if (node->obj->key == *(const int*)key && node->obj != *list) {
            return node;
        }
        node = node->next;
    }

    CustomObject *new_obj = create_custom_object();
    memcpy(new_obj, *list, sizeof(CustomObject));
    new_obj->key = *(const int*)key;
    HashNode *new_node = (HashNode*)malloc(sizeof(HashNode));
    new_node->obj = new_obj;
    new_node->next = hash_table[index];
    hash_table[index] = new_node;
    return new_node;
}

void enqueue(const void *key, void (*func)(CustomObject*)) {
    pthread_mutex_lock(&queue_mutex);
    QueueNode *node = (QueueNode*)malloc(sizeof(QueueNode));
    node->key = key;
    node->func = func;
    node->next = NULL;

    QueueNode **head = &queues[QUEUE_BATCH];
    while (*head) {
        if ((*head)->priority <= QUEUE_BATCH && !(*head)->is_processed) {
            node->next = *head;
            *head = node;
            break;
        }
        head = &((*head)->next);
    }

    pthread_mutex_unlock(&queue_mutex);
}

void run_queues() {
    while (1) {
        pthread_mutex_lock(&queue_mutex);
        int queue_index = -1;
        QueueNode **head = &queues[QUEUE_BATCH];
        while (*head && queue_index == -1) {
            if ((*head)->priority >= QUEUE_BATCH) {
                queue_index = QUEUE_BATCH;
            } else if (!(*head)->is_processed) {
                queue_index = (*head)->priority;
            }
            head = &((*head)->next);
        }
        QueueNode *temp = *head;
        if (queue_index == -1) {
            pthread_mutex_unlock(&queue_mutex);
            usleep(100000); // Sleep for 100ms to avoid busy waiting
            continue;
        }

        (*head)->is_processed = true;
        pthread_mutex_unlock(&queue_mutex);

        CustomObject *obj = find_or_create((const void*)&temp->key, temp->func);
        // Process the object here, with atomic updates for marking as pending or completed
        // ...

        if (obj->state == COMPLETED) {
            free_custom_object(obj);
            free(temp);
        }
    }
}
