#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>
#include <limits.h>
#include <Windows.h> // For interop with C#

typedef struct {
    int PHY_CELL_ID;
    int TRANSMIT_POWER_LEVEL;
    unsigned int* TRANSPORT_BLOCK_SIZE;
} LTE_Uplink_Traffic_Configuration;

typedef struct ListNode {
    LTE_Uplink_Traffic_Configuration config;
    struct ListNode* next;
} ListNode;

ListNode* createNode(LTE_Uplink_Traffic_Configuration config) {
    ListNode* newNode = (ListNode*)malloc(sizeof(ListNode));
    if (!newNode) {
        printf("Memory allocation failed\n");
        return NULL;
    }
    newNode->config = config;
    newNode->next = NULL;
    return newNode;
}

bool isSorted(ListNode* head) {
    ListNode* current = head;
    while (current && current->next) {
        if (current->config.PHY_CELL_ID > current->next->config.PHY_CELL_ID)
            return false;
        current = current->next;
    }
    return true;
}

ListNode* mergeSortedLists(ListNode** lists, int count) {
    if (count <= 0) return NULL;

    ListNode* mergedHead = lists[0];
    ListNode* current = mergedHead;
    for (int i = 1; i < count; ++i) {
        ListNode* nextList = lists[i];
        while (current && nextList) {
            if (current->config.PHY_CELL_ID <= nextList->config.PHY_CELL_ID) {
                current = current->next;
            } else {
                ListNode* temp = nextList;
                nextList = nextList->next;
                temp->next = current;
                current = temp;
            }
        }

        if (current)
            current->next = nextList;
        else
            mergedHead = nextList;
    }

    return mergedHead;
}

void freeList(ListNode* head) {
    while (head) {
        ListNode* temp = head;
        head = head->next;
        free(temp);
    }
}

int getMemoryStats() {
    MEMORYSTATUSEX memInfo;
    memInfo.dwLength = sizeof(memInfo);
    GlobalMemoryStatusEx(&memInfo);
    return (int)(memInfo.ullTotalPhys - memInfo.ullAvailPhys);
}

ListNode* createManagedList() {
    ListNode* head = NULL;
    int capacity = 16;
    int numEntries = 0;

    // Function for adding a configuration
    void addConfig(LTE_Uplink_Traffic_Configuration config) {
        if (numEntries >= capacity) {
            ListNode** lists = realloc(head, capacity * 2 * sizeof(ListNode*));
            if (!lists) {
                printf("Memory allocation failed\n");
                return;
            }
            head = mergeSortedLists((ListNode**)lists, capacity);
            capacity *= 2;
        }

        ListNode* newNode = createNode(config);
        if (!newNode) {
            printf("Memory allocation failed\n");
            return;
        }

        newNode->next = head;
        head = newNode;
        qsort((void*)head, numEntries + 1, sizeof(LTE_Uplink_Traffic_Configuration), compareConfigs); // Sort the list after each addition to maintain uniqueness
        numEntries++;
    }

    // Compare two configurations by their PHY_CELL_ID values
    int compareConfigs(const void* a, const void* b) {
        return ((LTE_Uplink_Traffic_Configuration*)a)->PHY_CELL_ID - ((LTE_Uplink_Traffic_Configuration*)b)->PHY_CELL_ID;
    }

    // Save and load list from/to disk (for data persistence)
    void serialize(const char* filename) {
        FILE* file = fopen(filename, "wb");
        if (!file) return;

        fwrite(&numEntries, sizeof(int), 1, file);
        fwrite(head, sizeof(ListNode), numEntries, file);
        fclose(file);
    }

    void deserialize(const char* filename) {
        FILE* file = fopen(filename, "rb");
        if (!file) return;

        fread(&numEntries, sizeof(int), 1, file);
        freeList(head);
        head = NULL;

        ListNode** lists = (ListNode**)malloc(numEntries * sizeof(ListNode*));
        for (int i = 0; i < numEntries; ++i) {
            lists[i] = NULL;
        }

        ListNode* currentHead = head;
        while (numEntries > 0) {
            ListNode* newNode = malloc(sizeof(ListNode));
            fread(newNode, sizeof(ListNode), 1, file);

            if (!currentHead) {
                currentHead = newNode;
            } else {
                while (current->next) {
                    current = current->next;
                }
                current->next = newNode;
            }

            lists[newNode->config.PHY_CELL_ID - 1] = newNode;
            numEntries--;
        }

        free(lists);
        head = mergeSortedLists((ListNode**)lists, numEntries + 1);
        fclose(file);
    }

    return head;
}
