#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <time.h>

typedef struct _UE_INFO {
    uint32_t RX_UE_INFORMATION_TAG;
    uint64_t RNTI;
    struct _UE_INFO* next;
} UE_INFO;

typedef struct _CRC_INDICATION {
    bool CRCFLAG;
    pthread_mutex_t lock;
} CRC_INDICATION;

typedef struct _NFAPI_CRC_INDICATION_PDU {
    RX_UE_INFORMATION_TAG tag;
    uint64_t rnti;
    CRC_INDICATION* crcIndication;
} NFAPI_CRC_INDICATION_PDU_T;

void init_crcc(CRC_INDICATION* crc) {
    crc->CRCFLAG = rand() % 2;
    pthread_mutex_init(&crc->lock, NULL);
}

UE_INFO* find_ue(UE_INFO** head, uint32_t tag) {
    UE_INFO* current = *head;
    while (current != NULL) {
        if (current->RX_UE_INFORMATION_TAG == tag) {
            return current;
        }
        current = current->next;
    }
    return NULL;
}

void add_ue(UE_INFO** head, UE_INFO* new_ue) {
    UE_INFO* current = *head;
    if (current == NULL || current->RX_UE_INFORMATION_TAG != new_ue->RX_UE_INFORMATION_TAG) {
        if (*head == NULL) {
            *head = new_ue;
        } else {
            while (current->next != NULL) {
                current = current->next;
            }
            current->next = new_ue;
        }
    } else {
        fprintf(stderr, "Error: UE already exists.\n");
    }
}

void resize_list(NFAPI_CRC_INDICATION_PDU_T** list, size_t new_capacity) {
    if (new_capacity > 1024) {
        fprintf(stderr, "Error: New capacity exceeds maximum limit.\n");
        return;
    }

    NFAPI_CRC_INDICATION_PDU_T* new_list = malloc(new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (new_list == NULL) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return;
    }

    size_t min_size = new_capacity < *((size_t*)list) ? new_capacity : *((size_t*)list);
    UE_INFO* ue_head[min_size];
    for (size_t i = 0; i < min_size; ++i) {
        ue_head[i] = NULL;
    }

    size_t counter = 0;
    for (size_t i = 0; i < *((size_t*)list); ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = &(*list)[i];
        UE_INFO* ue = find_ue(ue_head, pdu->tag);
        if (ue == NULL) {
            add_ue(ue_head + counter, malloc(sizeof(UE_INFO)));
            ue = *ue_head++;
            ue->RX_UE_INFORMATION_TAG = pdu->tag;
            ue->RNTI = pdu->rnti;
            ++counter;
        } else {
            ue->RNTI = pdu->rnti;
        }
        if (pdu->crcIndication) {
            pthread_mutex_lock(&pdu->crcIndication->lock);
            (*list)[i].crcIndication = &new_list[counter].crcIndication;
            init_crcc(new_list + counter);
            pthread_mutex_unlock(&pdu->crcIndication->lock);
        }
    }

    *((size_t*)list) = counter;
}

NFAPI_CRC_INDICATION_PDU_T* create_pdus(size_t count, void (*data_retriever)(uint32_t tag, uint64_t* rnti)) {
    NFAPI_CRC_INDICATION_PDU_T* list = malloc(count * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (list == NULL) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return NULL;
    }

    size_t* ue_counts = malloc(1024 * sizeof(size_t));
    if (ue_counts == NULL) {
        free(list);
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return NULL;
    }

    for (size_t i = 0; i < 1024; ++i) {
        ue_counts[i] = 0;
    }

    UE_INFO** ue_head = malloc(1024 * sizeof(UE_INFO*));
    if (ue_head == NULL) {
        free(list);
        free(ue_counts);
        fprintf(stderr, "Error: Memory allocation failed.\n");
        return NULL;
    }

    for (size_t i = 0; i < count; ++i) {
        uint32_t tag = rand() % 1024;
        uint64_t rnti;

        if (data_retriever(tag, &rnti)) {
            UE_INFO* ue = find_ue(ue_head[tag], tag);
            if (ue == NULL) {
                ue = malloc(sizeof(UE_INFO));
                if (ue == NULL) {
                    free(list);
                    free(ue_counts);
                    free(ue_head);
                    fprintf(stderr, "Error: Memory allocation failed.\n");
                    return NULL;
                }
                ue->RX_UE_INFORMATION_TAG = tag;
                ue->RNTI = rnti;
                ue->next = ue_head[tag];
                ue_head[tag] = ue;
            } else {
                ue->RNTI = rnti;
            }

            CRC_INDICATION crc;
            init_crcc(&crc);
            list[i].tag = tag;
            list[i].rnti = rnti;
            list[i].crcIndication = &crc.crcIndication;
        } else {
            list[i].tag = tag;
            list[i].rnti = 0;
            list[i].crcIndication = NULL;
        }
    }

    free(ue_counts);
    free(ue_head);

    return list;
}

void deallocate_pdus(NFAPI_CRC_INDICATION_PDU_T* list, size_t count) {
    for (size_t i = 0; i < count; ++i) {
        UE_INFO* ue = find_ue(NULL, list[i].tag);
        if (ue != NULL) {
            UE_INFO* temp = ue;
            ue = ue->next;
            free(temp);
        }
    }
    free(list);
}
```

