struct PAGING_MESSAGE {
    uint16_t PCI;
    uint32_t MME_ID;
    uint16_t SEQUENCE_NUMBER;
};

static tbb::concurrent_hash_map<uint32_t, LTE_ENB_RRC_INST*> RRC_INSTANCES;
static size_t num_allocations = 0, num_deallocations = 0;
static pthread_mutex_t performance_monitor_lock = PTHREAD_MUTEX_INITIALIZER;

void rrc_instances_init() {
    RRC_INSTANCES.construct(512);
}

LTE_ENB_RRC_INST* find_or_create_instance(uint32_t cell_id) {
    pthread_mutex_lock(&performance_monitor_lock);
    ++num_allocations;
    pthread_mutex_unlock(&performance_monitor_lock);

    auto it = RRC_INSTANCES.find(cell_id);
    if (it != RRC_INSTANCES.end()) {
        return it->second;
    }

    LTE_ENB_RRC_INST* new_instance = static_cast<LTE_ENB_RRC_INST*>(malloc(sizeof(LTE_ENB_RRC_INST)));
    if (new_instance == nullptr) {
        // Handle out-of-memory error gracefully
        return nullptr;
    }

    new_instance->CELL_ID = cell_id;
    RRC_INSTANCES.insert(std::make_pair(cell_id, new_instance));

    return new_instance;
}

void delete_instance(LTE_ENB_RRC_INST* instance) {
    pthread_mutex_lock(&performance_monitor_lock);
    ++num_deallocations;
    pthread_mutex_unlock(&performance_monitor_lock);

    RRC_INSTANCES.erase(instance->CELL_ID);
    free(instance);
}
