pthread_mutex_t list_mutex = PTHREAD_MUTEX_INITIALIZER;
static size_t num_pdus = 0;
static size_t max_pdus = 0;
static size_t total_allocated = 0;
static size_t total_freed = 0;
static clock_t start_time = 0;

NFAPI_CRC_INDICATION_PDU_T* create_pdu() {
    NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!pdu) return nullptr;

    pdu->RX_UE_INFORMATION_TAG = generate_tag(); // Custom function to generate tag
    pdu->RNTI = generate_rnti(); // Custom function to generate RNTI
    pdu->CRC_INDICATION_REL8_TAG.CRCFLAG = (rand() % 2) == 0 ? true : false;
    if (!allocate_resource(pdu)) {
        free(pdu);
        return nullptr;
    }

    total_allocated++;
    return pdu;
}

void destroy_pdu(NFAPI_CRC_INDICATION_PDU_T *pdu) {
    if (!pdu) return;

    free_resource(pdu);
    free(pdu);
    total_freed++;
}

void log_statistics() {
    clock_t end_time = clock();
    double duration = (end_time - start_time) / CLOCKS_PER_SEC;
    printf("Total memory allocated: %ld bytes\n", total_allocated * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    printf("Total PDU count: %ld\n", num_pdus);
    printf("Total freed PDUs: %ld\n", total_freed);
    printf("Processing time: %.4fs\n", duration);
}

void *pdu_creator(void *arg) {
    while (true) {
        pthread_mutex_lock(&list_mutex);
        if (num_pdus >= max_pdus) {
            pthread_mutex_unlock(&list_mutex);
            break;
        }
        num_pdus++;
        NFAPI_CRC_INDICATION_PDU_T *pdu = create_pdu();
        if (!pdu) {
            pthread_mutex_unlock(&list_mutex);
            continue;
        }
        start_time = clock(); // Reset timer on each PDU creation
        pthread_mutex_unlock(&list_mutex);
    }
    return nullptr;
}

void populate_pdu_list(size_t n) {
    max_pdus = n;
    pthread_t threads[n];

    for (size_t i = 0; i < n; ++i) {
        if (pthread_create(&threads[i], nullptr, pdu_creator, nullptr)) {
            perror("pthread_create");
            exit(1);
        }
    }

    for (size_t i = 0; i < n; ++i) {
        if (pthread_join(threads[i], nullptr)) {
            perror("pthread_join");
            exit(1);
        }
    }
}
