typedef struct LTE_RRC_CU_PDU_T {
    uint32_t id;
    uint16_t sequence_number;
    bool status;
    void* resource; // Resource handle managed by external API
} LTE_RRC_CU_PDU_T;

typedef struct DynamicListNode_T {
    LTE_RRC_CU_PDU_T data;
    struct DynamicListNode_T* next;
} DynamicListNode_T;

static DynamicListNode_T* head = NULL;
static size_t list_size = 0;
static pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;

void add_pdu(LTE_RRC_CU_PDU_T pdu) {
    pthread_mutex_lock(&list_lock);

    DynamicListNode_T* new_node = malloc(sizeof(DynamicListNode_T));
    if (!new_node) {
        printf("Out of memory!\n");
        pthread_mutex_unlock(&list_lock);
        return;
    }

    new_node->data = pdu;
    new_node->next = head;
    head = new_node;
    list_size++;

    // Log memory usage and other runtime statistics here

    pthread_mutex_unlock(&list_lock);
}

void remove_pdu(uint32_t id) {
    pthread_mutex_lock(&list_lock);

    DynamicListNode_T* current = head;
    DynamicListNode_T* previous = NULL;

    while (current != NULL) {
        if (current->data.id == id) {
            if (previous == NULL) {
                head = current->next;
            } else {
                previous->next = current->next;
            }

            free(current);
            list_size--;

            // Log memory usage and other runtime statistics here

            pthread_mutex_unlock(&list_lock);
            return;
        }

        previous = current;
        current = current->next;
    }

    pthread_mutex_unlock(&list_lock);
}

void log_statistics() {
    // Log memory usage, processing time, resource consumption, etc.
}
