import hashlib
import os
import sys
from io import BytesIO

def md5_file(filename):
    hasher = hashlib.md5()
    with open(filename, 'rb') as f:
        buf = f.read(65564)
        while len(buf) > 0:
            hasher.update(buf)
            buf = f.read(65564)
    return hasher.digest()
