#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int sensor_id;
    double value;
    time_t timestamp;
} DataPoint;

struct Window {
    double mean, variance, peak, last_peak, max_age, weighted_score;
    size_t count;
};

struct Window window[NUM_SENSORS]; // Replace NUM_SENSORS with the number of sensor types

void updateWindow(int sensor_id, const DataPoint *data_point) {
    struct timespec now;
    clock_gettime(CLOCK_REALTIME, &now);

    double time_diff = (double)(now.tv_sec - data_point->timestamp) + (double)(now.tv_nsec - data_point->timestamp * 1e9) / 1e9;

    if (time_diff > 600) // 10 minutes
        return;

    window[sensor_id].count++;

    double dt = time_diff / 60; // convert to minutes
    window[sensor_id].max_age = fmin(window[sensor_id].max_age, dt);

    if (dt <= 5) {
        window[sensor_id].mean += (data_point->value - window[sensor_id].mean) / dt;
        window[sensor_id].variance += (data_point->value - window[sensor_id].mean) * (data_point->value - window[sensor_id].mean) * dt - window[sensor_id].variance * 2 * dt;
        window[sensor_id].peak = fmax(window[sensor_id].peak, data_point->value);
    }

    if (fabs(data_point->value - window[sensor_id].last_peak) > 3 * sqrt(window[sensor_id].variance))
        window[sensor_id].weighted_score += exp(-dt / 5); // decay with time

    window[sensor_id].last_peak = data_point->value;
}

int findMaxAnomaly() {
    int max_index = -1;
    double max_weighted_score = 0;

    for (size_t i = 0; i < NUM_SENSORS; ++i) {
        if (window[i].count != 0 && window[i].weighted_score > max_weighted_score) {
            max_index = i;
            max_weighted_score = window[i].weighted_score;
        }
    }

    return max_index;
}

void processData(const DataPoint *data_point) {
    updateWindow(data_point->sensor_id, data_point);

    static double total_points = 0, mean = 0, stddev = 0;
    static size_t point_count = 0;

    total_points++;
    point_count++;
    mean += (data_point->value - mean) / point_count;
    stddev = sqrt((data_point->value - mean) * (data_point->value - mean) * point_count - stddev * 2 * point_count);
}
