['1. Here is the Python code for calculating MD5 hashes of multiple files in a directory and its subdirectories:

```python
import os
import hashlib
import time
import logging
from concurrent.futures import ThreadPoolExecutor, as_completed

def md5_hash(file_path):
    hasher = hashlib.md5()
    with open(file_path, 'rb') as f:
        while True:
            data = f.read(8192)
            if not data:
                break
            hasher.update(data)
    return hasher.hexdigest()

def log_info(message):
    now = time.strftime('%Y-%m-%d %H:%M:%S', time.localtime())
    print(f"{now} - {message}")

def process_file(file, executor):
    start = time.time()
    file_hash = md5_hash(file)
    log_info(f'Processing {file} (start)')
    log_info(f'File size: {os.path.getsize(file)} bytes')
    end = time.time()
    log_info(f'Processing {file} (end, elapsed {end - start}s)')
    return file, file_hash, start, end

def calculate_hashes(directory, executor):
    files = []
    for root, dirs, files in os.walk(directory):
        for file in files:
            if not file.startswith('.'):
                files.append((root, file))
    tasks = [executor.submit(process_file, f, executor) for f in files]
    results = as_completed(tasks)
    for result in results:
        file, hash_, start, end = result.result()
        log_info(f'File {file} hashed ({hash_})')

def async_reduce(arr, initial, callback):
    with ThreadPoolExecutor() as executor:
        partials = [executor.submit(callback, arr[i], arr[j]) for i in range(len(arr)) for j in range(i+1, len(arr))]
        result = next(partials).result() if arr else initial
        for part in as_completed(partials):
            result = part.result(initial) if part.exception() is None else initial
        return result

def main():
    log_info('Starting...')
    directory = 'path/to/your/directory'
    executor = ThreadPoolExecutor(max_workers=4)
    calculate_hashes(directory, executor)
    executor.shutdown(wait=True)
    summary_report = _build_summary_report()
    log_info('\nSummary Report:\n')
    for line in summary_report:
        log_info(line)

def _build_summary_report():
    with open('file_sizes.txt', 'r') as file:
        sizes = [int(line.strip()) for line in file]
        total_size = sum(sizes)

    hashes = []
    with open('hashes.txt', 'r') as file:
        hashes = [file.readline().strip() for _ in range(len(sizes))]

    return (f'Total files processed: {len(sizes)}\n',
            f'Total size of all files: {total_size} bytes\n',
            '\n'.join(hashes))
```

  2. Here is the JavaScript code for an asynchronous reduction operation using `reduce()` method:

```javascript
async function asyncReduce(arr, initial, callback) {
  const promises = [];

  for (let i = 0; i < arr.length; i++) {
    for (let j = i + 1; j < arr.length; j++) {
      promises.push(new Promise((resolve, reject) => {
        callback(arr[i], arr[j])
          .then(value => resolve(value))
          .catch(error => reject(error));
      }));
    }
  }

  let result = initial;

  for (let promise of promises) {
    try {
      const currentResult = await promise;
      result = currentResult;
    } catch (error) {
      throw error;
    }
  }

  return result;
}
```

You can test the asyncReduce function with the following code:

```javascript
const numbers = [1, 2, 3, 4];
asyncReduce(numbers, 0, (acc, curr) => acc + curr)
  .then(result => console.log(`Result: ${result}`))
  .catch(error => console.error(`Error: ${error.message}`));
```

In this example, the result should be `10`, as expected. This code creates an array of numbers and uses asyncReduce to perform a reduction operation (sum) on them using the provided callback function. The result is then logged.']

