#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <openssl/sha.h>
#include <openssl/aes.h>
#include <pthread.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <sys/mman.h>

typedef struct {
    char name[64];
    long start_time;
    long end_time;
} record;

struct MD5Context;
typedef void* (*MD5Update)(struct MD5Context*, const char*, size_t);
typedef char* (*MD5Final)(struct MD5Context*);

struct MD5Context {
    unsigned char digest[16];
    unsigned int num;
    unsigned char data[4096];
};

const char base[] = "record_";
static pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
static long max_records = 1000; // configurable limit
static time_t seed = time(NULL);
static int fd_log, offset = 0;
static AES_KEY aes_key;

MD5Update md5_update;
MD5Final md5_final;

// Initialize MD5 context and update function pointers
void init_md5() {
    const EVP_MD *md = EVP_md5();
    md5_update = EVP_MD_CTX_new_with_digestfile(md);
    md5_final = EVP_MD_CTX_ctrl(md5_update, EVP_CTRL_MD_FINALIZE);
}

// Utility function to compute the MD5 hash of a given string
void compute_md5(const char *str) {
    EVP_MD_CTX_reset(md5_update);
    int ret = EVP_DigestUpdate(md5_update, str, strlen(str));
    if (ret <= 0) {
        perror("EVP_DigestUpdate");
        exit(EXIT_FAILURE);
    }
}

// Compute the concatenated MD5 hash of an array of strings
void compute_concatenated_md5(const char **strs, size_t n) {
    for (size_t i = 0; i < n; ++i) {
        compute_md5(strs[i]);
        if (i != n - 1)
            compute_md5(":"); // separator between strings in the hash
    }
}

// Create and validate records, dynamically allocating memory for tasks.
record* createNFATasksAndValidateRecords(int max_tasks, ...) {
    va_list args;
    int n = 0;
    record *records = NULL;

    // Ensure the maximum number of tasks does not exceed the system-wide limit
    if (max_tasks > max_records) {
        perror("Exceeded maximum records limit");
        return NULL;
    }

    records = malloc(sizeof(record) * max_tasks);
    if (!records) {
        perror("Failed to allocate memory for tasks");
        return NULL;
    }

    // Initialize the MD5 context and compute hashes for each record identifier and concatenated hashes of all strings
    init_md5();
    compute_concatenated_md5(records, max_tasks);

    char *hashes = malloc((max_tasks + 1) * sizeof(char *) * strlen(EVP_MD_CTX_get0_digest(md5_update)->md->md_name));
    if (!hashes) {
        perror("Failed to allocate memory for hashes");
        free(records);
        return NULL;
    }

    va_start(args, max_tasks);
    while (n < max_tasks && va_arg(args, int)) {
        const char *name = va_arg(args, const char*);
        long start_time = va_arg(args, long);
        long end_time = va_arg(args, long);

        // Validate input and ensure no two tasks overlap in their duration
        for (int i = 0; i < n; ++i) {
            if ((start_time <= records[i].start_time && start_time + (end_time - start_time) > records[i].end_time) ||
                (records[i].start_time <= start_time && records[i].end_time > end_time)) {
                perror("Task overlaps with existing task");
                free(hashes);
                free(records);
                return NULL;
            }
        }

        // Generate unique string identifiers for each record and compute their MD5 hashes
        snprintf(records[n].name, sizeof(records[n].name), "%s%ld", base, n);
        char *record_hash = malloc(sizeof(char) * strlen(EVP_MD_CTX_get0_digest(md5_update)->md->md_name));
        if (!record_hash) {
            perror("Failed to allocate memory for individual hashes");
            free(hashes);
            free(records);
            return NULL;
        }
        snprintf(record_hash, sizeof(char) * strlen(EVP_MD_CTX_get0_digest(md5_update)->md->md_name), "%s", EVP_MD_CTX_get0_digest(md5_update)->md->md_name);
        compute_md5(records[n].name);
        strcat(record_hash, ":"); // separator between the hash and the concatenated hash
        strcat(record_hash, EVP_MD_CTX_get0_digest(md5_update)->md->md_name);

        // Store hashes in a dynamically allocated array of strings
        char *hash = malloc((strlen(records[n].name) + strlen(record_hash)) * sizeof(char));
        if (!hash) {
            perror("Failed to allocate memory for concatenated hash");
            free(record_hash);
            free(hashes);
            free(records);
            return NULL;
        }
        strcpy(hash, records[n].name);
        strcat(hash, record_hash);
        hashes[(n * (sizeof(char *) * strlen(EVP_MD_CTX_get0_digest(md5_update)->md->md_name)) + offset++] = hash;

        // Encrypt the record's identifier and store it in the record structure
        AES_encrypt(reinterpret_cast<unsigned char*>(records[n].name), reinterpret_cast<unsigned char*>(records[n].name), &aes_key);

        records[n].start_time = start_time;
        records[n].end_time = end_time;
        ++n;
    }
    va_end(args);

    return records;
}
```

