    // Check memory usage threshold
    if (total_size > THRESHOLD) {
        fprintf(stderr, "Memory allocation failed: exceeded the specified limit of %d MB\n", THRESHOLD / (1024 * 1024));
        return NULL;
    }

    mlockall(MCL_CURRENT | MCL_FUTURE); // Lock memory for performance

    State* states = mmap(NULL, total_size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);

    if (states == MAP_FAILED) {
        perror("Memory allocation failed");
        return NULL;
