    pthread_attr_t attr;
    pthread_attr_init(&attr);
    pthread_attr_setdetachstate(&attr, PTHREAD_CREATE_JOINABLE);

    // Allocate and initialize NFAPI_CRC_INDICATION_PDU_T structures
    for (int i = 0; i < n; ++i) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        if (!pdu) {
            perror("Memory allocation failed");

            // Free previously allocated states and exit gracefully
            for (int j = 0; j < i; ++j) {
                free(states[j].next);
