        pdu->rnti = (uint16_t)(rand() % 65536);
        pdu->crc_indication_tag.value = rand();
        pdu->crcflag = rand() % 2;

        // Set state ID and next state pointer here based on the logic you want to implement
    }

    // Handle joined threads if needed
    pthread_attr_destroy(&attr);

    return states;
}
