    pthread_cond_t cond;
    queue_t queue;
    int max_threads;
    int num_threads;
    int total_allocated;
    int error_count;
} Allocator;

void *worker(void *arg) {
    Allocator *alloc = arg;
    while (1) {
        pthread_mutex_lock(&alloc->mutex);
        while (alloc->total_allocated >= alloc->max_threads || alloc->num_threads == alloc->max_threads) {
            pthread_cond_wait(&alloc->cond, &alloc->mutex);
        }
        if (alloc->error_count > 1000) {
            pthread_mutex_unlock(&alloc->mutex);
            break;
        }
        alloc->num_threads++;
        pthread_mutex_unlock(&alloc->mutex);

        NFAPI_CRC_INDICATION_PDU_T *pdu = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu) {
            alloc->error_count++;
            free(pdu);
            pthread_mutex_lock(&alloc->mutex);
            alloc->num_threads--;
            pthread_mutex_unlock(&alloc->mutex);
            continue;
        }

        // Populate the PDU structure with required fields
        // ...

        pthread_mutex_lock(&alloc->mutex);
        alloc->total_allocated++;
        pthread_mutex_unlock(&alloc->mutex)

        pthread_mutex_lock(&alloc->queue.mutex);
        enqueue(&alloc->queue, pdu);
        pthread_mutex_unlock(&alloc->queue.mutex);
    }
    return NULL;
}

Allocator *create_allocator(int max_threads) {
    Allocator *alloc = malloc(sizeof(Allocator));
    if (!alloc) {
        fprintf(stderr, "Error allocating memory for allocator\n");
        return NULL;
    }
    pthread_mutex_init(&alloc->mutex, NULL);
    pthread_cond_init(&alloc->cond, NULL);
    queue_init(&alloc->queue);
    alloc->max_threads = max_threads;
    alloc->num_threads = 0;
    alloc->total_allocated = 0;
    alloc->error_count = 0;
    return alloc;
}

NFAPI_CRC_INDICATION_PDU_T *dequeue(Allocator *alloc) {
    pthread_mutex_lock(&alloc->queue.mutex);
    NFAPI_CRC_INDICATION_PDU_T *pdu = dequeue(&alloc->queue);
    if (pdu) {
        alloc->num_threads--;
        pthread_mutex_unlock(&alloc->queue.mutex);
    } else {
        pthread_mutex_unlock(&alloc->queue.mutex);
        // Wait for a worker thread to free the resource
    }
    return pdu;
}
