        pthread_mutex_unlock(&connections_mutex);
        return;
    }
    num_connections++;
    connections = realloc(connections, sizeof(char *) * num_connections);
    connections[num_connections - 1] = strdup(conn_str);
    pthread_mutex_unlock(&connections_mutex);
}

void delete_connection(int index) {
    pthread_mutex_lock(&connections_mutex);
    if (index >= 0 && index < num_connections) {
        free(connections[index]);
        memmove(&connections[index], &connections[index + 1], sizeof(char *) * (num_connections - index - 1));
        connections = realloc(connections, sizeof(char *) * (num_connections - 1));
        num_connections--;
    }
    pthread_mutex_unlock(&connections_mutex);
}

void cleanup() {
    int i;

    pthread_mutex_lock(&connections_mutex);
    for (i = 0; i < num_connections; i++) {
