#include <stdlib.h>
#include <stdio.h>

typedef struct MemoryPool {
    void* buffer;
    size_t capacity;
    size_t allocated;
} MemoryPool;

MemoryPool* createMemoryPool(size_t size, size_t max) {
    MemoryPool* pool = malloc(sizeof(MemoryPool));
    if (!pool) return NULL;

    pool->capacity = max * size;
    pool->allocated = 0;
    pool->buffer = calloc(pool->capacity, size);
    if (!pool->buffer) {
        free(pool);
        return NULL;
    }

    return pool;
}

void* allocFromPool(MemoryPool* pool) {
    if (pool->allocated >= pool->capacity) return NULL;

    void* result = (char*)pool->buffer + pool->allocated;
    pool->allocated += sizeof(data_point);
    return result;
}

void freeToPool(MemoryPool* pool, void* ptr) {
    if (!ptr) return;

    pool->allocated -= sizeof(data_point);
}
```

