typedef struct data_point {
    double value;
    int timestamp;
    char* id;
    char* description;
    struct data_point* next;
} DataPoint;

DataPoint* createDataPoint(double val, int time, char* id, char* desc) {
    DataPoint* dp = malloc(sizeof(DataPoint));
    if (!dp) return NULL;

    dp->value = val;
    dp->timestamp = time;
    dp->id = strdup(id);
    dp->description = strdup(desc);
    dp->next = NULL;

    return dp;
}

void addToList(DataPoint** list, DataPoint* node) {
    if (!node || !list) return;

    DataPoint* current = *list;
    if (!current) {
        *list = node;
        return;
    }

    while (current->next) current = current->next;
    current->next = node;
}
