ResolutionResult resolveDns(const char *hostname) {
    ResolutionResult result = { 0 };
    struct hostent *host_info = NULL;
    struct in_addr **ip_list = NULL;
    int num_ips, i;

    // Perform DNS resolution using gethostbyname()
    host_info = gethostbyname(hostname);
    if (!host_info) {
        result.error = -1; // Hostname does not resolve
        return result;
    }

    ip_list = host_info->h_addr_list;
    num_ips = *ip_list == NULL ? 0 : (int)calloc(*ip_list - 1, sizeof(struct in_addr*));
    memcpy(&ip_list[1], ip_list, sizeof(struct in_addr*)*(num_ips-1));
    ip_list[num_ips] = NULL;

