#include <vector>
#include <algorithm>
#include <numeric>
#include <cmath>
#include <iostream>
#include <ctime>
#include <chrono>
#include <boost/random/normal_distribution.hpp>
#include <boost/math/tools/quantiles.hpp>

// Define a custom data structure for sensor readings
struct SensorReading {
    int id;
    double value;
    std::time_t timestamp;
};

class AnomalyDetector {
private:
    const int WINDOW_SIZE = 30 * 60; // 30 minutes in seconds
    std::vector<SensorReading> data;
    std::unordered_map<int, std::vector<double>> sensorDataHist;
    std::unordered_map<int, std::pair<double, double>> summaryStats; // median, IQR for each sensor type
    std::unordered_map<int, boost::random::normal_distribution<double>> models; // anomaly detection model
    int totalValidDataPoints = 0;
    std::chrono::steady_clock::time_point lastUpdate;

public:
    void process(const SensorReading& reading) {
        if (reading.value != std::numeric_limits<double>::valid()) || // Check for valid data and corrupted values
            !std::chrono::system_clock::to_time_t(reading.timestamp)) { // Check for invalid timestamps
            return;
        }

        int sensorId = reading.id;
        totalValidDataPoints++;

        auto now = std::chrono::steady_clock::now();
        auto elapsed = std::chrono::duration<double>(now - lastUpdate).count();
        if (elapsed > 1) { // Compute statistics and update models every second
            updateStats(sensorId);
            lastUpdate = now;
        }

        sensorDataHist[sensorId].push_back(reading.value);
        if (sensorDataHist[sensorId].size() > WINDOW_SIZE) {
            sensorDataHist[sensorId].pop_front(); // Maintain a rolling time window of the last 30 minutes
        }
    }

    std::pair<int, double> getAnomaly() const {
        int maxCIWidthSensorId = -1;
        double maxCIWidthValue = std::numeric_limits<double>::max();

        for (const auto& entry : summaryStats) {
            int sensorId = entry.first;
            const auto& [med, iqr] = entry.second;
            double ciWidth = calculateConfidenceInterval(sensorId);

            if (ciWidth < maxCIWidthValue) {
                maxCIWidthSensorId = sensorId;
                maxCIWidthValue = ciWidth;
            }
        }

        return std::make_pair(maxCIWidthSensorId, summaryStats.at(maxCIWidthSensorId).first); // Return the sensor ID with the widest confidence interval and its corresponding value
    }

private:
    void updateStats(int sensorId) {
        if (sensorDataHist.find(sensorId) == sensorDataHist.end()) return;

        auto sortedValues = sensorDataHist[sensorId];
        std::nth_element(sortedValues.begin(), std::next(sortedValues.begin(), WINDOW_SIZE / 2), sortedValues.end()); // Find median
        double median = *std::next(sortedValues.begin(), WINDOW_SIZE / 2);
        double iqr = sortedValues[WINDOW_SIZE * 0.75] - sortedValues[WINDOW_SIZE * 0.25];

        summaryStats[sensorId] = std::make_pair(median, iqr);

        boost::math::tools::quantiles<double> q(sortedValues); // Compute skewness
        double skew = (q(0.148) - 3 * median + q(0.852)) / iqr;

        models[sensorId] = boost::random::normal_distribution<double>(summaryStats[sensorId].first, sqrt(iqr + skew * skew / 6)); // Update anomaly detection model
    }

    double calculateConfidenceInterval(int sensorId) const {
        int sampleSize = static_cast<int>(summaryStats.at(sensorId).second.second * 1.34 + 0.5); // Adjust for bootstrap method and the fact that we're using a normal distribution as our model
        std::vector<double> bootstrapSamples;

        for (size_t i = 0; i < sampleSize; ++i) {
            int index = rand() % sensorDataHist[sensorId].size();
            bootstrapSamples.push_back(sensorDataHist[sensorId][index]);
        }

        std::sort(bootstrapSamples.begin(), bootstrapSamples.end());
        double q1 = bootstrapSamples[sampleSize * 0.25];
        double q3 = bootstrapSamples[sampleSize * 0.75];
        return q3 - q1; // Confidence interval is the IQR of the bootstrap samples
    }
};
