    fl->num_frames = 0;
    pthread_mutex_init(&fl->mutex, NULL);
    sem_init(&fl->rate_limiter, 0, MAX_FRAMES);
}

MAC_HEADER_T* allocate_frame(struct FrameList* fl) {
    MAC_HEADER_T *frame;
    struct FrameListNode *new_node = (struct FrameListNode*)malloc(sizeof(struct FrameListNode) + ALIGNMENT - 1);

    if (!new_node) return NULL;

    frame = &new_node->frame;
    new_node->next = fl->head;
    fl->head = new_node;
    ++fl->num_frames;

    return frame;
}

int process_frame(MAC_HEADER_T* frame) {
