}

void framelist_process(struct FrameList* fl, int num_frames_to_process) {
    struct FrameListNode* current = fl->head;
    size_t processed = 0;

    pthread_mutex_lock(&fl->mutex);

    for (size_t i = 0; i < num_frames_to_process && current != NULL; ++i) {
        if (current->frame.seq_number == 0 || process_frame(current->frame) < 0) {
            ++fl->num_frames; // Reclaim the memory if processing fails or frame has an invalid sequence number
            current = current->next;
            continue;
        }
        processed++;
        current = current->next;
    }

    pthread_mutex_unlock(&fl->mutex);

    printf("Processed: %zu frames, Valid: %zu, Invalid: %zu\n", fl->num_frames - processed, processed, fl->num_frames);
}

void* rate_limiter(void *arg) {
    sem_wait(&((struct FrameList*)arg)->rate_limiter);
    return 0;
}
