    sw->total_value = 0.0;
    sw->cumulative_weighted_sum = 0.0;

    struct dynamic_array data_arr;
    da_init(&data_arr, window_size);
    sw->data = (Transaction**) mmap(NULL, sizeof(Transaction*) * window_size, PROT_READ | PROT_WRITE, MAP_PRIVATE | MAP_ANONYMOUS, -1, 0);
    for (size_t i = 0; i < window_size; ++i) {
        sw->data[i] = data_arr.base + i;
    }

    return sw;
}

void sw_push(struct sliding_window *sw, Transaction t) {
    sem_wait(&sw->lock);

    if (difftime(time(NULL), t.timestamp) > 5) {
        sem_post(&sw->lock);
        return;
    }

    ++sw->num_transactions;
    sw->total_value += t.value;

    // Adaptive data fetching strategy based on system metrics and data availability
    if (sw->num_transactions >= sw->window_size) {
        size_t oldest = 0;
        for (size_t i = 1; i < sw->window_size; ++i) {
            if (da_get_timestamp(sw->data[oldest]) > da_get_timestamp(sw->data[i])) {
                oldest = i;
            }
        }
        Transaction *oldest_txn = sw->data[oldest];
        sw->total_value -= oldest_txn->value;
        --sw->num_transactions;
        da_pop(sw->data[oldest]);
    }

    sw->cumulative_weighted_sum += t.value * sw->weight_factor;
    sw->weight_factor *= (double)(sw->window_size - sw->num_transactions) / sw->window_size;

    sem_post(&sw->lock);
}

Transaction* process_transactions(struct sliding_window *sw, size_t buffer_size) {
    struct dynamic_array transaction_buffer;
    da_init(&transaction_buffer, buffer_size);

    Transaction *highest_txn = NULL;
    double highest_weighted_sum = 0.0;
    size_t total_processed = 0;

    sem_wait(&sw->lock);
    for (size_t i = sw->num_transactions - 1; i < sw->window_size && i < da_get_length(sw->data); ++i) {
        if (difftime(time(NULL), da_get_timestamp(sw->data[i])) <= 5) {
            da_push(&transaction_buffer, sw->data[i]);
            total_processed++;

            double weight = sw->weight_factor * sw->num_transactions / (double)sw->window_size;
            if (weight > highest_weighted_sum) {
                highest_txn = sw->data[i];
                highest_weighted_sum = weight;
            }
        }
    }
    sem_post(&sw->lock);

    // Process the transactions in the buffer using multi-threading and log them
    pthread_t threads[buffer_size];
    for (size_t i = 0; i < buffer_size; ++i) {
        pthread_create(&threads[i], NULL, process_transaction_in_thread, &transaction_buffer);
    }
    for (size_t i = 0; i < buffer_size; ++i) {
        pthread_join(threads[i], NULL);
    }

    Transaction* result = malloc(sizeof(Transaction));
    memcpy(result, highest_txn, sizeof(Transaction));

    // Update the sliding window metrics with the processed transactions and return results
    sw->num_transactions -= total_processed;
    for (size_t i = 0; i < total_processed; ++i) {
        sw_push(sw, transaction_buffer.base[i]);
        log_transaction(transaction_buffer.base[i]);
    }

    free(result); // Clear data in the allocated structure to ensure responsiveness and low memory usage under different load conditions
    da_destroy(&transaction_buffer);

    return highest_txn;
}

