#include <arpa/inet.h>
#include <netdb.h>
#include <pthread.h>
#include <sys/socket.h>
#include <unistd.h>
#include <errno.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_QUERIES 100
#define MAX_RETRIES 3
#define MAX_HOSTNAME_LENGTH 256
#define BACKOFF_FACTOR 2

typedef struct {
    char hostname[MAX_HOSTNAME_LENGTH];
    int sockfd;
    struct addrinfo *result;
    pid_t tid;
    enum { FREE, IN_PROGRESS, FAILED } status;
} query_data_t;

pthread_mutex_t query_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t query_cv = PTHREAD_COND_INITIALIZER;
int num_queries = 0;

int dns_query(const char *hostname) {
    int err = 0;
    struct addrinfo hints, *res;
    memset(&hints, 0, sizeof(hints));
    hints.ai_family = AF_UNSPEC; // IPv4 or IPv6
    hints.ai_socktype = SOCK_STREAM;

    err = getaddrinfo(hostname, NULL, &hints, &res);
    if (err != 0) {
        return errno;
    }

    query_data_t *query_data = malloc(sizeof(query_data_t));
    strncpy(query_data->hostname, hostname, MAX_HOSTNAME_LENGTH);
    query_data->sockfd = -1;
    query_data->result = res;
    query_data->tid = 0;
    query_data->status = FREE;

    pthread_mutex_lock(&query_mutex);
    while (num_queries >= MAX_QUERIES) {
        pthread_cond_wait(&query_cv, &query_mutex);
    }
    num_queries++;
    query_data->tid = pthread_self();
    query_data->status = IN_PROGRESS;
    pthread_mutex_unlock(&query_mutex);

    int retries = 0;
    while (retries < MAX_RETRIES) {
        err = pthread_create(&query_data->tid, NULL, dns_worker, query_data);
        if (err == 0) {
            break;
        }
        sleep(1 << BACKOFF_FACTOR * retries); // exponential backoff
        retries++;
    }

    if (retries == MAX_RETRIES && err != 0) {
        free(query_data);
        return EAI_AGAIN; // retry later
    }

    return 0;
}

void* dns_worker(void *arg) {
    query_data_t *query_data = arg;
    int sockfd = socket(query_data->result->ai_family, query_data->result->ai_socktype, query_data->result->ai_protocol);
    if (sockfd == -1) {
        fprintf(stderr, "socket() failed: %s\n", strerror(errno));
        query_data->status = FAILED;
        free(query_data);
        pthread_mutex_lock(&query_mutex);
        num_queries--;
        pthread_mutex_unlock(&query_mutex);
        return NULL;
    }

    int err = connect(sockfd, query_data->result->ai_addr, query_data->result->ai_addrlen);
    if (err == 0) {
        // handle successful connection here
        query_data->status = FREE;
        close(sockfd);
        free(query_data);
        pthread_mutex_lock(&query_mutex);
        num_queries--;
        pthread_cond_signal(&query_cv);
        pthread_mutex_unlock(&query_mutex);
        return NULL;
    } else if (errno != EINPROGRESS) { // EINPROGRESS means connection in progress, handled below
        fprintf(stderr, "connect() failed: %s\n", strerror(errno));
        query_data->status = FAILED;
        close(sockfd);
        free(query_data);
        pthread_mutex_lock(&query_mutex);
        num_queries--;
        pthread_cond_signal(&query_cv);
        pthread_mutex_unlock(&query_mutex);
        return NULL;
    }

    fd_set master_fds, read_fds;
    FD_ZERO(&master_fds);
    FD_ZERO(&read_fds);
    FD_SET(sockfd, &master_fds);

    struct timeval tv = { 10, 0 }; // 10ms timeout
    int max_fd = sockfd;

    while (1) {
        read_fds = master_fds;
        select(max_fd + 1, &read_fds, NULL, NULL, &tv);

        if (FD_ISSET(sockfd, &read_fds)) {
            // handle successful connection here
            query_data->status = FREE;
            close(sockfd);
            free(query_data);
            pthread_mutex_lock(&query_mutex);
            num_queries--;
            pthread_cond_signal(&query_cv);
            pthread_mutex_unlock(&query_mutex);
            return NULL;
        }
    }

    // This should never be reached, but if it is, indicate an error and cleanup resources.
    fprintf(stderr, "dns_worker() exited unexpectedly\n");
    query_data->status = FAILED;
    close(sockfd);
    free(query_data);
    pthread_mutex_lock(&query_mutex);
    num_queries--;
    pthread_cond_signal(&query_cv);
    pthread_mutex_unlock(&query_mutex);
    return NULL;
}
