typedef struct {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

#define STR_LEN 64
#define HASH_SIZE SHA256_DIGEST_LENGTH
#define MAX_RETRIES 3
#define MD5_HASH_BUF_SIZE (HASH_SIZE * 2 + 1)

void populateNFAPICRCWithTasks(int max_tasks, int key_size, AES_KEY *aes_ctx) {
    pthread_mutex_t mutex;
    pthread_cond_t cond;
    int tasks_count = 0;
    NFAPI_CRC_INDICATION_PDU_T* tasks;
    char* keys;
    long* offsets;
    char** hashes;
    char record_id[STR_LEN];

    pthread_mutex_init(&mutex, NULL);
    pthread_cond_init(&cond, NULL);

    // Allocate memory for arrays, handle edge cases and validate sizes to prevent buffer overflows.
    tasks = malloc(max_tasks * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    keys = calloc(key_size, sizeof(char));
    offsets = calloc(max_tasks, sizeof(long));
    hashes = mmap(NULL, max_tasks * MD5_HASH_BUF_SIZE, PROT_READ | PROT_WRITE, MAP_SHARED | MAP_ANONYMOUS, -1, 0);

    if (!tasks || !keys || !offsets || !hashes) {
        fprintf(stderr, "Memory allocation failed!\n");
        exit(EXIT_FAILURE);
    }

    // Initialize AES context and populate tasks.
    for (int i = 0; i < max_tasks && tasks_count < max_tasks; ++i) {
        do {
            // Generate unique string identifier and compute its MD5 hash.
            snprintf(record_id, STR_LEN, "record_%lu_%ld_%d", (long)time(NULL), (long)getpid(), rand());

            SHA256((unsigned char*)record_id, strlen(record_id), hashes[tasks_count]);

        } while (tasks_count > 0 && memcmp(hashes[tasks_count], hashes[tasks_count - 1], MD5_HASH_BUF_SIZE) == 0);

        tasks[i].tag.rnti = htons(ntohs(tasks[i-1].tag.rnti) + 1); // Increment RNTI value for each new task.
        tasks[i].tag.crc = 0;
        tasks[i].rnti = ntohs(tasks[i].tag.rnti);
        tasks[i].crc_indication.value = rand() % 2;

        strncpy(keys + i * key_size, &tasks[i].rnti, sizeof(int)); // Store keys in corresponding positions.
        offsets[tasks_count] = i;
        tasks_count++;
    }

    // Cleanup and handle exceptions.
    munmap(hashes, max_tasks * MD5_HASH_BUF_SIZE);
    free(keys);
    free(offsets);
    pthread_mutex_destroy(&mutex);
    pthread_cond_destroy(&cond);
}
