class DnsResolver {
public:
    explicit DnsResolver(b::io_service& io_service) : resolver_(io_service), cache_(), lock_() {}

    int resolve(const char* hostname, ip_address& ip_addr);

private:
    b::io_service& resolver_;
    b::cache_1<std::string, addrinfo*> cache_;
    mutex lock_;
};

int DnsResolver::resolve(const char* hostname, ip_address& ip_addr) {
    auto start = std::chrono::steady_clock::now();
    auto it = cache_.find(hostname);
    if (it != cache_.end()) {
        // Use cached address if available
        memcpy(ip_addr, it->second->ai_addr, it->second->ai_addrlen);
        return 0;
    }

    auto query = make_shared<b::query*>(hostname);
    auto handler = [this, hostname, ip_addr](const b::system_error& error, const b::query* query) {
        if (!error) {
            // Use resolved address and update cache
            memcpy(ip_addr, query->result()->ai_addr, query->result()->ai_addrlen);
            lock_.lock();
            auto old_it = cache_.insert({hostname, query->result()});
            lock_.unlock();
            return 0;
        } else {
            // Handle error, e.g., by retrying or returning an error code
            return -1;
        }
    };

    resolver_.async_resolve(query->query(), *handler);
    auto elapsed = std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now() - start).count();
    if (elapsed > timeout_) {
        // Handle timeout, e.g., by returning an error code
        return -2;
    }
    return 0;
}

