    size_t capacity;
    size_t size;
    NFAPI_CRC_INDICATION_PDU_T* data;
    void(*destroy)(NFAPI_CRC_INDICATION_PDU_T*);
} NFAPI_CRC_INDICATION_LIST_T;

static inline void init_version(void** data, size_t size) {
    *data = calloc(size, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!*data) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        exit(-1);
    }
}

static void destroy_version(NFAPI_CRC_INDICATION_PDU_T* data) {
    free(data);
}

void nfapi_crc_indication_list_init(NFAPI_CRC_INDICATION_LIST_T** list, size_t capacity) {
    if (capacity > 1024) {
        fprintf(stderr, "Error: Capacity must be less than or equal to 1024.\n");
        return;
    }

    *list = malloc(sizeof(NFAPI_CRC_INDICATION_LIST_T));
    if (!*list) {
        fprintf(stderr, "Error: Memory allocation failed.\n");
        exit(-1);
    }

    init_version(&(*list)->data, capacity);
    (*list)->capacity = capacity;
    (*list)->size = 0;
    (*list)->destroy = destroy_version;
}

void nfapi_crc_indication_list_push(NFAPI_CRC_INDICATION_LIST_T* list, const NFAPI_CRC_INDICATION_PDU_T* element) {
    if (list->size == list->capacity) {
        size_t new_capacity = (list->capacity * 2 > 1024) ? 1024 : (list->capacity * 2);
        NFAPI_CRC_INDICATION_PDU_T* new_data = realloc(list->data, new_capacity * sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!new_data) {
            fprintf(stderr, "Error: Memory allocation failed.\n");
            exit(-1);
        }
        list->data = new_data;
        list->capacity = new_capacity;
    }

    bool unique = true;
    for (size_t i = 0; i < list->size; ++i) {
        if ((list->data[i].RX_UE_INFORMATION_TAG == element->RX_UE_INFORMATION_TAG) &&
            (list->data[i].RNTI == element->RNTI)) {
            unique = false;
            break;
        }
    }

    if (unique) {
        list->data[list->size++] = *element;
        printf("Element added: Size %zu, Elements added %zu\n", list->capacity, list->size);
    } else {
        fprintf(stderr, "Error: Duplicate element encountered.\n");
    }
}

void nfapi_crc_indication_list_perform_tracking() {
    printf("Allocations: %zu\n", (size_t)calloc(1, sizeof(NFAPI_CRC_INDICATION_PDU_T)) + 1); // Initial allocation
    printf("Deallocations: %zu\n", (size_t)(*list)->destroy(*list->data));                // Destroy at the end
}
