    }
    sem_post(&mutex);

    // Periodic garbage collection and efficient memory deallocation
    if (num_entries > 0) {
        for (unsigned int i = num_entries - 1; i > 0 && num_entries > limit / 2; --i) {
            if (list[i].rnti == list[i - 1].rnti) {
                memmove(&list[i], &list[i + 1], (num_entries - i - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
                --num_entries;
            }
        }
    }

    return list;
}

