// Configuration structure for forbidden extensions and maximum length of the new extension.
struct Config {
    size_t max_ext_len;
    char* forbidden_exts[];
};

// Function to extract directory path, filename, and file extension from the input filename.
char* get_base_name(const char* filename) {
    const size_t path_len = strlen(filename);
    for (size_t i = path_len; i > 0 && filename[i] != '/' && filename[i] != '\\'; --i) {}
    size_t start = (i == 0) ? 0 : i + 1;
    return strdup(&filename[start]);
}

// Function to determine the number of digits to append to the new extension.
size_t get_digit_count(const char* filename) {
    size_t digit_count = 0;
    for (const char* p = filename; *p != '\0'; ++p) {
        if (isalpha(*p)) continue;
        if (isdigit(*p)) ++digit_count;
    }
    return digit_count;
}

// Function to check if the given extension is forbidden.
bool is_forbidden(const char* ext, struct Config* config) {
    const size_t num_exts = sizeof(config->forbidden_exts) / sizeof(char*);
    for (size_t i = 0; i < num_exts; ++i) {
        if (!strcmp(ext + 1, config->forbidden_exts[i])) return true;
    }
    return false;
}

// Function to check if the given filename exceeds the maximum length.
bool is_within_length(const char* filename, struct Config* config) {
    return strlen(filename) <= config->max_ext_len;
}

// Function to modify the extension based on the given criteria and return the modified filename as a new string.
char* modify_extension(const char* filename, struct Config* config) {
    if (!is_within_length(filename, config)) return strdup("Filename exceeds maximum length.");

    const char* base = get_base_name(filename);
    size_t digit_count = get_digit_count(base);
    size_t ext_len = strlen(strchr(base, '.') ? "" : ".");
    ext_len += digit_count;

    if (ext_len > config->max_ext_len) {
        free(base);
        return strdup("Extension too long after appending digits.");
    }

    char* new_filename = malloc(strlen(filename) + ext_len + 1);
    strcpy(new_filename, filename);

    // Append the calculated number of digits to the existing extension if it does not already contain a digit; otherwise, append a sequence of random digits of the same length.
    char* dot = strrchr(new_filename, '.');
    if (!dot) {
        dot = new_filename + strlen(new_filename);
        *dot++ = '.';
        *dot = '\0';
    }

    size_t ext_len2 = strlen(dot);
    if (ext_len2 < digit_count && !isdigit(*dot)) {
        strcpy(dot, &base[digit_count]);
    } else {
        char digits[digit_count + 1];
        for (size_t i = 0; i < digit_count; ++i) digits[i] = '0' + rand() % 10;
        strcpy(dot, digits);
    }

    free(base);
    return new_filename;
}

// The C function that takes a filename as input and modifies its extension based on the given criteria.
char* modify_file_extension(const char* filename, struct Config* config) {
    if (is_forbidden(strchr(filename, '.'), config)) return strdup("Forbidden extension detected.");
    return modify_extension(filename, config);
}
