#include "mac_frame_allocator.h"
#include <stdio.h>
#include <stdlib.h>
#include <pthread.h>
#include <semaphore.h>

// Error codes and constants
#define ERROR_OUT_OF_MEMORY -1
#define ERROR_INVALID_FRAME_SIZE -2
#define MAX_FRAME_SIZE 0x7fff
#define MAX_FRAMES_PER_ALLOCATION 8192
#define SEMAPHORE_COUNT 4

// Linked list node structure
typedef struct mac_frame_node {
    MAC_HEADER_T frame;
    struct mac_frame_node* next;
} MAC_FRAME_NODE;

// Global semaphore for rate limiting
sem_t allocator_semaphore[SEMAPHORE_COUNT];

int mac_frame_allocator(MAC_HEADER_T** frames, size_t max_frames, size_t* processed_frames) {
    MAC_FRAME_NODE* current_list = NULL;
    MAC_FRAME_NODE** linked_list = &current_list;
    int valid_frames = 0;
    int total_attempts = 0;

    // Allocate memory for MAX_FRAMES_PER_ALLOCATION frames
    size_t frames_to_allocate = (max_frames < MAX_FRAMES_PER_ALLOCATION) ? max_frames : MAX_FRAMES_PER_ALLOCATION;
    *frames = malloc(frames_to_allocate * sizeof(MAC_HEADER_T));
    if (!(*frames)) {
        fprintf(stderr, "Error: Out of memory\n");
        return ERROR_OUT_OF_MEMORY;
    }
    total_attempts += frames_to_allocate;

    // Process each frame and add it to the linked list if valid
    for (size_t i = 0; i < frames_to_allocate; ++i) {
        sem_wait(&allocator_semaphore[i % SEMAPHORE_COUNT]);

        // Perform integrity checks and validate frame size
        if ((*frames)[i].payload_size > MAX_FRAME_SIZE) {
            fprintf(stderr, "Error: Invalid frame size\n");
            continue;
        }

        ++valid_frames;
        *linked_list = realloc(*linked_list, sizeof(MAC_FRAME_NODE) + valid_frames * sizeof(MAC_HEADER_T));
        if (!*linked_list) {
            fprintf(stderr, "Error: Out of memory\n");
            sem_post(&allocator_semaphore[i % SEMAPHORE_COUNT]);
            return ERROR_OUT_OF_MEMORY;
        }

        // Copy the frame and set the alignment
        (*linked_list)->frame = (*frames)[i];
        memset((char*)(*linked_list) + sizeof(MAC_FRAME_NODE), 0, valid_frames * sizeof(MAC_HEADER_T));
        for (size_t j = 0; j < valid_frames; ++j) {
            ((uintptr_t)&((*linked_list)->frame)) &= ~15U; // Align to 16-byte boundary
        }
        *linked_list += sizeof(MAC_FRAME_NODE) + valid_frames * sizeof(MAC_HEADER_T);

        sem_post(&allocator_semaphore[i % SEMAPHORE_COUNT]);
    }

    // Store the number of processed frames
    *processed_frames = valid_frames;

    return 0;
}
```

