#include <stdio.h>
#include <stdlib.h>
#include <stdbool.h>
#include <pthread.h>
#include <semaphore.h>

#define MAX_ELEMENTS 4096
#define UNIQUE_ID_OFFSET 32

typedef struct {
    uint32_t tx_stream_id;
    uint8_t transmission_type;
    bool transmission_status;
} PHY_LAYER_TRANSACTION_T;

typedef struct NODE {
    PHY_LAYER_TRANSACTION_T data;
    struct NODE *next;
} NODE;

struct LIST {
    uint64_t allocations;
    uint64_t deallocations;
    sem_t lock;
    NODE* head;
    NODE* tail;
    size_t size;
};

void init_list(struct LIST* list) {
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    sem_init(&list->lock, 0, 1);
}

NODE* create_node(PHY_LAYER_TRANSACTION_T data) {
    NODE* new_node = (NODE*)malloc(sizeof(NODE));
    if (!new_node) return NULL;
    new_node->data = data;
    new_node->next = NULL;
    return new_node;
}

void insert_node(struct LIST* list, NODE* node) {
    sem_wait(&list->lock);
    if (list->head) {
        list->tail->next = node;
        list->tail = node;
    } else {
        list->head = list->tail = node;
    }
    sem_post(&list->lock);
}

NODE* remove_node(struct LIST* list) {
    sem_wait(&list->lock);
    NODE* temp = list->head;
    if (temp) {
        list->head = temp->next;
        if (!list->head) list->tail = NULL;
    }
    sem_post(&list->lock);
    return temp;
}

PHY_LAYER_TRANSACTION_T* find_unique_id(struct LIST* list, uint32_t id) {
    sem_wait(&list->lock);
    NODE* current = list->head;
    while (current != NULL) {
        if (current->data.tx_stream_id == id) {
            sem_post(&list->lock);
            return &current->data;
        }
        current = current->next;
    }
    sem_post(&list->lock);
    return NULL;
}

void log_operation(struct LIST* list, size_t operation, uint32_t id) {
    printf("Operation %ld: Size - %zu, Element ID - %u\n", operation, list->size, id);
}

void resize_list(struct LIST* list, size_t new_size) {
    if (new_size <= list->size) return;

    NODE** nodes = realloc(list->head, new_size * sizeof(NODE));
    if (!nodes) return;

    list->head = nodes;
    for (size_t i = list->size; i < new_size; ++i) {
        list->head[i] = NULL;
    }
}

struct LIST* manage_list(void) {
    struct LIST* list = (struct LIST*)malloc(sizeof(struct LIST));
    if (!list) return NULL;
    init_list(list);

    void* buffer;
    size_t new_size;

    while (true) {
        PHY_LAYER_TRANSACTION_T data = // get transaction data from user input

        uint32_t id = data.tx_stream_id;
        NODE* found = find_unique_id(list, id);

        if (found) {
            PHY_LAYER_TRANSACTION_T* original_data = &found->data;
            uint32_t unique_id = id | (original_data->tx_stream_id << UNIQUE_ID_OFFSET);
            data.tx_stream_id = unique_id;
        }

        NODE* new_node = create_node(data);
        if (!new_node) break;

        insert_node(list, new_node);
        ++list->size;
        log_operation(list, 1, id);

        if (list->size >= MAX_ELEMENTS) {
            resize_list(list, list->size * 2);
        }
    }

    free(list);

    return NULL;
}
```
