NFAPI_CRC_INDICATION_PDU_T* create_array(size_t N) {
    if (N <= 0) return NULL;

    NFAPI_CRC_INDICATION_PDU_T *arr = (NFAPI_CRC_INDICATION_PDU_T *) malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!arr) {
        fprintf(stderr, "Error: Allocation failed\n");
        return NULL;
    }

    size_t i = 0;
    srand(time(NULL));

    for (i = 0; i < N - 1; ++i) {
        arr[i].rnti = i + 1;
        arr[i].crcflag = rand() % 2;

        // Check for unique RNTIs and CRCF Flags
        for (size_t j = i + 1; j < N; ++j) {
            if ((arr[i].rnti == arr[j].rnti) || (arr[i].crcflag == arr[j].crcflag && abs(i - j) == 1)) {
                free(arr);
                fprintf(stderr, "Error: Memory allocation failed due to invalid input\n");
                return NULL;
