    HashNode** table;
    pthread_mutex_t lock;
};

HashTable* create_hash_table(unsigned int size) {
    // Initialize hash table with given size and empty slots
    HashTable* table = malloc(sizeof(HashTable));
    if (!table) {
        fprintf(stderr, "Error: Out of memory\n");
        return NULL;
    }
    table->size = size;
    table->table = calloc(size, sizeof(HashNode*));
    if (!table->table) {
        fprintf(stderr, "Error: Out of memory\n");
        free(table);
        return NULL;
    }
    table->lock = PTHREAD_MUTEX_INITIALIZER;
    return table;
}

void destroy_hash_table(HashTable* table) {
    if (!table) return;
    for (unsigned int i = 0; i < table->size; ++i) {
        HashNode* node = table->table[i];
        while (node) {
            HashNode* temp = node;
            node = node->next;
            free(temp);
        }
    }
    free(table->table);
    free(table);
}

HashNode* find_record(HashTable* table, int key) {
    // Find the given record in the hash table
    unsigned int index = hash(key);
    pthread_mutex_lock(&table->lock);
    HashNode* current = table->table[index];
    while (current != NULL && current->record.key != key) {
        current = current->next;
    }
    pthread_mutex_unlock(&table->lock);
    return current;
}

int insert_record(HashTable* table, int key, long offset) {
    // Insert a new record into the hash table with the given key and offset
    if (find_record(table, key)) {
        return -1; // Key already exists
    }
    unsigned int index = hash(key);
    pthread_mutex_lock(&table->lock);
    HashNode* new_node = malloc(sizeof(HashNode));
    if (!new_node) {
        fprintf(stderr, "Error: Out of memory\n");
        pthread_mutex_unlock(&table->lock);
        return -1;
    }
    new_node->record.key = key;
    new_node->record.offset = offset;
    new_node->next = table->table[index];
    table->table[index] = new_node;
    pthread_mutex_unlock(&table->lock);
    return 0; // Successfully inserted
}

