#include <iostream>
#include <cstdlib>
#include <new>
#include <exception>
#include <stdexcept>
#include <vector>

struct NFAPI_CRC_INDICATION_PDU_T {
    RX_UE_INFORMATION_TAG tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crcIndication;
    bool crcFlag;
};

class Node {
public:
    NFAPI_CRC_INDICATION_PDU_T data;
    Node* next;
    Node* prev;

    Node(const NFAPI_CRC_INDICATION_PDU_T& data, Node* next = nullptr, Node* prev = nullptr) : data(data), next(next), prev(prev) {}
};

class DynamicList {
private:
    std::vector<Node*> nodes;
    Node* head = nullptr;
    Node* tail = nullptr;

public:
    ~DynamicList() {
        while (!nodes.empty()) {
            pop_back();
        }
    }

    void push_front(const NFAPI_CRC_INDICATION_PDU_T& data) {
        if (head == nullptr) {
            head = new Node(data);
            tail = head;
        } else {
            Node* newNode = new Node(data, head, nullptr);
            head->prev = newNode;
            head = newNode;
        }
        nodes.push_back(head);
    }

    void push_back(const NFAPI_CRC_INDICATION_PDU_T& data) {
        if (tail == nullptr) {
            tail = new Node(data);
            head = tail;
        } else {
            Node* newNode = new Node(data, nullptr, tail);
            tail->next = newNode;
            tail = newNode;
        }
        nodes.push_back(tail);
    }

    void remove(size_t index) {
        if (index >= nodes.size()) {
            throw std::out_of_range("Index out of range");
        }

        Node* nodeToRemove = nodes[index];
        if (index == 0) {
            head = head->next;
            if (head != nullptr) {
                head->prev = nullptr;
            } else {
                tail = nullptr;
            }
            nodes.erase(nodes.begin());
        } else if (index == nodes.size() - 1) {
            tail = tail->prev;
            nodes.pop_back();
        } else {
            nodeToRemove->prev->next = nodeToRemove->next;
            nodeToRemove->next->prev = nodeToRemove->prev;
            nodes.erase(nodes.begin() + index);
        }
        delete nodeToRemove;
    }

    void iterate_and_print_rnti() const {
        for (const auto& node : nodes) {
            std::cout << node->data.rnti << std::endl;
        }
    }
};
