void init_hash_map(hash_map_t* map, size_t capacity) {
    map->capacity = capacity;
    map->num_elements = 0;
    map->array = calloc(capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T*));
}

void resize_hash_map(hash_map_t* map) {
    if (map->num_elements >= map->capacity) {
        size_t new_capacity = map->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T** new_array = realloc(map->array, sizeof(NFAPI_CRC_INDICATION_PDU_T*) * new_capacity);
        if (!new_array) {
            fprintf(stderr, "Failed to resize hash map\n");
            exit(EXIT_FAILURE);
        }
        map->array = new_array;
        map->capacity = new_capacity;
    }
}

size_t get_hash(const NFAPI_CRC_INDICATION_PDU_T* data, size_t capacity) {
    uint64_t hash = 0;
    for (size_t i = 0; i < sizeof(NFAPI_CRC_INDICATION_PDU_T); ++i) {
        hash = (hash * 31 + data[i]) % capacity;
    }
    return hash;
}

bool insert_data(hash_map_t* map, const NFAPI_CRC_INDICATION_PDU_T* data) {
    size_t index = get_hash(data, map->capacity);
    resize_hash_map(map);

    while (map->array[index]) {
        if (map->array[index]->tag == data->tag) {
            return false; // Collision: update the value instead of inserting a new one.
        }
        ++index = (index + 1) % map->capacity;
    }

    map->array[index] = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    *map->array[index] = *data;
    ++map->num_elements;
    return true; // Successfully inserted the data.
}

void* generate_rnti() {
    static uint32_t seed = 1;
    uint64_t xorshift128plus_state = (seed << 12) ^ (seed << 25) ^ (seed >> 37);
    intptr_t rnti;
    memcpy(&rnti, &xorshift128plus_state, sizeof(rnti));
    return &rnti;
}

void generate_crcflag() {
    static uint64_t seed = 0xdeadbeef; // Seed can be changed as needed for reproducibility.
    uint32_t crcflag;
    memcpy(&crcflag, &seed, sizeof(crcflag));
    seed = (36969 * seed + 12345) & 0xFFFFFFFF; // Simple and fast method for generating a uniformly distributed integer.
}

NFAPI_CRC_INDICATION_PDU_T* create_data(uint32_t* rnti, uint64_t seed) {
