    data->tag = get_hash(*rnti) % MAX_TAGS; // Assign a valid RX_UE_INFORMATION_TAG based on the RNTI.
    data->cindication.CRCFLAG = 0; // Initialize the CRCFLAG with zero, to be set later.
    generate_crcflag(); // Set a random value for the CRCFLAG using the provided seed.
    return data;
}

void cleanup(NFAPI_CRC_INDICATION_PDU_T** array, size_t num_elements) {
    for (size_t i = 0; i < num_elements; ++i) {
