    }
    free(array);
}

void create_data_array(NFAPI_CRC_INDICATION_PDU_T** array, size_t* num_elements, size_t capacity, uint64_t seed) {
    hash_map_t map;
    init_hash_map(&map, capacity);

    // Use posix_memalign to ensure proper alignment of the dynamically allocated memory.
    if (posix_memalign(array, sizeof(NFAPI_CRC_INDICATION_PDU_T), num_elements * sizeof(NFAPI_CRC_INDICATION_PDU_T))) {
        fprintf(stderr, "Failed to allocate memory for data array\n");
        exit(EXIT_FAILURE);
    }

    for (size_t i = 0; i < *num_elements; ++i) {
        uint32_t* rnti = malloc(sizeof(uint32_t));
        NFAPI_CRC_INDICATION_PDU_T* data = create_data(rnti, seed);

        while (!insert_data(&map, data)) {
            // Backoff strategy when memory allocation fails.
            usleep(1000 * (rand() % 5 + 1));
            if (i > *num_elements) {
                fprintf(stderr, "Memory allocation and collision handling failed\n");
                exit(EXIT_FAILURE);
            }
        }

        array[i] = data;
    }
}
