typedef struct HashNode {
    CRC_INDICATION_PDU_T data;
    struct HashNode* next;
} HashNode;

unsigned long hashFunction(const void* key) {
    const uint64_t m = 1e9 + 31;
    uint64_t hash = ((uint64_t)key % m) * 2654435761;
    return hash % m;
}

void initHashMap(HashNode*** hashTable, unsigned long* tableSize, unsigned long* elements) {
    *tableSize = 1024;
    *elements = 0;
    *hashTable = calloc(*tableSize, sizeof(HashNode*));
}

void insertData(HashNode** hashTable, unsigned long key, CRC_INDICATION_PDU_T data) {
    unsigned long index = hashFunction(&key);
    HashNode** currentNode = hashTable + index;
    while (*currentNode != NULL)
        currentNode = &(*currentNode)->next;
    *currentNode = malloc(sizeof(HashNode));
    (**currentNode) = (HashNode){ .data = data, .next = NULL };
    (*elements)++;
}

bool findData(const HashNode** hashTable, unsigned long key, CRC_INDICATION_PDU_T* result) {
    unsigned long index = hashFunction(&key);
    const HashNode* currentNode = *hashTable + index;
    do {
        if (currentNode->data.tag == key) {
            *result = currentNode->data;
            return true;
        }
    } while ((currentNode = currentNode->next));
    return false;
}

void randomNumberGenerator(unsigned long* seed, unsigned int crcflag) {
    // Implement Mersenne Twister or Linear Congruential Generator here.
    // I will use the Linear Congruential Generator for simplicity.
    *seed = (16807 * (*seed) + 1) % 2147483647;
    unsigned int random = ((*seed) < (2147483647 >> 1)) ? (*seed) * crcflag : (*seed) * (~crcflag & 32767);
}

CRC_INDICATION_PDU_T* initArray(unsigned long N, unsigned long seed) {
    if (N <= 0) return NULL;

    CRC_INDICATION_PDU_T* array = calloc(N, sizeof(CRC_INDICATION_PDU_T));
    HashNode** hashTable = NULL;
    unsigned long tableSize = 0, elements = 0;
    if (!array) {
        printf("Memory allocation failed\n");
        return NULL;
    }

    initHashMap(&hashTable, &tableSize, &elements);

    for (unsigned long i = 0; i < N; ++i) {
        CRC_INDICATION_PDU_T data = { i % MAX_TAG, i, 0 };
        unsigned long backoff = 1 << i;

        while (!findData(hashTable, data.tag, NULL) && elements < N) {
            randomNumberGenerator(&seed, data.crc_indication);
            insertData(hashTable, data.tag, data);
        }
    }

    return array;
}
