```c
#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_MEMORY 16 * (1024 * 1024) // Maximum memory limit in bytes, 16MB

typedef struct record {
    int value;
} Record;

void init_memory(int* offsets, int n, int* keys, int m, Record** records, size_t* total_size) {
    *total_size = sizeof(int) * n + sizeof(int) * m + sizeof(Record) * 10000;
    if(*total_size > MAX_MEMORY) {
        fprintf(stderr, "Insufficient memory. Request too large.\n");
        exit(EXIT_FAILURE);
    }

    offsets = (int*) malloc(*total_size);
    keys = (int*) ((char*)offsets + sizeof(int) * n);
    records = (Record*) ((char*)keys + sizeof(int) * m);

    memset(offsets, 0, sizeof(int) * n);
    memset(keys, 0, sizeof(int) * m);
    srand(time(NULL));

    for (size_t i = 0; i < 10000; ++i) {
        records[i].value = rand() % 100 + 1;
    }
}

void free_memory(int* offsets, int* keys, Record** records) {
    free(offsets);
    free(keys);
    free(records);
}
