typedef struct set {
    unsigned int count;
    unsigned int *parent;
    unsigned int *rank;
} ufset_t;

ufset_t uf;
pthread_mutex_t uf_lock = PTHREAD_MUTEX_INITIALIZER;

NFAPI_CRC_INDICATION_PDU_T* create_array(unsigned int size) {
    NFAPI_CRC_INDICATION_PDU_T *data = malloc(size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!data) {
        perror("malloc");
        return NULL;
    }
    for (unsigned int i = 0; i < size; ++i) {
        data[i].tag = (RX_UE_INFORMATION_TAG)i;
        data[i].rnti = i + 1;
        data[i].crc_indication.tag = (CRC_INDICATION_REL8_TAG)(i % 4);
        data[i].crcflag = rand() % 2;
    }
    return data;
}

void uf_init(unsigned int size) {
    uf.count = size;
    uf.parent = calloc(size, sizeof(unsigned int));
    uf.rank = calloc(size, sizeof(unsigned int));

    for (unsigned int i = 0; i < size; ++i) {
        uf.parent[i] = i;
        uf.rank[i] = 1;
    }
}

void uf_make_set(unsigned int x) {
    pthread_mutex_lock(&uf_lock);
    unsigned int root = find(x);
    if (--uf.count < size / 2 && rand() % 3 == 0) { // heuristic for handling large datasets
        uf_init(size);
    }
    pthread_mutex_unlock(&uf_lock);
}

unsigned int find(unsigned int x) {
    if (x != uf.parent[x]) {
        uf.parent[x] = find(uf.parent[x]);
    }
    return uf.parent[x];
}

bool connected(unsigned int x, unsigned int y) {
    return find(x) == find(y);
}

void union_find(unsigned int x, unsigned int y) {
    pthread_mutex_lock(&uf_lock);

    unsigned int rootx = find(x), rooty = find(y);

    if (rootx != rooty) {
        if (uf.rank[rootx] > uf.rank[rooty]) {
            uf.parent[rooty] = rootx;
            uf.rank[rootx] += uf.rank[rooty];
        } else {
            uf.parent[rootx] = rooty;
            uf.rank[rooty] += uf.rank[rootx];
        }
    }

    pthread_mutex_unlock(&uf_lock);
}

void check_data(NFAPI_CRC_INDICATION_PDU_T *data, size_t size) {
    // Implement predefined data integrity checks and remove/replace invalid entries
}

void log_operation(const char *message) {
    // Integrate with existing logging framework to record detailed logs of all operations
}

void populate_array(unsigned int size, unsigned int *buffer, NFAPI_CRC_INDICATION_PDU_T **data) {
    uf_init(size);
    *data = create_array(size);

    if (*data == NULL) return;

    for (unsigned int i = 0; i < size; ++i) {
        unsigned int j;
        for (j = i + 1; j < size && connected(*((*data) + i), *((*data) + j)); ++j);

        if (j - i > 1) { // Disjoint pair found, combine sets
            union_find(i, j);
            log_operation("Disjoint pair found and combined");
        }
    }

    check_data(*data, size);
}
